SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `frzk_dissertation`;
START TRANSACTION;
-- Alle Änderungen sind auf die Dissertation FRZK und Kapitel 1 begrenzt.
-- Vorhandene andere Kapitel und Literaturangaben werden nicht gelöscht.
SET @frzk_diss_id := (SELECT `id` FROM `dissertations` WHERE `project_code`='FRZK' LIMIT 1);
SET @frzk_rev_id := (SELECT `id` FROM `revisions` WHERE `dissertation_id`=@frzk_diss_id AND `revision_code`='K1_RELEASE_CHAPTERMAP_2026-11-06' LIMIT 1);
SET @frzk_ch1_id := (SELECT `id` FROM `chapters` WHERE `dissertation_id`=@frzk_diss_id AND `chapter_number`='1' LIMIT 1);
-- Alte Hauptabbildungen vor dem Merge in temporäre, konfliktfreie Nummern umhängen.
-- Dies betrifft ausschließlich die drei historischen FRZK-K1-Figuren, nicht andere Kapitel.
UPDATE figures f JOIN research_objects ro ON ro.id=f.object_id
SET f.figure_number=CONCAT('K1_MIG_',f.id)
WHERE ro.dissertation_id=@frzk_diss_id AND ro.chapter_id=@frzk_ch1_id
  AND ro.object_code IN ('K1.FIG.1_F1','K1.FIG.1_F2','K1.FIG.1_F3')
  AND f.figure_number IN ('1.F1','1.F2','1.F3','1.F4');

