UPDATE sections SET body_text='Geltungsbereich: Diese Anlage beschreibt ausschließlich das in Abschnitt 1.2 neu festgelegte Referenzmodell. Sie rekonstruiert nicht die unbekannten historischen Rechenparameter der ursprünglichen beiden Abbildungen.',content_sha256='1796520618312b6950c0145572c00619d01e210a6d88851f2dd5346621fcabae',current_revision_id=@k1_final_rev WHERE id=@k1_section_id;


