UPDATE sections SET body_text='s = 1 m; b = 1 m; d = 3 m; a = 0,20 m⁻¹; xₛ = 5 m; c = 299 792 458 m/s. Der Parameterbereich bildet ein Dreieck mit A = (−0,5; −0,5) m, B = (0,5; −0,5) m und C = (0; h) m, h = (√3 − 1)/2 ≈ 0,3660254 m.\n\nEin Gitterpunkt (u, v) gehört genau dann zum geschlossenen Dreieck, wenn −0,5 ≤ u ≤ 0,5 sowie −0,5 ≤ v ≤ h − √3·|u| gelten. Außerhalb dieses Gebiets wird keine Laufzeit ausgewertet und keine Dreiecksfarbe vergeben.',content_sha256='cf98a84674b00cac9614cf16f1142626a811ecd4a7cc6f3eb2aebf3943983830',current_revision_id=@k1_final_rev WHERE id=@k1_section_id;



DELETE FROM paragraphs WHERE section_id=@k1_section_id AND paragraph_index>2;

SET @k1_section_id := (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1);

UPDATE sections SET body_text='h = (sqrt(3) - 1) / 2\n\nU = 281 äquidistante Werte von -0.5 bis +0.5 (einschließlich)\n\nV = 281 äquidistante Werte von -0.5 bis h (einschließlich)\n\nfür jedes (u,v) aus U × V:\n\nfalls v < -0.5 oder v > h - sqrt(3)*abs(u): überspringen\n\nxQ = 3.0 + 0.20*(u*u - v*v)\n\nL1 = sqrt((5.0 - xQ)^2 + u*u + v*v)\n\nL2 = abs(xQ - 1.0)\n\ntau_ns = 1e9*(L1 + L2)/299792458\n\ntau_ns für die Farbdarstellung dem Punkt (u,v) zuordnen',content_sha256='57eae7ef585dd50c9075c3a7ddf7a0d2390f067261f268800ac1de1fc60fdae2',current_revision_id=@k1_final_rev WHERE id=@k1_section_id;











