SET @k1_section_id := (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.3' LIMIT 1);

UPDATE sections SET body_text='Die Laufzeit wird in Nanosekunden dargestellt. Zur Wiedergabe von Abbildung 1.F4 wird eine gefüllte Konturdarstellung mit 25 linear verteilten Stufengrenzen von 13,34 ns bis 13,75 ns und der Farbpalette „viridis“ verwendet. Die Dreiecksränder werden als Linien verbunden. Die Gitterpunkte außerhalb des Dreiecks bleiben maskiert. Die Farbgrenzen sind fest vorgegeben und werden nicht für jede Wiederholung neu an die Daten angepasst.',content_sha256='84bd5c1aa58fd95a2dd5a059e530abbf9911f258dc61522bd0378d56d9ce4317',current_revision_id=@k1_final_rev WHERE id=@k1_section_id;


