UPDATE sections SET body_text='Analytischer Kontrollpunkt (u,v) = (0,0): τ = 13,3425638079 ns. Eckpunkte A und B: je τ = 13,7472449142 ns. Eckpunkt C: τ = 13,4519250616 ns. Auf dem beschriebenen 281 × 281-Gitter liegen 39 481 Punkte innerhalb der Dreiecksmaske; der kleinste erfasste Gitterwert beträgt ungefähr 13,3425647406 ns, der größte 13,7472449142 ns. Die geringe Abweichung des Gitterminimums vom Wert am Mittelpunkt entsteht, weil v = 0 keine der 281 gleichmäßig verteilten v-Koordinaten ist.',content_sha256='b83637b062b862c6db1564dfeaf1b70742613c4cb50da0619bc386bec132135d',current_revision_id=@k1_final_rev WHERE id=@k1_section_id;


