UPDATE sections SET body_text='Die Regel beschreibt einen idealisierten zweiteiligen Signalweg vom Sender über einen zugeordneten Flächenpunkt zu einem Punkt der Beobachtungsebene. Sie berücksichtigt keine realistische winkelabhängige Reflexion, keine Mehrfachwege und keine Streu- oder Dämpfungseffekte. Das Ergebnis ist deshalb ein geometrisch begründetes Laufzeit-Skalarfeld, kein nachgewiesenes optisches Messverfahren. Die zwei historischen Skizzen in Abschnitt 1.2 bleiben ohne ihre ursprünglichen Daten eigenständige Illustrationen; mit diesem Referenzmodell werden sie nicht nachträglich validiert.',content_sha256='55b2319d4573fc1a7a2f1a94a5d8ef6bcf8ff15276782f366a452582fd02d9a0',current_revision_id=@k1_final_rev WHERE id=@k1_section_id;


