-- Abschlusskontrolle. Abbildungen: 4 Hauptabbildungen + 5 Anlage 1A + 7 Anlage 1A.2 = 16.
SELECT ch.chapter_number,ch.status,rv.revision_code,rv.source_filename,rv.content_sha256
FROM chapters ch JOIN revisions rv ON rv.id=ch.current_revision_id WHERE ch.id=@frzk_ch1_id;
SELECT 'sections' AS objekt,COUNT(*) AS anzahl FROM sections WHERE chapter_id=@frzk_ch1_id
UNION ALL SELECT 'paragraphs',COUNT(*) FROM paragraphs p JOIN sections s ON p.section_id=s.id WHERE s.chapter_id=@frzk_ch1_id
UNION ALL SELECT 'literature',COUNT(DISTINCT so.id) FROM citations ci JOIN sources so ON so.id=ci.source_id JOIN sections se ON se.id=ci.section_id WHERE se.chapter_id=@frzk_ch1_id
UNION ALL SELECT 'figures',COUNT(*) FROM figures f JOIN research_objects r ON r.id=f.object_id WHERE r.chapter_id=@frzk_ch1_id
UNION ALL SELECT 'tables',COUNT(*) FROM manuscript_tables t JOIN research_objects r ON r.id=t.object_id WHERE r.chapter_id=@frzk_ch1_id
UNION ALL SELECT 'equations',COUNT(*) FROM equations e JOIN research_objects r ON r.id=e.object_id WHERE r.chapter_id=@frzk_ch1_id;
SELECT figure_number,caption FROM figures f JOIN research_objects r ON r.id=f.object_id WHERE r.chapter_id=@frzk_ch1_id ORDER BY figure_number;
SELECT check_code,status FROM validation_checks WHERE chapter_id=@frzk_ch1_id AND status IN ('OPEN','FAIL','WARNING') ORDER BY check_code;
