INSERT INTO `dissertations` (`project_code`, `title`, `language_code`, `status`, `notes`) VALUES ('FRZK', 'Funktionales Raum-Zeit-Kohärenzsystem (FRZK) – Dissertation', 'de', 'REVIEW', 'Kapitel 1 als Autorenfassung abgeschlossen; mathematische Sonderstrukturen als Zusatz zum methodischen Problemlöseansatz. Wissenschaftliche Originalstellen-/Ethikprüfungen zum Teil offen.') ON DUPLICATE KEY UPDATE `project_code`=VALUES(`project_code`);
INSERT INTO `revisions` (`dissertation_id`, `revision_code`, `title`, `revision_type`, `source_filename`, `content_sha256`, `status`, `notes`) VALUES (@frzk_diss_id, 'K1_RELEASE_CHAPTERMAP_2026-11-06', 'Kapitel 1 – korrigierte Kapitelzuordnung mit Anlagen 1A–1E', 'RELEASE', 'FRZK_Kapitel_1_FINAL_Kapitel_2_korrigiert_2026-11-06.docx', 'b90546627250f4820dcacec017a8124e2c1defd0110538e004623a8a2a71e269', 'FINAL', 'Korrigierte Autorenrevision: Kapitel 2 als Grundlagenkapitel; offene externe Quellen- und Nutzungsrechtsprüfungen in validation_checks/issues.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `revision_type`=VALUES(`revision_type`), `source_filename`=VALUES(`source_filename`), `content_sha256`=VALUES(`content_sha256`), `status`=VALUES(`status`), `notes`=VALUES(`notes`);
INSERT INTO `chapters` (`dissertation_id`, `chapter_number`, `title`, `sort_order`, `status`, `current_revision_id`, `body_text`, `notes`) VALUES (@frzk_diss_id, '1', 'Einleitung', 1, 'RELEASED', @frzk_rev_id, '1.0 Einleitung\nIn meiner Nachhilfepraxis beobachte ich wiederholt, dass Lernende bei komplexen Aufgaben Schwierigkeiten haben, relevante Angaben zu ordnen, Beziehungen zu erkennen und den eigenen Lösungsweg zu reflektieren. Ich untersuche deshalb einen methodischen Ablauf, der bei der Formulierung der Problemstellung beginnt, Gegebenes und Gesuchtes trennt, Beziehungen erschließt, eine Lösung entwickelt und diese überprüft. Das Funktionale Raum-Zeit-Kohärenzsystem (FRZK) verstehe ich primär als methodischen Ansatz zur Problemstellung und Problemlösung. Seine mathematischen Erweiterungen um besondere Grenzwert- und Vektorsymbole gehören nicht zum allgemeinen methodischen Grundgerüst. Ob das Vorgehen die Nachvollziehbarkeit, Fehlererkennung und Übertragbarkeit von Lösungsstrategien verbessert, bleibt eine empirisch zu prüfende Frage.\nDie Fragestellung berührt wissenschaftliche Diskussionen über Modellbildung, Beobachtung und die Begriffe Raum und Zeit. Rovelli behandelt die Grundlagen unseres Zeitverständnisses und die Grenzen herkömmlicher Vorstellungen von Zeit (Rovelli, Carlo (2018). The Order of Time. London: Penguin Books.)[1]. Ich verwende diese Darstellung als physikalisch-philosophischen Hintergrund, nicht als Bestätigung einer aus dem FRZK hervorgehenden Raumzeit oder als Nachweis seines didaktischen Nutzens.\nDie Systemtheorie und die Kybernetik eröffnen unterschiedliche Perspektiven auf Systembeziehungen, Beobachtung und die Beschreibung von Lern- und Kommunikationsprozessen (von Foerster, Heinz (1981). Observing Systems. Seaside, CA: Intersystems Publications.)[2] (Maturana, Humberto R.; Varela, Francisco J. (1987). The Tree of Knowledge: The Biological Roots of Human Understanding. Boston: Shambhala.)[3]. Für die Entwicklung und Untersuchung didaktischer Verfahren ist die gestaltungsorientierte Lehr-Lernforschung ein methodischer Bezugspunkt (Reinmann, Gabi (2005). Innovation ohne Forschung? Ein Plädoyer für den Design-Based Research-Ansatz in der Lehr-Lernforschung. Unterrichtswissenschaft, 33(1), S. 52–69. DOI: 10.25656/01:5787.)[4]. Einen Ansatz zur Begleitung und Anregung eigenständiger Lernprozesse erläutert Arnold (Arnold, Rolf (2012). Wie man lehrt, ohne zu belehren. 29 Regeln für eine kluge Lehre. Das LENA-Modell. 1. Auflage. Heidelberg: Carl-Auer. ISBN: 978-3-89670-838-0.)[5]. Sfard untersucht mathematisches Denken aus einer kommunikationstheoretischen Perspektive (Sfard, Anna (2008). Thinking as Communicating: Human Development, the Growth of Discourses, and Mathematizing. Cambridge: Cambridge University Press. DOI: 10.1017/CBO9780511499944.)[6]. Luhmann stellt mit seiner Theorie sozialer Systeme einen weiteren, davon zu unterscheidenden systemtheoretischen Bezug bereit (Luhmann, Niklas (1984). Soziale Systeme: Grundriß einer allgemeinen Theorie. Frankfurt am Main: Suhrkamp.)[7]. Keiner dieser Ansätze beweist bereits die Wirksamkeit des FRZK.\nDas methodische Grundgerüst des FRZK beschreibt eine Folge nachvollziehbarer Bearbeitungshandlungen: Eine Problemstellung wird zunächst geklärt und als Frage formuliert; anschließend werden bekannte und gesuchte Größen, Voraussetzungen und Beziehungen geordnet, Lösungsansätze entwickelt, ausgeführt und anhand der Ergebnisse überprüft. Die ausdrückliche Darstellung funktionaler Zusammenhänge ist ein Hilfsmittel innerhalb dieses Weges, nicht dessen einziges Ziel. Das Grundgerüst setzt weder ein bestimmtes Koordinatensystem noch eine spezielle Geometrie, Dynamik oder Algebra voraus. Rekursion, Fixpunkte, Kohärenzbedingungen und mathematische Sonderzeichen werden nur dann hinzugenommen, wenn die konkrete Aufgabe dies erfordert.\nDie in Kapitel 3 behandelten besonderen FRZK-Zustände, gerichteten Grenzannäherungen, Grenzzeichen, Null- und Vektoroperationen sowie die orthogonale Ausgangsorientierung bilden eine gesonderte mathematische Erweiterung des methodischen Ansatzes. Sie sind nicht als Voraussetzungen für jede Problemstellung oder für jede Anwendung des FRZK zu verstehen. Ihre Bedeutung, Rechenregeln und Gültigkeitsbereiche müssen unabhängig vom Grundgerüst definiert und formal geprüft werden. Insbesondere ist eine leere Darstellung nicht mit der mathematisch leeren Menge oder einem physikalisch leeren Raum gleichzusetzen; ein FRZK-Nullzustand ist kein gewöhnlicher reeller Zahlenwert und ein orientierter Nullzustand nicht ohne zusätzliche Information rückskalierbar.\n\n1.1 Entstehung der Forschungsfrage aus der Unterrichtspraxis\n\n\n1.1.1 Praktisches Beispiel: Textaufgabe\nIn meiner Nachhilfepraxis begegnen mir Aufgaben, bei denen Schülerinnen und Schüler die gegebenen Informationen zwar lesen oder notieren können, deren funktionale Beziehungen und die gesuchte Größe aber noch nicht erkennen. Die folgenden Beispiele begründen die Forschungsfrage aus meiner Perspektive. Sie sind zunächst Unterrichtsbeobachtungen und keine repräsentative empirische Untersuchung.\nBeispiel 1: Eine Schülerin 3. Klasse Grundschule sollte die Aufgabe: „Ein Bauer hat 173 Kartoffeln und 8 Säcke. Wieviel Kartoffeln kommen in einen Sack und wie viele bleiben übrig?“. Mein Standardansatz zur Lösung von Textaufgaben besteht darin, alles, was gegeben ist, mit blau und alles, was gesucht ist, mit grün zu unterstreichen, dann die Angaben in den Notizblock zu übertragen und schließlich zu lösen. Ich habe der Schülerin diesen Ansatz empfohlen und ihr aufgetragen, die Aufgabe zu lösen. Nach etwa 15 Minuten habe ich versucht die Lösung zu kontrollieren und festgestellt, dass die Schülerin die gesamte Aufgabe mit blau unterstrichen hatte und in ihren Notizblock 1:1 übernommen hatte.\nMan könnte zunächst feststellen, dass die Aufgabe nicht im erwarteten Sinne gelöst wurde. Bei genauerer Betrachtung hatte die Schülerin jedoch meinen Arbeitsauftrag befolgt und die gesamte Aufgabenstellung als gegeben markiert. Ich deutete dieses Verhalten als möglichen Hinweis darauf, dass sie die für die Lösung benötigten Informationen noch nicht voneinander unterscheiden konnte. Ob ihr insbesondere die Situation mit Bauer und Kartoffeln unvertraut war, lässt sich aus dieser einen Beobachtung allein nicht sicher ableiten. Die Schülerin zeigte eine erkennbare Bearbeitungsaktivität; die mathematische Lösung und die dafür notwendige Interpretation der Angaben blieben zunächst offen.\nIch erarbeitete daraufhin mit der Schülerin auf einem leeren Blatt Papier eine schrittweise Strukturierung der Situation. Die vom Autor bereitgestellte Anlage 1A („Inkrementelles Setup einer Textaufgabe“) veranschaulicht in fünf Bildern den Weg vom leeren Blatt über eine Orientierung in der Situation zur Unterscheidung von Gesuchtem und Gegebenem. Sie dokumentiert einen didaktischen Aufbau, ist aber kein datiertes Original der von der Schülerin angefertigten Lösung und kein standardisiert erhobener Lernfortschritt. Der berichtete Gesprächsverlauf bleibt eine retrospektive Unterrichtsbeobachtung.\n\n1.1.2 Praktisches Beispiel: Lineare Zusammenhänge\nZwei Schülerinnen aus der 9. Klasse Gymnasium standen vor der Aufgabe: „Wie würdest du deinem besten Freund oder deiner besten Freundin erklären, was eine lineare Funktion ist?“ Die Aufgabe zielte darauf ab, ein grundlegendes Verständnis für lineare Funktionen zu entwickeln, indem die Schülerinnen den Begriff selbstständig formulieren und ihre eigenen Worte finden sollten, um diese mathematische Beziehung zu erklären. Doch anstatt eine klare Vorstellung von einer linearen Funktion zu entwickeln, standen die Schülerinnen vor einer mentalen Blockade.\nIn einer ersten Rückmeldung erklärten beide Schülerinnen, dass sie nicht wüssten, wie sie ihre Antwort beginnen sollten. Ich deutete dies als Hinweis darauf, dass ihnen ein sprachlicher und anschaulicher Zugang zu der gefragten Beziehung fehlte. Ob dabei die Begriffskenntnis, das Vorwissen, die konkrete Aufgabenstellung oder weitere Faktoren entscheidend waren, ließ sich in dieser Situation nicht isolieren.\nEine der Schülerinnen äußerte: „Was ist das, eine Linie? Es sind doch Zahlen, aber wie hängen die zusammen?“ Sie hatte Schwierigkeiten, das Konzept einer linearen Funktion als eine mathematische Beziehung zu begreifen, die über abstrakte Zahlen und Parameter hinausgeht und in einem konkreten Zusammenhang, wie etwa einer realen Situation (z.B. eine Geschwindigkeit über Zeit oder den Zusammenhang zwischen dem Einkommen und den Arbeitsstunden), interpretiert werden könnte. Auch die andere Schülerin konnte die Aufgabe nicht anders angehen, als die Parameter der linearen Funktion als isolierte mathematische Elemente zu betrachten, ohne deren Einfluss auf die Gestalt der Linie oder auf die Veränderung der Werte in einer praktischen Anwendung zu begreifen.\nIn der Situation konnten die Schülerinnen die Formel einer linearen Funktion benennen, hatten aber Schwierigkeiten, die Bedeutung der Parameter und den Zusammenhang der Größen in eigenen Worten zu erläutern. Für meine Untersuchung ist daran besonders interessant, ob eine ausdrücklich geordnete Darstellung von Größen, Beziehungen und Beispielen den Übergang von einer symbolischen Schreibweise zu einer fachlich angemessenen Erklärung unterstützen kann.\nIch beobachtete, dass die Schülerinnen zunächst nach einer bekannten Definition suchten und eigene Beispiele kaum verwendeten. Daraus ergibt sich für mich eine prüfbare didaktische Frage: Welche Darstellungshilfen erleichtern es Lernenden, den mathematischen Zusammenhang als Beziehung veränderlicher Größen zu beschreiben? Die Beobachtung allein lässt weder auf eine allgemeine Ursache noch auf die Wirksamkeit einer bestimmten Unterrichtsmethode schließen.\nDie beiden Unterrichtsbeobachtungen lassen sich mit der didaktischen Frage verbinden, wie Lernende tragfähige Begriffe aufbauen und neues Wissen mit vorhandenem Wissen verknüpfen. Bruner behandelt die Struktur von Unterrichtsinhalten und die schrittweise Vertiefung grundlegender Vorstellungen (Bruner, Jerome S. (1960). The Process of Education. Cambridge, MA: Harvard University Press. DOI: 10.4159/9780674028999.)[8]. Ausubels Arbeiten befassen sich mit der Bedeutung der kognitiven Struktur für sinnvolles sprachliches Lernen (Ausubel, David P. (1963). The Psychology of Meaningful Verbal Learning. New York: Grune & Stratton.)[9]. Die genaue Zuordnung einzelner Buchseiten bleibt bis zur Editionsprüfung offen.\n\n1.1.3 Ergänzendes Beispiel: Ungewöhnliche Lösungswege\nRudolf Taschner: Der Irrtum des Pythagoras\nAls Beispiel für die öffentliche Vermittlung mathematischer Fragestellungen nenne ich Rudolf Taschners Vortrag „Der Irrtum des Pythagoras“ (Taschner, Rudolf (2013). Der Irrtum des Pythagoras. Videoaufzeichnung, math.space, TIB AV-Portal. DOI: 10.5446/15789.)[10]. Für meine Arbeit ist daran die Frage relevant, wie ein zunächst ungewohnter mathematischer Zugang fachlich geprüft und verständlich erläutert werden kann. Ich übernehme aus dem Vortrag weder ein wörtliches Zitat noch eine Abbildung; seine Erwähnung dient als Anregung für diese didaktische Fragestellung, nicht als Beleg für die Wirksamkeit des FRZK.\n\n1.1.4 Zwischenbilanz\nDie Unterrichtsbeispiele verdeutlichen mein Erkenntnisinteresse: Lernende benötigen bei mathematischen Aufgaben nicht allein Rechenverfahren, sondern müssen Angaben, Begriffe und funktionale Beziehungen unterscheiden und aufeinander beziehen können. Ich möchte prüfen, ob ein systematischer Darstellungsrahmen dabei unterstützt, die Problemstellung zu verstehen, den Lösungsweg zu begründen und das Verfahren auf neue Aufgaben zu übertragen. Die Beispiele zeigen den Anlass dieser Untersuchung, nicht bereits deren Ergebnis.\n\n1.2 Lösungsweg und Ergebnis\nUm die Entstehung meiner Forschungsfrage nachvollziehbar zu machen, wählte ich zunächst bewusst eine Aufgabe außerhalb meiner üblichen Nachhilfepraxis: Wie lässt sich eine gekrümmte, im Allgemeinen intrinsisch nichteuklidische Fläche auf einer zweidimensionalen Beobachtungsfläche durch berechnete Signalgrößen darstellen? Mein Interesse an Geometrie, Astronomie und physikalischer Modellbildung gab den Anlass. Die nachfolgende Beschreibung unterscheidet die ursprüngliche Ideenskizze von einem neu festgelegten, rechnerisch reproduzierbaren Referenzfall.\nBei der Bearbeitung trennte ich zunächst die Angaben, die frei wählbaren Annahmen und die gesuchten Ergebnisse. Unter einem zunächst leeren Bezugssystem verstand ich dabei kein physikalisches Vakuum und keine mathematisch leere Menge, sondern ein Koordinaten- und Darstellungsgerüst, dessen konkrete Objekte und Regeln ich erst nach und nach festlegte.\nIn der ursprünglichen Skizze setzte ich den Beobachter in den Ursprung eines räumlichen Koordinatensystems, führte eine gekrümmte Fläche ein und wählte ein gleichseitiges Dreieck als zweidimensionale Beobachtungsfläche. Die historische Darstellung in Abbildung 1.F2 dokumentiert diese Reihenfolge; aus der Skizze allein lassen sich jedoch weder die genaue Flächenfunktion noch messbare Signalwerte bestimmen.\nAbbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.\nDie Darstellung unterscheidet den Beobachter im Koordinatenursprung, die dreieckige Beobachtungsebene und die untersuchte gekrümmte Fläche. Welche Eigenschaften die Fläche besitzt, ist mathematisch erst nach Angabe einer Parametrisierung und eines Definitionsbereichs entschieden.\nEine zweidimensionale Darstellung macht eine dreidimensionale Situation nicht vollständig sichtbar. Daher unterscheide ich im Folgenden ausdrücklich zwischen den geometrischen Objekten des Modells, den berechneten Signalgrößen und deren Farbcodierung. Aus einer graphischen Projektion folgt weder, dass physikalischer Raum entsteht, noch, dass die Modellgröße eine tatsächliche Messung darstellt.\nDie geometrische Skizze beantwortete die eigentliche Aufgabe noch nicht. Um Beziehungen quantitativ auszuwerten, musste ich festlegen, welcher Punkt der gekrümmten Fläche welchem Punkt des Dreiecks zugeordnet wird. Eine solche eindeutige Zuordnung ist die hier benötigte Bezugsfunktion; sie ist eine Modellentscheidung und keine automatisch aus der Zeichnung folgende Gesetzmäßigkeit.\nAnschließend ergänzte ich einen Sender und eine Signalvorschrift. Erst damit ließ sich jedem zugeordneten Punktpaar eine berechenbare Laufzeit zuweisen. Der Sender ist kein allgemeines Axiom des FRZK, sondern ausschließlich ein Bestandteil dieses technischen Beispiels. Die Einführung von Laufzeiten macht eine zeitbezogene Größe auswertbar; sie bedeutet nicht, dass sich die Geometrie selbst zeitlich verändern muss.\nIm Ausgangsgedanken sollte ein Signal vom Sender über einen Punkt der gekrümmten Fläche zu einem zugeordneten Punkt des Beobachtungsdreiecks gelangen. Die gesamte Weglänge wurde in eine Laufzeit umgerechnet und anschließend farblich kodiert. Damit entsteht eine zweidimensionale Darstellung eines aus einer dreidimensionalen Konstruktion abgeleiteten Skalarfelds. Für eine wissenschaftlich wiederholbare Berechnung sind die Geometrie, die Zuordnung und die Ausbreitungsannahmen ausdrücklich anzugeben.\nAbbildung 1.F3 zeigt die ursprüngliche Visualisierung solcher berechneten Laufzeitgrößen. Die dafür verwendeten Originalparameter, Programmdateien und Rohdaten sind hier nicht dokumentiert; deshalb gebe ich ihre Werte nicht nachträglich als überprüft aus. Stattdessen definiere ich im Folgenden ein unabhängiges Referenzmodell, mit dem derselbe methodische Rechengang vollständig nachvollzogen werden kann. Über einen rechtlichen Status oder Schutzrechte trifft dieser Abschnitt keine Aussage.\nAbbildung 1.F3: Ursprüngliche dreidimensionale Visualisierung modellierter Signallaufzeiten. Die historischen Rechenparameter sind für die vorliegende Fassung nicht belegt; die Darstellung wird daher nicht als numerischer Nachweis des nachfolgenden Referenzmodells verwendet. Eigene Darstellung.\nReproduzierbares technisches Referenzmodell\nDie folgende Konkretisierung ist eine ausdrücklich neu festgelegte Modellvariante, keine nachträgliche Rekonstruktion der unzugänglichen Originalrechnung. Sie dient dazu, den in der Entstehungsgeschichte beschriebenen Rechenweg mit vollständig offengelegten Größen und Regeln zu demonstrieren. Alle Koordinaten und Längen werden in Metern, Zeiten in Sekunden beziehungsweise Nanosekunden angegeben.\nKoordinatensystem und Dreieck. Der Beobachter O=(0, 0, 0) ist der geometrische Bezugspunkt. Das Beobachtungsdreieck liegt in der Ebene x=b mit b=1 m; seine Seitenlänge beträgt s=1 m. Für die beiden ebenen Koordinaten u und v wird das abgeschlossene Dreiecksgebiet D durch die Eckpunkte A, B und C festgelegt (Gleichung 1.1):\nWord-LaTeX: A=(-\\tfrac{s}{2},-\\tfrac{s}{2}),\\quad B=(\\tfrac{s}{2},-\\tfrac{s}{2}),\\quad C=(0,\\frac{(\\sqrt{3}-1)s}{2})\nDie Punkte A, B und C der vorstehenden Formel sind (u,v)-Koordinaten in der Beobachtungsebene. Das Dreieck ist gleichseitig, denn alle drei Seiten haben die Länge s. Jeder Punkt (u,v)∈D beschreibt genau einen Beobachtungspunkt P(u,v) in der Ebene x=b.\nGekrümmte Fläche und Bezugsfunktion. Im dreidimensionalen Raum definiere ich die Fläche Q durch die folgende Parametrisierung. Für das Beispiel setze ich d=3 m und a=0,20 m⁻¹; der Definitionsbereich der Fläche ist genau das Dreiecksgebiet D. Die Zuordnung P(u,v)↔Q(u,v) verwendet dieselben beiden Parameter u und v und ist daher eindeutig (Gleichung 1.2).\nWord-LaTeX: Q(u,v)=\\left(d+a(u^{2}-v^{2}),\\,u,\\,v\\right),\\qquad P(u,v)=(b,u,v)\nDie Oberfläche ist eine Sattelfläche. Ihre Gauß-Krümmung ergibt sich aus den ersten und zweiten Ableitungen der Flächenfunktion und ist bei a≠0 überall negativ (Gleichung 1.3):\nWord-LaTeX: K(u,v)=\\frac{-4a^{2}}{\\left(1+4a^{2}(u^{2}+v^{2})\\right)^{2}}<0\nDamit ist „nichteuklidisch“ in diesem Beispiel präzisiert: Gemeint ist die innere Geometrie einer gekrümmten zweidimensionalen Fläche, nicht eine Krümmung des umgebenden dreidimensionalen Raums oder der physikalischen Raumzeit. Wege außerhalb der Fläche werden im Referenzmodell euklidisch berechnet.\nSender, Signalweg und Ausbreitungsannahmen. Der Sender liegt bei S=(xₛ,0,0) mit xₛ=5 m. Jeder Flächenpunkt Q(u,v) wird idealisiert als punktförmiger, unmittelbar weiterstrahlender Signalpunkt angenommen. Für das jeweilige Parameterpaar wird genau der zweite Wegabschnitt von Q(u,v) zu P(u,v) ausgewertet. Beide Wegabschnitte sind gerade Strecken im dreidimensionalen euklidischen Raum. Das Modell setzt Vakuumausbreitung mit konstanter Geschwindigkeit c, keine Laufzeitverzögerung am Flächenpunkt und keine Abschwächung voraus. Brechung, Beugung, Mehrfachwege, Abschattung und die winkelabhängige Reflexionsbedingung werden nicht modelliert. Das ist eine idealisierte Zuordnungsvorschrift und kein vollständiges optisches Reflexionsmodell.\nMess- beziehungsweise Rechengröße. Die zugeordnete Gesamtlaufzeit ist die Summe der beiden euklidischen Segmentlängen, geteilt durch die Ausbreitungsgeschwindigkeit. Mit xₛ=5 m, b=1 m, d=3 m und a=0,20 m⁻¹ gilt (Gleichung 1.4):\nWord-LaTeX: \\tau(u,v)=\\frac{\\sqrt{\\left(x_{S}-d-a(u^{2}-v^{2})\\right)^{2}+u^{2}+v^{2}}+d+a(u^{2}-v^{2})-b}{c}\nDabei steht c=299 792 458 m/s für die im Internationalen Einheitensystem exakt festgelegte Vakuumlichtgeschwindigkeit (Bureau International des Poids et Mesures (2026). The International System of Units, 9. Auflage, aktualisierte Fassung. DOI: 10.59161/AUEZ1291.)[15]. Die berechnete Laufzeit ist eine Modellgröße. Eine tatsächliche Messung oder ein bestimmter physikalischer Reflexionsvorgang wird dadurch nicht nachgewiesen.\nErgebnisfunktion und Darstellung. Mit der Zuordnung jedes Beobachtungspunkts zu seiner Laufzeit entsteht ein Skalarfeld auf dem Dreieck (Gleichung 1.5):\nWord-LaTeX: F:P(u,v)\\longmapsto \\tau(u,v),\\qquad (u,v)\\in D\nZur numerischen Darstellung werden die Bereiche −0,50 m ≤ u ≤ 0,50 m und −0,50 m ≤ v ≤ (√3−1)/2 m jeweils mit 281 gleichmäßig verteilten Stützstellen abgetastet. Ausgewertet werden ausschließlich Punkte innerhalb des abgeschlossenen Dreiecks D. An jedem gültigen Gitterpunkt werden Q, die beiden Signalstrecken und τ in dieser Reihenfolge berechnet. Für die reproduzierbare Farbkodierung in Abbildung 1.F4 wird der Bereich von 13,34 ns bis 13,75 ns fest vorgegeben; größere Werte entsprechen dem oberen Ende der Farbskala. Die exakte Gebietsmaske, die Farbstufen und der Algorithmus sind in Anlage 1E dokumentiert.\nKontrollrechnung. Für (u,v)=(0,0) folgt Q=(3,0,0) m und P=(1,0,0) m. Damit betragen beide Wegabschnitte jeweils 2 m. Aus der Gesamtstrecke von 4 m ergibt sich τ(0,0)=13,3426 ns. Für die beiden unteren Dreiecksecken A und B ergeben sich jeweils 13,7472 ns; für die obere Ecke C ergibt sich 13,4519 ns. Diese Zahlen lassen sich unmittelbar durch Einsetzen in die angegebenen Gleichungen kontrollieren.\nAbbildung 1.F4: Numerisch reproduzierte Laufzeitverteilung auf dem Beobachtungsdreieck für die offengelegten Referenzparameter (s=1 m, b=1 m, d=3 m, a=0,20 m⁻¹, xₛ=5 m, c=299 792 458 m/s). Berechnung und Darstellung für diese Dissertation; nicht aus den historischen Abbildungen 1.F2 und 1.F3 abgeleitet.\nPrüfgrenzen des Referenzfalls. Die Gleichungen ermöglichen es, den geometrischen und numerischen Rechenweg unabhängig zu wiederholen; insbesondere sind Definitionsbereich, Flächenfunktion, Zuordnung, Signalweg, Konstanten und Farbbereich festgelegt. Damit ist die modellinterne Reproduzierbarkeit des hier definierten Referenzfalls hergestellt. Offen bleibt dagegen, ob die ursprünglichen Abbildungen auf denselben oder anderen Parametern beruhen. Ebenso ist mit der Konstruktion weder die physikalische Gültigkeit einer realen Signalstreuung noch eine allgemeine mathematische oder didaktische Wirksamkeit des FRZK belegt.\nDas Referenzmodell zeigt, wie sich eine technische Problemstellung durch explizite Annahmen, eine definierte Geometrie, eine Zuordnungsregel und überprüfbare Rechnungen bearbeiten lässt. Darin liegt sein methodischer Bezug zum FRZK: Aus einer zunächst offenen Frage wird ein nachvollziehbarer Lösungsweg entwickelt und geprüft. Weder die gewählte Geometrie noch die Signalvorschrift sind Bestandteile des allgemeinen FRZK-Grundgerüsts; spezielle mathematische FRZK-Zustände und Operatoren werden in diesem Referenzmodell nicht benötigt.\nZwischen dem technischen Beispiel und meinen Unterrichtsbeobachtungen erkenne ich ein gemeinsames methodisches Motiv: Ich bestimme relevante Größen und Annahmen, ordne Beziehungen ausdrücklich zu und überprüfe die daraus ableitbaren Ergebnisse. Bei der Kartoffelaufgabe betrifft dies gegebene und gesuchte Angaben, bei linearen Funktionen die Abhängigkeit veränderlicher Größen. Eine Verbesserung von Lernleistungen ist damit noch nicht nachgewiesen.\nDas technische Referenzmodell und die Unterrichtsbeobachtungen sind methodisch vergleichbar, aber weder mathematisch noch empirisch identisch. Carroll diskutiert das Verhältnis naturwissenschaftlicher Weltbeschreibung zu weiterführenden philosophischen Fragestellungen (Carroll, Sean (2016). The Big Picture: On the Origins of Life, Meaning, and the Universe Itself. New York: Dutton.)[11]. Dieser allgemeine Bezug begründet weder die vorliegende technische Modellwahl noch die pädagogische Wirksamkeit des FRZK.\nIm Beispiel der Grundschülerin konnte ich beobachten, dass sie zunächst alle Informationen als gleichwertig behandelte. Eine schrittweise Strukturierung der Aufgabe bot die Gelegenheit, zwischen den vorhandenen Angaben und der gesuchten Größe zu unterscheiden. Welche Rolle dabei die konkrete Alltagssituation, das Vorwissen und die sprachliche Aufgabenformulierung spielten, blieb offen.\nBei den Schülerinnen der neunten Klasse zeigte sich eine andere Schwierigkeit: Eine bekannte Formel konnte nicht ohne Weiteres in eine verständliche Erklärung überführt werden. Für die Modellierung ist deshalb zu unterscheiden zwischen einer symbolischen Darstellung, den Bedeutungen ihrer Variablen und den funktionalen Beziehungen im jeweiligen Sachkontext. Die mögliche didaktische Wirkung einer solchen Unterscheidung ist Gegenstand meiner Untersuchung.\nAus beiden Situationen leite ich keine allgemeine Lerntheorie ab. Ich entwickle daraus eine Forschungsfrage nach dem Nutzen expliziter Orientierung: Hilft es, wenn Lernende einen mathematischen Zusammenhang durch eigene Beschreibungen, Beispiele und überprüfbare Zuordnungen erschließen?\n\n1.3 Die Rolle des Tutors und die Struktur von Nachhilfe im Kontext der individuellen Lernförderung\nNach meinen Erfahrungen aus drei Jahren Nachhilfepraxis umfasst die Aufgabe eines Tutors mehr als das Nachholen versäumter Lerninhalte oder die kurzfristige Vorbereitung auf Leistungsüberprüfungen. In meiner Arbeit dienen die Nachhilfestunden auch der Vertiefung behandelter Themen, der Überprüfung des übergreifenden fachlichen Verständnisses und der schrittweisen Entwicklung eigenständiger Problemlösestrategien. Ich bezeichne diese Arbeit als spezifischer auf den einzelnen Lernenden ausgerichtet, weil ich Aufgaben, Erklärungen, Rückfragen und Übungsphasen unmittelbar an dessen fachlichen Voraussetzungen anpassen kann. Damit beschreibe ich die Möglichkeiten meiner konkreten Nachhilfepraxis, nicht eine allgemeingültige Überlegenheit der Nachhilfe gegenüber dem Schulunterricht.\nDer schulische Unterricht ist an Lehrpläne, Unterrichtszeiten und das gemeinsame Lernen einer Klasse gebunden. Auch dort finden Differenzierung, individuelle Förderung und Vertiefung statt. In meinen kleinen Nachhilfegruppen kann ich jedoch zusätzliche Zeit auf einzelne Verständnisfragen verwenden, frühere Grundlagen erneut aufgreifen und das Tempo sowie den Schwierigkeitsgrad der Aufgaben personenbezogen verändern. Die Vertiefung richtet sich dabei nicht nur auf aktuelle Hausaufgaben, sondern auf die fachlichen Zusammenhänge des jeweiligen Themengebiets.\nEin zentraler Bestandteil ist die allgemeine Verständniskontrolle über die unmittelbar bearbeitete Aufgabe hinaus. Dazu lasse ich Lernende Begriffe und Zusammenhänge in eigenen Worten erklären, Lösungsentscheidungen begründen, typische Fehler erkennen und bekannte Verfahren in veränderten Aufgabenstellungen anwenden. Zeigen sich dabei Lücken im Vorwissen, greife ich diese gezielt auf. Rückfragen, ergänzende Erklärungen und die Anpassung der Arbeitsblätter dienen so nicht allein der Kontrolle eines Rechenergebnisses, sondern der Überprüfung, ob der zugrunde liegende mathematische Gedanke verstanden wurde. Die in Abschnitt 1.5 erläuterte altersabhängige Selbstkontrolle von Arbeitsergebnissen ersetzt diese übergreifende fachliche Verständniskontrolle nicht.\nIch messe der Lernatmosphäre, dem fachlichen Feedback und der nachvollziehbaren Rückmeldung über Lösungswege besondere Aufmerksamkeit bei. Hattie bündelt umfangreiche Forschung zu Faktoren schulischen Lernens und behandelt unter anderem die Bedeutung von Rückmeldung (Hattie, John (2009). Visible Learning: A Synthesis of Over 800 Meta-Analyses Relating to Achievement. London: Routledge.)[12]. Daraus lässt sich für meine konkreten Lerngruppen weder eine bestimmte Effektstärke ableiten noch die Wirksamkeit des FRZK voraussetzen; diese Zusammenhänge müssen im Untersuchungsdesign getrennt beobachtet werden.\nDie individuelle Förderung berücksichtigt unterschiedliche Vorkenntnisse, Stärken, Schwierigkeiten und Interessen. Zu Beginn eines Themengebiets erhalten die Lernenden eine Concept-Map oder ein Kompendium als Überblick. Anschließend erfolgt die Vertiefung themen- und defizitorientiert anhand persönlich angepasster Arbeitsblätter. Durch gezielte Rückmeldungen und Verständnisfragen beobachte ich, welche Beziehungen bereits sicher erklärt werden können und wo weitere Übungen oder eine erneute grundlegende Erklärung erforderlich sind.\nNicht zuletzt spielt die Berücksichtigung der persönlichen Bezugssysteme der Lernenden eine zentrale Rolle. Lernende können nur dann effektiv lernen, wenn neue Informationen in ein für sie verständliches und handhabbares System eingebunden werden. Durch die Aktivierung und den Aufbau eines solchen Bezugssystems werden abstrakte Inhalte greifbar, Zusammenhänge sichtbar und das eigenständige Arbeiten gefördert.\nDie Wirkung des Tutors auf die Lernenden ist entscheidend für den Erfolg der Nachhilfestunde. Ein Tutor hat die Aufgabe, eine positive, unterstützende Lernatmosphäre zu schaffen, die es den Lernenden ermöglicht, sich mit dem Stoff auseinanderzusetzen und gleichzeitig Vertrauen in ihre eigenen Fähigkeiten zu entwickeln. Die zwischenmenschliche Beziehung zwischen Tutor und Lernendem spielt dabei eine ebenso wichtige Rolle wie die fachliche Expertise. Empathie, Verständnis und die Fähigkeit, auf die individuellen Bedürfnisse des Lernenden einzugehen, sind ebenso entscheidend wie das Fachwissen.\nDiese wechselseitige Beziehung bildet in meiner Nachhilfepraxis eine wichtige Arbeitsbedingung. Ich verstehe meine Rolle nicht allein als Wissensvermittler, sondern als Lernbegleiter, der eigenständige Lösungsversuche aufgreift und durch Erklärungen, Rückfragen und gemeinsame Überprüfung weiterführt. In schriftlichen Rückmeldungen und Rezensionen werden insbesondere eine verlässliche Unterrichtsstruktur, individuelle Vorbereitung, wiederholte Erklärungen und eine unterstützende Lernbeziehung hervorgehoben (vgl. die qualitative Materialauswertung in Abschnitt 1.5, Tabelle 1.2). Diese Fremdeinschätzungen ergänzen meine Eigenbeobachtungen, ersetzen aber weder eine systematische Vergleichsstudie noch einen gesonderten Wirksamkeitsnachweis des FRZK.\n\n1.4 Didaktische Differenzierung und Lernende\n\n\n1.4.1 Die Didaktische Differenzierung zwischen Nachhilfe und regulärem Unterricht\nDie Unterschiede zwischen meinem Nachhilfeangebot und dem schulischen Unterricht liegen aus meiner Sicht vor allem in den Rahmenbedingungen und in der Schwerpunktsetzung. Der Schulunterricht verfolgt gemeinsame curriculare Ziele und muss die Lernprozesse einer ganzen Klasse organisieren. Die Nachhilfe kann demgegenüber unter den Bedingungen kleiner Lerngruppen gezielter an individuellen Wissenslücken, Verständnisproblemen und Interessen ansetzen. Sie bietet mir die Möglichkeit, einen Unterrichtsgegenstand so lange aus verschiedenen Blickwinkeln zu bearbeiten, bis der Lernende seine wesentlichen Begriffe und Beziehungen nachvollziehbar erklären kann. Dies ist eine Beschreibung meines praktischen Vorgehens, keine Aussage, dass entsprechende Förderung im Schulunterricht grundsätzlich fehlt.\nIn meiner dreijährigen Praxis hat sich für die Nachhilfe ein Schwerpunkt auf stoffliche Vertiefung, allgemeine Verständniskontrolle und eigenständige Anwendung herausgebildet. Bei der Kontrolle beschränke ich mich nicht auf richtig oder falsch gelöste Aufgaben: Ich frage nach dem Warum eines Verfahrens, überprüfe die Verfügbarkeit vorausgesetzter Grundkenntnisse und lasse ähnliche Zusammenhänge in neuen Darstellungen oder Kontexten erläutern. Aus den erkennbaren Schwierigkeiten leite ich die Auswahl und den Schwierigkeitsgrad der nächsten individuell angepassten Arbeitsblätter ab. Diese wiederkehrende Arbeitsweise ist eine qualitative empirische Eigenbeobachtung aus meiner Nachhilfepraxis; ein vergleichender Nachweis höherer Lernwirksamkeit gegenüber dem Schulunterricht ist damit nicht erbracht. Die direkte Prüfung sämtlicher Rechenergebnisse und die fachliche Überprüfung des Verständnisses behandle ich dabei als unterschiedliche Aufgaben; mit zunehmendem Lernstand kann ein größerer Teil der Ergebniskontrolle von den Lernenden übernommen werden.\n\n1.4.2 Die Bedeutung der Bezugssysteme und der persönlichen Relevanz\nEin zentrales Thema meiner Nachhilfe ist das jeweilige Vorwissen der Lernenden, das ich in diesem Zusammenhang als persönliches didaktisches Bezugssystem bezeichne. Ich versuche, mathematische Themen mit bereits vertrauten Vorstellungen und geeigneten Beispielen zu verknüpfen und zugleich die fachlichen Grundlagen hinter einem Verfahren zu verdeutlichen. Die in Abschnitt 1.1 beschriebenen Unterrichtsbeobachtungen zeigen Schwierigkeiten beim Erfassen von Aufgabenangaben beziehungsweise beim Erklären einer linearen Funktion. Aus diesen Einzelfällen lässt sich jedoch nicht sicher schließen, dass fehlender Lebensweltbezug die Ursache war.\nFür meine Unterrichtsgestaltung ergibt sich daraus die Frage, ob Lernende die bearbeiteten Beziehungen auch unabhängig von der ursprünglichen Beispielaufgabe verstehen. Deshalb schließe ich an eine Erklärung gezielte Verständnisfragen, Varianten und Transferaufgaben an. Wenn eine Aufgabe richtig gerechnet, aber der zugehörige Zusammenhang nicht eigenständig erläutert werden kann, bildet dies in meiner Praxis einen Anlass für weitere Vertiefung. Ob die so gestaltete Nachhilfe zu nachhaltigeren Lernergebnissen führt, ist gesondert zu prüfen.\n\n1.4.3 Die Lernenden\nIn meiner bisherigen Nachhilfepraxis begleite ich häufig Lernende, deren schulische Leistungen sehr unterschiedlich sind und die zum Teil erhebliche fachliche Schwierigkeiten mitbringen. Beobachtete Notenverteilungen aus meinen Gruppen sind bislang nicht nach einem einheitlichen Erhebungsverfahren dokumentiert worden. Deshalb verwende ich an dieser Stelle keine Prozentanteile als vermeintlich statistisch gesicherte Stichprobenbeschreibung. Die Ausgangsleistungen werden erst für die geplante Untersuchung nach festgelegten Kriterien erfasst. Eine konkrete anonymisierte Übersicht unterschiedlicher Klassenstufen und Schulformen innerhalb der Kursgruppen ist in Abschnitt 1.5 (Tabelle 1.1) dokumentiert; sie dient der Beschreibung der Lernumgebung, nicht als Nachweis von Lernerfolgen.\nFür die Unterrichtsgestaltung bedeutet dies, dass unterschiedliche Vorkenntnisse und Schwierigkeiten im Unterricht zu berücksichtigen sind. Standardisierte Erklärungen können hilfreich sein, müssen jedoch nicht für alle Lernenden ausreichen. Das Prinzip eines zunächst bewusst reduzierten Bezugssystems soll es ermöglichen, aufgabenrelevante Informationen schrittweise zu ordnen. Es setzt nicht voraus, dass die Lernenden tatsächlich ohne Vorwissen lernen können; vielmehr muss ich den Zusammenhang zu bereits vorhandenen Kenntnissen im Lernprozess untersuchen.\nDas Bezugssystem der Lernenden ist nicht mit einem mathematischen Koordinatensystem gleichzusetzen. Ich verwende den Ausdruck an dieser Stelle als didaktische Metapher für die jeweils verfügbaren Vorstellungen, Erfahrungen und Kenntnisse, mit denen Lernende Angaben einer Aufgabe einordnen. Ob die schrittweise explizite Darstellung funktionaler Beziehungen das eigene Verständnis und den Transfer unterstützt, bleibt Gegenstand der Untersuchung.\nBei der Bearbeitung einzelner Aufgaben nutze ich ein zunächst leeres Darstellungsblatt als methodisches Hilfsmittel, um aufgabenrelevante Angaben, Begriffe und Beziehungen schrittweise festzuhalten. Dieses aufgabenbezogene Vorgehen ist von der Concept-Map beziehungsweise dem Kompendium zu unterscheiden, die zu Beginn eines Themengebiets einen übergreifenden Überblick bereitstellen. Ich verbinde die Aufgabenbearbeitung in der Nachhilfe mit Fragen, Rückmeldungen und einer möglichst unterstützenden Lernatmosphäre. Ein nachweisbarer Lernvorteil folgt aus dieser Beschreibung noch nicht.\nMeine Erfahrungen als Nachhilfelehrer sowie meine Tätigkeiten als Verfahrenstechniker, IT-Projektleiter und Dozent helfen mir bei der Strukturierung von Aufgabenstellungen und bei der Gestaltung individueller Lernangebote. Das leere Bezugssystem setze ich in meiner Praxis als methodische Unterstützung ein. Ob diese Unterstützung zu nachweisbaren Verbesserungen beim Aufgabenverständnis, bei der eigenständigen Bearbeitung oder beim Transfer führt, muss ich anhand dokumentierter Lernverläufe und geeigneter Vergleichsmaßstäbe untersuchen.\nFür meine Unterrichtspraxis bildet dieses Vorgehen einen erprobungsbedürftigen Ausgangspunkt zur individuellen Anpassung von Aufgaben und Hilfen. Darin sehe ich einen möglichen Untersuchungsgegenstand des FRZK, nicht bereits ein gegenüber regulärem Unterricht überlegenes Verfahren.\n\n1.5 Die Lernumgebung und Unterrichtsführung\nMeine Nachhilfe findet in Unterrichtsräumen der Schülerhilfe statt. Der hier beschriebene Raum verfügt über acht Plätze an einem quadratischen Tisch sowie über eine Tafel. Ich sitze gewöhnlich an einer Ecke des Tisches; auch einige Lernende bevorzugen bestimmte Plätze, die Platzwahl bleibt jedoch frei. Bei Bedarf ändere ich die Sitzordnung, beispielsweise um Gruppenarbeit zu ermöglichen, konzentriertes Arbeiten zu erleichtern oder den Zugang zum Laptop sicherzustellen.\nIch möchte den Unterrichtsraum so gestalten, dass die Lernenden einen persönlichen Bezug zu ihm entwickeln und sich dort wohlfühlen. Obwohl acht Plätze vorhanden sind, betreue ich in meinen Lerngruppen höchstens sechs Lernende gleichzeitig. Zwei Lerngruppen haben eigene Plakate mit den Aussagen „Mathe macht stark“ und „Ma(ke)the Best“ angebracht. Diese Texte entstanden ohne meine Vorgabe; ich verstehe sie als Hinweise auf die Haltung der betreffenden Lernenden, nicht als systematisch erhobene Ergebnisse.\nKursbelegung als dokumentierter Hinweis auf heterogene Lerngruppen.\nEin konkreter Einblick in die Zusammensetzung meiner Lerngruppen ergibt sich aus der ICAS-Kursbelegungsansicht für die Woche vom 9. bis 15. November 2026. Der bereitgestellte Ausschnitt enthält fünf Unterrichtsgruppen mit jeweils fünf oder sechs eingetragenen Lernenden, insgesamt 27 Kursbelegungen. Zwei Lernende sind in jeweils zwei Gruppen eingetragen; damit lassen sich im Ausschnitt 25 unterschiedliche Lernende anhand der Einträge unterscheiden. Die erfassten Klassenstufen reichen von 5 bis 12. Schon innerhalb einzelner Kurse treten Unterschiede von mehreren Klassenstufen sowie verschiedene Schulformkennzeichnungen auf. In einer Gruppe werden Aufgaben aus Mathematik und Physik parallel bearbeitet. Die nachfolgende Übersicht gibt nur anonymisierte Strukturmerkmale wieder.\nTabelle 1.1: Anonymisierte Kursbelegungen in fünf sichtbaren Lerngruppen. Quelle: ICAS-Kursübersicht, Woche 09.11.–15.11.2026, vom Autor bereitgestellter Bildschirmausschnitt; eigene Zählung. Die Schulformkürzel sind unverändert aus der Ansicht übernommen.\nDie Übersicht dokumentiert die aktuelle organisatorische Heterogenität: Beispielsweise umfasst Gruppe D die Klassenstufen 7, 9, 10 und 12. Die gleichzeitige Betreuung unterschiedlicher Jahrgangsstufen und teils unterschiedlicher Fächer verlangt voneinander abweichende Aufgaben, Rückfragen und Erklärungen. Dies ist ein wesentlicher Grund für den Einsatz persönlich angepasster Arbeitsblätter und für die in diesem Abschnitt beschriebene alters- und lernstandsabhängige Selbstkontrolle. Bei einer vollständigen Kontrolle aller Aufgaben durch den Tutor würde die für individuelle Hilfe verfügbare Zeit entsprechend eingeschränkt.\nDie Kursübersicht ist ein Beleg für eingetragene Belegungen einer einzelnen, zum Zeitpunkt des Screenshots noch bevorstehenden Kalenderwoche. Sie erlaubt keine Feststellung über tatsächliche Anwesenheit, regelmäßige Belegungsmuster über drei Jahre, individuelle Lernfortschritte oder die Wirksamkeit des FRZK. Für eine empirische Auswertung der Unterrichtspraxis müssen Belegung, Anwesenheit, Lernstand und Leistungsentwicklung getrennt dokumentiert werden. Der ursprüngliche Bildschirmausschnitt enthält personenbezogene Angaben minderjähriger Lernender und wird deshalb nicht unverändert in die Dissertation übernommen.\nDie 90-minütigen Lerneinheiten orientieren sich an vier aufeinanderfolgenden Phasen. Individuelle Fragen und Hilfestellungen erfolgen während der Arbeitsphase:\nBlitzlicht – 5 Minuten: Die Lernenden berichten kurz über Erlebnisse und benennen ihre aktuelle Stimmung.\nArbeitsphase – 75 Minuten: Themenbezogene Vertiefung mit persönlich angepassten Arbeitsblättern, Bearbeitung fachlicher Defizite, Ergebnisselbstkontrolle und fortlaufende allgemeine Verständniskontrolle, bei Bedarf mit Übertragungsaufgaben.\nNachhilfehefter – 5 Minuten: Die Lernenden ordnen die erarbeiteten Unterlagen in ihre nach einem einheitlichen Ablagesystem geführten Fachhefter ein.\nAbschlussreflexion – 5 Minuten: Die Lernenden berichten über ihre Arbeit und darüber, was sie verstanden haben; ich gebe dazu eine individuelle Rückmeldung.\nZu Beginn eines neuen Themengebiets erhalten die Lernenden von mir eine Concept-Map oder ein Kompendium. Dieses Material gibt einen fachlichen Überblick und macht wichtige Begriffe sowie Beziehungen sichtbar. Der anschließende Unterricht erfolgt themenbezogen und defizitorientiert mit persönlich angepassten Arbeitsblättern. Dabei vertiefe ich den Stoff, überprüfe fortlaufend, ob die Lernenden die fachlichen Zusammenhänge auch ohne unmittelbare Vorlage erklären können, und greife erkannte Lücken im Vorwissen auf. Zu den Verständnisprüfungen gehören Begründungsfragen, eigene Formulierungen, die Analyse von Fehlern und die Anwendung auf veränderte Aufgaben. Concept-Map oder Kompendium bleiben bei Bedarf als Nachschlage- und Orientierungsunterlagen verfügbar; sie ersetzen die individuelle Arbeitsblattarbeit nicht.\nDiese Abfolge aus thematischer Einführung, vertiefender Arbeitsblattarbeit und allgemeiner Verständniskontrolle habe ich über drei Jahre in meiner Nachhilfepraxis wiederholt angewandt und beobachtet. Nach meiner Praxiseinschätzung macht die zusätzliche Kontrolle über das bloße Rechenergebnis hinaus unterschiedliche Wissensstände und Verständnislücken sichtbar und ermöglicht mir, nachfolgende Aufgaben gezielter auszuwählen. Diese qualitative empirische Eigenbeobachtung wird durch Rückmeldungen von Lernenden und beobachtete schulische Leistungsentwicklungen ergänzt, die im Folgenden als eigene, unterschiedliche Beobachtungsarten ausgewiesen werden.\nRückmeldungen von Lernenden. Ergänzend zu meinen Unterrichtsbeobachtungen habe ich informelle Gespräche mit Schülerinnen und Schülern der 11. Gymnasialklasse geführt, die nach meiner Angabe bereits mindestens ein Jahr meine Nachhilfe besucht hatten. Die Lernenden beschrieben den wahrgenommenen Nutzen der Nachhilfe sinngemäß als deutlich bessere schulische Ausgangslage gegenüber einer Situation ohne diese Unterstützung. Für diese Gesprächsangabe liegen im hier ausgewerteten Material weder ein standardisierter Fragebogen noch vollständige Originalprotokolle oder eine gesicherte Anzahl befragter Personen vor (vgl. Nachweisstatus NB-16, Anlage 1B). Daher verwende ich sie ausschließlich als qualitative Selbsteinschätzung nach eigener Gesprächswiedergabe, nicht als systematisch ausgewertete Befragung oder Kausalbeleg.\nBerichtete Notenentwicklung. In den bereitgestellten Unterlagen finden sich Elternmitteilungen und abgeschriebene Online-Rezensionen, die Verbesserungen in Mathematik beschreiben. Eine Elternmitteilung berichtet über den Wechsel einer Zeugnisnote von 4 auf 3 (NB-07), eine übermittelte Online-Rezension über eine Verbesserung um zwei Notenstufen (NB-09). Weitere Rückmeldungen berichten allgemeiner über verbesserte Noten (NB-10, NB-11); ein Bericht über mehrere Lehrkräfte ist nicht eindeutig meiner Unterrichtstätigkeit zuzuordnen (NB-13). Originalzeugnisse, Vergleichszeitpunkte und vollständige schulische Verlaufsdaten liegen zu diesen Angaben im Prüfkorpus nicht vor. Die Angaben belegen somit elterlich berichtete Leistungsentwicklungen, keine unabhängig verifizierten Notenverläufe und erst recht keine kausal nachgewiesene FRZK-Wirkung.\nQualitative Fremdrückmeldungen zur Unterrichtsgestaltung\nFür die vorläufige explorative Sichtung habe ich eine vom Autor zusammengestellte Materialsammlung ausgewertet (private schriftliche Lernendenrückmeldungen, vom Autor redigierte Gesprächswiedergaben, Elternmitteilungen sowie übertragene Texte öffentlicher Rezensionen). Als Nachweisregister führe ich die einzelnen Fundstellen unter den Kennungen NB-01 bis NB-16 in Anlage 1B. Jede Kennung ist als Quelle, Textart, Aussagegehalt und Prüfstatus erläutert. Die Materialien wurden weder mit einem einheitlichen Fragenkatalog erhoben noch als vollständige Übersicht aller positiven und negativen Erfahrungen zusammengestellt. Deshalb handelt es sich um eine selektive qualitative Materialauswertung, nicht um eine repräsentative Befragung. Es werden keine Namen, Telefonnummern oder identifizierenden Details aus den Originalnachrichten in die Anlage übernommen.\nMehrere Rückmeldungen heben individuell vorbereitete Arbeitsblätter (NB-03, NB-14), eine feste Unterrichtsstruktur mit Blitzlicht und Reflexion (NB-03, NB-14) sowie wiederholte Erklärungen und gemeinsame fachliche Klärungen (NB-03, NB-14) hervor. Die Rückmeldung zur Einbeziehung eigener Lösungswege (NB-04) liegt als unmittelbar von einem Lernenden verfasste Ergänzung vor. Die fünfteilige Beschreibung zu NB-03 wurde hingegen vom Autor redigiert und dem Lernenden zur Verwendung vorgelegt; sie ist daher keine wortgetreue Verschriftlichung einer Schüleräußerung. Eine weitergehende Fassung wurde später vorgeschlagen, aber im vorliegenden Material nicht ausdrücklich bestätigt (NB-05) und deshalb nicht als Schülerrückmeldung ausgewertet.\nTabelle 1.2 ordnet die identifizierten Unterrichtsmerkmale den konkreten Fundstellen aus Anlage 1B zu. Mehrfachnennungen und mögliche Identitätsüberschneidungen werden nicht als statistisch unabhängige Antworten gewertet. Die Einträge zeigen, welche Merkmale in den vorliegenden Fremdrückmeldungen beschrieben werden, nicht wie häufig sie in der Grundgesamtheit vorkommen oder ob sie in jeder Stunde nachweislich umgesetzt wurden.\nTabelle 1.2: Qualitativ identifizierte Merkmale der Unterrichtsführung. Quelle: Materialsammlung „meine Bewertungen.txt“, eigene vorläufige Kategorisierung. Die Belegkennungen NB-xx verweisen auf das pseudonymisierungsarme Nachweisregister in Anlage 1B. Originalplattformen, berichtete Noten und Urheberschaften übertragener Rezensionstexte wurden nicht unabhängig überprüft.\nMethodische Grenzen der Rückmeldungen. Die Sammlung ist positiv selektiert und enthält auch bloße Entwürfe, vom Autor redigierte Gesprächszusammenfassungen und Verwaltungsnotizen. NB-05, NB-06, NB-08 und NB-15 werden nicht als bestätigte Lernendenbewertungen in die Befundbildung aufgenommen. Für NB-02 und NB-03 ist eine schriftliche Zustimmung der betreffenden Lernenden zur anonymisierten Verwendung der jeweils vorgelegten Formulierungen dokumentiert; diese Zustimmung ersetzt nicht automatisch weitere erforderliche datenschutz- oder sorgeberechtigtenbezogene Prüfungen. Die Einzeläußerung NB-04 ist ein direkter Zusatz desselben Lernenden wie NB-03 und kein zweiter unabhängiger Fall. Mögliche Überschneidungen zwischen persönlichen Mitteilungen und Plattformrezensionen sind nicht auflösbar; daher wird weder eine Zahl unabhängiger Personen noch eine Zufriedenheitsquote ausgewiesen. Kritik, Nichtteilnahme und ausbleibende Rückmeldungen wurden nicht systematisch erfasst.\nAbgrenzung zum FRZK. Das anonymisierte Register dokumentiert Aussagen über meine bereits bestehende Nachhilfepraxis: Vorbereitung, angepasste Aufgaben, Lernbeziehung, Reflexion, individuelle Erklärungen und wahrgenommene Lernentwicklungen. Die beschriebenen Leistungen dürfen nicht als Wirkung des erst gesondert zu untersuchenden FRZK-Darstellungsrahmens gewertet werden. Weder der anfängliche Einsatz einer Concept-Map beziehungsweise eines Kompendiums noch die ungefähren prozentualen Kontrollmodelle sind durch die vorliegenden Fremdrückmeldungen als solche ausdrücklich belegt. Sie bleiben zunächst Aussagen über meine eigene Unterrichtsorganisation.\nErgebniskontrolle, Selbstkontrolle und Betreuungszeit\nDie beiden folgenden Orientierungsmodelle zur Unterrichtsorganisation beruhen auf wiederholten qualitativen Eigenbeobachtungen aus drei Jahren Nachhilfepraxis. Sie wurden weder durch standardisierte Zeitmessungen noch durch eine systematische Zählung aller Arbeitsergebnisse gewonnen und sind deshalb keine statistisch abgesicherten Verteilungen oder nachgewiesenen optimalen Unterrichtsquoten. Das erste Modell beschreibt, wer Arbeitsergebnisse kontrolliert; das zweite Modell betrifft die inhaltliche Gewichtung von Übungsrechnen und Problembearbeitung. Beide Modelle dürfen nicht miteinander gleichgesetzt werden. Unter Ergebniskontrolle verstehe ich die Prüfung bearbeiteter Aufgaben und Resultate. Davon unterscheide ich die allgemeine Verständniskontrolle anhand von Rückfragen zu Begriffen, Begründungen und Übertragungen, die unabhängig von der Klassenstufe Bestandteil meiner Betreuung bleibt.\nFür den ungefähren Anteil der durch mich unmittelbar kontrollierten Arbeitsergebnisse haben sich die in Tabelle 1.3 dargestellten, lernstandsabhängig anpassbaren Richtwerte herausgebildet:\nTabelle 1.3: Erfahrungsbasierte Aufteilung der Ergebniskontrolle nach Lernstufen. Eigene qualitative Praxisbeobachtungen aus drei Jahren Nachhilfe; keine standardisierte Messung.\nDie Lösungen in den Arbeitsblättern ermöglichen den Lernenden einen eigenständigen Abgleich ihrer Ergebnisse und, soweit vorhanden, ihrer Rechenwege. Erkannte Abweichungen führen zu erneuter Bearbeitung oder zu gezielten Rückfragen. Meine unmittelbare Kontrolle konzentriert sich bei älteren Lernenden stärker auf ausgewählte Aufgaben, erkennbare Fehlerschwerpunkte und die Überprüfung des fachlichen Verständnisses. Die Zuordnung in Tabelle 1.3 stellt keine starre Altersnorm dar: Lernstand, Aufgabenschwierigkeit und Bedarf an Unterstützung können eine andere Verteilung erfordern.\nDie Verlagerung geeigneter Ergebniskontrollen in die Eigenverantwortung hat auch organisatorische Gründe. Während einer 75-minütigen Arbeitsphase betreue ich zeitweise bis zu sechs Lernende unterschiedlicher Klassen- und Studienjahre. Würde ich für die vollständige Kontrolle der Aufgaben jedes Lernenden jeweils zehn Minuten ansetzen, ergäben sich rechnerisch 6 × 10 = 60 Minuten. Von der Arbeitsphase blieben dann nur 15 Minuten für individuelle Erklärungen, die Bearbeitung anderer Schwierigkeiten und allgemeine Verständniskontrollen. Wechsel- und Unterbrechungszeiten sind dabei noch nicht berücksichtigt. Diese Modellrechnung veranschaulicht einen möglichen Zeitkonflikt; sie ist keine standardisierte Zeitmessung.\nAus meiner Unterrichtserfahrung wäre eine durchgängige vollständige Ergebniskontrolle sämtlicher Aufgaben durch mich bei sechs gleichzeitig betreuten Lernenden pädagogisch nicht angemessen: Die Zeit für die individuelle Betreuung der anderen Lernenden würde zu stark eingeschränkt. Die angeleitete Selbstkontrolle erhält daher eine doppelte Funktion: Sie unterstützt das eigenständige Arbeiten und schafft Betreuungszeit für fachliche Rückfragen und gezielte Vertiefung. Daraus folgt noch kein Nachweis einer höheren Lernwirksamkeit.\nIn der geplanten systematischen Untersuchung sollen die tatsächlich vom Tutor überprüften Arbeitsergebnisse, die selbst kontrollierten Lösungen, dabei unerkannte Fehler sowie zusätzliche Hilfestellungen gesondert dokumentiert werden. Auf diese Weise lassen sich die bisherigen Richtwerte später anhand nachvollziehbarer Beobachtungen prüfen.\nGewichtung von Übungsrechnen und Problembearbeitung\nTabelle 1.4: Erfahrungsbasierte inhaltliche Schwerpunktsetzung in der Arbeitsphase. Die Anteile beschreiben eine ungefähre Planungspraxis, keine gemessenen Zeiten und keine allgemeinen Empfehlungen.\nDie zweite Einteilung beschreibt die von mir bevorzugte Gewichtung fachlicher Arbeitsschwerpunkte, nicht die Zeit für persönliche Ergebniskontrolle. Sie wird an individuelle Lernstände, Themen und Aufgaben angepasst; insbesondere kann notwendiges Übungsrechnen auch in höheren Klassen einen größeren Umfang erhalten. Die Angaben in den Tabellen 1.3 und 1.4 sind daher als erfahrungsbasierte, noch zu überprüfende Orientierung zu verstehen. Aus ihnen lässt sich weder eine allgemeingültige optimale Verteilung noch ein kausaler Einfluss auf schulische Leistungen oder auf die Wirksamkeit des FRZK ableiten.\n\n1.6 Forschungsstand und wissenschaftlicher Kontext\n\n\n1.6.1 Physikalische Perspektiven: Emergenz von Raumzeit\nEinige Ansätze der theoretischen Physik untersuchen, ob bestimmte Raumzeit- oder Gravitationseigenschaften aus tieferliegenden Strukturen hervorgehen können (Rovelli, Carlo (2016). Reality Is Not What It Seems: The Journey to Quantum Gravity. London: Penguin.)[13] (Verlinde, Erik P. (2017). Emergent Gravity and the Dark Universe. SciPost Physics, 2(3), Artikel 016. DOI: 10.21468/SciPostPhys.2.3.016.)[14]. Diese Ansätze sind nicht allgemein bestätigte Aussagen über die Entstehung der Raumzeit und stellen keinen physikalischen Gültigkeitsbeleg für das FRZK dar. Für meine Arbeit dienen sie ausschließlich als Beispiel dafür, warum die Unterscheidung von Grundannahmen und abgeleiteten Modellgrößen wichtig ist.\n\n1.6.2 Systemtheoretische und kybernetische Ansätze\nSystemtheoretische und kybernetische Arbeiten untersuchen unter anderem Rückbezüge, Beobachtungsbedingungen und die Abhängigkeit von Beschreibungen [2][3]. Für mein Vorhaben ist dies ein möglicher begrifflicher Vergleichsrahmen. Ich setze jedoch weder eine rekursive Selbstbezüglichkeit noch eine besondere Beobachterstruktur als notwendige Eigenschaft sämtlicher im FRZK dargestellter Funktionen voraus.\n\n1.6.3 Didaktische und bildungswissenschaftliche Modelle\nIn der didaktischen und bildungswissenschaftlichen Forschung bestehen bereits mehrere Ansätze, die einzelne Aspekte meines Vorhabens berühren. Die Abgrenzung des FRZK muss deshalb bei konkreten Funktionen und prüfbaren Unterschieden ansetzen, nicht bei der bloßen Verwendung der Wörter „Struktur“, „Beziehung“ oder „Bezugssystem“. Für meine Untersuchung sind die Repräsentation fachlichen Wissens, das Bearbeiten mathematischer Probleme, die lernprozessbezogene Rückmeldung und das selbstregulierte Lernen von besonderer Bedeutung.\nConcept-Maps werden in der Literatur als grafische Werkzeuge zur Organisation und Darstellung von Wissen beschrieben. Novak und Cañas erläutern, dass Begriffe durch beschriftete Beziehungen zu sinnvollen Aussagen verknüpft werden können (Novak; Cañas, 2008, S. 1) [16]. In meiner Nachhilfepraxis dienen Concept-Maps oder Kompendien zu Beginn eines Themas der fachlichen Orientierung. Die anschließende Bearbeitung erfolgt überwiegend mit individuell angepassten Arbeitsblättern. Daraus folgt weder, dass diese Einführung bereits das FRZK darstellt, noch dass eine grafische Übersicht als solche eine methodische Neuerung ist.\nDer Umgang mit mehreren Darstellungsformen ist ebenfalls wissenschaftlich untersucht. Ainsworth differenziert in ihrem DeFT-Rahmen zwischen der Gestaltung multipler Repräsentationen, ihren Funktionen und den kognitiven Anforderungen an die Lernenden. Ihr Beitrag zeigt zugleich, dass mehrere Darstellungen allein keinen Lernerfolg garantieren (Ainsworth, 2006, S. 183–198, insbesondere S. 183) [17]. Bei mathematischen Aufgaben unterscheide ich daher sprachliche Aufgabenbeschreibung, Gleichung, grafische Veranschaulichung und Bedeutung der Variablen. Ob der zusätzliche FRZK-Rahmen diese Übergänge erleichtert, ist eine offene Frage; der bloße Wechsel von Darstellungen ist keine FRZK-spezifische Leistung.\nFür das mathematische Problemlösen beschreibt Schoenfeld einen Analyseansatz, der kognitive Ressourcen, heuristische Strategien, Kontrolle des Lösungsprozesses und Überzeugungen unterscheidet (Schoenfeld, 1985) [18]. Die bibliografischen Angaben und diese thematische Gliederung sind durch den Verlag nachweisbar; eine auf einzelne Buchseiten bezogene Originalstellenprüfung steht noch aus. Meine Unterrichtsbeobachtungen zu Textaufgaben und linearen Funktionen lassen sich damit vorläufig in einen etablierten Forschungszusammenhang einordnen. Weder das Erkennen relevanter Angaben noch das Reflektieren eines Lösungswegs kann daher ohne weitere Abgrenzung als neu ausgewiesen werden.\nZur Rückmeldung und Verständniskontrolle unterscheiden Hattie und Timperley unter anderem Feedback zur Aufgabe, zum Bearbeitungsprozess und zur Selbstregulation (Hattie; Timperley, 2007, S. 86 und 90) [19]. Damit ist fachlich zu trennen, ob ich eine korrekte Endlösung kontrolliere, einen Lösungsweg bespreche oder die selbstständige Fehlerprüfung eines Lernenden fördere. Für meine altersabhängige Verlagerung der Ergebniskontrolle auf die Lernenden ist ergänzend die Forschung zur Selbstregulation einschlägig: Zimmerman beschreibt unter anderem Zielsetzung, Selbstbeobachtung, Selbstbewertung und Reflexion (Zimmerman, 2002, S. 64 und 68) [20]. Die in Abschnitt 1.5 genannten Prozentwerte bleiben gleichwohl empirische Richtwerte meiner Praxis und werden nicht durch diese Literatur als optimale Stufenmodelle bestätigt.\nDie Einzelförderung und die Unterschiede zur Gruppenunterrichtung werden unter anderem bei Bloom (1984) [21] thematisiert. Der historische Beitrag zu individuellen Tutorbedingungen ist ein Vergleichsrahmen, keine direkte Untersuchung meiner fachlich und altersmäßig heterogenen Nachhilfegruppen mit bis zu sechs Lernenden. Die Metadaten und der Untersuchungsgegenstand sind bibliografisch gesichert; der vollständige Primärtext wurde für die hier vorgelegte Stellenprüfung nicht ausgewertet. Aus Bloom leite ich deshalb weder eine bestimmte Effektstärke meiner Nachhilfe noch eine Überlegenheit gegenüber dem Schulunterricht ab.\nAls entwicklungsorientierter methodischer Bezugspunkt bleibt Design-Based Research relevant (Reinmann, 2005) [4]. Ein solcher Bezug erfordert die überprüfbare Dokumentation der Entwicklung, Erprobung, Rückmeldung und gegebenenfalls Überarbeitung des Verfahrens. Die bereits vorliegenden qualitativen Bewertungen aus Anlage 1B dokumentieren meine bestehende Unterrichtspraxis; sie ersetzen weder eine systematische Untersuchung der FRZK-Anwendung noch eine gezielte Gegenüberstellung mit bestehenden Verfahren.\n\n1.6.4 Interdisziplinäre Verortung des FRZK\nDie theoretischen Anknüpfungen betreffen unterschiedliche Ebenen: mathematische Modellierung und formale Gültigkeit, didaktische Darstellung und Unterrichtsorganisation sowie die Beobachtung von Lernprozessen. Systemtheorie und theoretische Physik dienen mir zur begrifflichen und methodischen Orientierung; die didaktische Begründung des Lernverfahrens muss hingegen auf einschlägiger Bildungs- und Mathematikdidaktik beruhen. Die gemeinsame Verwendung von Begriffen wie „Beobachtung“, „Orientierung“ oder „Kohärenz“ stellt keine Identität dieser Theorien her und belegt weder neue physikalische Gesetze noch die Wirksamkeit des FRZK.\n\n1.6.5 Abgrenzung bestehender Verfahren und vorläufige Forschungsfrage\nConcept-Maps strukturieren Begriffe und deren Beziehungen; in meiner Praxis eröffnen sie ein Thema. Multiple Repräsentationen, Problemlösestrategien sowie Feedback- und Selbstregulationsmodelle beschreiben weitere etablierte Aspekte des Lernprozesses [16][17][18][19][20]. Das FRZK beansprucht demgegenüber zunächst die Funktion eines ausdrücklich beschriebenen methodischen Vorgehens, das von der Problemformulierung über die Unterscheidung von Gegebenem und Gesuchtem, die Prüfung von Voraussetzungen und Zusammenhängen bis zur Entwicklung, Ausführung und Kontrolle einer Lösung reicht. Die mathematischen Erweiterungen des FRZK, insbesondere besondere Symbole und Operationen für Grenzwert- und Vektorprobleme, sind davon zu trennen. Ob die methodische Abfolge gegenüber bestehenden Problemlösestrategien eigenständig ist, muss kritisch verglichen und nicht bloß behauptet werden.\nEin möglicher didaktischer Zusatznutzen folgt nicht schon aus einem geordneten Arbeitsblatt, einer Concept-Map oder einer ausführlicheren Erklärung. Zu prüfen ist, ob ein zusätzlich explizit durchlaufener und dokumentierter FRZK-Problemlöseweg bei vergleichbarer Aufgabenstellung und Tutorunterstützung zu nachvollziehbareren Begründungen, früherer Fehlererkennung oder besserem Transfer führt. Die besonderen Grenzwert- und Vektorzeichen sind für diese allgemeine Intervention nicht erforderlich. Gleiche Unterrichtsbedingungen ohne den zusätzlich festgelegten Ablauf bilden die Vergleichsbasis. Positive Rückmeldungen und Notenentwicklungen aus meiner bisherigen Nachhilfe belegen noch keinen solchen Zusatznutzen.\nDie herangezogenen Arbeiten belegen, dass wesentliche Einzelbestandteile des beschriebenen Vorgehens bereits Forschungsgegenstände sind. Die vorliegende Auswahl ist jedoch keine vollständige systematische Recherche zu allen formalen Darstellungs- und Modellierungsverfahren. Dass hier kein mit dem vorgeschlagenen FRZK identisches Verfahren dargestellt wird, beweist deshalb weder seine weltweite Neuheit noch die Nichtexistenz verwandter Ansätze. Eine belastbare Neuheitsbehauptung verlangt eine gesonderte, methodisch dokumentierte Recherche und eine präzise Gegenüberstellung definierter Merkmale.\nFür die nachfolgenden Kapitel bestehen drei voneinander zu unterscheidende Prüfaufgaben: Erstens ist das methodische Grundgerüst des FRZK nachvollziehbar zu beschreiben und gegenüber vorhandenen Verfahren abzugrenzen. Zweitens müssen seine gesonderten mathematischen Erweiterungen auf definierte Bereiche, formale Konsistenz und mögliche Gegenbeispiele geprüft werden. Drittens ist ein möglicher didaktischer Zusatznutzen empirisch zu untersuchen. Die Prüfung einer Ebene ersetzt nicht die Prüfung einer anderen.\n\n1.7 Forschungsziel\nIch unterscheide die Entwicklung des FRZK als methodischen Ansatz zur Problemstellung und Problemlösung von seinen zusätzlichen mathematischen Symbol- und Operationssystemen. Davon gesondert ist zu prüfen, ob das methodische Vorgehen im Unterricht Vorteile gegenüber der bestehenden Praxis bietet. Aus dieser Trennung ergeben sich methodische, formale und didaktische Forschungsfragen mit unterschiedlichen Geltungsbereichen.\nMit dem Funktionalen Raum-Zeit-Kohärenzsystem (FRZK) möchte ich Aufgaben so bearbeiten, dass aus einer zunächst zu klärenden Problemstellung ein begründeter, überprüfbarer Lösungsweg entsteht. Die methodische Abfolge umfasst Problemformulierung, Bestimmung der Angaben und Zielgrößen, Klärung der Voraussetzungen und Beziehungen, Entwicklung und Durchführung der Lösung sowie Ergebnisprüfung. Eine grafische oder formale Darstellung kann diesen Ablauf stützen, ist jedoch nicht selbst mit ihm gleichzusetzen. Der Ansatz beansprucht damit weder die Erzeugung physikalischer Raumzeit noch eine besondere mathematische Symbolik als universelle Voraussetzung.\nDie erste Forschungsfrage lautet, wie sich dieser problemorientierte Ablauf so präzisieren lässt, dass er in verschiedenen mathematischen und gegebenenfalls weiteren fachlichen Situationen nachvollziehbar angewendet werden kann. Für konkrete Aufgaben sind die erforderlichen Größen, Annahmen, funktionalen Beziehungen und Gültigkeitsbedingungen jeweils ausdrücklich anzugeben. Besondere Fälle wie Rekursion, Rückbezug oder Kohärenzprüfung und die Verwendung spezieller Grenzwert- oder Vektorzeichen verlangen gesonderte Definitionen; sie gehören nicht notwendig zum allgemeinen methodischen Ablauf.\nEin zweiter Forschungsgegenstand betrifft die formale Prüfung eigens eingeführter mathematischer FRZK-Erweiterungen. Zu klären ist, für welche definierten Mengen, Zustände und Operatoren die jeweiligen Rechenregeln widerspruchsfrei und reproduzierbar angewendet werden können. Diese Frage ist von der Verständlichkeit des methodischen Problemlösewegs ebenso zu trennen wie vom empirischen Nachweis einer didaktischen Wirkung.\nDie didaktische Forschungsfrage lautet, ob und unter welchen Bedingungen die systematische Anwendung des beschriebenen Problemlösewegs das Aufgabenverständnis, die Auswahl und Begründung eines Verfahrens, die Fehlererkennung, die Ergebniskontrolle und die Übertragung auf neue Aufgaben unterstützt. Dabei ist die ausdrückliche Trennung zwischen Problemfrage, gegebenen Informationen, gesuchten Größen, Voraussetzungen und funktionalen Beziehungen ein möglicher, aber nicht der einzige Wirkmechanismus.\nErgänzend frage ich, wie die Nachvollziehbarkeit solcher Darstellungen beurteilt werden kann: Welche Merkmale machen einen Lösungsweg überprüfbar, welche Voraussetzungen müssen offengelegt werden und wie lassen sich Schwierigkeiten in der Anwendung des FRZK selbst dokumentieren? Dabei berücksichtige ich ausdrücklich auch Fälle, in denen der Ansatz keinen erkennbaren Zusatznutzen bietet.\nDiese Fragen bestimmen die Gliederung der Untersuchung. Zunächst arbeite ich die relevanten wissenschaftlichen Bezüge und die mathematischen Voraussetzungen heraus. Darauf folgen die Beschreibung des Modellierungsrahmens sowie seine fachliche und didaktische Prüfung. Ein interner Konsistenznachweis ersetzt keine empirische Untersuchung.\n\n1.7.1 Forschungsfragen und prüfbarer Zusatznutzen\nForschungsgegenstand.  Ich untersuche drei getrennte Gegenstände: erstens das FRZK als methodischen Ablauf vom Formulieren bis zum Lösen und Prüfen einer Problemstellung; zweitens die fachliche Gültigkeit gesondert definierter mathematischer Erweiterungen für Grenzwert- und Vektoraufgaben; drittens den möglichen didaktischen Zusatznutzen eines ausdrücklich angewendeten FRZK-Problemlösewegs gegenüber der bereits etablierten Nachhilfepraxis. Die positiven Schüler- und Elternrückmeldungen aus Anlage 1B charakterisieren diese Praxis; sie sind keine Interventionsdaten zur Wirksamkeit des FRZK.\nPrimäre didaktische Frage (F1).  Verbessert die zusätzliche, ausdrücklich dokumentierte Anwendung des methodischen FRZK-Problemlösewegs bei fachlich vergleichbaren Aufgaben und vergleichbarer Tutorunterstützung die Nachvollziehbarkeit einer selbstständig entwickelten Lösung gegenüber der üblichen themen- und defizitorientierten Bearbeitung? Als primärer Vergleichswert ist ein vorab fixierter Summenwert aus vier Kriterien von 0 bis 12 Punkten vorgesehen. Sonderzeichen der Grenzwert- und Vektorrechnung sind für diesen allgemeinen Vergleich nicht vorgesehen.\nSekundäre Fragen (F2–F4). F2: Erkennen Lernende fachliche Fehler oder unzulässige Annahmen früher bzw. selbstständiger? F3: Übertragen sie eine erarbeitete Beziehung auf eine neue, strukturell vergleichbare Aufgabe? F4: Welchen zusätzlichen Zeit- und Unterstützungsbedarf erzeugt die Darstellung, und in welchen Lernstufen oder Aufgabentypen erscheint sie hilfreich, entbehrlich oder hinderlich? Eine erwartete positive Wirkung ist eine Arbeitshypothese, kein bereits vorliegendes Ergebnis. Nullbefunde und Nachteile gehören zum Untersuchungsgegenstand.\n\n1.7.2 Präzise Definition der beiden Bearbeitungsbedingungen\nGemeinsame Unterrichtsbasis. Beide Bedingungen finden innerhalb der regulären, 90-minütigen Nachhilfe statt. Der Themenbeginn kann durch eine Concept-Map oder ein Kompendium vorbereitet werden; anschließend arbeite ich mit persönlich angepassten Aufgabenblättern, fachlichen Rückfragen, vertiefenden Erklärungen, einer altersabhängigen Ergebnisselbstkontrolle und einer Abschlussreflexion. Diese Bestandteile sind keine FRZK-spezifische Intervention. Die festgelegte Unterrichtsorganisation mit Blitzlicht, Arbeitsphase, Hefterführung und Auswertung bleibt unverändert.\nBedingung K (übliche Bearbeitung). Lernende bearbeiten eine fachlich passende Aufgabe mit den gewohnten Hilfen und zugelassenen Lösungsdarstellungen. Sie dürfen Angaben unterstreichen, Skizzen anfertigen, Formeln verwenden, nachfragen und Lösungen selbst kontrollieren. Es wird jedoch kein zusätzliches verpflichtendes FRZK-Protokoll vorgegeben. Bereits vorhandene Strukturierungsstrategien werden nicht künstlich unterbunden; ihr Auftreten wird im Protokoll vermerkt.\nBedingung F (zusätzlicher FRZK-Schritt).  Bei identischer fachlicher Zielsetzung bearbeiten Lernende die Aufgabe mithilfe eines einseitigen, vorab festgelegten FRZK-Problemlösebogens mit fünf Schritten: (1) die Problemfrage und das Ziel verständlich formulieren, (2) Gegebenes und Gesuchtes unterscheiden, (3) erforderliche Annahmen, Größen und Beziehungen begründet festlegen, (4) einen Lösungsweg entwickeln und ausführen und (5) Ergebnis, Gültigkeit und Übertragbarkeit prüfen, soweit fachlich sinnvoll. Die Schritte sind anhand der Schülerlösung nachvollziehbar. Spezielle FRZK-Grenzzeichen, Nullzustände oder Vektoroperationen gehören nicht zum methodischen Grundgerüst und werden in diesem allgemeinen Unterrichtsvergleich nicht verlangt.\nIsolierung des Unterschieds. Zwischen K und F darf nicht zugleich die Qualität des Arbeitsblatts, die verfügbare Arbeitszeit, die Intensität der Tutorhilfe oder der Zugang zu Lösungen verändert werden. Die FRZK-Bearbeitung erfolgt innerhalb derselben vorgesehenen Aufgabenzeit. Zusätzliche Hilfen, Zeitüberschreitungen und unvorhergesehene Abweichungen werden erfasst. Die vollständige Beschreibung von Materialien, Durchführung, Anpassungen und tatsächlicher Anwendung orientiert sich ergänzend an der TIDieR-Berichtsstruktur [22]; diese stammt aus der Interventionsforschung und wird hier nur als Dokumentationshilfe, nicht als Wirksamkeitsnachweis verwendet.\n\n1.7.3 Untersuchungsanlage, Stichprobe und Vergleichbarkeit\nExplorative Planung. Vorgesehen ist eine kleine, nicht repräsentativ gezogene Gelegenheitsstichprobe von ungefähr 25 Lernenden aus unterschiedlichen Schularten und Klassen- bzw. Studienjahren. Die sichtbaren Kursbelegungen aus Tabelle 1.1 entsprechen nicht automatisch der späteren Forschungsstichprobe. Einschlusskriterien, Einwilligungen, verfügbare Lernende, Teilnahmezeitraum, Ausgangsleistungen sowie dokumentierte Ausschlüsse werden vor Beginn der Auswertung festgelegt. Aussagen über eine repräsentative Gesamtpopulation sind nicht beabsichtigt.\nAufgabenpaare. Für vorab bestimmte Stoffgebiete werden Aufgabenpaare konstruiert, die denselben mathematischen Kompetenzbereich, ähnliche Rechenanforderungen und einen vergleichbaren sprachlichen Schwierigkeitsgrad aufweisen. Mindestens ein Aufgabenpaar umfasst das Identifizieren relevanter Angaben, ein anderes die Erklärung funktionaler Beziehungen; eine neue Transferaufgabe wird gesondert bereitgestellt. Eine fachkundige zweite Person prüft die Vergleichbarkeit der Aufgaben, bevor die eigentliche Untersuchung beginnt. Die Aufgaben einschließlich Musterlösungen werden versioniert archiviert.\nZuordnung und Reihenfolge. Wenn durchführbar, bearbeitet ein Lernender mehrere vergleichbare Aufgaben unter beiden Bedingungen; die Reihenfolge K→F bzw. F→K wird nach einem vorab dokumentierten Plan ausbalanciert. Eine zufällige Zuordnung wird nur dann berichtet, wenn sie tatsächlich durchgeführt und protokolliert wurde. Lern- und Übertragungseffekte sind besonders kritisch, weil einmal erlernte FRZK-Schritte in späteren K-Aufgaben weiterverwendet werden können. Ein solcher Übertrag ist keine Verletzung durch den Lernenden, sondern ein möglicher Störfaktor und zugleich ein zu dokumentierender Befund. Falls er die Trennung der Bedingungen verhindert, beschränke ich die Auswertung auf Machbarkeit und beschreibende Beobachtungen oder verwende ein prospektiv begründetes anderes Vergleichsdesign.\nUnterrichtsalltag als Kontext. Die Lerngruppen können bis zu sechs Personen mit unterschiedlichen Klassenstufen umfassen. Für die Untersuchungsaufgaben muss daher festgelegt werden, welche Zeitfenster, individuellen Tutorhinweise und äußeren Unterbrechungen zulässig sind. Die reguläre Förderung anderer Lernender darf durch die Datenerhebung nicht beeinträchtigt werden. Fachlich notwendige Hilfen werden aus pädagogischen Gründen nicht verweigert, sondern mit Zeitpunkt, Art und Umfang protokolliert.\n\n1.7.4 Messinstrumente und Bewertungsregeln\nPrimärer Zielwert. Der Lösungsweg wird mit einem vierdimensionalen Bewertungsraster beurteilt: A – korrekte Bestimmung gegebener und gesuchter Größen; B – Beschreibung funktionaler Beziehungen und wesentlicher Gültigkeitsbedingungen; C – fachlich begründete Wahl und Durchführung des Lösungsverfahrens; D – selbstständige Übertragung auf eine neue, strukturell ähnliche Aufgabe. Jede Dimension erhält 0 bis 3 Punkte, insgesamt 0 bis 12 Punkte. Der Transferwert D wird ausschließlich aus einer gesonderten, vorab festgelegten Transferaufgabe ermittelt, nicht aus der Wiederholung des vorgeführten Lösungswegs. Die vorläufigen Ankerbeschreibungen stehen in Anlage 1D.\nBewertungsvoraussetzungen. Vor Beginn der Hauptdatenerhebung werden die Aufgaben und die vollständigen Ankerbeispiele für die Punktstufen 0, 1, 2 und 3 fachlich erprobt, erforderlichenfalls überarbeitet und anschließend als feste Version freigegeben. Die Punktzahl 0–12 ist eine entworfene, nicht bereits validierte Bewertungsskala. Lösungen werden nach Möglichkeit ohne Angabe der Bearbeitungsbedingung pseudonymisiert durch eine zweite fachkundige Person bewertet; Abweichungen zwischen den Bewertungen werden dokumentiert. Eine Anpassung des Rasters an bereits beobachtete gewünschte Ergebnisse ist ausgeschlossen.\nWeitere Beobachtungsgrößen. Sekundär werden Bearbeitungszeit und gegebenenfalls Zeitüberschreitung, fachliche Fehlerarten, selbstständig bemerkte und korrigierte Fehler, Häufigkeit und Art von Tutorhinweisen, tatsächlich geleistete Selbstkontrolle sowie vollständig, teilweise oder nicht ausgeführte FRZK-Schritte protokolliert. Notenänderungen und die bereits vorliegenden Bewertungen der Nachhilfepraxis gehören nicht zum primären FRZK-Vergleich.\n\n1.7.5 Datenerhebung, Dokumentation und Qualitätssicherung\nSitzungsprotokoll. Zu jeder ausgewerteten Aufgabenbearbeitung sind mindestens pseudonymisierte Kennung, Klassen- oder Studienjahr, Aufgaben- und Materialversion, Stoffgebiet, Datum, Bedingung K/F, Zuordnungs- und Reihenfolgeplan, Dauer, Hilfen, Selbstkontrolle, unerwartete Ereignisse sowie die archivierte Schülerlösung zu dokumentieren. Die Datenerfassung erfolgt in meiner didaktisch-methodischen Datenbank. Deren konkrete technische Bezeichnung, Datenmodell, Zugriffsrechte und Prüfregeln werden erst im Methodenkapitel verbindlich angegeben. Ein Muster des Protokolls steht in Anlage 1D.\nDurchführungstreue.  Für F werden die fünf Schritte des methodischen FRZK-Problemlösebogens anhand der tatsächlich ausgefüllten Darstellung erfasst; für K wird festgehalten, ob vergleichbare Strukturierungen spontan verwendet wurden. Personalisierte Arbeitsblätter dürfen in beiden Bedingungen nach denselben dokumentierten Regeln angepasst werden. Abweichungen vom Unterrichtsplan, fehlende Daten und vorzeitige Bearbeitungsabbrüche werden nicht nachträglich verschwiegen. Die Intervention wird dadurch nicht mit einer besonders gut vorbereiteten Unterrichtsstunde verwechselt.\nBeobachter- und Erwartungseinfluss. Da ich zugleich Tutor, Entwickler und Untersuchender bin, bestehen Risiken durch eigene Erwartungen, unterschiedliche Hilfestellungen und mein Vorwissen über die Lernenden. Eine unabhängige Zweitbewertung der anonymisierten Aufgabenlösungen, vorab freigegebene Bewertungskriterien und ein getrenntes Protokoll aller Tutorhinweise sollen diese Risiken vermindern, aber nicht vollständig beseitigen. Die dokumentierte Untersuchung orientiert sich an der allgemeinen Forderung nach nachvollziehbarer Evidenzbewertung in der Bildungsforschung [23], ohne die Anforderungen einer randomisierten Wirksamkeitsstudie als bereits erfüllt darzustellen.\n\n1.7.6 Geplante Auswertung und Entscheidungsmaßstab\nAuswertung. Ich berichte zunächst Zahl und Merkmale der tatsächlich teilnehmenden Lernenden, Aufgabenpaare und auswertbaren Bearbeitungen sowie fehlende Werte und Abweichungen vom Plan. Für die 0–12-Punkte-Summen und die getrennten Kriterien werden Verteilungen, Median, Spannweite und – soweit sinnvoll – Streuungsmaße beschrieben. Bei zuordenbaren, hinreichend vergleichbaren Aufgabenpaaren werden individuelle Differenzen F minus K ausgewiesen und nach Schulstufe bzw. Aufgabentyp explorativ betrachtet. Die kleine und heterogene Stichprobe erlaubt ohne weitergehende Voraussetzungen keine verallgemeinernden Kausalbehauptungen.\nInterpretation. Ein positiver Unterschied gilt zunächst als Hinweis auf einen möglichen Zusatznutzen unter den dokumentierten Bedingungen. Er ist kritisch gegen Aufgabenunterschiede, Übung, Reihenfolge, Übertragung, Tutorhilfe, Vorkenntnisse und zusätzliche Bearbeitungszeit abzuwägen. Bei ungeklärter Vergleichbarkeit oder unzureichender Trennung der Bedingungen darf ich auch einen größeren Zahlenunterschied nicht als isolierten FRZK-Effekt ausgeben. Nullbefunde, Verschlechterungen, abgebrochene Bearbeitungen und Fälle ohne FRZK-Mehrwert werden gleichrangig berichtet.\nGetrennte Nachweisketten.  Die fachliche Schlüssigkeit des allgemeinen methodischen FRZK-Problemlösewegs und seine Abgrenzung gegenüber bekannten Verfahren werden unabhängig vom Unterrichtsergebnis beurteilt. Spezielle mathematische Erweiterungen erhalten jeweils eine eigene formale Prüfung. Die didaktische Untersuchung bezieht sich auf die konkret operationalisierte Problemstellungs- und Lösungsintervention. Gute Unterrichtsbewertungen, verbesserte Noten oder korrekte Modellgleichungen können keinen dieser Nachweise stellvertretend ersetzen.\n\n1.7.7 Forschungsethik, Datenschutz und Geltungsgrenzen\nFreiwilligkeit. Da minderjährige Lernende beteiligt sein können und ich zugleich ihr Tutor bin, dürfen Teilnahme oder Nichtteilnahme keinerlei Einfluss auf Nachhilfe, Bewertung oder Betreuung haben. Vor der Datenerhebung werden die erforderlichen Zustimmungen der Sorgeberechtigten und die altersangemessene Zustimmung der Lernenden sowie gegebenenfalls eine unabhängige institutionelle oder ethische Prüfung geklärt. Informationen zu Rückzugsmöglichkeiten, Aufbewahrungsdauer und Löschung sind in verständlicher Form bereitzustellen.\nTrennung der Datenbestände. Identifizierende Kontaktdaten und die Zuordnungstabelle werden getrennt und zugriffsgeschützt aufbewahrt. Für die Auswertung werden nur erforderliche Merkmale und pseudonymisierte Schülerlösungen verwendet. Die vorhandenen Bewertungen aus Anlage 1B dienen ausschließlich als qualitative Kontextdaten, soweit ihre Verwendung zulässig ist. Unbestätigte Gesprächszusammenfassungen oder nicht unabhängig belegte Notenverbesserungen werden nicht als gesicherte Wirkungsdaten umgedeutet.\nStatus der Planung. Die vorstehenden Angaben beschreiben ein zu präzisierendes, vor der Erhebung festzulegendes Untersuchungsprotokoll; sie behaupten weder eine bereits durchgeführte Randomisierung noch validierte Skalen, bestätigte Stichprobengrößen oder eine nachgewiesene Wirksamkeit. Das vollständige Protokoll, die Aufgabenpaare, Ankerbeispiele, Auswertungsentscheidungen und ihre Versionen sind vor dem Beginn einer systematischen FRZK-Wirkungsuntersuchung zu fixieren.\n\n1.8 Persönliche und berufliche Motivation\nMein Interesse an einer wissenschaftlichen Auseinandersetzung mit mathematischen und technischen Fragestellungen reicht bis in meine Schul- und Studienzeit zurück. In späteren beruflichen Tätigkeiten konnte ich wissenschaftliche Methoden vor allem in der Entwicklung, Organisation und Vermittlung komplexer Systeme anwenden. Die Frage, wie aus einer umfangreichen Aufgabenstellung eine nachvollziehbare Struktur entsteht, begleitete mich dabei in unterschiedlichen Zusammenhängen.\nErfahrungen aus der Verfahrenstechnik, aus der Informationstechnologie und aus der Erwachsenenbildung haben mein Verständnis dafür geprägt, dass die explizite Darstellung von Voraussetzungen und Beziehungen eine wichtige Voraussetzung für die gemeinsame Bearbeitung komplexer Probleme sein kann. Diese Berufserfahrung ist eine Motivation für die Themenwahl, aber kein wissenschaftlicher Nachweis der Eignung des FRZK.\nIn meiner späteren Unterrichts- und Nachhilfetätigkeit rückte für mich die Frage in den Mittelpunkt, wie sich ein solches Vorgehen auf mathematische Lernaufgaben übertragen lässt. Ich habe dabei wiederkehrende Schwierigkeiten beobachtet, aus denen ich prüfbare Fragestellungen ableite. Ihre Ursachen und mögliche Verbesserungen müssen im Rahmen einer systematisch dokumentierten Untersuchung geklärt werden.\nMit der Dissertation möchte ich diese Erfahrungen in ein wissenschaftlich kontrollierbares Vorhaben überführen. Mein Ziel ist, einen offen gelegten Darstellungsrahmen zu formulieren, seine Grenzen zu benennen und seinen möglichen didaktischen Nutzen anhand geeigneter Kriterien untersuchen zu lassen. Persönliche Überzeugung und wissenschaftlicher Befund bleiben dabei ausdrücklich getrennt.\n\n1.9 Wissenschaftliche Relevanz und Abgrenzung des Vorhabens\nKapitel 2 erarbeitet die mathematischen, methodischen und didaktischen Grundlagen des FRZK. Es stellt funktionale Zusammenhänge und ihre Darstellungsformen ebenso dar wie zentrale Bedingungen des Aufgabenverständnisses, des Problemlösens und der individuellen Lernförderung. Die einschlägige Fachliteratur wird dabei zur Begründung, Einordnung und kritischen Abgrenzung herangezogen; Kapitel 2 ist jedoch keine eigenständige Literaturprüfung oder systematische Evidenzsynthese. Kapitel 3 entwickelt darauf aufbauend die formale Beschreibung des FRZK und die davon getrennt zu prüfenden mathematischen Erweiterungen. Formal nachgewiesene Teilresultate spezieller Grenzwert- und Vektoroperatoren ersetzen weder den Vergleich des methodischen Problemlöseverfahrens mit bestehenden Ansätzen noch die empirische Prüfung seines möglichen Lernnutzens.\nDie wissenschaftliche Relevanz des Projekts liegt in der überprüfbaren Frage, wie Problemstellungen methodisch erfasst, strukturiert, bearbeitet und gelöst werden können und ob die explizite Anwendung dieses Ablaufs Lernenden einen Zusatznutzen bietet. Die einzelnen Bearbeitungsschritte sollen unabhängig von meiner Person nachvollziehbar sein und an unterschiedlichen Aufgaben erprobt und kritisch mit bestehenden Problemlöseverfahren verglichen werden. Gesonderte mathematische Symbolerweiterungen begründen diesen methodischen Anspruch weder automatisch noch ersetzen sie ihn.\nIch gehe von der Arbeitsannahme aus, dass ein fehlender oder unzureichend strukturierter Überblick über Variablen und Beziehungen die Bearbeitung mathematischer Aufgaben erschweren kann. Diese Annahme ist weder allgemein noch für jede Lernsituation bewiesen. Die Dissertation muss deshalb die Bedingungen angeben, unter denen eine FRZK-Darstellung nützlich, entbehrlich oder möglicherweise hinderlich ist.\nUnter einem zunächst leeren Darstellungsrahmen verstehe ich hier methodisch, dass die für eine konkrete Aufgabe benötigten Angaben und Beziehungen schrittweise eingetragen werden. Dies ist nicht mit der leeren Menge der Mathematik identisch. Eine solche Arbeitsweise soll Vorannahmen sichtbar machen; sie bedeutet nicht, dass Lernende ohne Vorwissen arbeiten oder dass mathematische Strukturen aus dem Nichts entstehen.\nDie Analogie zu technischen Modellierungs- und Datenbanksystemen hilft mir, Annahmen, Eingaben, Verknüpfungen und Ausgaben getrennt zu dokumentieren. Ich verwende diese Analogie als heuristisches Werkzeug, nicht als Beweis dafür, dass kognitive Prozesse denselben Regeln wie Softwarearchitekturen folgen.\nFür die Dissertation ergibt sich daraus ein begrenzter methodischer Anspruch: Ich möchte das Vorgehen von der Problemformulierung bis zur begründeten Lösung und Ergebniskontrolle präzisieren, seine Grenzen bestimmen und es auf ausgewählte Lernaufgaben anwenden. Ob Lernende dadurch besser verstehen, begründen oder übertragen können, ist empirisch zu prüfen. Die darüber hinaus eingeführten mathematischen FRZK-Symbole sind unabhängig davon in ihrem jeweiligen formalen Geltungsbereich zu untersuchen.\nDie zusätzlichen mathematischen Festlegungen – insbesondere zu typisierten Nullzuständen, Grenzrichtungen, orthogonaler Ausgangsorientierung und Vektoroperationen – werden auf der Grundlage von Kapitel 2 in Kapitel 3 eigenständig definiert und formal geprüft. Sie gehören nicht notwendig zum allgemein anwendbaren methodischen Grundgerüst. Die Einleitung macht deshalb weder diese Erweiterungen zu Voraussetzungen jeder Problemstellung noch leitet sie ihre mathematische Gültigkeit aus einer gelungenen Unterrichtsanwendung ab.\n\n1.10 Aufbau der Arbeit\nKapitel 2 beschreibt die mathematischen, methodischen und didaktischen Grundlagen des FRZK. Dazu gehören insbesondere funktionale Zusammenhänge und Modelle, Repräsentationen und Visualisierungen, Aufgabenverständnis und Problemlösen, Vorwissen und Begriffsbildung, individuelle Lernförderung, mathematisches Argumentieren, Fehlerdiagnose und Lernumgebungen. Die fachwissenschaftliche und didaktische Literatur wird innerhalb dieser Grundlagenarbeit herangezogen, um die verwendeten Begriffe und Ansätze wissenschaftlich einzuordnen. Kapitel 2 ist keine eigenständige Literaturprüfung.\nKapitel 3 formalisiert den methodischen FRZK-Ablauf auf der Grundlage der in Kapitel 2 entwickelten Begriffe: Problemstellung, Angaben und Zielgrößen, Voraussetzungen und Beziehungen, Lösungsentwicklung sowie Ergebniskontrolle. Davon getrennt werden zusätzliche mathematische FRZK-Strukturen entwickelt, insbesondere typisierte Grenzzustände, Vektorkonstruktionen und spezielle Operationen. Für sie sind Definitionen, Annahmen, Rechenregeln und Gültigkeitsbereiche jeweils eigens anzugeben und zu prüfen. Auch die orthogonale Ausgangsorientierung im Nullgrenzzustand gehört nur zu denjenigen mathematischen Modellen, in denen sie ausdrücklich festgelegt ist; sie ist keine Voraussetzung für jede methodische FRZK-Anwendung.\nDie folgenden Untersuchungskapitel behandeln die Anwendung und Grenzen des methodischen Vorgehens sowie die eigenständige formale Prüfung zusätzlich eingeführter mathematischer Konstruktionen. Rekursionen, Fixpunkte, besondere Grenzzustände oder Kohärenzbedingungen sind speziell definierte Untersuchungsfälle und keine universell notwendigen Bearbeitungsschritte des FRZK. Ein formaler Beweis für eine bestimmte Modellklasse begründet weder die globale Konsistenz sämtlicher Erweiterungen noch ein neues physikalisches Gesetz.\nDer didaktische Teil der Arbeit soll den methodischen FRZK-Ablauf zur Problemstellung und Problemlösung an ausgewählten Aufgaben untersuchen. Hierfür werden Beobachtungskriterien, Aufgabenformate, Vergleichsbedingungen und Auswertungsverfahren offengelegt. Mathematische Zusatzzeichen und -operatoren werden nur bei einer gesondert gekennzeichneten, fachlich geeigneten Aufgabenklasse verwendet und dürfen nicht unbemerkt Bestandteil der allgemeinen didaktischen Intervention werden.\nMit diesem Aufbau unterscheide ich die in Kapitel 2 dargestellten fachlichen Grundlagen, die formale Entwicklung und mathematische Prüfung in Kapitel 3 sowie die spätere empirische Untersuchung der methodischen Anwendung. Die Literatur dient in den betreffenden Kapiteln der wissenschaftlichen Begründung und Abgrenzung; sie bildet nicht den alleinigen Gegenstand von Kapitel 2. Dadurch sollen auch nicht bestätigte Annahmen und die Grenzen des entwickelten Ansatzes nachvollziehbar geprüft werden können.\n\n1.11 Zusammenfassung\nMit dieser Einleitung stelle ich das Funktionale Raum-Zeit-Kohärenzsystem vorrangig als methodischen Ansatz zur Formulierung, Strukturierung, Bearbeitung und Lösung von Problemen vor. Das Forschungsinteresse leite ich aus Schwierigkeiten beim Verstehen von Aufgaben, dem Erkennen von Größen und Beziehungen sowie der Überprüfung eigener Lösungswege ab. Die Einleitung beschreibt Anlass, Zielsetzung, wissenschaftliche Abgrenzung und geplanten Untersuchungsweg, ohne besondere mathematische Erweiterungen zur Voraussetzung der Methode zu machen.\nDer angestrebte Beitrag besteht in einem nachvollziehbaren, kritisch überprüfbaren Problemlöseverfahren und in der Untersuchung seines möglichen didaktischen Nutzens. Zusätzliche mathematische Symbole und Operationen aus Grenzwert- und Vektorrechnung bilden einen gesonderten, formal zu prüfenden Erweiterungsbereich. Ob der methodische Ansatz Vorteile gegenüber vorhandenen Verfahren bietet, lässt sich aus Unterrichtsbeobachtungen oder Modellbeschreibungen allein nicht folgern.\nDie folgenden Kapitel müssen daher das methodische Grundgerüst, die Reichweite und Konsistenz spezieller mathematischer Erweiterungen sowie die didaktische Tragfähigkeit getrennt untersuchen. Die Unterscheidung zwischen Problemlöseverfahren, formaler Zusatzstruktur und empirischer Wirksamkeit bleibt leitend.', 'Vollständige Textfassung inkl. Literaturverzeichnis und Anlagen in sections/paragraphs; Medien als separate figure_assets. RELEASED meint Autorenfreigabe, nicht universelle wissenschaftliche Begutachtung.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `body_text`=VALUES(`body_text`), `notes`=VALUES(`notes`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.0', 'Einleitung', 1, 0, 'In meiner Nachhilfepraxis beobachte ich wiederholt, dass Lernende bei komplexen Aufgaben Schwierigkeiten haben, relevante Angaben zu ordnen, Beziehungen zu erkennen und den eigenen Lösungsweg zu reflektieren. Ich untersuche deshalb einen methodischen Ablauf, der bei der Formulierung der Problemstellung beginnt, Gegebenes und Gesuchtes trennt, Beziehungen erschließt, eine Lösung entwickelt und diese überprüft. Das Funktionale Raum-Zeit-Kohärenzsystem (FRZK) verstehe ich primär als methodischen Ansatz zur Problemstellung und Problemlösung. Seine mathematischen Erweiterungen um besondere Grenzwert- und Vektorsymbole gehören nicht zum allgemeinen methodischen Grundgerüst. Ob das Vorgehen die Nachvollziehbarkeit, Fehlererkennung und Übertragbarkeit von Lösungsstrategien verbessert, bleibt eine empirisch zu prüfende Frage.\n\nDie Fragestellung berührt wissenschaftliche Diskussionen über Modellbildung, Beobachtung und die Begriffe Raum und Zeit. Rovelli behandelt die Grundlagen unseres Zeitverständnisses und die Grenzen herkömmlicher Vorstellungen von Zeit (Rovelli, Carlo (2018). The Order of Time. London: Penguin Books.)[1]. Ich verwende diese Darstellung als physikalisch-philosophischen Hintergrund, nicht als Bestätigung einer aus dem FRZK hervorgehenden Raumzeit oder als Nachweis seines didaktischen Nutzens.\n\nDie Systemtheorie und die Kybernetik eröffnen unterschiedliche Perspektiven auf Systembeziehungen, Beobachtung und die Beschreibung von Lern- und Kommunikationsprozessen (von Foerster, Heinz (1981). Observing Systems. Seaside, CA: Intersystems Publications.)[2] (Maturana, Humberto R.; Varela, Francisco J. (1987). The Tree of Knowledge: The Biological Roots of Human Understanding. Boston: Shambhala.)[3]. Für die Entwicklung und Untersuchung didaktischer Verfahren ist die gestaltungsorientierte Lehr-Lernforschung ein methodischer Bezugspunkt (Reinmann, Gabi (2005). Innovation ohne Forschung? Ein Plädoyer für den Design-Based Research-Ansatz in der Lehr-Lernforschung. Unterrichtswissenschaft, 33(1), S. 52–69. DOI: 10.25656/01:5787.)[4]. Einen Ansatz zur Begleitung und Anregung eigenständiger Lernprozesse erläutert Arnold (Arnold, Rolf (2012). Wie man lehrt, ohne zu belehren. 29 Regeln für eine kluge Lehre. Das LENA-Modell. 1. Auflage. Heidelberg: Carl-Auer. ISBN: 978-3-89670-838-0.)[5]. Sfard untersucht mathematisches Denken aus einer kommunikationstheoretischen Perspektive (Sfard, Anna (2008). Thinking as Communicating: Human Development, the Growth of Discourses, and Mathematizing. Cambridge: Cambridge University Press. DOI: 10.1017/CBO9780511499944.)[6]. Luhmann stellt mit seiner Theorie sozialer Systeme einen weiteren, davon zu unterscheidenden systemtheoretischen Bezug bereit (Luhmann, Niklas (1984). Soziale Systeme: Grundriß einer allgemeinen Theorie. Frankfurt am Main: Suhrkamp.)[7]. Keiner dieser Ansätze beweist bereits die Wirksamkeit des FRZK.\n\nDas methodische Grundgerüst des FRZK beschreibt eine Folge nachvollziehbarer Bearbeitungshandlungen: Eine Problemstellung wird zunächst geklärt und als Frage formuliert; anschließend werden bekannte und gesuchte Größen, Voraussetzungen und Beziehungen geordnet, Lösungsansätze entwickelt, ausgeführt und anhand der Ergebnisse überprüft. Die ausdrückliche Darstellung funktionaler Zusammenhänge ist ein Hilfsmittel innerhalb dieses Weges, nicht dessen einziges Ziel. Das Grundgerüst setzt weder ein bestimmtes Koordinatensystem noch eine spezielle Geometrie, Dynamik oder Algebra voraus. Rekursion, Fixpunkte, Kohärenzbedingungen und mathematische Sonderzeichen werden nur dann hinzugenommen, wenn die konkrete Aufgabe dies erfordert.\n\nDie in Kapitel 3 behandelten besonderen FRZK-Zustände, gerichteten Grenzannäherungen, Grenzzeichen, Null- und Vektoroperationen sowie die orthogonale Ausgangsorientierung bilden eine gesonderte mathematische Erweiterung des methodischen Ansatzes. Sie sind nicht als Voraussetzungen für jede Problemstellung oder für jede Anwendung des FRZK zu verstehen. Ihre Bedeutung, Rechenregeln und Gültigkeitsbereiche müssen unabhängig vom Grundgerüst definiert und formal geprüft werden. Insbesondere ist eine leere Darstellung nicht mit der mathematisch leeren Menge oder einem physikalisch leeren Raum gleichzusetzen; ein FRZK-Nullzustand ist kein gewöhnlicher reeller Zahlenwert und ein orientierter Nullzustand nicht ohne zusätzliche Information rückskalierbar.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'dfe347fa1b18770fad28555828ceec6949ccdf32001c121c20c2c144f9dd7f1e') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.1', 'Entstehung der Forschungsfrage aus der Unterrichtspraxis', 1, 6, '', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.1.1', 'Praktisches Beispiel: Textaufgabe', 2, 7, 'In meiner Nachhilfepraxis begegnen mir Aufgaben, bei denen Schülerinnen und Schüler die gegebenen Informationen zwar lesen oder notieren können, deren funktionale Beziehungen und die gesuchte Größe aber noch nicht erkennen. Die folgenden Beispiele begründen die Forschungsfrage aus meiner Perspektive. Sie sind zunächst Unterrichtsbeobachtungen und keine repräsentative empirische Untersuchung.\n\nBeispiel 1: Eine Schülerin 3. Klasse Grundschule sollte die Aufgabe: „Ein Bauer hat 173 Kartoffeln und 8 Säcke. Wieviel Kartoffeln kommen in einen Sack und wie viele bleiben übrig?“. Mein Standardansatz zur Lösung von Textaufgaben besteht darin, alles, was gegeben ist, mit blau und alles, was gesucht ist, mit grün zu unterstreichen, dann die Angaben in den Notizblock zu übertragen und schließlich zu lösen. Ich habe der Schülerin diesen Ansatz empfohlen und ihr aufgetragen, die Aufgabe zu lösen. Nach etwa 15 Minuten habe ich versucht die Lösung zu kontrollieren und festgestellt, dass die Schülerin die gesamte Aufgabe mit blau unterstrichen hatte und in ihren Notizblock 1:1 übernommen hatte.\n\nMan könnte zunächst feststellen, dass die Aufgabe nicht im erwarteten Sinne gelöst wurde. Bei genauerer Betrachtung hatte die Schülerin jedoch meinen Arbeitsauftrag befolgt und die gesamte Aufgabenstellung als gegeben markiert. Ich deutete dieses Verhalten als möglichen Hinweis darauf, dass sie die für die Lösung benötigten Informationen noch nicht voneinander unterscheiden konnte. Ob ihr insbesondere die Situation mit Bauer und Kartoffeln unvertraut war, lässt sich aus dieser einen Beobachtung allein nicht sicher ableiten. Die Schülerin zeigte eine erkennbare Bearbeitungsaktivität; die mathematische Lösung und die dafür notwendige Interpretation der Angaben blieben zunächst offen.\n\nIch erarbeitete daraufhin mit der Schülerin auf einem leeren Blatt Papier eine schrittweise Strukturierung der Situation. Die vom Autor bereitgestellte Anlage 1A („Inkrementelles Setup einer Textaufgabe“) veranschaulicht in fünf Bildern den Weg vom leeren Blatt über eine Orientierung in der Situation zur Unterscheidung von Gesuchtem und Gegebenem. Sie dokumentiert einen didaktischen Aufbau, ist aber kein datiertes Original der von der Schülerin angefertigten Lösung und kein standardisiert erhobener Lernfortschritt. Der berichtete Gesprächsverlauf bleibt eine retrospektive Unterrichtsbeobachtung.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '1098d17f89d74785490e1846d5b8b734f7ec475ccf0731d005867f765df76ae4') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.1.2', 'Praktisches Beispiel: Lineare Zusammenhänge', 2, 13, 'Zwei Schülerinnen aus der 9. Klasse Gymnasium standen vor der Aufgabe: „Wie würdest du deinem besten Freund oder deiner besten Freundin erklären, was eine lineare Funktion ist?“ Die Aufgabe zielte darauf ab, ein grundlegendes Verständnis für lineare Funktionen zu entwickeln, indem die Schülerinnen den Begriff selbstständig formulieren und ihre eigenen Worte finden sollten, um diese mathematische Beziehung zu erklären. Doch anstatt eine klare Vorstellung von einer linearen Funktion zu entwickeln, standen die Schülerinnen vor einer mentalen Blockade.\n\nIn einer ersten Rückmeldung erklärten beide Schülerinnen, dass sie nicht wüssten, wie sie ihre Antwort beginnen sollten. Ich deutete dies als Hinweis darauf, dass ihnen ein sprachlicher und anschaulicher Zugang zu der gefragten Beziehung fehlte. Ob dabei die Begriffskenntnis, das Vorwissen, die konkrete Aufgabenstellung oder weitere Faktoren entscheidend waren, ließ sich in dieser Situation nicht isolieren.\n\nEine der Schülerinnen äußerte: „Was ist das, eine Linie? Es sind doch Zahlen, aber wie hängen die zusammen?“ Sie hatte Schwierigkeiten, das Konzept einer linearen Funktion als eine mathematische Beziehung zu begreifen, die über abstrakte Zahlen und Parameter hinausgeht und in einem konkreten Zusammenhang, wie etwa einer realen Situation (z.B. eine Geschwindigkeit über Zeit oder den Zusammenhang zwischen dem Einkommen und den Arbeitsstunden), interpretiert werden könnte. Auch die andere Schülerin konnte die Aufgabe nicht anders angehen, als die Parameter der linearen Funktion als isolierte mathematische Elemente zu betrachten, ohne deren Einfluss auf die Gestalt der Linie oder auf die Veränderung der Werte in einer praktischen Anwendung zu begreifen.\n\nIn der Situation konnten die Schülerinnen die Formel einer linearen Funktion benennen, hatten aber Schwierigkeiten, die Bedeutung der Parameter und den Zusammenhang der Größen in eigenen Worten zu erläutern. Für meine Untersuchung ist daran besonders interessant, ob eine ausdrücklich geordnete Darstellung von Größen, Beziehungen und Beispielen den Übergang von einer symbolischen Schreibweise zu einer fachlich angemessenen Erklärung unterstützen kann.\n\nIch beobachtete, dass die Schülerinnen zunächst nach einer bekannten Definition suchten und eigene Beispiele kaum verwendeten. Daraus ergibt sich für mich eine prüfbare didaktische Frage: Welche Darstellungshilfen erleichtern es Lernenden, den mathematischen Zusammenhang als Beziehung veränderlicher Größen zu beschreiben? Die Beobachtung allein lässt weder auf eine allgemeine Ursache noch auf die Wirksamkeit einer bestimmten Unterrichtsmethode schließen.\n\nDie beiden Unterrichtsbeobachtungen lassen sich mit der didaktischen Frage verbinden, wie Lernende tragfähige Begriffe aufbauen und neues Wissen mit vorhandenem Wissen verknüpfen. Bruner behandelt die Struktur von Unterrichtsinhalten und die schrittweise Vertiefung grundlegender Vorstellungen (Bruner, Jerome S. (1960). The Process of Education. Cambridge, MA: Harvard University Press. DOI: 10.4159/9780674028999.)[8]. Ausubels Arbeiten befassen sich mit der Bedeutung der kognitiven Struktur für sinnvolles sprachliches Lernen (Ausubel, David P. (1963). The Psychology of Meaningful Verbal Learning. New York: Grune & Stratton.)[9]. Die genaue Zuordnung einzelner Buchseiten bleibt bis zur Editionsprüfung offen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'dd87198335435ba2bf745ac02a6b278186afce4a662ac048e77f6029f6a403df') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.1.3', 'Ergänzendes Beispiel: Ungewöhnliche Lösungswege', 2, 20, 'Rudolf Taschner: Der Irrtum des Pythagoras\n\nAls Beispiel für die öffentliche Vermittlung mathematischer Fragestellungen nenne ich Rudolf Taschners Vortrag „Der Irrtum des Pythagoras“ (Taschner, Rudolf (2013). Der Irrtum des Pythagoras. Videoaufzeichnung, math.space, TIB AV-Portal. DOI: 10.5446/15789.)[10]. Für meine Arbeit ist daran die Frage relevant, wie ein zunächst ungewohnter mathematischer Zugang fachlich geprüft und verständlich erläutert werden kann. Ich übernehme aus dem Vortrag weder ein wörtliches Zitat noch eine Abbildung; seine Erwähnung dient als Anregung für diese didaktische Fragestellung, nicht als Beleg für die Wirksamkeit des FRZK.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '187921421eb0d8da56d209fed70be938cb69d3c925232a31418db9d335ce375e') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.1.4', 'Zwischenbilanz', 2, 25, 'Die Unterrichtsbeispiele verdeutlichen mein Erkenntnisinteresse: Lernende benötigen bei mathematischen Aufgaben nicht allein Rechenverfahren, sondern müssen Angaben, Begriffe und funktionale Beziehungen unterscheiden und aufeinander beziehen können. Ich möchte prüfen, ob ein systematischer Darstellungsrahmen dabei unterstützt, die Problemstellung zu verstehen, den Lösungsweg zu begründen und das Verfahren auf neue Aufgaben zu übertragen. Die Beispiele zeigen den Anlass dieser Untersuchung, nicht bereits deren Ergebnis.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '68d782a5c085ee4f34df95db950647a32ad41f7f198cc7342cb3b8b9a7859d33') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.2', 'Lösungsweg und Ergebnis', 1, 28, 'Um die Entstehung meiner Forschungsfrage nachvollziehbar zu machen, wählte ich zunächst bewusst eine Aufgabe außerhalb meiner üblichen Nachhilfepraxis: Wie lässt sich eine gekrümmte, im Allgemeinen intrinsisch nichteuklidische Fläche auf einer zweidimensionalen Beobachtungsfläche durch berechnete Signalgrößen darstellen? Mein Interesse an Geometrie, Astronomie und physikalischer Modellbildung gab den Anlass. Die nachfolgende Beschreibung unterscheidet die ursprüngliche Ideenskizze von einem neu festgelegten, rechnerisch reproduzierbaren Referenzfall.\n\nBei der Bearbeitung trennte ich zunächst die Angaben, die frei wählbaren Annahmen und die gesuchten Ergebnisse. Unter einem zunächst leeren Bezugssystem verstand ich dabei kein physikalisches Vakuum und keine mathematisch leere Menge, sondern ein Koordinaten- und Darstellungsgerüst, dessen konkrete Objekte und Regeln ich erst nach und nach festlegte.\n\nIn der ursprünglichen Skizze setzte ich den Beobachter in den Ursprung eines räumlichen Koordinatensystems, führte eine gekrümmte Fläche ein und wählte ein gleichseitiges Dreieck als zweidimensionale Beobachtungsfläche. Die historische Darstellung in Abbildung 1.F2 dokumentiert diese Reihenfolge; aus der Skizze allein lassen sich jedoch weder die genaue Flächenfunktion noch messbare Signalwerte bestimmen.\n\nAbbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.\n\nDie Darstellung unterscheidet den Beobachter im Koordinatenursprung, die dreieckige Beobachtungsebene und die untersuchte gekrümmte Fläche. Welche Eigenschaften die Fläche besitzt, ist mathematisch erst nach Angabe einer Parametrisierung und eines Definitionsbereichs entschieden.\n\nEine zweidimensionale Darstellung macht eine dreidimensionale Situation nicht vollständig sichtbar. Daher unterscheide ich im Folgenden ausdrücklich zwischen den geometrischen Objekten des Modells, den berechneten Signalgrößen und deren Farbcodierung. Aus einer graphischen Projektion folgt weder, dass physikalischer Raum entsteht, noch, dass die Modellgröße eine tatsächliche Messung darstellt.\n\nDie geometrische Skizze beantwortete die eigentliche Aufgabe noch nicht. Um Beziehungen quantitativ auszuwerten, musste ich festlegen, welcher Punkt der gekrümmten Fläche welchem Punkt des Dreiecks zugeordnet wird. Eine solche eindeutige Zuordnung ist die hier benötigte Bezugsfunktion; sie ist eine Modellentscheidung und keine automatisch aus der Zeichnung folgende Gesetzmäßigkeit.\n\nAnschließend ergänzte ich einen Sender und eine Signalvorschrift. Erst damit ließ sich jedem zugeordneten Punktpaar eine berechenbare Laufzeit zuweisen. Der Sender ist kein allgemeines Axiom des FRZK, sondern ausschließlich ein Bestandteil dieses technischen Beispiels. Die Einführung von Laufzeiten macht eine zeitbezogene Größe auswertbar; sie bedeutet nicht, dass sich die Geometrie selbst zeitlich verändern muss.\n\nIm Ausgangsgedanken sollte ein Signal vom Sender über einen Punkt der gekrümmten Fläche zu einem zugeordneten Punkt des Beobachtungsdreiecks gelangen. Die gesamte Weglänge wurde in eine Laufzeit umgerechnet und anschließend farblich kodiert. Damit entsteht eine zweidimensionale Darstellung eines aus einer dreidimensionalen Konstruktion abgeleiteten Skalarfelds. Für eine wissenschaftlich wiederholbare Berechnung sind die Geometrie, die Zuordnung und die Ausbreitungsannahmen ausdrücklich anzugeben.\n\nAbbildung 1.F3 zeigt die ursprüngliche Visualisierung solcher berechneten Laufzeitgrößen. Die dafür verwendeten Originalparameter, Programmdateien und Rohdaten sind hier nicht dokumentiert; deshalb gebe ich ihre Werte nicht nachträglich als überprüft aus. Stattdessen definiere ich im Folgenden ein unabhängiges Referenzmodell, mit dem derselbe methodische Rechengang vollständig nachvollzogen werden kann. Über einen rechtlichen Status oder Schutzrechte trifft dieser Abschnitt keine Aussage.\n\nAbbildung 1.F3: Ursprüngliche dreidimensionale Visualisierung modellierter Signallaufzeiten. Die historischen Rechenparameter sind für die vorliegende Fassung nicht belegt; die Darstellung wird daher nicht als numerischer Nachweis des nachfolgenden Referenzmodells verwendet. Eigene Darstellung.\n\nReproduzierbares technisches Referenzmodell\n\nDie folgende Konkretisierung ist eine ausdrücklich neu festgelegte Modellvariante, keine nachträgliche Rekonstruktion der unzugänglichen Originalrechnung. Sie dient dazu, den in der Entstehungsgeschichte beschriebenen Rechenweg mit vollständig offengelegten Größen und Regeln zu demonstrieren. Alle Koordinaten und Längen werden in Metern, Zeiten in Sekunden beziehungsweise Nanosekunden angegeben.\n\nKoordinatensystem und Dreieck. Der Beobachter O=(0, 0, 0) ist der geometrische Bezugspunkt. Das Beobachtungsdreieck liegt in der Ebene x=b mit b=1 m; seine Seitenlänge beträgt s=1 m. Für die beiden ebenen Koordinaten u und v wird das abgeschlossene Dreiecksgebiet D durch die Eckpunkte A, B und C festgelegt (Gleichung 1.1):\n\nWord-LaTeX: A=(-\\tfrac{s}{2},-\\tfrac{s}{2}),\\quad B=(\\tfrac{s}{2},-\\tfrac{s}{2}),\\quad C=(0,\\frac{(\\sqrt{3}-1)s}{2})\n\nDie Punkte A, B und C der vorstehenden Formel sind (u,v)-Koordinaten in der Beobachtungsebene. Das Dreieck ist gleichseitig, denn alle drei Seiten haben die Länge s. Jeder Punkt (u,v)∈D beschreibt genau einen Beobachtungspunkt P(u,v) in der Ebene x=b.\n\nGekrümmte Fläche und Bezugsfunktion. Im dreidimensionalen Raum definiere ich die Fläche Q durch die folgende Parametrisierung. Für das Beispiel setze ich d=3 m und a=0,20 m⁻¹; der Definitionsbereich der Fläche ist genau das Dreiecksgebiet D. Die Zuordnung P(u,v)↔Q(u,v) verwendet dieselben beiden Parameter u und v und ist daher eindeutig (Gleichung 1.2).\n\nWord-LaTeX: Q(u,v)=\\left(d+a(u^{2}-v^{2}),\\,u,\\,v\\right),\\qquad P(u,v)=(b,u,v)\n\nDie Oberfläche ist eine Sattelfläche. Ihre Gauß-Krümmung ergibt sich aus den ersten und zweiten Ableitungen der Flächenfunktion und ist bei a≠0 überall negativ (Gleichung 1.3):\n\nWord-LaTeX: K(u,v)=\\frac{-4a^{2}}{\\left(1+4a^{2}(u^{2}+v^{2})\\right)^{2}}<0\n\nDamit ist „nichteuklidisch“ in diesem Beispiel präzisiert: Gemeint ist die innere Geometrie einer gekrümmten zweidimensionalen Fläche, nicht eine Krümmung des umgebenden dreidimensionalen Raums oder der physikalischen Raumzeit. Wege außerhalb der Fläche werden im Referenzmodell euklidisch berechnet.\n\nSender, Signalweg und Ausbreitungsannahmen. Der Sender liegt bei S=(xₛ,0,0) mit xₛ=5 m. Jeder Flächenpunkt Q(u,v) wird idealisiert als punktförmiger, unmittelbar weiterstrahlender Signalpunkt angenommen. Für das jeweilige Parameterpaar wird genau der zweite Wegabschnitt von Q(u,v) zu P(u,v) ausgewertet. Beide Wegabschnitte sind gerade Strecken im dreidimensionalen euklidischen Raum. Das Modell setzt Vakuumausbreitung mit konstanter Geschwindigkeit c, keine Laufzeitverzögerung am Flächenpunkt und keine Abschwächung voraus. Brechung, Beugung, Mehrfachwege, Abschattung und die winkelabhängige Reflexionsbedingung werden nicht modelliert. Das ist eine idealisierte Zuordnungsvorschrift und kein vollständiges optisches Reflexionsmodell.\n\nMess- beziehungsweise Rechengröße. Die zugeordnete Gesamtlaufzeit ist die Summe der beiden euklidischen Segmentlängen, geteilt durch die Ausbreitungsgeschwindigkeit. Mit xₛ=5 m, b=1 m, d=3 m und a=0,20 m⁻¹ gilt (Gleichung 1.4):\n\nWord-LaTeX: \\tau(u,v)=\\frac{\\sqrt{\\left(x_{S}-d-a(u^{2}-v^{2})\\right)^{2}+u^{2}+v^{2}}+d+a(u^{2}-v^{2})-b}{c}\n\nDabei steht c=299 792 458 m/s für die im Internationalen Einheitensystem exakt festgelegte Vakuumlichtgeschwindigkeit (Bureau International des Poids et Mesures (2026). The International System of Units, 9. Auflage, aktualisierte Fassung. DOI: 10.59161/AUEZ1291.)[15]. Die berechnete Laufzeit ist eine Modellgröße. Eine tatsächliche Messung oder ein bestimmter physikalischer Reflexionsvorgang wird dadurch nicht nachgewiesen.\n\nErgebnisfunktion und Darstellung. Mit der Zuordnung jedes Beobachtungspunkts zu seiner Laufzeit entsteht ein Skalarfeld auf dem Dreieck (Gleichung 1.5):\n\nWord-LaTeX: F:P(u,v)\\longmapsto \\tau(u,v),\\qquad (u,v)\\in D\n\nZur numerischen Darstellung werden die Bereiche −0,50 m ≤ u ≤ 0,50 m und −0,50 m ≤ v ≤ (√3−1)/2 m jeweils mit 281 gleichmäßig verteilten Stützstellen abgetastet. Ausgewertet werden ausschließlich Punkte innerhalb des abgeschlossenen Dreiecks D. An jedem gültigen Gitterpunkt werden Q, die beiden Signalstrecken und τ in dieser Reihenfolge berechnet. Für die reproduzierbare Farbkodierung in Abbildung 1.F4 wird der Bereich von 13,34 ns bis 13,75 ns fest vorgegeben; größere Werte entsprechen dem oberen Ende der Farbskala. Die exakte Gebietsmaske, die Farbstufen und der Algorithmus sind in Anlage 1E dokumentiert.\n\nKontrollrechnung. Für (u,v)=(0,0) folgt Q=(3,0,0) m und P=(1,0,0) m. Damit betragen beide Wegabschnitte jeweils 2 m. Aus der Gesamtstrecke von 4 m ergibt sich τ(0,0)=13,3426 ns. Für die beiden unteren Dreiecksecken A und B ergeben sich jeweils 13,7472 ns; für die obere Ecke C ergibt sich 13,4519 ns. Diese Zahlen lassen sich unmittelbar durch Einsetzen in die angegebenen Gleichungen kontrollieren.\n\nAbbildung 1.F4: Numerisch reproduzierte Laufzeitverteilung auf dem Beobachtungsdreieck für die offengelegten Referenzparameter (s=1 m, b=1 m, d=3 m, a=0,20 m⁻¹, xₛ=5 m, c=299 792 458 m/s). Berechnung und Darstellung für diese Dissertation; nicht aus den historischen Abbildungen 1.F2 und 1.F3 abgeleitet.\n\nPrüfgrenzen des Referenzfalls. Die Gleichungen ermöglichen es, den geometrischen und numerischen Rechenweg unabhängig zu wiederholen; insbesondere sind Definitionsbereich, Flächenfunktion, Zuordnung, Signalweg, Konstanten und Farbbereich festgelegt. Damit ist die modellinterne Reproduzierbarkeit des hier definierten Referenzfalls hergestellt. Offen bleibt dagegen, ob die ursprünglichen Abbildungen auf denselben oder anderen Parametern beruhen. Ebenso ist mit der Konstruktion weder die physikalische Gültigkeit einer realen Signalstreuung noch eine allgemeine mathematische oder didaktische Wirksamkeit des FRZK belegt.\n\nDas Referenzmodell zeigt, wie sich eine technische Problemstellung durch explizite Annahmen, eine definierte Geometrie, eine Zuordnungsregel und überprüfbare Rechnungen bearbeiten lässt. Darin liegt sein methodischer Bezug zum FRZK: Aus einer zunächst offenen Frage wird ein nachvollziehbarer Lösungsweg entwickelt und geprüft. Weder die gewählte Geometrie noch die Signalvorschrift sind Bestandteile des allgemeinen FRZK-Grundgerüsts; spezielle mathematische FRZK-Zustände und Operatoren werden in diesem Referenzmodell nicht benötigt.\n\nZwischen dem technischen Beispiel und meinen Unterrichtsbeobachtungen erkenne ich ein gemeinsames methodisches Motiv: Ich bestimme relevante Größen und Annahmen, ordne Beziehungen ausdrücklich zu und überprüfe die daraus ableitbaren Ergebnisse. Bei der Kartoffelaufgabe betrifft dies gegebene und gesuchte Angaben, bei linearen Funktionen die Abhängigkeit veränderlicher Größen. Eine Verbesserung von Lernleistungen ist damit noch nicht nachgewiesen.\n\nDas technische Referenzmodell und die Unterrichtsbeobachtungen sind methodisch vergleichbar, aber weder mathematisch noch empirisch identisch. Carroll diskutiert das Verhältnis naturwissenschaftlicher Weltbeschreibung zu weiterführenden philosophischen Fragestellungen (Carroll, Sean (2016). The Big Picture: On the Origins of Life, Meaning, and the Universe Itself. New York: Dutton.)[11]. Dieser allgemeine Bezug begründet weder die vorliegende technische Modellwahl noch die pädagogische Wirksamkeit des FRZK.\n\nIm Beispiel der Grundschülerin konnte ich beobachten, dass sie zunächst alle Informationen als gleichwertig behandelte. Eine schrittweise Strukturierung der Aufgabe bot die Gelegenheit, zwischen den vorhandenen Angaben und der gesuchten Größe zu unterscheiden. Welche Rolle dabei die konkrete Alltagssituation, das Vorwissen und die sprachliche Aufgabenformulierung spielten, blieb offen.\n\nBei den Schülerinnen der neunten Klasse zeigte sich eine andere Schwierigkeit: Eine bekannte Formel konnte nicht ohne Weiteres in eine verständliche Erklärung überführt werden. Für die Modellierung ist deshalb zu unterscheiden zwischen einer symbolischen Darstellung, den Bedeutungen ihrer Variablen und den funktionalen Beziehungen im jeweiligen Sachkontext. Die mögliche didaktische Wirkung einer solchen Unterscheidung ist Gegenstand meiner Untersuchung.\n\nAus beiden Situationen leite ich keine allgemeine Lerntheorie ab. Ich entwickle daraus eine Forschungsfrage nach dem Nutzen expliziter Orientierung: Hilft es, wenn Lernende einen mathematischen Zusammenhang durch eigene Beschreibungen, Beispiele und überprüfbare Zuordnungen erschließen?', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '092b07351069a3904e8b3f278b02b2bfaed1d8e2033c1845138fadf00fc852ac') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.3', 'Die Rolle des Tutors und die Struktur von Nachhilfe im Kontext der individuellen Lernförderung', 1, 75, 'Nach meinen Erfahrungen aus drei Jahren Nachhilfepraxis umfasst die Aufgabe eines Tutors mehr als das Nachholen versäumter Lerninhalte oder die kurzfristige Vorbereitung auf Leistungsüberprüfungen. In meiner Arbeit dienen die Nachhilfestunden auch der Vertiefung behandelter Themen, der Überprüfung des übergreifenden fachlichen Verständnisses und der schrittweisen Entwicklung eigenständiger Problemlösestrategien. Ich bezeichne diese Arbeit als spezifischer auf den einzelnen Lernenden ausgerichtet, weil ich Aufgaben, Erklärungen, Rückfragen und Übungsphasen unmittelbar an dessen fachlichen Voraussetzungen anpassen kann. Damit beschreibe ich die Möglichkeiten meiner konkreten Nachhilfepraxis, nicht eine allgemeingültige Überlegenheit der Nachhilfe gegenüber dem Schulunterricht.\n\nDer schulische Unterricht ist an Lehrpläne, Unterrichtszeiten und das gemeinsame Lernen einer Klasse gebunden. Auch dort finden Differenzierung, individuelle Förderung und Vertiefung statt. In meinen kleinen Nachhilfegruppen kann ich jedoch zusätzliche Zeit auf einzelne Verständnisfragen verwenden, frühere Grundlagen erneut aufgreifen und das Tempo sowie den Schwierigkeitsgrad der Aufgaben personenbezogen verändern. Die Vertiefung richtet sich dabei nicht nur auf aktuelle Hausaufgaben, sondern auf die fachlichen Zusammenhänge des jeweiligen Themengebiets.\n\nEin zentraler Bestandteil ist die allgemeine Verständniskontrolle über die unmittelbar bearbeitete Aufgabe hinaus. Dazu lasse ich Lernende Begriffe und Zusammenhänge in eigenen Worten erklären, Lösungsentscheidungen begründen, typische Fehler erkennen und bekannte Verfahren in veränderten Aufgabenstellungen anwenden. Zeigen sich dabei Lücken im Vorwissen, greife ich diese gezielt auf. Rückfragen, ergänzende Erklärungen und die Anpassung der Arbeitsblätter dienen so nicht allein der Kontrolle eines Rechenergebnisses, sondern der Überprüfung, ob der zugrunde liegende mathematische Gedanke verstanden wurde. Die in Abschnitt 1.5 erläuterte altersabhängige Selbstkontrolle von Arbeitsergebnissen ersetzt diese übergreifende fachliche Verständniskontrolle nicht.\n\nIch messe der Lernatmosphäre, dem fachlichen Feedback und der nachvollziehbaren Rückmeldung über Lösungswege besondere Aufmerksamkeit bei. Hattie bündelt umfangreiche Forschung zu Faktoren schulischen Lernens und behandelt unter anderem die Bedeutung von Rückmeldung (Hattie, John (2009). Visible Learning: A Synthesis of Over 800 Meta-Analyses Relating to Achievement. London: Routledge.)[12]. Daraus lässt sich für meine konkreten Lerngruppen weder eine bestimmte Effektstärke ableiten noch die Wirksamkeit des FRZK voraussetzen; diese Zusammenhänge müssen im Untersuchungsdesign getrennt beobachtet werden.\n\nDie individuelle Förderung berücksichtigt unterschiedliche Vorkenntnisse, Stärken, Schwierigkeiten und Interessen. Zu Beginn eines Themengebiets erhalten die Lernenden eine Concept-Map oder ein Kompendium als Überblick. Anschließend erfolgt die Vertiefung themen- und defizitorientiert anhand persönlich angepasster Arbeitsblätter. Durch gezielte Rückmeldungen und Verständnisfragen beobachte ich, welche Beziehungen bereits sicher erklärt werden können und wo weitere Übungen oder eine erneute grundlegende Erklärung erforderlich sind.\n\nNicht zuletzt spielt die Berücksichtigung der persönlichen Bezugssysteme der Lernenden eine zentrale Rolle. Lernende können nur dann effektiv lernen, wenn neue Informationen in ein für sie verständliches und handhabbares System eingebunden werden. Durch die Aktivierung und den Aufbau eines solchen Bezugssystems werden abstrakte Inhalte greifbar, Zusammenhänge sichtbar und das eigenständige Arbeiten gefördert.\n\nDie Wirkung des Tutors auf die Lernenden ist entscheidend für den Erfolg der Nachhilfestunde. Ein Tutor hat die Aufgabe, eine positive, unterstützende Lernatmosphäre zu schaffen, die es den Lernenden ermöglicht, sich mit dem Stoff auseinanderzusetzen und gleichzeitig Vertrauen in ihre eigenen Fähigkeiten zu entwickeln. Die zwischenmenschliche Beziehung zwischen Tutor und Lernendem spielt dabei eine ebenso wichtige Rolle wie die fachliche Expertise. Empathie, Verständnis und die Fähigkeit, auf die individuellen Bedürfnisse des Lernenden einzugehen, sind ebenso entscheidend wie das Fachwissen.\n\nDiese wechselseitige Beziehung bildet in meiner Nachhilfepraxis eine wichtige Arbeitsbedingung. Ich verstehe meine Rolle nicht allein als Wissensvermittler, sondern als Lernbegleiter, der eigenständige Lösungsversuche aufgreift und durch Erklärungen, Rückfragen und gemeinsame Überprüfung weiterführt. In schriftlichen Rückmeldungen und Rezensionen werden insbesondere eine verlässliche Unterrichtsstruktur, individuelle Vorbereitung, wiederholte Erklärungen und eine unterstützende Lernbeziehung hervorgehoben (vgl. die qualitative Materialauswertung in Abschnitt 1.5, Tabelle 1.2). Diese Fremdeinschätzungen ergänzen meine Eigenbeobachtungen, ersetzen aber weder eine systematische Vergleichsstudie noch einen gesonderten Wirksamkeitsnachweis des FRZK.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '5c75f4a9618b373ee9991e0f5bd97650a06061504efffb9937d29ecfd77ad83e') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.4', 'Didaktische Differenzierung und Lernende', 1, 85, '', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.4.1', 'Die Didaktische Differenzierung zwischen Nachhilfe und regulärem Unterricht', 2, 86, 'Die Unterschiede zwischen meinem Nachhilfeangebot und dem schulischen Unterricht liegen aus meiner Sicht vor allem in den Rahmenbedingungen und in der Schwerpunktsetzung. Der Schulunterricht verfolgt gemeinsame curriculare Ziele und muss die Lernprozesse einer ganzen Klasse organisieren. Die Nachhilfe kann demgegenüber unter den Bedingungen kleiner Lerngruppen gezielter an individuellen Wissenslücken, Verständnisproblemen und Interessen ansetzen. Sie bietet mir die Möglichkeit, einen Unterrichtsgegenstand so lange aus verschiedenen Blickwinkeln zu bearbeiten, bis der Lernende seine wesentlichen Begriffe und Beziehungen nachvollziehbar erklären kann. Dies ist eine Beschreibung meines praktischen Vorgehens, keine Aussage, dass entsprechende Förderung im Schulunterricht grundsätzlich fehlt.\n\nIn meiner dreijährigen Praxis hat sich für die Nachhilfe ein Schwerpunkt auf stoffliche Vertiefung, allgemeine Verständniskontrolle und eigenständige Anwendung herausgebildet. Bei der Kontrolle beschränke ich mich nicht auf richtig oder falsch gelöste Aufgaben: Ich frage nach dem Warum eines Verfahrens, überprüfe die Verfügbarkeit vorausgesetzter Grundkenntnisse und lasse ähnliche Zusammenhänge in neuen Darstellungen oder Kontexten erläutern. Aus den erkennbaren Schwierigkeiten leite ich die Auswahl und den Schwierigkeitsgrad der nächsten individuell angepassten Arbeitsblätter ab. Diese wiederkehrende Arbeitsweise ist eine qualitative empirische Eigenbeobachtung aus meiner Nachhilfepraxis; ein vergleichender Nachweis höherer Lernwirksamkeit gegenüber dem Schulunterricht ist damit nicht erbracht. Die direkte Prüfung sämtlicher Rechenergebnisse und die fachliche Überprüfung des Verständnisses behandle ich dabei als unterschiedliche Aufgaben; mit zunehmendem Lernstand kann ein größerer Teil der Ergebniskontrolle von den Lernenden übernommen werden.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '9c80e7197698222571d68397ccdb161032d5c10cf8a0c48294f20630358683d3') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.4.2', 'Die Bedeutung der Bezugssysteme und der persönlichen Relevanz', 2, 90, 'Ein zentrales Thema meiner Nachhilfe ist das jeweilige Vorwissen der Lernenden, das ich in diesem Zusammenhang als persönliches didaktisches Bezugssystem bezeichne. Ich versuche, mathematische Themen mit bereits vertrauten Vorstellungen und geeigneten Beispielen zu verknüpfen und zugleich die fachlichen Grundlagen hinter einem Verfahren zu verdeutlichen. Die in Abschnitt 1.1 beschriebenen Unterrichtsbeobachtungen zeigen Schwierigkeiten beim Erfassen von Aufgabenangaben beziehungsweise beim Erklären einer linearen Funktion. Aus diesen Einzelfällen lässt sich jedoch nicht sicher schließen, dass fehlender Lebensweltbezug die Ursache war.\n\nFür meine Unterrichtsgestaltung ergibt sich daraus die Frage, ob Lernende die bearbeiteten Beziehungen auch unabhängig von der ursprünglichen Beispielaufgabe verstehen. Deshalb schließe ich an eine Erklärung gezielte Verständnisfragen, Varianten und Transferaufgaben an. Wenn eine Aufgabe richtig gerechnet, aber der zugehörige Zusammenhang nicht eigenständig erläutert werden kann, bildet dies in meiner Praxis einen Anlass für weitere Vertiefung. Ob die so gestaltete Nachhilfe zu nachhaltigeren Lernergebnissen führt, ist gesondert zu prüfen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '19f6c06c1553e138d07837071d620fa7ca0bdc2c96363f5ebbebfc2cb4658935') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.4.3', 'Die Lernenden', 2, 94, 'In meiner bisherigen Nachhilfepraxis begleite ich häufig Lernende, deren schulische Leistungen sehr unterschiedlich sind und die zum Teil erhebliche fachliche Schwierigkeiten mitbringen. Beobachtete Notenverteilungen aus meinen Gruppen sind bislang nicht nach einem einheitlichen Erhebungsverfahren dokumentiert worden. Deshalb verwende ich an dieser Stelle keine Prozentanteile als vermeintlich statistisch gesicherte Stichprobenbeschreibung. Die Ausgangsleistungen werden erst für die geplante Untersuchung nach festgelegten Kriterien erfasst. Eine konkrete anonymisierte Übersicht unterschiedlicher Klassenstufen und Schulformen innerhalb der Kursgruppen ist in Abschnitt 1.5 (Tabelle 1.1) dokumentiert; sie dient der Beschreibung der Lernumgebung, nicht als Nachweis von Lernerfolgen.\n\nFür die Unterrichtsgestaltung bedeutet dies, dass unterschiedliche Vorkenntnisse und Schwierigkeiten im Unterricht zu berücksichtigen sind. Standardisierte Erklärungen können hilfreich sein, müssen jedoch nicht für alle Lernenden ausreichen. Das Prinzip eines zunächst bewusst reduzierten Bezugssystems soll es ermöglichen, aufgabenrelevante Informationen schrittweise zu ordnen. Es setzt nicht voraus, dass die Lernenden tatsächlich ohne Vorwissen lernen können; vielmehr muss ich den Zusammenhang zu bereits vorhandenen Kenntnissen im Lernprozess untersuchen.\n\nDas Bezugssystem der Lernenden ist nicht mit einem mathematischen Koordinatensystem gleichzusetzen. Ich verwende den Ausdruck an dieser Stelle als didaktische Metapher für die jeweils verfügbaren Vorstellungen, Erfahrungen und Kenntnisse, mit denen Lernende Angaben einer Aufgabe einordnen. Ob die schrittweise explizite Darstellung funktionaler Beziehungen das eigene Verständnis und den Transfer unterstützt, bleibt Gegenstand der Untersuchung.\n\nBei der Bearbeitung einzelner Aufgaben nutze ich ein zunächst leeres Darstellungsblatt als methodisches Hilfsmittel, um aufgabenrelevante Angaben, Begriffe und Beziehungen schrittweise festzuhalten. Dieses aufgabenbezogene Vorgehen ist von der Concept-Map beziehungsweise dem Kompendium zu unterscheiden, die zu Beginn eines Themengebiets einen übergreifenden Überblick bereitstellen. Ich verbinde die Aufgabenbearbeitung in der Nachhilfe mit Fragen, Rückmeldungen und einer möglichst unterstützenden Lernatmosphäre. Ein nachweisbarer Lernvorteil folgt aus dieser Beschreibung noch nicht.\n\nMeine Erfahrungen als Nachhilfelehrer sowie meine Tätigkeiten als Verfahrenstechniker, IT-Projektleiter und Dozent helfen mir bei der Strukturierung von Aufgabenstellungen und bei der Gestaltung individueller Lernangebote. Das leere Bezugssystem setze ich in meiner Praxis als methodische Unterstützung ein. Ob diese Unterstützung zu nachweisbaren Verbesserungen beim Aufgabenverständnis, bei der eigenständigen Bearbeitung oder beim Transfer führt, muss ich anhand dokumentierter Lernverläufe und geeigneter Vergleichsmaßstäbe untersuchen.\n\nFür meine Unterrichtspraxis bildet dieses Vorgehen einen erprobungsbedürftigen Ausgangspunkt zur individuellen Anpassung von Aufgaben und Hilfen. Darin sehe ich einen möglichen Untersuchungsgegenstand des FRZK, nicht bereits ein gegenüber regulärem Unterricht überlegenes Verfahren.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '03cdb1d82f9aeb612e87e64fe6b68e89627bf71a05744ca7e41f91907806c11b') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.5', 'Die Lernumgebung und Unterrichtsführung', 1, 102, 'Meine Nachhilfe findet in Unterrichtsräumen der Schülerhilfe statt. Der hier beschriebene Raum verfügt über acht Plätze an einem quadratischen Tisch sowie über eine Tafel. Ich sitze gewöhnlich an einer Ecke des Tisches; auch einige Lernende bevorzugen bestimmte Plätze, die Platzwahl bleibt jedoch frei. Bei Bedarf ändere ich die Sitzordnung, beispielsweise um Gruppenarbeit zu ermöglichen, konzentriertes Arbeiten zu erleichtern oder den Zugang zum Laptop sicherzustellen.\n\nIch möchte den Unterrichtsraum so gestalten, dass die Lernenden einen persönlichen Bezug zu ihm entwickeln und sich dort wohlfühlen. Obwohl acht Plätze vorhanden sind, betreue ich in meinen Lerngruppen höchstens sechs Lernende gleichzeitig. Zwei Lerngruppen haben eigene Plakate mit den Aussagen „Mathe macht stark“ und „Ma(ke)the Best“ angebracht. Diese Texte entstanden ohne meine Vorgabe; ich verstehe sie als Hinweise auf die Haltung der betreffenden Lernenden, nicht als systematisch erhobene Ergebnisse.\n\nKursbelegung als dokumentierter Hinweis auf heterogene Lerngruppen.\n\nEin konkreter Einblick in die Zusammensetzung meiner Lerngruppen ergibt sich aus der ICAS-Kursbelegungsansicht für die Woche vom 9. bis 15. November 2026. Der bereitgestellte Ausschnitt enthält fünf Unterrichtsgruppen mit jeweils fünf oder sechs eingetragenen Lernenden, insgesamt 27 Kursbelegungen. Zwei Lernende sind in jeweils zwei Gruppen eingetragen; damit lassen sich im Ausschnitt 25 unterschiedliche Lernende anhand der Einträge unterscheiden. Die erfassten Klassenstufen reichen von 5 bis 12. Schon innerhalb einzelner Kurse treten Unterschiede von mehreren Klassenstufen sowie verschiedene Schulformkennzeichnungen auf. In einer Gruppe werden Aufgaben aus Mathematik und Physik parallel bearbeitet. Die nachfolgende Übersicht gibt nur anonymisierte Strukturmerkmale wieder.\n\nTabelle 1.1: Anonymisierte Kursbelegungen in fünf sichtbaren Lerngruppen. Quelle: ICAS-Kursübersicht, Woche 09.11.–15.11.2026, vom Autor bereitgestellter Bildschirmausschnitt; eigene Zählung. Die Schulformkürzel sind unverändert aus der Ansicht übernommen.\n\nDie Übersicht dokumentiert die aktuelle organisatorische Heterogenität: Beispielsweise umfasst Gruppe D die Klassenstufen 7, 9, 10 und 12. Die gleichzeitige Betreuung unterschiedlicher Jahrgangsstufen und teils unterschiedlicher Fächer verlangt voneinander abweichende Aufgaben, Rückfragen und Erklärungen. Dies ist ein wesentlicher Grund für den Einsatz persönlich angepasster Arbeitsblätter und für die in diesem Abschnitt beschriebene alters- und lernstandsabhängige Selbstkontrolle. Bei einer vollständigen Kontrolle aller Aufgaben durch den Tutor würde die für individuelle Hilfe verfügbare Zeit entsprechend eingeschränkt.\n\nDie Kursübersicht ist ein Beleg für eingetragene Belegungen einer einzelnen, zum Zeitpunkt des Screenshots noch bevorstehenden Kalenderwoche. Sie erlaubt keine Feststellung über tatsächliche Anwesenheit, regelmäßige Belegungsmuster über drei Jahre, individuelle Lernfortschritte oder die Wirksamkeit des FRZK. Für eine empirische Auswertung der Unterrichtspraxis müssen Belegung, Anwesenheit, Lernstand und Leistungsentwicklung getrennt dokumentiert werden. Der ursprüngliche Bildschirmausschnitt enthält personenbezogene Angaben minderjähriger Lernender und wird deshalb nicht unverändert in die Dissertation übernommen.\n\nDie 90-minütigen Lerneinheiten orientieren sich an vier aufeinanderfolgenden Phasen. Individuelle Fragen und Hilfestellungen erfolgen während der Arbeitsphase:\n\nBlitzlicht – 5 Minuten: Die Lernenden berichten kurz über Erlebnisse und benennen ihre aktuelle Stimmung.\n\nArbeitsphase – 75 Minuten: Themenbezogene Vertiefung mit persönlich angepassten Arbeitsblättern, Bearbeitung fachlicher Defizite, Ergebnisselbstkontrolle und fortlaufende allgemeine Verständniskontrolle, bei Bedarf mit Übertragungsaufgaben.\n\nNachhilfehefter – 5 Minuten: Die Lernenden ordnen die erarbeiteten Unterlagen in ihre nach einem einheitlichen Ablagesystem geführten Fachhefter ein.\n\nAbschlussreflexion – 5 Minuten: Die Lernenden berichten über ihre Arbeit und darüber, was sie verstanden haben; ich gebe dazu eine individuelle Rückmeldung.\n\nZu Beginn eines neuen Themengebiets erhalten die Lernenden von mir eine Concept-Map oder ein Kompendium. Dieses Material gibt einen fachlichen Überblick und macht wichtige Begriffe sowie Beziehungen sichtbar. Der anschließende Unterricht erfolgt themenbezogen und defizitorientiert mit persönlich angepassten Arbeitsblättern. Dabei vertiefe ich den Stoff, überprüfe fortlaufend, ob die Lernenden die fachlichen Zusammenhänge auch ohne unmittelbare Vorlage erklären können, und greife erkannte Lücken im Vorwissen auf. Zu den Verständnisprüfungen gehören Begründungsfragen, eigene Formulierungen, die Analyse von Fehlern und die Anwendung auf veränderte Aufgaben. Concept-Map oder Kompendium bleiben bei Bedarf als Nachschlage- und Orientierungsunterlagen verfügbar; sie ersetzen die individuelle Arbeitsblattarbeit nicht.\n\nDiese Abfolge aus thematischer Einführung, vertiefender Arbeitsblattarbeit und allgemeiner Verständniskontrolle habe ich über drei Jahre in meiner Nachhilfepraxis wiederholt angewandt und beobachtet. Nach meiner Praxiseinschätzung macht die zusätzliche Kontrolle über das bloße Rechenergebnis hinaus unterschiedliche Wissensstände und Verständnislücken sichtbar und ermöglicht mir, nachfolgende Aufgaben gezielter auszuwählen. Diese qualitative empirische Eigenbeobachtung wird durch Rückmeldungen von Lernenden und beobachtete schulische Leistungsentwicklungen ergänzt, die im Folgenden als eigene, unterschiedliche Beobachtungsarten ausgewiesen werden.\n\nRückmeldungen von Lernenden. Ergänzend zu meinen Unterrichtsbeobachtungen habe ich informelle Gespräche mit Schülerinnen und Schülern der 11. Gymnasialklasse geführt, die nach meiner Angabe bereits mindestens ein Jahr meine Nachhilfe besucht hatten. Die Lernenden beschrieben den wahrgenommenen Nutzen der Nachhilfe sinngemäß als deutlich bessere schulische Ausgangslage gegenüber einer Situation ohne diese Unterstützung. Für diese Gesprächsangabe liegen im hier ausgewerteten Material weder ein standardisierter Fragebogen noch vollständige Originalprotokolle oder eine gesicherte Anzahl befragter Personen vor (vgl. Nachweisstatus NB-16, Anlage 1B). Daher verwende ich sie ausschließlich als qualitative Selbsteinschätzung nach eigener Gesprächswiedergabe, nicht als systematisch ausgewertete Befragung oder Kausalbeleg.\n\nBerichtete Notenentwicklung. In den bereitgestellten Unterlagen finden sich Elternmitteilungen und abgeschriebene Online-Rezensionen, die Verbesserungen in Mathematik beschreiben. Eine Elternmitteilung berichtet über den Wechsel einer Zeugnisnote von 4 auf 3 (NB-07), eine übermittelte Online-Rezension über eine Verbesserung um zwei Notenstufen (NB-09). Weitere Rückmeldungen berichten allgemeiner über verbesserte Noten (NB-10, NB-11); ein Bericht über mehrere Lehrkräfte ist nicht eindeutig meiner Unterrichtstätigkeit zuzuordnen (NB-13). Originalzeugnisse, Vergleichszeitpunkte und vollständige schulische Verlaufsdaten liegen zu diesen Angaben im Prüfkorpus nicht vor. Die Angaben belegen somit elterlich berichtete Leistungsentwicklungen, keine unabhängig verifizierten Notenverläufe und erst recht keine kausal nachgewiesene FRZK-Wirkung.\n\nQualitative Fremdrückmeldungen zur Unterrichtsgestaltung\n\nFür die vorläufige explorative Sichtung habe ich eine vom Autor zusammengestellte Materialsammlung ausgewertet (private schriftliche Lernendenrückmeldungen, vom Autor redigierte Gesprächswiedergaben, Elternmitteilungen sowie übertragene Texte öffentlicher Rezensionen). Als Nachweisregister führe ich die einzelnen Fundstellen unter den Kennungen NB-01 bis NB-16 in Anlage 1B. Jede Kennung ist als Quelle, Textart, Aussagegehalt und Prüfstatus erläutert. Die Materialien wurden weder mit einem einheitlichen Fragenkatalog erhoben noch als vollständige Übersicht aller positiven und negativen Erfahrungen zusammengestellt. Deshalb handelt es sich um eine selektive qualitative Materialauswertung, nicht um eine repräsentative Befragung. Es werden keine Namen, Telefonnummern oder identifizierenden Details aus den Originalnachrichten in die Anlage übernommen.\n\nMehrere Rückmeldungen heben individuell vorbereitete Arbeitsblätter (NB-03, NB-14), eine feste Unterrichtsstruktur mit Blitzlicht und Reflexion (NB-03, NB-14) sowie wiederholte Erklärungen und gemeinsame fachliche Klärungen (NB-03, NB-14) hervor. Die Rückmeldung zur Einbeziehung eigener Lösungswege (NB-04) liegt als unmittelbar von einem Lernenden verfasste Ergänzung vor. Die fünfteilige Beschreibung zu NB-03 wurde hingegen vom Autor redigiert und dem Lernenden zur Verwendung vorgelegt; sie ist daher keine wortgetreue Verschriftlichung einer Schüleräußerung. Eine weitergehende Fassung wurde später vorgeschlagen, aber im vorliegenden Material nicht ausdrücklich bestätigt (NB-05) und deshalb nicht als Schülerrückmeldung ausgewertet.\n\nTabelle 1.2 ordnet die identifizierten Unterrichtsmerkmale den konkreten Fundstellen aus Anlage 1B zu. Mehrfachnennungen und mögliche Identitätsüberschneidungen werden nicht als statistisch unabhängige Antworten gewertet. Die Einträge zeigen, welche Merkmale in den vorliegenden Fremdrückmeldungen beschrieben werden, nicht wie häufig sie in der Grundgesamtheit vorkommen oder ob sie in jeder Stunde nachweislich umgesetzt wurden.\n\nTabelle 1.2: Qualitativ identifizierte Merkmale der Unterrichtsführung. Quelle: Materialsammlung „meine Bewertungen.txt“, eigene vorläufige Kategorisierung. Die Belegkennungen NB-xx verweisen auf das pseudonymisierungsarme Nachweisregister in Anlage 1B. Originalplattformen, berichtete Noten und Urheberschaften übertragener Rezensionstexte wurden nicht unabhängig überprüft.\n\nMethodische Grenzen der Rückmeldungen. Die Sammlung ist positiv selektiert und enthält auch bloße Entwürfe, vom Autor redigierte Gesprächszusammenfassungen und Verwaltungsnotizen. NB-05, NB-06, NB-08 und NB-15 werden nicht als bestätigte Lernendenbewertungen in die Befundbildung aufgenommen. Für NB-02 und NB-03 ist eine schriftliche Zustimmung der betreffenden Lernenden zur anonymisierten Verwendung der jeweils vorgelegten Formulierungen dokumentiert; diese Zustimmung ersetzt nicht automatisch weitere erforderliche datenschutz- oder sorgeberechtigtenbezogene Prüfungen. Die Einzeläußerung NB-04 ist ein direkter Zusatz desselben Lernenden wie NB-03 und kein zweiter unabhängiger Fall. Mögliche Überschneidungen zwischen persönlichen Mitteilungen und Plattformrezensionen sind nicht auflösbar; daher wird weder eine Zahl unabhängiger Personen noch eine Zufriedenheitsquote ausgewiesen. Kritik, Nichtteilnahme und ausbleibende Rückmeldungen wurden nicht systematisch erfasst.\n\nAbgrenzung zum FRZK. Das anonymisierte Register dokumentiert Aussagen über meine bereits bestehende Nachhilfepraxis: Vorbereitung, angepasste Aufgaben, Lernbeziehung, Reflexion, individuelle Erklärungen und wahrgenommene Lernentwicklungen. Die beschriebenen Leistungen dürfen nicht als Wirkung des erst gesondert zu untersuchenden FRZK-Darstellungsrahmens gewertet werden. Weder der anfängliche Einsatz einer Concept-Map beziehungsweise eines Kompendiums noch die ungefähren prozentualen Kontrollmodelle sind durch die vorliegenden Fremdrückmeldungen als solche ausdrücklich belegt. Sie bleiben zunächst Aussagen über meine eigene Unterrichtsorganisation.\n\nErgebniskontrolle, Selbstkontrolle und Betreuungszeit\n\nDie beiden folgenden Orientierungsmodelle zur Unterrichtsorganisation beruhen auf wiederholten qualitativen Eigenbeobachtungen aus drei Jahren Nachhilfepraxis. Sie wurden weder durch standardisierte Zeitmessungen noch durch eine systematische Zählung aller Arbeitsergebnisse gewonnen und sind deshalb keine statistisch abgesicherten Verteilungen oder nachgewiesenen optimalen Unterrichtsquoten. Das erste Modell beschreibt, wer Arbeitsergebnisse kontrolliert; das zweite Modell betrifft die inhaltliche Gewichtung von Übungsrechnen und Problembearbeitung. Beide Modelle dürfen nicht miteinander gleichgesetzt werden. Unter Ergebniskontrolle verstehe ich die Prüfung bearbeiteter Aufgaben und Resultate. Davon unterscheide ich die allgemeine Verständniskontrolle anhand von Rückfragen zu Begriffen, Begründungen und Übertragungen, die unabhängig von der Klassenstufe Bestandteil meiner Betreuung bleibt.\n\nFür den ungefähren Anteil der durch mich unmittelbar kontrollierten Arbeitsergebnisse haben sich die in Tabelle 1.3 dargestellten, lernstandsabhängig anpassbaren Richtwerte herausgebildet:\n\nTabelle 1.3: Erfahrungsbasierte Aufteilung der Ergebniskontrolle nach Lernstufen. Eigene qualitative Praxisbeobachtungen aus drei Jahren Nachhilfe; keine standardisierte Messung.\n\nDie Lösungen in den Arbeitsblättern ermöglichen den Lernenden einen eigenständigen Abgleich ihrer Ergebnisse und, soweit vorhanden, ihrer Rechenwege. Erkannte Abweichungen führen zu erneuter Bearbeitung oder zu gezielten Rückfragen. Meine unmittelbare Kontrolle konzentriert sich bei älteren Lernenden stärker auf ausgewählte Aufgaben, erkennbare Fehlerschwerpunkte und die Überprüfung des fachlichen Verständnisses. Die Zuordnung in Tabelle 1.3 stellt keine starre Altersnorm dar: Lernstand, Aufgabenschwierigkeit und Bedarf an Unterstützung können eine andere Verteilung erfordern.\n\nDie Verlagerung geeigneter Ergebniskontrollen in die Eigenverantwortung hat auch organisatorische Gründe. Während einer 75-minütigen Arbeitsphase betreue ich zeitweise bis zu sechs Lernende unterschiedlicher Klassen- und Studienjahre. Würde ich für die vollständige Kontrolle der Aufgaben jedes Lernenden jeweils zehn Minuten ansetzen, ergäben sich rechnerisch 6 × 10 = 60 Minuten. Von der Arbeitsphase blieben dann nur 15 Minuten für individuelle Erklärungen, die Bearbeitung anderer Schwierigkeiten und allgemeine Verständniskontrollen. Wechsel- und Unterbrechungszeiten sind dabei noch nicht berücksichtigt. Diese Modellrechnung veranschaulicht einen möglichen Zeitkonflikt; sie ist keine standardisierte Zeitmessung.\n\nAus meiner Unterrichtserfahrung wäre eine durchgängige vollständige Ergebniskontrolle sämtlicher Aufgaben durch mich bei sechs gleichzeitig betreuten Lernenden pädagogisch nicht angemessen: Die Zeit für die individuelle Betreuung der anderen Lernenden würde zu stark eingeschränkt. Die angeleitete Selbstkontrolle erhält daher eine doppelte Funktion: Sie unterstützt das eigenständige Arbeiten und schafft Betreuungszeit für fachliche Rückfragen und gezielte Vertiefung. Daraus folgt noch kein Nachweis einer höheren Lernwirksamkeit.\n\nIn der geplanten systematischen Untersuchung sollen die tatsächlich vom Tutor überprüften Arbeitsergebnisse, die selbst kontrollierten Lösungen, dabei unerkannte Fehler sowie zusätzliche Hilfestellungen gesondert dokumentiert werden. Auf diese Weise lassen sich die bisherigen Richtwerte später anhand nachvollziehbarer Beobachtungen prüfen.\n\nGewichtung von Übungsrechnen und Problembearbeitung\n\nTabelle 1.4: Erfahrungsbasierte inhaltliche Schwerpunktsetzung in der Arbeitsphase. Die Anteile beschreiben eine ungefähre Planungspraxis, keine gemessenen Zeiten und keine allgemeinen Empfehlungen.\n\nDie zweite Einteilung beschreibt die von mir bevorzugte Gewichtung fachlicher Arbeitsschwerpunkte, nicht die Zeit für persönliche Ergebniskontrolle. Sie wird an individuelle Lernstände, Themen und Aufgaben angepasst; insbesondere kann notwendiges Übungsrechnen auch in höheren Klassen einen größeren Umfang erhalten. Die Angaben in den Tabellen 1.3 und 1.4 sind daher als erfahrungsbasierte, noch zu überprüfende Orientierung zu verstehen. Aus ihnen lässt sich weder eine allgemeingültige optimale Verteilung noch ein kausaler Einfluss auf schulische Leistungen oder auf die Wirksamkeit des FRZK ableiten.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '7b38280003671f54e708804feca549af0831dd245d3bbf1813cc105d1c4aadcd') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.6', 'Forschungsstand und wissenschaftlicher Kontext', 1, 142, '', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.6.1', 'Physikalische Perspektiven: Emergenz von Raumzeit', 2, 143, 'Einige Ansätze der theoretischen Physik untersuchen, ob bestimmte Raumzeit- oder Gravitationseigenschaften aus tieferliegenden Strukturen hervorgehen können (Rovelli, Carlo (2016). Reality Is Not What It Seems: The Journey to Quantum Gravity. London: Penguin.)[13] (Verlinde, Erik P. (2017). Emergent Gravity and the Dark Universe. SciPost Physics, 2(3), Artikel 016. DOI: 10.21468/SciPostPhys.2.3.016.)[14]. Diese Ansätze sind nicht allgemein bestätigte Aussagen über die Entstehung der Raumzeit und stellen keinen physikalischen Gültigkeitsbeleg für das FRZK dar. Für meine Arbeit dienen sie ausschließlich als Beispiel dafür, warum die Unterscheidung von Grundannahmen und abgeleiteten Modellgrößen wichtig ist.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'cbfebed7e1bd539c02fae06440ea84d4c589ee0c85c67f95b402d5343d74a280') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.6.2', 'Systemtheoretische und kybernetische Ansätze', 2, 145, 'Systemtheoretische und kybernetische Arbeiten untersuchen unter anderem Rückbezüge, Beobachtungsbedingungen und die Abhängigkeit von Beschreibungen [2][3]. Für mein Vorhaben ist dies ein möglicher begrifflicher Vergleichsrahmen. Ich setze jedoch weder eine rekursive Selbstbezüglichkeit noch eine besondere Beobachterstruktur als notwendige Eigenschaft sämtlicher im FRZK dargestellter Funktionen voraus.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '56bb90b7889f6b1549a08cb522e09f27f184e7804b354545536ffe42fbb28125') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.6.3', 'Didaktische und bildungswissenschaftliche Modelle', 2, 147, 'In der didaktischen und bildungswissenschaftlichen Forschung bestehen bereits mehrere Ansätze, die einzelne Aspekte meines Vorhabens berühren. Die Abgrenzung des FRZK muss deshalb bei konkreten Funktionen und prüfbaren Unterschieden ansetzen, nicht bei der bloßen Verwendung der Wörter „Struktur“, „Beziehung“ oder „Bezugssystem“. Für meine Untersuchung sind die Repräsentation fachlichen Wissens, das Bearbeiten mathematischer Probleme, die lernprozessbezogene Rückmeldung und das selbstregulierte Lernen von besonderer Bedeutung.\n\nConcept-Maps werden in der Literatur als grafische Werkzeuge zur Organisation und Darstellung von Wissen beschrieben. Novak und Cañas erläutern, dass Begriffe durch beschriftete Beziehungen zu sinnvollen Aussagen verknüpft werden können (Novak; Cañas, 2008, S. 1) [16]. In meiner Nachhilfepraxis dienen Concept-Maps oder Kompendien zu Beginn eines Themas der fachlichen Orientierung. Die anschließende Bearbeitung erfolgt überwiegend mit individuell angepassten Arbeitsblättern. Daraus folgt weder, dass diese Einführung bereits das FRZK darstellt, noch dass eine grafische Übersicht als solche eine methodische Neuerung ist.\n\nDer Umgang mit mehreren Darstellungsformen ist ebenfalls wissenschaftlich untersucht. Ainsworth differenziert in ihrem DeFT-Rahmen zwischen der Gestaltung multipler Repräsentationen, ihren Funktionen und den kognitiven Anforderungen an die Lernenden. Ihr Beitrag zeigt zugleich, dass mehrere Darstellungen allein keinen Lernerfolg garantieren (Ainsworth, 2006, S. 183–198, insbesondere S. 183) [17]. Bei mathematischen Aufgaben unterscheide ich daher sprachliche Aufgabenbeschreibung, Gleichung, grafische Veranschaulichung und Bedeutung der Variablen. Ob der zusätzliche FRZK-Rahmen diese Übergänge erleichtert, ist eine offene Frage; der bloße Wechsel von Darstellungen ist keine FRZK-spezifische Leistung.\n\nFür das mathematische Problemlösen beschreibt Schoenfeld einen Analyseansatz, der kognitive Ressourcen, heuristische Strategien, Kontrolle des Lösungsprozesses und Überzeugungen unterscheidet (Schoenfeld, 1985) [18]. Die bibliografischen Angaben und diese thematische Gliederung sind durch den Verlag nachweisbar; eine auf einzelne Buchseiten bezogene Originalstellenprüfung steht noch aus. Meine Unterrichtsbeobachtungen zu Textaufgaben und linearen Funktionen lassen sich damit vorläufig in einen etablierten Forschungszusammenhang einordnen. Weder das Erkennen relevanter Angaben noch das Reflektieren eines Lösungswegs kann daher ohne weitere Abgrenzung als neu ausgewiesen werden.\n\nZur Rückmeldung und Verständniskontrolle unterscheiden Hattie und Timperley unter anderem Feedback zur Aufgabe, zum Bearbeitungsprozess und zur Selbstregulation (Hattie; Timperley, 2007, S. 86 und 90) [19]. Damit ist fachlich zu trennen, ob ich eine korrekte Endlösung kontrolliere, einen Lösungsweg bespreche oder die selbstständige Fehlerprüfung eines Lernenden fördere. Für meine altersabhängige Verlagerung der Ergebniskontrolle auf die Lernenden ist ergänzend die Forschung zur Selbstregulation einschlägig: Zimmerman beschreibt unter anderem Zielsetzung, Selbstbeobachtung, Selbstbewertung und Reflexion (Zimmerman, 2002, S. 64 und 68) [20]. Die in Abschnitt 1.5 genannten Prozentwerte bleiben gleichwohl empirische Richtwerte meiner Praxis und werden nicht durch diese Literatur als optimale Stufenmodelle bestätigt.\n\nDie Einzelförderung und die Unterschiede zur Gruppenunterrichtung werden unter anderem bei Bloom (1984) [21] thematisiert. Der historische Beitrag zu individuellen Tutorbedingungen ist ein Vergleichsrahmen, keine direkte Untersuchung meiner fachlich und altersmäßig heterogenen Nachhilfegruppen mit bis zu sechs Lernenden. Die Metadaten und der Untersuchungsgegenstand sind bibliografisch gesichert; der vollständige Primärtext wurde für die hier vorgelegte Stellenprüfung nicht ausgewertet. Aus Bloom leite ich deshalb weder eine bestimmte Effektstärke meiner Nachhilfe noch eine Überlegenheit gegenüber dem Schulunterricht ab.\n\nAls entwicklungsorientierter methodischer Bezugspunkt bleibt Design-Based Research relevant (Reinmann, 2005) [4]. Ein solcher Bezug erfordert die überprüfbare Dokumentation der Entwicklung, Erprobung, Rückmeldung und gegebenenfalls Überarbeitung des Verfahrens. Die bereits vorliegenden qualitativen Bewertungen aus Anlage 1B dokumentieren meine bestehende Unterrichtspraxis; sie ersetzen weder eine systematische Untersuchung der FRZK-Anwendung noch eine gezielte Gegenüberstellung mit bestehenden Verfahren.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '465725610dfea0c961e0c2a31a4bc7a3b0fb778a5c98773c0e5f57be5e4ccbff') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.6.4', 'Interdisziplinäre Verortung des FRZK', 2, 155, 'Die theoretischen Anknüpfungen betreffen unterschiedliche Ebenen: mathematische Modellierung und formale Gültigkeit, didaktische Darstellung und Unterrichtsorganisation sowie die Beobachtung von Lernprozessen. Systemtheorie und theoretische Physik dienen mir zur begrifflichen und methodischen Orientierung; die didaktische Begründung des Lernverfahrens muss hingegen auf einschlägiger Bildungs- und Mathematikdidaktik beruhen. Die gemeinsame Verwendung von Begriffen wie „Beobachtung“, „Orientierung“ oder „Kohärenz“ stellt keine Identität dieser Theorien her und belegt weder neue physikalische Gesetze noch die Wirksamkeit des FRZK.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '710a254c7ba41661b6d776a2069432a6dd3514f61bc6146c88dbbeed4b2cc8aa') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.6.5', 'Abgrenzung bestehender Verfahren und vorläufige Forschungsfrage', 2, 157, 'Concept-Maps strukturieren Begriffe und deren Beziehungen; in meiner Praxis eröffnen sie ein Thema. Multiple Repräsentationen, Problemlösestrategien sowie Feedback- und Selbstregulationsmodelle beschreiben weitere etablierte Aspekte des Lernprozesses [16][17][18][19][20]. Das FRZK beansprucht demgegenüber zunächst die Funktion eines ausdrücklich beschriebenen methodischen Vorgehens, das von der Problemformulierung über die Unterscheidung von Gegebenem und Gesuchtem, die Prüfung von Voraussetzungen und Zusammenhängen bis zur Entwicklung, Ausführung und Kontrolle einer Lösung reicht. Die mathematischen Erweiterungen des FRZK, insbesondere besondere Symbole und Operationen für Grenzwert- und Vektorprobleme, sind davon zu trennen. Ob die methodische Abfolge gegenüber bestehenden Problemlösestrategien eigenständig ist, muss kritisch verglichen und nicht bloß behauptet werden.\n\nEin möglicher didaktischer Zusatznutzen folgt nicht schon aus einem geordneten Arbeitsblatt, einer Concept-Map oder einer ausführlicheren Erklärung. Zu prüfen ist, ob ein zusätzlich explizit durchlaufener und dokumentierter FRZK-Problemlöseweg bei vergleichbarer Aufgabenstellung und Tutorunterstützung zu nachvollziehbareren Begründungen, früherer Fehlererkennung oder besserem Transfer führt. Die besonderen Grenzwert- und Vektorzeichen sind für diese allgemeine Intervention nicht erforderlich. Gleiche Unterrichtsbedingungen ohne den zusätzlich festgelegten Ablauf bilden die Vergleichsbasis. Positive Rückmeldungen und Notenentwicklungen aus meiner bisherigen Nachhilfe belegen noch keinen solchen Zusatznutzen.\n\nDie herangezogenen Arbeiten belegen, dass wesentliche Einzelbestandteile des beschriebenen Vorgehens bereits Forschungsgegenstände sind. Die vorliegende Auswahl ist jedoch keine vollständige systematische Recherche zu allen formalen Darstellungs- und Modellierungsverfahren. Dass hier kein mit dem vorgeschlagenen FRZK identisches Verfahren dargestellt wird, beweist deshalb weder seine weltweite Neuheit noch die Nichtexistenz verwandter Ansätze. Eine belastbare Neuheitsbehauptung verlangt eine gesonderte, methodisch dokumentierte Recherche und eine präzise Gegenüberstellung definierter Merkmale.\n\nFür die nachfolgenden Kapitel bestehen drei voneinander zu unterscheidende Prüfaufgaben: Erstens ist das methodische Grundgerüst des FRZK nachvollziehbar zu beschreiben und gegenüber vorhandenen Verfahren abzugrenzen. Zweitens müssen seine gesonderten mathematischen Erweiterungen auf definierte Bereiche, formale Konsistenz und mögliche Gegenbeispiele geprüft werden. Drittens ist ein möglicher didaktischer Zusatznutzen empirisch zu untersuchen. Die Prüfung einer Ebene ersetzt nicht die Prüfung einer anderen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '4da17d596f313a679615191b0faea00f237d98367c1aabeaa557a3efa4c7fb5d') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.7', 'Forschungsziel', 1, 162, 'Ich unterscheide die Entwicklung des FRZK als methodischen Ansatz zur Problemstellung und Problemlösung von seinen zusätzlichen mathematischen Symbol- und Operationssystemen. Davon gesondert ist zu prüfen, ob das methodische Vorgehen im Unterricht Vorteile gegenüber der bestehenden Praxis bietet. Aus dieser Trennung ergeben sich methodische, formale und didaktische Forschungsfragen mit unterschiedlichen Geltungsbereichen.\n\nMit dem Funktionalen Raum-Zeit-Kohärenzsystem (FRZK) möchte ich Aufgaben so bearbeiten, dass aus einer zunächst zu klärenden Problemstellung ein begründeter, überprüfbarer Lösungsweg entsteht. Die methodische Abfolge umfasst Problemformulierung, Bestimmung der Angaben und Zielgrößen, Klärung der Voraussetzungen und Beziehungen, Entwicklung und Durchführung der Lösung sowie Ergebnisprüfung. Eine grafische oder formale Darstellung kann diesen Ablauf stützen, ist jedoch nicht selbst mit ihm gleichzusetzen. Der Ansatz beansprucht damit weder die Erzeugung physikalischer Raumzeit noch eine besondere mathematische Symbolik als universelle Voraussetzung.\n\nDie erste Forschungsfrage lautet, wie sich dieser problemorientierte Ablauf so präzisieren lässt, dass er in verschiedenen mathematischen und gegebenenfalls weiteren fachlichen Situationen nachvollziehbar angewendet werden kann. Für konkrete Aufgaben sind die erforderlichen Größen, Annahmen, funktionalen Beziehungen und Gültigkeitsbedingungen jeweils ausdrücklich anzugeben. Besondere Fälle wie Rekursion, Rückbezug oder Kohärenzprüfung und die Verwendung spezieller Grenzwert- oder Vektorzeichen verlangen gesonderte Definitionen; sie gehören nicht notwendig zum allgemeinen methodischen Ablauf.\n\nEin zweiter Forschungsgegenstand betrifft die formale Prüfung eigens eingeführter mathematischer FRZK-Erweiterungen. Zu klären ist, für welche definierten Mengen, Zustände und Operatoren die jeweiligen Rechenregeln widerspruchsfrei und reproduzierbar angewendet werden können. Diese Frage ist von der Verständlichkeit des methodischen Problemlösewegs ebenso zu trennen wie vom empirischen Nachweis einer didaktischen Wirkung.\n\nDie didaktische Forschungsfrage lautet, ob und unter welchen Bedingungen die systematische Anwendung des beschriebenen Problemlösewegs das Aufgabenverständnis, die Auswahl und Begründung eines Verfahrens, die Fehlererkennung, die Ergebniskontrolle und die Übertragung auf neue Aufgaben unterstützt. Dabei ist die ausdrückliche Trennung zwischen Problemfrage, gegebenen Informationen, gesuchten Größen, Voraussetzungen und funktionalen Beziehungen ein möglicher, aber nicht der einzige Wirkmechanismus.\n\nErgänzend frage ich, wie die Nachvollziehbarkeit solcher Darstellungen beurteilt werden kann: Welche Merkmale machen einen Lösungsweg überprüfbar, welche Voraussetzungen müssen offengelegt werden und wie lassen sich Schwierigkeiten in der Anwendung des FRZK selbst dokumentieren? Dabei berücksichtige ich ausdrücklich auch Fälle, in denen der Ansatz keinen erkennbaren Zusatznutzen bietet.\n\nDiese Fragen bestimmen die Gliederung der Untersuchung. Zunächst arbeite ich die relevanten wissenschaftlichen Bezüge und die mathematischen Voraussetzungen heraus. Darauf folgen die Beschreibung des Modellierungsrahmens sowie seine fachliche und didaktische Prüfung. Ein interner Konsistenznachweis ersetzt keine empirische Untersuchung.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'b222d6c8fb25859c8af569d3cdaed842655723134dcfc80c29c5c312b2129d4e') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.7.1', 'Forschungsfragen und prüfbarer Zusatznutzen', 2, 170, 'Forschungsgegenstand.  Ich untersuche drei getrennte Gegenstände: erstens das FRZK als methodischen Ablauf vom Formulieren bis zum Lösen und Prüfen einer Problemstellung; zweitens die fachliche Gültigkeit gesondert definierter mathematischer Erweiterungen für Grenzwert- und Vektoraufgaben; drittens den möglichen didaktischen Zusatznutzen eines ausdrücklich angewendeten FRZK-Problemlösewegs gegenüber der bereits etablierten Nachhilfepraxis. Die positiven Schüler- und Elternrückmeldungen aus Anlage 1B charakterisieren diese Praxis; sie sind keine Interventionsdaten zur Wirksamkeit des FRZK.\n\nPrimäre didaktische Frage (F1).  Verbessert die zusätzliche, ausdrücklich dokumentierte Anwendung des methodischen FRZK-Problemlösewegs bei fachlich vergleichbaren Aufgaben und vergleichbarer Tutorunterstützung die Nachvollziehbarkeit einer selbstständig entwickelten Lösung gegenüber der üblichen themen- und defizitorientierten Bearbeitung? Als primärer Vergleichswert ist ein vorab fixierter Summenwert aus vier Kriterien von 0 bis 12 Punkten vorgesehen. Sonderzeichen der Grenzwert- und Vektorrechnung sind für diesen allgemeinen Vergleich nicht vorgesehen.\n\nSekundäre Fragen (F2–F4). F2: Erkennen Lernende fachliche Fehler oder unzulässige Annahmen früher bzw. selbstständiger? F3: Übertragen sie eine erarbeitete Beziehung auf eine neue, strukturell vergleichbare Aufgabe? F4: Welchen zusätzlichen Zeit- und Unterstützungsbedarf erzeugt die Darstellung, und in welchen Lernstufen oder Aufgabentypen erscheint sie hilfreich, entbehrlich oder hinderlich? Eine erwartete positive Wirkung ist eine Arbeitshypothese, kein bereits vorliegendes Ergebnis. Nullbefunde und Nachteile gehören zum Untersuchungsgegenstand.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'b249efbf6221dd279574f735a7bbbdf1b76377263832a04963651e0513dfd528') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.7.2', 'Präzise Definition der beiden Bearbeitungsbedingungen', 2, 174, 'Gemeinsame Unterrichtsbasis. Beide Bedingungen finden innerhalb der regulären, 90-minütigen Nachhilfe statt. Der Themenbeginn kann durch eine Concept-Map oder ein Kompendium vorbereitet werden; anschließend arbeite ich mit persönlich angepassten Aufgabenblättern, fachlichen Rückfragen, vertiefenden Erklärungen, einer altersabhängigen Ergebnisselbstkontrolle und einer Abschlussreflexion. Diese Bestandteile sind keine FRZK-spezifische Intervention. Die festgelegte Unterrichtsorganisation mit Blitzlicht, Arbeitsphase, Hefterführung und Auswertung bleibt unverändert.\n\nBedingung K (übliche Bearbeitung). Lernende bearbeiten eine fachlich passende Aufgabe mit den gewohnten Hilfen und zugelassenen Lösungsdarstellungen. Sie dürfen Angaben unterstreichen, Skizzen anfertigen, Formeln verwenden, nachfragen und Lösungen selbst kontrollieren. Es wird jedoch kein zusätzliches verpflichtendes FRZK-Protokoll vorgegeben. Bereits vorhandene Strukturierungsstrategien werden nicht künstlich unterbunden; ihr Auftreten wird im Protokoll vermerkt.\n\nBedingung F (zusätzlicher FRZK-Schritt).  Bei identischer fachlicher Zielsetzung bearbeiten Lernende die Aufgabe mithilfe eines einseitigen, vorab festgelegten FRZK-Problemlösebogens mit fünf Schritten: (1) die Problemfrage und das Ziel verständlich formulieren, (2) Gegebenes und Gesuchtes unterscheiden, (3) erforderliche Annahmen, Größen und Beziehungen begründet festlegen, (4) einen Lösungsweg entwickeln und ausführen und (5) Ergebnis, Gültigkeit und Übertragbarkeit prüfen, soweit fachlich sinnvoll. Die Schritte sind anhand der Schülerlösung nachvollziehbar. Spezielle FRZK-Grenzzeichen, Nullzustände oder Vektoroperationen gehören nicht zum methodischen Grundgerüst und werden in diesem allgemeinen Unterrichtsvergleich nicht verlangt.\n\nIsolierung des Unterschieds. Zwischen K und F darf nicht zugleich die Qualität des Arbeitsblatts, die verfügbare Arbeitszeit, die Intensität der Tutorhilfe oder der Zugang zu Lösungen verändert werden. Die FRZK-Bearbeitung erfolgt innerhalb derselben vorgesehenen Aufgabenzeit. Zusätzliche Hilfen, Zeitüberschreitungen und unvorhergesehene Abweichungen werden erfasst. Die vollständige Beschreibung von Materialien, Durchführung, Anpassungen und tatsächlicher Anwendung orientiert sich ergänzend an der TIDieR-Berichtsstruktur [22]; diese stammt aus der Interventionsforschung und wird hier nur als Dokumentationshilfe, nicht als Wirksamkeitsnachweis verwendet.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'c0d393c2ad37c0e366acde21d40b693172584a06beba4efad52cca9b75426e00') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.7.3', 'Untersuchungsanlage, Stichprobe und Vergleichbarkeit', 2, 179, 'Explorative Planung. Vorgesehen ist eine kleine, nicht repräsentativ gezogene Gelegenheitsstichprobe von ungefähr 25 Lernenden aus unterschiedlichen Schularten und Klassen- bzw. Studienjahren. Die sichtbaren Kursbelegungen aus Tabelle 1.1 entsprechen nicht automatisch der späteren Forschungsstichprobe. Einschlusskriterien, Einwilligungen, verfügbare Lernende, Teilnahmezeitraum, Ausgangsleistungen sowie dokumentierte Ausschlüsse werden vor Beginn der Auswertung festgelegt. Aussagen über eine repräsentative Gesamtpopulation sind nicht beabsichtigt.\n\nAufgabenpaare. Für vorab bestimmte Stoffgebiete werden Aufgabenpaare konstruiert, die denselben mathematischen Kompetenzbereich, ähnliche Rechenanforderungen und einen vergleichbaren sprachlichen Schwierigkeitsgrad aufweisen. Mindestens ein Aufgabenpaar umfasst das Identifizieren relevanter Angaben, ein anderes die Erklärung funktionaler Beziehungen; eine neue Transferaufgabe wird gesondert bereitgestellt. Eine fachkundige zweite Person prüft die Vergleichbarkeit der Aufgaben, bevor die eigentliche Untersuchung beginnt. Die Aufgaben einschließlich Musterlösungen werden versioniert archiviert.\n\nZuordnung und Reihenfolge. Wenn durchführbar, bearbeitet ein Lernender mehrere vergleichbare Aufgaben unter beiden Bedingungen; die Reihenfolge K→F bzw. F→K wird nach einem vorab dokumentierten Plan ausbalanciert. Eine zufällige Zuordnung wird nur dann berichtet, wenn sie tatsächlich durchgeführt und protokolliert wurde. Lern- und Übertragungseffekte sind besonders kritisch, weil einmal erlernte FRZK-Schritte in späteren K-Aufgaben weiterverwendet werden können. Ein solcher Übertrag ist keine Verletzung durch den Lernenden, sondern ein möglicher Störfaktor und zugleich ein zu dokumentierender Befund. Falls er die Trennung der Bedingungen verhindert, beschränke ich die Auswertung auf Machbarkeit und beschreibende Beobachtungen oder verwende ein prospektiv begründetes anderes Vergleichsdesign.\n\nUnterrichtsalltag als Kontext. Die Lerngruppen können bis zu sechs Personen mit unterschiedlichen Klassenstufen umfassen. Für die Untersuchungsaufgaben muss daher festgelegt werden, welche Zeitfenster, individuellen Tutorhinweise und äußeren Unterbrechungen zulässig sind. Die reguläre Förderung anderer Lernender darf durch die Datenerhebung nicht beeinträchtigt werden. Fachlich notwendige Hilfen werden aus pädagogischen Gründen nicht verweigert, sondern mit Zeitpunkt, Art und Umfang protokolliert.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '1eb01c342175b4079328bb799227e9f47c6733c0cc4516c0d1c5c44ec19cfc54') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.7.4', 'Messinstrumente und Bewertungsregeln', 2, 184, 'Primärer Zielwert. Der Lösungsweg wird mit einem vierdimensionalen Bewertungsraster beurteilt: A – korrekte Bestimmung gegebener und gesuchter Größen; B – Beschreibung funktionaler Beziehungen und wesentlicher Gültigkeitsbedingungen; C – fachlich begründete Wahl und Durchführung des Lösungsverfahrens; D – selbstständige Übertragung auf eine neue, strukturell ähnliche Aufgabe. Jede Dimension erhält 0 bis 3 Punkte, insgesamt 0 bis 12 Punkte. Der Transferwert D wird ausschließlich aus einer gesonderten, vorab festgelegten Transferaufgabe ermittelt, nicht aus der Wiederholung des vorgeführten Lösungswegs. Die vorläufigen Ankerbeschreibungen stehen in Anlage 1D.\n\nBewertungsvoraussetzungen. Vor Beginn der Hauptdatenerhebung werden die Aufgaben und die vollständigen Ankerbeispiele für die Punktstufen 0, 1, 2 und 3 fachlich erprobt, erforderlichenfalls überarbeitet und anschließend als feste Version freigegeben. Die Punktzahl 0–12 ist eine entworfene, nicht bereits validierte Bewertungsskala. Lösungen werden nach Möglichkeit ohne Angabe der Bearbeitungsbedingung pseudonymisiert durch eine zweite fachkundige Person bewertet; Abweichungen zwischen den Bewertungen werden dokumentiert. Eine Anpassung des Rasters an bereits beobachtete gewünschte Ergebnisse ist ausgeschlossen.\n\nWeitere Beobachtungsgrößen. Sekundär werden Bearbeitungszeit und gegebenenfalls Zeitüberschreitung, fachliche Fehlerarten, selbstständig bemerkte und korrigierte Fehler, Häufigkeit und Art von Tutorhinweisen, tatsächlich geleistete Selbstkontrolle sowie vollständig, teilweise oder nicht ausgeführte FRZK-Schritte protokolliert. Notenänderungen und die bereits vorliegenden Bewertungen der Nachhilfepraxis gehören nicht zum primären FRZK-Vergleich.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '210112eb9688115403e27cad60a4eb09bb357a295716d16379b244f6a5fb61dd') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.7.5', 'Datenerhebung, Dokumentation und Qualitätssicherung', 2, 188, 'Sitzungsprotokoll. Zu jeder ausgewerteten Aufgabenbearbeitung sind mindestens pseudonymisierte Kennung, Klassen- oder Studienjahr, Aufgaben- und Materialversion, Stoffgebiet, Datum, Bedingung K/F, Zuordnungs- und Reihenfolgeplan, Dauer, Hilfen, Selbstkontrolle, unerwartete Ereignisse sowie die archivierte Schülerlösung zu dokumentieren. Die Datenerfassung erfolgt in meiner didaktisch-methodischen Datenbank. Deren konkrete technische Bezeichnung, Datenmodell, Zugriffsrechte und Prüfregeln werden erst im Methodenkapitel verbindlich angegeben. Ein Muster des Protokolls steht in Anlage 1D.\n\nDurchführungstreue.  Für F werden die fünf Schritte des methodischen FRZK-Problemlösebogens anhand der tatsächlich ausgefüllten Darstellung erfasst; für K wird festgehalten, ob vergleichbare Strukturierungen spontan verwendet wurden. Personalisierte Arbeitsblätter dürfen in beiden Bedingungen nach denselben dokumentierten Regeln angepasst werden. Abweichungen vom Unterrichtsplan, fehlende Daten und vorzeitige Bearbeitungsabbrüche werden nicht nachträglich verschwiegen. Die Intervention wird dadurch nicht mit einer besonders gut vorbereiteten Unterrichtsstunde verwechselt.\n\nBeobachter- und Erwartungseinfluss. Da ich zugleich Tutor, Entwickler und Untersuchender bin, bestehen Risiken durch eigene Erwartungen, unterschiedliche Hilfestellungen und mein Vorwissen über die Lernenden. Eine unabhängige Zweitbewertung der anonymisierten Aufgabenlösungen, vorab freigegebene Bewertungskriterien und ein getrenntes Protokoll aller Tutorhinweise sollen diese Risiken vermindern, aber nicht vollständig beseitigen. Die dokumentierte Untersuchung orientiert sich an der allgemeinen Forderung nach nachvollziehbarer Evidenzbewertung in der Bildungsforschung [23], ohne die Anforderungen einer randomisierten Wirksamkeitsstudie als bereits erfüllt darzustellen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '56eed93096a935d08b0feb3b3f02eaaf3966bbe01a903d2ad3efb1bf86eebbef') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.7.6', 'Geplante Auswertung und Entscheidungsmaßstab', 2, 192, 'Auswertung. Ich berichte zunächst Zahl und Merkmale der tatsächlich teilnehmenden Lernenden, Aufgabenpaare und auswertbaren Bearbeitungen sowie fehlende Werte und Abweichungen vom Plan. Für die 0–12-Punkte-Summen und die getrennten Kriterien werden Verteilungen, Median, Spannweite und – soweit sinnvoll – Streuungsmaße beschrieben. Bei zuordenbaren, hinreichend vergleichbaren Aufgabenpaaren werden individuelle Differenzen F minus K ausgewiesen und nach Schulstufe bzw. Aufgabentyp explorativ betrachtet. Die kleine und heterogene Stichprobe erlaubt ohne weitergehende Voraussetzungen keine verallgemeinernden Kausalbehauptungen.\n\nInterpretation. Ein positiver Unterschied gilt zunächst als Hinweis auf einen möglichen Zusatznutzen unter den dokumentierten Bedingungen. Er ist kritisch gegen Aufgabenunterschiede, Übung, Reihenfolge, Übertragung, Tutorhilfe, Vorkenntnisse und zusätzliche Bearbeitungszeit abzuwägen. Bei ungeklärter Vergleichbarkeit oder unzureichender Trennung der Bedingungen darf ich auch einen größeren Zahlenunterschied nicht als isolierten FRZK-Effekt ausgeben. Nullbefunde, Verschlechterungen, abgebrochene Bearbeitungen und Fälle ohne FRZK-Mehrwert werden gleichrangig berichtet.\n\nGetrennte Nachweisketten.  Die fachliche Schlüssigkeit des allgemeinen methodischen FRZK-Problemlösewegs und seine Abgrenzung gegenüber bekannten Verfahren werden unabhängig vom Unterrichtsergebnis beurteilt. Spezielle mathematische Erweiterungen erhalten jeweils eine eigene formale Prüfung. Die didaktische Untersuchung bezieht sich auf die konkret operationalisierte Problemstellungs- und Lösungsintervention. Gute Unterrichtsbewertungen, verbesserte Noten oder korrekte Modellgleichungen können keinen dieser Nachweise stellvertretend ersetzen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '94c66883141e303a650eaf4a24a9b37358df13854f474484c17c968c3b76d1b8') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.7.7', 'Forschungsethik, Datenschutz und Geltungsgrenzen', 2, 196, 'Freiwilligkeit. Da minderjährige Lernende beteiligt sein können und ich zugleich ihr Tutor bin, dürfen Teilnahme oder Nichtteilnahme keinerlei Einfluss auf Nachhilfe, Bewertung oder Betreuung haben. Vor der Datenerhebung werden die erforderlichen Zustimmungen der Sorgeberechtigten und die altersangemessene Zustimmung der Lernenden sowie gegebenenfalls eine unabhängige institutionelle oder ethische Prüfung geklärt. Informationen zu Rückzugsmöglichkeiten, Aufbewahrungsdauer und Löschung sind in verständlicher Form bereitzustellen.\n\nTrennung der Datenbestände. Identifizierende Kontaktdaten und die Zuordnungstabelle werden getrennt und zugriffsgeschützt aufbewahrt. Für die Auswertung werden nur erforderliche Merkmale und pseudonymisierte Schülerlösungen verwendet. Die vorhandenen Bewertungen aus Anlage 1B dienen ausschließlich als qualitative Kontextdaten, soweit ihre Verwendung zulässig ist. Unbestätigte Gesprächszusammenfassungen oder nicht unabhängig belegte Notenverbesserungen werden nicht als gesicherte Wirkungsdaten umgedeutet.\n\nStatus der Planung. Die vorstehenden Angaben beschreiben ein zu präzisierendes, vor der Erhebung festzulegendes Untersuchungsprotokoll; sie behaupten weder eine bereits durchgeführte Randomisierung noch validierte Skalen, bestätigte Stichprobengrößen oder eine nachgewiesene Wirksamkeit. Das vollständige Protokoll, die Aufgabenpaare, Ankerbeispiele, Auswertungsentscheidungen und ihre Versionen sind vor dem Beginn einer systematischen FRZK-Wirkungsuntersuchung zu fixieren.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'dfc7b69fbed3cb85dd78da588acf0389a70049912a9df41a8e9e9418125b8e91') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.8', 'Persönliche und berufliche Motivation', 1, 200, 'Mein Interesse an einer wissenschaftlichen Auseinandersetzung mit mathematischen und technischen Fragestellungen reicht bis in meine Schul- und Studienzeit zurück. In späteren beruflichen Tätigkeiten konnte ich wissenschaftliche Methoden vor allem in der Entwicklung, Organisation und Vermittlung komplexer Systeme anwenden. Die Frage, wie aus einer umfangreichen Aufgabenstellung eine nachvollziehbare Struktur entsteht, begleitete mich dabei in unterschiedlichen Zusammenhängen.\n\nErfahrungen aus der Verfahrenstechnik, aus der Informationstechnologie und aus der Erwachsenenbildung haben mein Verständnis dafür geprägt, dass die explizite Darstellung von Voraussetzungen und Beziehungen eine wichtige Voraussetzung für die gemeinsame Bearbeitung komplexer Probleme sein kann. Diese Berufserfahrung ist eine Motivation für die Themenwahl, aber kein wissenschaftlicher Nachweis der Eignung des FRZK.\n\nIn meiner späteren Unterrichts- und Nachhilfetätigkeit rückte für mich die Frage in den Mittelpunkt, wie sich ein solches Vorgehen auf mathematische Lernaufgaben übertragen lässt. Ich habe dabei wiederkehrende Schwierigkeiten beobachtet, aus denen ich prüfbare Fragestellungen ableite. Ihre Ursachen und mögliche Verbesserungen müssen im Rahmen einer systematisch dokumentierten Untersuchung geklärt werden.\n\nMit der Dissertation möchte ich diese Erfahrungen in ein wissenschaftlich kontrollierbares Vorhaben überführen. Mein Ziel ist, einen offen gelegten Darstellungsrahmen zu formulieren, seine Grenzen zu benennen und seinen möglichen didaktischen Nutzen anhand geeigneter Kriterien untersuchen zu lassen. Persönliche Überzeugung und wissenschaftlicher Befund bleiben dabei ausdrücklich getrennt.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '4be1986860d74f629929ef1802ad915fb0f9634b5145a24691c8a8e071fe582e') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.9', 'Wissenschaftliche Relevanz und Abgrenzung des Vorhabens', 1, 205, 'Kapitel 2 erarbeitet die mathematischen, methodischen und didaktischen Grundlagen des FRZK. Es stellt funktionale Zusammenhänge und ihre Darstellungsformen ebenso dar wie zentrale Bedingungen des Aufgabenverständnisses, des Problemlösens und der individuellen Lernförderung. Die einschlägige Fachliteratur wird dabei zur Begründung, Einordnung und kritischen Abgrenzung herangezogen; Kapitel 2 ist jedoch keine eigenständige Literaturprüfung oder systematische Evidenzsynthese. Kapitel 3 entwickelt darauf aufbauend die formale Beschreibung des FRZK und die davon getrennt zu prüfenden mathematischen Erweiterungen. Formal nachgewiesene Teilresultate spezieller Grenzwert- und Vektoroperatoren ersetzen weder den Vergleich des methodischen Problemlöseverfahrens mit bestehenden Ansätzen noch die empirische Prüfung seines möglichen Lernnutzens.\n\nDie wissenschaftliche Relevanz des Projekts liegt in der überprüfbaren Frage, wie Problemstellungen methodisch erfasst, strukturiert, bearbeitet und gelöst werden können und ob die explizite Anwendung dieses Ablaufs Lernenden einen Zusatznutzen bietet. Die einzelnen Bearbeitungsschritte sollen unabhängig von meiner Person nachvollziehbar sein und an unterschiedlichen Aufgaben erprobt und kritisch mit bestehenden Problemlöseverfahren verglichen werden. Gesonderte mathematische Symbolerweiterungen begründen diesen methodischen Anspruch weder automatisch noch ersetzen sie ihn.\n\nIch gehe von der Arbeitsannahme aus, dass ein fehlender oder unzureichend strukturierter Überblick über Variablen und Beziehungen die Bearbeitung mathematischer Aufgaben erschweren kann. Diese Annahme ist weder allgemein noch für jede Lernsituation bewiesen. Die Dissertation muss deshalb die Bedingungen angeben, unter denen eine FRZK-Darstellung nützlich, entbehrlich oder möglicherweise hinderlich ist.\n\nUnter einem zunächst leeren Darstellungsrahmen verstehe ich hier methodisch, dass die für eine konkrete Aufgabe benötigten Angaben und Beziehungen schrittweise eingetragen werden. Dies ist nicht mit der leeren Menge der Mathematik identisch. Eine solche Arbeitsweise soll Vorannahmen sichtbar machen; sie bedeutet nicht, dass Lernende ohne Vorwissen arbeiten oder dass mathematische Strukturen aus dem Nichts entstehen.\n\nDie Analogie zu technischen Modellierungs- und Datenbanksystemen hilft mir, Annahmen, Eingaben, Verknüpfungen und Ausgaben getrennt zu dokumentieren. Ich verwende diese Analogie als heuristisches Werkzeug, nicht als Beweis dafür, dass kognitive Prozesse denselben Regeln wie Softwarearchitekturen folgen.\n\nFür die Dissertation ergibt sich daraus ein begrenzter methodischer Anspruch: Ich möchte das Vorgehen von der Problemformulierung bis zur begründeten Lösung und Ergebniskontrolle präzisieren, seine Grenzen bestimmen und es auf ausgewählte Lernaufgaben anwenden. Ob Lernende dadurch besser verstehen, begründen oder übertragen können, ist empirisch zu prüfen. Die darüber hinaus eingeführten mathematischen FRZK-Symbole sind unabhängig davon in ihrem jeweiligen formalen Geltungsbereich zu untersuchen.\n\nDie zusätzlichen mathematischen Festlegungen – insbesondere zu typisierten Nullzuständen, Grenzrichtungen, orthogonaler Ausgangsorientierung und Vektoroperationen – werden auf der Grundlage von Kapitel 2 in Kapitel 3 eigenständig definiert und formal geprüft. Sie gehören nicht notwendig zum allgemein anwendbaren methodischen Grundgerüst. Die Einleitung macht deshalb weder diese Erweiterungen zu Voraussetzungen jeder Problemstellung noch leitet sie ihre mathematische Gültigkeit aus einer gelungenen Unterrichtsanwendung ab.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'b7d3edc01b5213600d9fbd98f390fcd65e40f6d95af4e90a0e5cebb14cc03f65') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.10', 'Aufbau der Arbeit', 1, 213, 'Kapitel 2 beschreibt die mathematischen, methodischen und didaktischen Grundlagen des FRZK. Dazu gehören insbesondere funktionale Zusammenhänge und Modelle, Repräsentationen und Visualisierungen, Aufgabenverständnis und Problemlösen, Vorwissen und Begriffsbildung, individuelle Lernförderung, mathematisches Argumentieren, Fehlerdiagnose und Lernumgebungen. Die fachwissenschaftliche und didaktische Literatur wird innerhalb dieser Grundlagenarbeit herangezogen, um die verwendeten Begriffe und Ansätze wissenschaftlich einzuordnen. Kapitel 2 ist keine eigenständige Literaturprüfung.\n\nKapitel 3 formalisiert den methodischen FRZK-Ablauf auf der Grundlage der in Kapitel 2 entwickelten Begriffe: Problemstellung, Angaben und Zielgrößen, Voraussetzungen und Beziehungen, Lösungsentwicklung sowie Ergebniskontrolle. Davon getrennt werden zusätzliche mathematische FRZK-Strukturen entwickelt, insbesondere typisierte Grenzzustände, Vektorkonstruktionen und spezielle Operationen. Für sie sind Definitionen, Annahmen, Rechenregeln und Gültigkeitsbereiche jeweils eigens anzugeben und zu prüfen. Auch die orthogonale Ausgangsorientierung im Nullgrenzzustand gehört nur zu denjenigen mathematischen Modellen, in denen sie ausdrücklich festgelegt ist; sie ist keine Voraussetzung für jede methodische FRZK-Anwendung.\n\nDie folgenden Untersuchungskapitel behandeln die Anwendung und Grenzen des methodischen Vorgehens sowie die eigenständige formale Prüfung zusätzlich eingeführter mathematischer Konstruktionen. Rekursionen, Fixpunkte, besondere Grenzzustände oder Kohärenzbedingungen sind speziell definierte Untersuchungsfälle und keine universell notwendigen Bearbeitungsschritte des FRZK. Ein formaler Beweis für eine bestimmte Modellklasse begründet weder die globale Konsistenz sämtlicher Erweiterungen noch ein neues physikalisches Gesetz.\n\nDer didaktische Teil der Arbeit soll den methodischen FRZK-Ablauf zur Problemstellung und Problemlösung an ausgewählten Aufgaben untersuchen. Hierfür werden Beobachtungskriterien, Aufgabenformate, Vergleichsbedingungen und Auswertungsverfahren offengelegt. Mathematische Zusatzzeichen und -operatoren werden nur bei einer gesondert gekennzeichneten, fachlich geeigneten Aufgabenklasse verwendet und dürfen nicht unbemerkt Bestandteil der allgemeinen didaktischen Intervention werden.\n\nMit diesem Aufbau unterscheide ich die in Kapitel 2 dargestellten fachlichen Grundlagen, die formale Entwicklung und mathematische Prüfung in Kapitel 3 sowie die spätere empirische Untersuchung der methodischen Anwendung. Die Literatur dient in den betreffenden Kapiteln der wissenschaftlichen Begründung und Abgrenzung; sie bildet nicht den alleinigen Gegenstand von Kapitel 2. Dadurch sollen auch nicht bestätigte Annahmen und die Grenzen des entwickelten Ansatzes nachvollziehbar geprüft werden können.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'a262e1f38a92b30cb9123f580faf748b6c2b0889168fd648ca7fb7b445222a83') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.11', 'Zusammenfassung', 1, 219, 'Mit dieser Einleitung stelle ich das Funktionale Raum-Zeit-Kohärenzsystem vorrangig als methodischen Ansatz zur Formulierung, Strukturierung, Bearbeitung und Lösung von Problemen vor. Das Forschungsinteresse leite ich aus Schwierigkeiten beim Verstehen von Aufgaben, dem Erkennen von Größen und Beziehungen sowie der Überprüfung eigener Lösungswege ab. Die Einleitung beschreibt Anlass, Zielsetzung, wissenschaftliche Abgrenzung und geplanten Untersuchungsweg, ohne besondere mathematische Erweiterungen zur Voraussetzung der Methode zu machen.\n\nDer angestrebte Beitrag besteht in einem nachvollziehbaren, kritisch überprüfbaren Problemlöseverfahren und in der Untersuchung seines möglichen didaktischen Nutzens. Zusätzliche mathematische Symbole und Operationen aus Grenzwert- und Vektorrechnung bilden einen gesonderten, formal zu prüfenden Erweiterungsbereich. Ob der methodische Ansatz Vorteile gegenüber vorhandenen Verfahren bietet, lässt sich aus Unterrichtsbeobachtungen oder Modellbeschreibungen allein nicht folgern.\n\nDie folgenden Kapitel müssen daher das methodische Grundgerüst, die Reichweite und Konsistenz spezieller mathematischer Erweiterungen sowie die didaktische Tragfähigkeit getrennt untersuchen. Die Unterscheidung zwischen Problemlöseverfahren, formaler Zusatzstruktur und empirischer Wirksamkeit bleibt leitend.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '2317c1254855625a02f7667a6cef590da5f33c74409982f841e83b4e9d475f27') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.LIT', 'Literaturverzeichnis', 1, 223, '[1] Rovelli, Carlo (2018). The Order of Time. London: Penguin Books.\n\n[2] von Foerster, Heinz (1981). Observing Systems. Seaside, CA: Intersystems Publications.\n\n[3] Maturana, Humberto R.; Varela, Francisco J. (1987). The Tree of Knowledge: The Biological Roots of Human Understanding. Boston: Shambhala.\n\n[4] Reinmann, Gabi (2005). Innovation ohne Forschung? Ein Plädoyer für den Design-Based Research-Ansatz in der Lehr-Lernforschung. Unterrichtswissenschaft, 33(1), S. 52–69. DOI: 10.25656/01:5787.\n\n[5] Arnold, Rolf (2012). Wie man lehrt, ohne zu belehren. 29 Regeln für eine kluge Lehre. Das LENA-Modell. 1. Auflage. Heidelberg: Carl-Auer. ISBN: 978-3-89670-838-0.\n\n[6] Sfard, Anna (2008). Thinking as Communicating: Human Development, the Growth of Discourses, and Mathematizing. Cambridge: Cambridge University Press. DOI: 10.1017/CBO9780511499944.\n\n[7] Luhmann, Niklas (1984). Soziale Systeme: Grundriß einer allgemeinen Theorie. Frankfurt am Main: Suhrkamp.\n\n[8] Bruner, Jerome S. (1960). The Process of Education. Cambridge, MA: Harvard University Press. DOI: 10.4159/9780674028999.\n\n[9] Ausubel, David P. (1963). The Psychology of Meaningful Verbal Learning. New York: Grune & Stratton.\n\n[10] Taschner, Rudolf (2013). Der Irrtum des Pythagoras. Videoaufzeichnung. Herausgeber: math.space; archiviert im TIB AV-Portal. DOI: 10.5446/15789.\n\n[11] Carroll, Sean (2016). The Big Picture: On the Origins of Life, Meaning, and the Universe Itself. New York: Dutton.\n\n[12] Hattie, John (2009). Visible Learning: A Synthesis of Over 800 Meta-Analyses Relating to Achievement. London: Routledge.\n\n[13] Rovelli, Carlo (2016). Reality Is Not What It Seems: The Journey to Quantum Gravity. London: Penguin.\n\n[14] Verlinde, Erik P. (2017). Emergent Gravity and the Dark Universe. SciPost Physics, 2(3), Artikel 016. DOI: 10.21468/SciPostPhys.2.3.016.\n\n[15] Bureau International des Poids et Mesures (2026). The International System of Units. 9. Auflage, aktualisierte Fassung. Sèvres: BIPM. DOI: 10.59161/AUEZ1291. URL: https://www.bipm.org/en/publications/si-brochure/\n\n[16] Novak, Joseph D.; Cañas, Alberto J. (2008). The Theory Underlying Concept Maps and How to Construct and Use Them. Technical Report IHMC CmapTools 2006-01 Rev 01-2008. Pensacola, FL: Institute for Human and Machine Cognition. URL: https://cmap.ihmc.us/publications/researchpapers/theoryunderlyingconceptmaps.pdf.\n\n[17] Ainsworth, Shaaron (2006). DeFT: A conceptual framework for considering learning with multiple representations. Learning and Instruction, 16(3), S. 183–198. DOI: 10.1016/j.learninstruc.2006.03.001.\n\n[18] Schoenfeld, Alan H. (1985). Mathematical Problem Solving. Orlando: Academic Press. DOI: 10.1016/C2013-0-05012-8. ISBN: 978-0-12-628870-4.\n\n[19] Hattie, John; Timperley, Helen (2007). The Power of Feedback. Review of Educational Research, 77(1), S. 81–112. DOI: 10.3102/003465430298487.\n\n[20] Zimmerman, Barry J. (2002). Becoming a Self-Regulated Learner: An Overview. Theory Into Practice, 41(2), S. 64–70. DOI: 10.1207/S15430421TIP4102_2.\n\n[21] Bloom, Benjamin S. (1984). The 2 Sigma Problem: The Search for Methods of Group Instruction as Effective as One-to-One Tutoring. Educational Researcher, 13(6), S. 4–16. DOI: 10.3102/0013189X013006004.\n\n[22] Hoffmann, Tammy C.; Glasziou, Paul P.; Boutron, Isabelle; Milne, Ruairidh; Perera, Rafael; Moher, David et al. (2014). Better reporting of interventions: template for intervention description and replication (TIDieR) checklist and guide. BMJ, 348, g1687. DOI: 10.1136/bmj.g1687. URL: https://www.bmj.com/content/348/bmj.g1687.\n\n[23] What Works Clearinghouse (2022). What Works Clearinghouse Procedures and Standards Handbook, Version 5.0 (revised December 2022). Washington, DC: U.S. Department of Education, Institute of Education Sciences. URL: https://ies.ed.gov/ncee/wwc/Handbooks.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '06b9adbdb70a9ad82f4a6540da7c96d7b1a57ef1c5ecc5b3b4b28f0bf2e04a18') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.A', 'Anlage 1A – Inkrementelles Setup einer Textaufgabe (vom Autor vorgelegte Bildfolge)', 1, 248, 'Herkunft: vom Autor eingereichte Datei „Anlage 1.A - Inkrementelles Setup einer Textaufgabe(1).docx“ mit fünf aufeinanderfolgenden Originalillustrationen. Die Abbildungen werden in ihrer ursprünglichen Reihenfolge und ohne inhaltliche Änderung wiedergegeben. Sie dokumentieren die Visualisierung des didaktischen Vorgehens, nicht eine datierte Schülerlösung.\n\nDie Schritte zeigen, dass hier nicht nur Angaben schematisch erfasst werden: Der Ausgangspunkt wird als Situation beschrieben, eine Problemfrage wird sichtbar und die bekannten Zahlen werden anschließend ergänzt. Die Auswertung und rechnerische Lösung folgen erst nach dieser Strukturierung. Diese Abfolge veranschaulicht das methodische FRZK-Grundgerüst, ohne besondere Grenzwert- oder Vektorsymbole vorauszusetzen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '3673378b188246749ca67add9394a7b640d459b64e9c6d5db2bb019fc18d8a12') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.A.1', 'Schritt 1 – Start: leeres Blatt', 2, 251, 'Die Aufgabe wird zunächst ohne vorgezeichnete mathematische Struktur betrachtet.\n\nAnlage 1A, Bild 1: Start: leeres Blatt. Bildquelle: vom Autor bereitgestellte Anlage 1.A.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '4085e3be21e552dab62d87c47b75c7877a7fe085c870fc7f62938883f21de205') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.A.2', 'Schritt 2 – Position festlegen', 2, 255, 'Originalauftrag: „Markiere bitte auf dem Blatt, wo du stehst und male dich selbst dazu!“\n\nAnlage 1A, Bild 2: Position festlegen. Bildquelle: vom Autor bereitgestellte Anlage 1.A.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '2d9186fa659f052906c3e6a59f460b564ed791ab04ea132217a7659db101e7bf') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.A.3', 'Schritt 3 – Situation erkennen', 2, 259, 'Originalfrage: „Was siehst Du?“\n\nAnlage 1A, Bild 3: Situation erkennen. Bildquelle: vom Autor bereitgestellte Anlage 1.A.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'cbd89ca7d1e3da156b960d96a877a6cd45d3686b3657c6d20c6627d62f86a05f') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.A.4', 'Schritt 4 – Gesuchtes sichtbar machen', 2, 263, 'Originalfrage: „Siehst Du, was gesucht ist?“; die acht Säcke werden als gegebene Behälter dargestellt. Gesucht sind die Anzahl Kartoffeln je Sack und der Rest.\n\nAnlage 1A, Bild 4: Gesuchtes sichtbar machen. Bildquelle: vom Autor bereitgestellte Anlage 1.A.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'bee36049b263a3efcdc7831f26b7ac1bbe922349df1a947389d8e656ca768c5a') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.A.5', 'Schritt 5 – Gegebenes ergänzen', 2, 267, 'Originalfrage: „Siehst Du, was noch gegeben ist?“; die Menge 173 wird sichtbar gemacht.\n\nAnlage 1A, Bild 5: Gegebenes ergänzen. Bildquelle: vom Autor bereitgestellte Anlage 1.A.\n\nErgänzende rechnerische Einordnung (nicht Bestandteil der ursprünglichen fünf Illustrationen): Bei gleichmäßiger Verteilung von 173 Kartoffeln auf 8 Säcke ergeben sich 21 Kartoffeln je Sack und 5 Kartoffeln Rest (173 = 8 · 21 + 5). Diese Rechnung darf nicht als im Bildmaterial dokumentierte Schülerleistung ausgegeben werden.\n\nNachweis- und Rechtevorbehalt: Die vorgelegte Anlage enthält eine bildliche Darstellung des vom Autor beschriebenen Lehrwegs, aber weder eine datierte Originalschrift der Schülerin noch ein standardisiertes Beobachtungsprotokoll. Entstehungsdatum, gegebenenfalls verwendete Drittanbieter-Bildmotive, Nutzungsrechte und die Zustimmung zur Veröffentlichung sind vor einer externen Dissertationseinreichung zu klären. Die Anlage kann den beschriebenen Ablauf veranschaulichen, jedoch weder Lernerfolg noch die Wirksamkeit des FRZK belegen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '00f36aa6af257c38a4361bae7e6340141061c666c6ac78a371113824885af287') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.B', 'Anlage 1B – Anonymisiertes Nachweisregister der Unterrichtsrückmeldungen', 1, 273, 'Prüfstand: 06.11.2026. Grundlage ist ausschließlich die vom Autor bereitgestellte Textsammlung „meine Bewertungen.txt“; NB-16 dokumentiert eine zusätzliche Autorenangabe aus dem Kapiteltext. Die Fundstellen sind für wissenschaftliche Nachprüfbarkeit gruppiert, jedoch nicht als unabhängige Personenbeobachtungen zu verstehen. Die Originaldatei enthält identifizierende Daten und gehört nicht in den öffentlich weitergegebenen Anhang.\n\nPrüfkategorien: D = unmittelbar vorliegende Nachricht; Z = vom Autor redigierte Gesprächszusammenfassung; P = von Eltern übermittelte Rückmeldung; O = in die Sammlung übertragener Rezensionstext, Originalplattform nicht geprüft; V = verwaltungsbezogener Eintrag; A = bloße Autorenangabe oder Entwurf. „Zustimmung dokumentiert“ bedeutet lediglich, dass im bereitgestellten Material eine positive Antwort auf eine Verwendungsanfrage sichtbar ist; daraus folgt noch keine abschließende datenschutzrechtliche Freigabe.\n\nTabelle A1B.1: Quellen- und Statusregister der bereitgestellten qualitativen Rückmeldungen. Zeitangaben „Datum relativ“ geben nur die im Abschrifttext enthaltenen relativen Angaben wieder; sie sind kein verifiziertes Publikationsdatum.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'e1b572db608a4d7fc8f8e6af07ab4eb8d181633cd835517a9a421fb4fe685d07') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.B.1', 'Kodierung der Unterrichtsmerkmale', 2, 278, 'Tabelle A1B.2: Kodierung der sieben Unterrichtsmerkmale und Zuordnung zu den Fundstellen des anonymisierten Nachweisregisters. Eigene qualitative Kategorisierung.\n\nGrenzen der Auswertung. Die Kodierung ist eine analytische Zuordnung zu einzelnen Aussagen und keine Frequenzzählung. NB-03/NB-04 bilden denselben Lernenden ab, bei NB-07/NB-10 sowie NB-01/NB-12 sind Überschneidungen möglich. Ohne vollständige Metadaten ist die Zahl unabhängiger Befragter unbestimmbar. Die elterlich berichteten Notenveränderungen sind nicht durch Originalzeugnisse verifiziert; die Nachhilfeleistung und ein möglicher zusätzlicher FRZK-Effekt dürfen daraus nicht kausal abgeleitet werden.\n\nArchivierungs- und Forschungsbedarf. Die Originaldatei sollte zugriffsbeschränkt und getrennt von dieser für das Manuskript vorgesehenen Fassung aufbewahrt werden. Für eine spätere belastbare Auswertung wären Erhebungszeitpunkt, Originalquelle, Identitätsabgleich (nur in geschützter Zuordnungsliste), Nutzungsbefugnis einschließlich erforderlicher Zustimmungen, dokumentierte Notenverläufe und systematisch erfasste Gegenbeispiele nachzutragen. Bis dahin erhalten unbestätigte Einträge keine Freigabe als wörtliches Lernendenzitat oder unabhängiger Wirkungsbeleg.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '95439e47591f3666a33acf39d81e0b839a1e90e6a2377a2dc14aa73e20bc1502') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.C', 'Anlage 1C – Literaturprüfung zu Abschnitt 1.6', 1, 284, 'Prüfstand 06.11.2026. Die Fundstellen wurden mit veröffentlichten Originaltexten bzw. Verlags- und Indexeinträgen abgeglichen. „Originaltext“ bedeutet eine am angegebenen Ort inhaltlich kontrollierte Textstelle; „Metadaten“ bezeichnet nur den überprüften bibliografischen Nachweis und den beschriebenen Forschungsgegenstand. Diese Anlage ist keine vollständige systematische Literaturrecherche.\n\nTabelle A1C.1: Aussage-Quelle-Prüfung der neu aufgenommenen Literatur [16]–[21]. Die Kurzbelege entsprechen veröffentlichten Originalauszügen; für [18] und [21] werden keine unüberprüften wörtlichen Originalzitate behauptet.\n\nOriginalfundorte (Prüfprovenienz): [16] https://cmap.ihmc.us/publications/researchpapers/theoryunderlyingconceptmaps.pdf ; [17] https://www.inf.ufpr.br/alexd/REPRESENTACOES_EXTERNAS/Ainsworth_2006.pdf ; [19] https://assess.ucr.edu/sites/g/files/rcwecm2336/files/2019-02/hattietimperley_2007.pdf ; [20] https://www.normanjackson.co.uk/uploads/1/0/8/4/10842717/zimmerman_-_2002_-_becoming_a_self-regulated_learner_an_overview__1_.pdf .\n\nBibliografische Kontrollstellen: [18] https://www.sciencedirect.com/book/monograph/9780126288704/mathematical-problem-solving ; [21] https://eric.ed.gov/?id=EJ303699 und https://journals.sagepub.com/doi/10.3102/0013189X013006004 . Verfügbarkeit und Zugriffsrechte der Originalpublikationen sind getrennt von ihrer bibliografischen Existenz zu beurteilen.\n\nOffener Prüfschritt: Für [18] und [21] sind vor einer abschließenden Originalstellen-Freigabe die relevanten Buch- bzw. Aufsatzseiten zu beschaffen. Die herangezogenen Arbeiten stützen den jeweiligen Forschungsstand, ersetzen jedoch keine systematische Neuheitsrecherche und keine Untersuchung der Wirkung des FRZK.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '3183841f3fd6d994dae9848d3931c2faa5899fa6f83f3ebc0455d953971a4fd4') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.D', 'Anlage 1D – Vorläufiges Untersuchungsprotokoll zu Abschnitt 1.7', 1, 291, 'Status: Forschungsplanung, 06.11.2026. Die folgenden Vorgaben sind ein Vorschlag zur prüfbaren Operationalisierung. Vor einer systematischen Datenerhebung sind Aufgaben, Aufgabenpaare, Materialien, Einwilligungen, Kriterien und die Freigabeversion verbindlich festzulegen.\n\nTabelle A1D.1: Vergleich der Unterrichtsbedingungen\n\nAbweichungen und mögliche Überträge von FRZK-Schritten auf K-Aufgaben werden protokolliert. Die Tabelle beschreibt den beabsichtigten Unterschied der Bedingungen, nicht bereits überprüfte Durchführungstreue.\n\nTabelle A1D.2: Vorläufiges Bewertungsraster (0–12 Punkte)\n\nDie Dimension D setzt eine eigenständige Transferaufgabe voraus. Punktestufen und Ankerbeispiele sind vor der Erhebung zu pilotieren und danach zu fixieren. Die Tabelle ist ein Entwurf, keine validierte Skala.\n\nTabelle A1D.3: Mindestfelder des Erhebungsprotokolls\n\nDokumentationsgrenze: Die Auflistung enthält keine personenbezogenen Schülerdaten. Vor einer Veröffentlichung sind auch indirekte Identifikationsrisiken kleiner heterogener Gruppen zu prüfen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'abb87167dce68899ce07f76403b0c57c315cf87f4c8af61e8720f1b7db164443') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, NULL, '1.E', 'Anlage 1E – Rechenvorschrift und Kontrollwerte des technischen Referenzmodells', 1, 305, 'Geltungsbereich: Diese Anlage beschreibt ausschließlich das in Abschnitt 1.2 neu festgelegte Referenzmodell. Sie rekonstruiert nicht die unbekannten historischen Rechenparameter der ursprünglichen beiden Abbildungen.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '1796520618312b6950c0145572c00619d01e210a6d88851f2dd5346621fcabae') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.E.1', '1. Parameter, Dreiecksgebiet und Koordinaten', 2, 307, 's = 1 m; b = 1 m; d = 3 m; a = 0,20 m⁻¹; xₛ = 5 m; c = 299 792 458 m/s. Der Parameterbereich bildet ein Dreieck mit A = (−0,5; −0,5) m, B = (0,5; −0,5) m und C = (0; h) m, h = (√3 − 1)/2 ≈ 0,3660254 m.\n\nEin Gitterpunkt (u, v) gehört genau dann zum geschlossenen Dreieck, wenn −0,5 ≤ u ≤ 0,5 sowie −0,5 ≤ v ≤ h − √3·|u| gelten. Außerhalb dieses Gebiets wird keine Laufzeit ausgewertet und keine Dreiecksfarbe vergeben.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'cf98a84674b00cac9614cf16f1142626a811ecd4a7cc6f3eb2aebf3943983830') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.E.2', '2. Algorithmus zur numerischen Wiederholung', 2, 310, 'h = (sqrt(3) - 1) / 2\n\nU = 281 äquidistante Werte von -0.5 bis +0.5 (einschließlich)\n\nV = 281 äquidistante Werte von -0.5 bis h (einschließlich)\n\nfür jedes (u,v) aus U × V:\n\nfalls v < -0.5 oder v > h - sqrt(3)*abs(u): überspringen\n\nxQ = 3.0 + 0.20*(u*u - v*v)\n\nL1 = sqrt((5.0 - xQ)^2 + u*u + v*v)\n\nL2 = abs(xQ - 1.0)\n\ntau_ns = 1e9*(L1 + L2)/299792458\n\ntau_ns für die Farbdarstellung dem Punkt (u,v) zuordnen', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '57eae7ef585dd50c9075c3a7ddf7a0d2390f067261f268800ac1de1fc60fdae2') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.E.3', '3. Reproduzierbare Farbabbildung', 2, 321, 'Die Laufzeit wird in Nanosekunden dargestellt. Zur Wiedergabe von Abbildung 1.F4 wird eine gefüllte Konturdarstellung mit 25 linear verteilten Stufengrenzen von 13,34 ns bis 13,75 ns und der Farbpalette „viridis“ verwendet. Die Dreiecksränder werden als Linien verbunden. Die Gitterpunkte außerhalb des Dreiecks bleiben maskiert. Die Farbgrenzen sind fest vorgegeben und werden nicht für jede Wiederholung neu an die Daten angepasst.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '28115909f986e363471745a61f9ac6165038a6e22b145a236bfd48cc87103a19') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.E.4', '4. Unabhängig nachgerechnete Kontrollwerte', 2, 323, 'Analytischer Kontrollpunkt (u,v) = (0,0): τ = 13,3425638079 ns. Eckpunkte A und B: je τ = 13,7472449142 ns. Eckpunkt C: τ = 13,4519250616 ns. Auf dem beschriebenen 281 × 281-Gitter liegen 39 481 Punkte innerhalb der Dreiecksmaske; der kleinste erfasste Gitterwert beträgt ungefähr 13,3425647406 ns, der größte 13,7472449142 ns. Die geringe Abweichung des Gitterminimums vom Wert am Mittelpunkt entsteht, weil v = 0 keine der 281 gleichmäßig verteilten v-Koordinaten ist.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, 'b83637b062b862c6db1564dfeaf1b70742613c4cb50da0619bc386bec132135d') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `sections` (`chapter_id`, `parent_section_id`, `section_number`, `title`, `level_no`, `sort_order`, `body_text`, `scientific_status`, `status`, `current_revision_id`, `content_sha256`) VALUES (@frzk_ch1_id, @frzk_parent_section_id, '1.E.5', '5. Physikalische und dokumentarische Grenzen', 2, 325, 'Die Regel beschreibt einen idealisierten zweiteiligen Signalweg vom Sender über einen zugeordneten Flächenpunkt zu einem Punkt der Beobachtungsebene. Sie berücksichtigt keine realistische winkelabhängige Reflexion, keine Mehrfachwege und keine Streu- oder Dämpfungseffekte. Das Ergebnis ist deshalb ein geometrisch begründetes Laufzeit-Skalarfeld, kein nachgewiesenes optisches Messverfahren. Die zwei historischen Skizzen in Abschnitt 1.2 bleiben ohne ihre ursprünglichen Daten eigenständige Illustrationen; mit diesem Referenzmodell werden sie nicht nachträglich validiert.', 'Autorenfassung 06.11.2026; Quellenbelege und empirische Wirkung differenziert zu prüfen', 'RELEASED', @frzk_rev_id, '55b2319d4573fc1a7a2f1a94a5d8ef6bcf8ff15276782f366a452582fd02d9a0') ON DUPLICATE KEY UPDATE `parent_section_id`=VALUES(`parent_section_id`), `title`=VALUES(`title`), `level_no`=VALUES(`level_no`), `sort_order`=VALUES(`sort_order`), `body_text`=VALUES(`body_text`), `scientific_status`=VALUES(`scientific_status`), `status`=VALUES(`status`), `current_revision_id`=VALUES(`current_revision_id`), `content_sha256`=VALUES(`content_sha256`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.0' LIMIT 1), 1, 'K1-P-0001', 'In meiner Nachhilfepraxis beobachte ich wiederholt, dass Lernende bei komplexen Aufgaben Schwierigkeiten haben, relevante Angaben zu ordnen, Beziehungen zu erkennen und den eigenen Lösungsweg zu reflektieren. Ich untersuche deshalb einen methodischen Ablauf, der bei der Formulierung der Problemstellung beginnt, Gegebenes und Gesuchtes trennt, Beziehungen erschließt, eine Lösung entwickelt und diese überprüft. Das Funktionale Raum-Zeit-Kohärenzsystem (FRZK) verstehe ich primär als methodischen Ansatz zur Problemstellung und Problemlösung. Seine mathematischen Erweiterungen um besondere Grenzwert- und Vektorsymbole gehören nicht zum allgemeinen methodischen Grundgerüst. Ob das Vorgehen die Nachvollziehbarkeit, Fehlererkennung und Übertragbarkeit von Lösungsstrategien verbessert, bleibt eine empirisch zu prüfende Frage.', 'b04fa3671810083b055254a8e4a9b80e39d8c9a0d14bf526138b03ce95ff3d34', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.0' LIMIT 1), 2, 'K1-P-0002', 'Die Fragestellung berührt wissenschaftliche Diskussionen über Modellbildung, Beobachtung und die Begriffe Raum und Zeit. Rovelli behandelt die Grundlagen unseres Zeitverständnisses und die Grenzen herkömmlicher Vorstellungen von Zeit (Rovelli, Carlo (2018). The Order of Time. London: Penguin Books.)[1]. Ich verwende diese Darstellung als physikalisch-philosophischen Hintergrund, nicht als Bestätigung einer aus dem FRZK hervorgehenden Raumzeit oder als Nachweis seines didaktischen Nutzens.', '37eed69ba4c872b4847c456a747f8451d4d60a19e0f6501656a2f09f602d4445', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.0' LIMIT 1), 3, 'K1-P-0003', 'Die Systemtheorie und die Kybernetik eröffnen unterschiedliche Perspektiven auf Systembeziehungen, Beobachtung und die Beschreibung von Lern- und Kommunikationsprozessen (von Foerster, Heinz (1981). Observing Systems. Seaside, CA: Intersystems Publications.)[2] (Maturana, Humberto R.; Varela, Francisco J. (1987). The Tree of Knowledge: The Biological Roots of Human Understanding. Boston: Shambhala.)[3]. Für die Entwicklung und Untersuchung didaktischer Verfahren ist die gestaltungsorientierte Lehr-Lernforschung ein methodischer Bezugspunkt (Reinmann, Gabi (2005). Innovation ohne Forschung? Ein Plädoyer für den Design-Based Research-Ansatz in der Lehr-Lernforschung. Unterrichtswissenschaft, 33(1), S. 52–69. DOI: 10.25656/01:5787.)[4]. Einen Ansatz zur Begleitung und Anregung eigenständiger Lernprozesse erläutert Arnold (Arnold, Rolf (2012). Wie man lehrt, ohne zu belehren. 29 Regeln für eine kluge Lehre. Das LENA-Modell. 1. Auflage. Heidelberg: Carl-Auer. ISBN: 978-3-89670-838-0.)[5]. Sfard untersucht mathematisches Denken aus einer kommunikationstheoretischen Perspektive (Sfard, Anna (2008). Thinking as Communicating: Human Development, the Growth of Discourses, and Mathematizing. Cambridge: Cambridge University Press. DOI: 10.1017/CBO9780511499944.)[6]. Luhmann stellt mit seiner Theorie sozialer Systeme einen weiteren, davon zu unterscheidenden systemtheoretischen Bezug bereit (Luhmann, Niklas (1984). Soziale Systeme: Grundriß einer allgemeinen Theorie. Frankfurt am Main: Suhrkamp.)[7]. Keiner dieser Ansätze beweist bereits die Wirksamkeit des FRZK.', 'bfaa44a62d42b134123b93fc2ffab4ad698507dfcbfbdbc6d8dbbfb9b82d4511', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.0' LIMIT 1), 4, 'K1-P-0004', 'Das methodische Grundgerüst des FRZK beschreibt eine Folge nachvollziehbarer Bearbeitungshandlungen: Eine Problemstellung wird zunächst geklärt und als Frage formuliert; anschließend werden bekannte und gesuchte Größen, Voraussetzungen und Beziehungen geordnet, Lösungsansätze entwickelt, ausgeführt und anhand der Ergebnisse überprüft. Die ausdrückliche Darstellung funktionaler Zusammenhänge ist ein Hilfsmittel innerhalb dieses Weges, nicht dessen einziges Ziel. Das Grundgerüst setzt weder ein bestimmtes Koordinatensystem noch eine spezielle Geometrie, Dynamik oder Algebra voraus. Rekursion, Fixpunkte, Kohärenzbedingungen und mathematische Sonderzeichen werden nur dann hinzugenommen, wenn die konkrete Aufgabe dies erfordert.', '259a3188f55ba5901909723a7d8dbfe3215713012bf3edfbe279c5b57861c1d3', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.0' LIMIT 1), 5, 'K1-P-0005', 'Die in Kapitel 3 behandelten besonderen FRZK-Zustände, gerichteten Grenzannäherungen, Grenzzeichen, Null- und Vektoroperationen sowie die orthogonale Ausgangsorientierung bilden eine gesonderte mathematische Erweiterung des methodischen Ansatzes. Sie sind nicht als Voraussetzungen für jede Problemstellung oder für jede Anwendung des FRZK zu verstehen. Ihre Bedeutung, Rechenregeln und Gültigkeitsbereiche müssen unabhängig vom Grundgerüst definiert und formal geprüft werden. Insbesondere ist eine leere Darstellung nicht mit der mathematisch leeren Menge oder einem physikalisch leeren Raum gleichzusetzen; ein FRZK-Nullzustand ist kein gewöhnlicher reeller Zahlenwert und ein orientierter Nullzustand nicht ohne zusätzliche Information rückskalierbar.', 'e3f14ce31cf6f4ee96da6671897da17a9301ed6996bf01ae18836e4901186353', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.1' LIMIT 1), 1, 'K1-P-0008', 'In meiner Nachhilfepraxis begegnen mir Aufgaben, bei denen Schülerinnen und Schüler die gegebenen Informationen zwar lesen oder notieren können, deren funktionale Beziehungen und die gesuchte Größe aber noch nicht erkennen. Die folgenden Beispiele begründen die Forschungsfrage aus meiner Perspektive. Sie sind zunächst Unterrichtsbeobachtungen und keine repräsentative empirische Untersuchung.', '012dc52f102dfbb019085f55f91d043a89c244c489d79c8a963df96b855271e2', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.1' LIMIT 1), 2, 'K1-P-0009', 'Beispiel 1: Eine Schülerin 3. Klasse Grundschule sollte die Aufgabe: „Ein Bauer hat 173 Kartoffeln und 8 Säcke. Wieviel Kartoffeln kommen in einen Sack und wie viele bleiben übrig?“. Mein Standardansatz zur Lösung von Textaufgaben besteht darin, alles, was gegeben ist, mit blau und alles, was gesucht ist, mit grün zu unterstreichen, dann die Angaben in den Notizblock zu übertragen und schließlich zu lösen. Ich habe der Schülerin diesen Ansatz empfohlen und ihr aufgetragen, die Aufgabe zu lösen. Nach etwa 15 Minuten habe ich versucht die Lösung zu kontrollieren und festgestellt, dass die Schülerin die gesamte Aufgabe mit blau unterstrichen hatte und in ihren Notizblock 1:1 übernommen hatte.', 'a4b0d374884a7224925c67a94c6820d2cced9d86187360dd47d0ff80bac21140', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.1' LIMIT 1), 3, 'K1-P-0010', 'Man könnte zunächst feststellen, dass die Aufgabe nicht im erwarteten Sinne gelöst wurde. Bei genauerer Betrachtung hatte die Schülerin jedoch meinen Arbeitsauftrag befolgt und die gesamte Aufgabenstellung als gegeben markiert. Ich deutete dieses Verhalten als möglichen Hinweis darauf, dass sie die für die Lösung benötigten Informationen noch nicht voneinander unterscheiden konnte. Ob ihr insbesondere die Situation mit Bauer und Kartoffeln unvertraut war, lässt sich aus dieser einen Beobachtung allein nicht sicher ableiten. Die Schülerin zeigte eine erkennbare Bearbeitungsaktivität; die mathematische Lösung und die dafür notwendige Interpretation der Angaben blieben zunächst offen.', '9901a3ea02ef48e81cf10832c0c0a399fe47be0cb894fae6d844c41b4d4316bc', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.1' LIMIT 1), 4, 'K1-P-0011', 'Ich erarbeitete daraufhin mit der Schülerin auf einem leeren Blatt Papier eine schrittweise Strukturierung der Situation. Die vom Autor bereitgestellte Anlage 1A („Inkrementelles Setup einer Textaufgabe“) veranschaulicht in fünf Bildern den Weg vom leeren Blatt über eine Orientierung in der Situation zur Unterscheidung von Gesuchtem und Gegebenem. Sie dokumentiert einen didaktischen Aufbau, ist aber kein datiertes Original der von der Schülerin angefertigten Lösung und kein standardisiert erhobener Lernfortschritt. Der berichtete Gesprächsverlauf bleibt eine retrospektive Unterrichtsbeobachtung.', '11139e280a9d4445a6d57db612bf1039557a639979fe870025baaae3e6d4409d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.2' LIMIT 1), 1, 'K1-P-0014', 'Zwei Schülerinnen aus der 9. Klasse Gymnasium standen vor der Aufgabe: „Wie würdest du deinem besten Freund oder deiner besten Freundin erklären, was eine lineare Funktion ist?“ Die Aufgabe zielte darauf ab, ein grundlegendes Verständnis für lineare Funktionen zu entwickeln, indem die Schülerinnen den Begriff selbstständig formulieren und ihre eigenen Worte finden sollten, um diese mathematische Beziehung zu erklären. Doch anstatt eine klare Vorstellung von einer linearen Funktion zu entwickeln, standen die Schülerinnen vor einer mentalen Blockade.', 'e061b41b28fd95b7cf051420081bbe6ba72d68d9c268212b83bd3c36f9772bc0', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.2' LIMIT 1), 2, 'K1-P-0015', 'In einer ersten Rückmeldung erklärten beide Schülerinnen, dass sie nicht wüssten, wie sie ihre Antwort beginnen sollten. Ich deutete dies als Hinweis darauf, dass ihnen ein sprachlicher und anschaulicher Zugang zu der gefragten Beziehung fehlte. Ob dabei die Begriffskenntnis, das Vorwissen, die konkrete Aufgabenstellung oder weitere Faktoren entscheidend waren, ließ sich in dieser Situation nicht isolieren.', 'cb048177eb6df53468d4c6137623d4c9b389d9c546f6ed23082984ab18c17502', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.2' LIMIT 1), 3, 'K1-P-0016', 'Eine der Schülerinnen äußerte: „Was ist das, eine Linie? Es sind doch Zahlen, aber wie hängen die zusammen?“ Sie hatte Schwierigkeiten, das Konzept einer linearen Funktion als eine mathematische Beziehung zu begreifen, die über abstrakte Zahlen und Parameter hinausgeht und in einem konkreten Zusammenhang, wie etwa einer realen Situation (z.B. eine Geschwindigkeit über Zeit oder den Zusammenhang zwischen dem Einkommen und den Arbeitsstunden), interpretiert werden könnte. Auch die andere Schülerin konnte die Aufgabe nicht anders angehen, als die Parameter der linearen Funktion als isolierte mathematische Elemente zu betrachten, ohne deren Einfluss auf die Gestalt der Linie oder auf die Veränderung der Werte in einer praktischen Anwendung zu begreifen.', '61bfb8ddbff3bcb03ddef29bb132b575df2ee7fef1aeecaffda71f56a3fce672', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.2' LIMIT 1), 4, 'K1-P-0017', 'In der Situation konnten die Schülerinnen die Formel einer linearen Funktion benennen, hatten aber Schwierigkeiten, die Bedeutung der Parameter und den Zusammenhang der Größen in eigenen Worten zu erläutern. Für meine Untersuchung ist daran besonders interessant, ob eine ausdrücklich geordnete Darstellung von Größen, Beziehungen und Beispielen den Übergang von einer symbolischen Schreibweise zu einer fachlich angemessenen Erklärung unterstützen kann.', '9fd4761666b2a8067a64328b2edec39dc7501cdb1419f6c508505b656b8429f7', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.2' LIMIT 1), 5, 'K1-P-0018', 'Ich beobachtete, dass die Schülerinnen zunächst nach einer bekannten Definition suchten und eigene Beispiele kaum verwendeten. Daraus ergibt sich für mich eine prüfbare didaktische Frage: Welche Darstellungshilfen erleichtern es Lernenden, den mathematischen Zusammenhang als Beziehung veränderlicher Größen zu beschreiben? Die Beobachtung allein lässt weder auf eine allgemeine Ursache noch auf die Wirksamkeit einer bestimmten Unterrichtsmethode schließen.', '729e238740fe322ca9f9606aea1e0e89f235a608beb9b7d85a4c830e7e8c3e39', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.2' LIMIT 1), 6, 'K1-P-0019', 'Die beiden Unterrichtsbeobachtungen lassen sich mit der didaktischen Frage verbinden, wie Lernende tragfähige Begriffe aufbauen und neues Wissen mit vorhandenem Wissen verknüpfen. Bruner behandelt die Struktur von Unterrichtsinhalten und die schrittweise Vertiefung grundlegender Vorstellungen (Bruner, Jerome S. (1960). The Process of Education. Cambridge, MA: Harvard University Press. DOI: 10.4159/9780674028999.)[8]. Ausubels Arbeiten befassen sich mit der Bedeutung der kognitiven Struktur für sinnvolles sprachliches Lernen (Ausubel, David P. (1963). The Psychology of Meaningful Verbal Learning. New York: Grune & Stratton.)[9]. Die genaue Zuordnung einzelner Buchseiten bleibt bis zur Editionsprüfung offen.', '3ec66c81be66901e42fa9700d8d68807e7b2c31185642c0c408ff975f854a941', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.3' LIMIT 1), 1, 'K1-P-0022', 'Rudolf Taschner: Der Irrtum des Pythagoras', '22d06b33af18e0b9aa2ebb934e118c431637fcffefe41e460207adcfe73a2bed', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.3' LIMIT 1), 2, 'K1-P-0023', 'Als Beispiel für die öffentliche Vermittlung mathematischer Fragestellungen nenne ich Rudolf Taschners Vortrag „Der Irrtum des Pythagoras“ (Taschner, Rudolf (2013). Der Irrtum des Pythagoras. Videoaufzeichnung, math.space, TIB AV-Portal. DOI: 10.5446/15789.)[10]. Für meine Arbeit ist daran die Frage relevant, wie ein zunächst ungewohnter mathematischer Zugang fachlich geprüft und verständlich erläutert werden kann. Ich übernehme aus dem Vortrag weder ein wörtliches Zitat noch eine Abbildung; seine Erwähnung dient als Anregung für diese didaktische Fragestellung, nicht als Beleg für die Wirksamkeit des FRZK.', '21633389646377f454882f6097110629d1d67e5a852b8dbef3c32b8abb79aba2', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.4' LIMIT 1), 1, 'K1-P-0026', 'Die Unterrichtsbeispiele verdeutlichen mein Erkenntnisinteresse: Lernende benötigen bei mathematischen Aufgaben nicht allein Rechenverfahren, sondern müssen Angaben, Begriffe und funktionale Beziehungen unterscheiden und aufeinander beziehen können. Ich möchte prüfen, ob ein systematischer Darstellungsrahmen dabei unterstützt, die Problemstellung zu verstehen, den Lösungsweg zu begründen und das Verfahren auf neue Aufgaben zu übertragen. Die Beispiele zeigen den Anlass dieser Untersuchung, nicht bereits deren Ergebnis.', '68d782a5c085ee4f34df95db950647a32ad41f7f198cc7342cb3b8b9a7859d33', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 1, 'K1-P-0029', 'Um die Entstehung meiner Forschungsfrage nachvollziehbar zu machen, wählte ich zunächst bewusst eine Aufgabe außerhalb meiner üblichen Nachhilfepraxis: Wie lässt sich eine gekrümmte, im Allgemeinen intrinsisch nichteuklidische Fläche auf einer zweidimensionalen Beobachtungsfläche durch berechnete Signalgrößen darstellen? Mein Interesse an Geometrie, Astronomie und physikalischer Modellbildung gab den Anlass. Die nachfolgende Beschreibung unterscheidet die ursprüngliche Ideenskizze von einem neu festgelegten, rechnerisch reproduzierbaren Referenzfall.', '39cff554a2b5f6382a7c2d81809023cb1d4acbe541d8bf408fa6778cd70bcd42', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 2, 'K1-P-0030', 'Bei der Bearbeitung trennte ich zunächst die Angaben, die frei wählbaren Annahmen und die gesuchten Ergebnisse. Unter einem zunächst leeren Bezugssystem verstand ich dabei kein physikalisches Vakuum und keine mathematisch leere Menge, sondern ein Koordinaten- und Darstellungsgerüst, dessen konkrete Objekte und Regeln ich erst nach und nach festlegte.', '2f337c31773881e091ac8057a8bc46083fd12f47804a50c012c13626b4b0cfe1', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 3, 'K1-P-0031', 'In der ursprünglichen Skizze setzte ich den Beobachter in den Ursprung eines räumlichen Koordinatensystems, führte eine gekrümmte Fläche ein und wählte ein gleichseitiges Dreieck als zweidimensionale Beobachtungsfläche. Die historische Darstellung in Abbildung 1.F2 dokumentiert diese Reihenfolge; aus der Skizze allein lassen sich jedoch weder die genaue Flächenfunktion noch messbare Signalwerte bestimmen.', 'f30f6a0ec1566d6f4f812a2017521cd47b87eddaee0c349bd01646bcbf5828da', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 4, 'K1-P-0033', 'Abbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.', '6b3b042c141e0553f86d2d94a991a88899b0ae1f4322b1fdc2a4c87effb84578', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 5, 'K1-P-0034', 'Die Darstellung unterscheidet den Beobachter im Koordinatenursprung, die dreieckige Beobachtungsebene und die untersuchte gekrümmte Fläche. Welche Eigenschaften die Fläche besitzt, ist mathematisch erst nach Angabe einer Parametrisierung und eines Definitionsbereichs entschieden.', '4a23f7be3232099b70187b20a316a0716480d048187635cf433125db2e646689', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 6, 'K1-P-0035', 'Eine zweidimensionale Darstellung macht eine dreidimensionale Situation nicht vollständig sichtbar. Daher unterscheide ich im Folgenden ausdrücklich zwischen den geometrischen Objekten des Modells, den berechneten Signalgrößen und deren Farbcodierung. Aus einer graphischen Projektion folgt weder, dass physikalischer Raum entsteht, noch, dass die Modellgröße eine tatsächliche Messung darstellt.', '136ea078b229342614ce810daaf81e0d022dafec847b2560e81e2b0c13229edd', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 7, 'K1-P-0036', 'Die geometrische Skizze beantwortete die eigentliche Aufgabe noch nicht. Um Beziehungen quantitativ auszuwerten, musste ich festlegen, welcher Punkt der gekrümmten Fläche welchem Punkt des Dreiecks zugeordnet wird. Eine solche eindeutige Zuordnung ist die hier benötigte Bezugsfunktion; sie ist eine Modellentscheidung und keine automatisch aus der Zeichnung folgende Gesetzmäßigkeit.', 'b0b693e5c873c5b271bb828c899e1ca9514a02034569585f48ba673ba80312ae', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 8, 'K1-P-0037', 'Anschließend ergänzte ich einen Sender und eine Signalvorschrift. Erst damit ließ sich jedem zugeordneten Punktpaar eine berechenbare Laufzeit zuweisen. Der Sender ist kein allgemeines Axiom des FRZK, sondern ausschließlich ein Bestandteil dieses technischen Beispiels. Die Einführung von Laufzeiten macht eine zeitbezogene Größe auswertbar; sie bedeutet nicht, dass sich die Geometrie selbst zeitlich verändern muss.', 'dae76d9d1574217c713f7f3116c1ebded39296ba7550fe72ce9d419808407471', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 9, 'K1-P-0038', 'Im Ausgangsgedanken sollte ein Signal vom Sender über einen Punkt der gekrümmten Fläche zu einem zugeordneten Punkt des Beobachtungsdreiecks gelangen. Die gesamte Weglänge wurde in eine Laufzeit umgerechnet und anschließend farblich kodiert. Damit entsteht eine zweidimensionale Darstellung eines aus einer dreidimensionalen Konstruktion abgeleiteten Skalarfelds. Für eine wissenschaftlich wiederholbare Berechnung sind die Geometrie, die Zuordnung und die Ausbreitungsannahmen ausdrücklich anzugeben.', '8041772119b135f5d5245c78c387d2144f89c2226a0312abc237512fd0723085', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 10, 'K1-P-0039', 'Abbildung 1.F3 zeigt die ursprüngliche Visualisierung solcher berechneten Laufzeitgrößen. Die dafür verwendeten Originalparameter, Programmdateien und Rohdaten sind hier nicht dokumentiert; deshalb gebe ich ihre Werte nicht nachträglich als überprüft aus. Stattdessen definiere ich im Folgenden ein unabhängiges Referenzmodell, mit dem derselbe methodische Rechengang vollständig nachvollzogen werden kann. Über einen rechtlichen Status oder Schutzrechte trifft dieser Abschnitt keine Aussage.', '888140fbd52d32862f31a63cf87e9e4f310694fd8379d565a623f8b897922eeb', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 11, 'K1-P-0041', 'Abbildung 1.F3: Ursprüngliche dreidimensionale Visualisierung modellierter Signallaufzeiten. Die historischen Rechenparameter sind für die vorliegende Fassung nicht belegt; die Darstellung wird daher nicht als numerischer Nachweis des nachfolgenden Referenzmodells verwendet. Eigene Darstellung.', '5bc3fe9c1f237a9b65284b9afc7783f2dbcec4a3c0518f8c4f9aeb4940c43ce5', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 12, 'K1-P-0042', 'Reproduzierbares technisches Referenzmodell', '50aba3203b5c2d326e6d3fe5d073280ab2478fa722b0ad1c47bf62109692daad', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 13, 'K1-P-0043', 'Die folgende Konkretisierung ist eine ausdrücklich neu festgelegte Modellvariante, keine nachträgliche Rekonstruktion der unzugänglichen Originalrechnung. Sie dient dazu, den in der Entstehungsgeschichte beschriebenen Rechenweg mit vollständig offengelegten Größen und Regeln zu demonstrieren. Alle Koordinaten und Längen werden in Metern, Zeiten in Sekunden beziehungsweise Nanosekunden angegeben.', '2655afa9db75f869005c1b8d9a6aa38bc6ff3bcfdc1c366a867f6b7cd1d9cba9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 14, 'K1-P-0044', 'Koordinatensystem und Dreieck. Der Beobachter O=(0, 0, 0) ist der geometrische Bezugspunkt. Das Beobachtungsdreieck liegt in der Ebene x=b mit b=1 m; seine Seitenlänge beträgt s=1 m. Für die beiden ebenen Koordinaten u und v wird das abgeschlossene Dreiecksgebiet D durch die Eckpunkte A, B und C festgelegt (Gleichung 1.1):', '11269b12189f9b48266b477e4bd8624c8b52c3ed7f561f4a1c478e0acdfeffb7', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 15, 'K1-P-0046', 'Word-LaTeX: A=(-\\tfrac{s}{2},-\\tfrac{s}{2}),\\quad B=(\\tfrac{s}{2},-\\tfrac{s}{2}),\\quad C=(0,\\frac{(\\sqrt{3}-1)s}{2})', '9f5c02e712181b4c3a120116988e0bb83c92f7038857b02def4fa4e90ef32d49', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 16, 'K1-P-0047', 'Die Punkte A, B und C der vorstehenden Formel sind (u,v)-Koordinaten in der Beobachtungsebene. Das Dreieck ist gleichseitig, denn alle drei Seiten haben die Länge s. Jeder Punkt (u,v)∈D beschreibt genau einen Beobachtungspunkt P(u,v) in der Ebene x=b.', '6a8b436d2bc6dd3a47f650d9ae608d932e40b1f061e4953577cd2f705c9659e2', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 17, 'K1-P-0048', 'Gekrümmte Fläche und Bezugsfunktion. Im dreidimensionalen Raum definiere ich die Fläche Q durch die folgende Parametrisierung. Für das Beispiel setze ich d=3 m und a=0,20 m⁻¹; der Definitionsbereich der Fläche ist genau das Dreiecksgebiet D. Die Zuordnung P(u,v)↔Q(u,v) verwendet dieselben beiden Parameter u und v und ist daher eindeutig (Gleichung 1.2).', '32ced43e75d6a2a670d1d8bdf20dbb37136af8b65fb88942e63faa92c94a892b', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 18, 'K1-P-0050', 'Word-LaTeX: Q(u,v)=\\left(d+a(u^{2}-v^{2}),\\,u,\\,v\\right),\\qquad P(u,v)=(b,u,v)', '487a9fa3c5a62559dab8db08e45dd8a094cf18f0b00bbed31d4559184469d686', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 19, 'K1-P-0051', 'Die Oberfläche ist eine Sattelfläche. Ihre Gauß-Krümmung ergibt sich aus den ersten und zweiten Ableitungen der Flächenfunktion und ist bei a≠0 überall negativ (Gleichung 1.3):', '1e1af513a310098382d6ab09b6e029b4ba98ada0176fd7680cca8e8d78b0e316', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 20, 'K1-P-0053', 'Word-LaTeX: K(u,v)=\\frac{-4a^{2}}{\\left(1+4a^{2}(u^{2}+v^{2})\\right)^{2}}<0', 'cc53ade50c584193f5c12932bd5581401c9894d8be37d416ae205244ca71109f', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 21, 'K1-P-0054', 'Damit ist „nichteuklidisch“ in diesem Beispiel präzisiert: Gemeint ist die innere Geometrie einer gekrümmten zweidimensionalen Fläche, nicht eine Krümmung des umgebenden dreidimensionalen Raums oder der physikalischen Raumzeit. Wege außerhalb der Fläche werden im Referenzmodell euklidisch berechnet.', 'dacaf80ad81a6301e5ac12298a388abcb45ba8736c3d3f57dd2ee246bf8d4b7c', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 22, 'K1-P-0055', 'Sender, Signalweg und Ausbreitungsannahmen. Der Sender liegt bei S=(xₛ,0,0) mit xₛ=5 m. Jeder Flächenpunkt Q(u,v) wird idealisiert als punktförmiger, unmittelbar weiterstrahlender Signalpunkt angenommen. Für das jeweilige Parameterpaar wird genau der zweite Wegabschnitt von Q(u,v) zu P(u,v) ausgewertet. Beide Wegabschnitte sind gerade Strecken im dreidimensionalen euklidischen Raum. Das Modell setzt Vakuumausbreitung mit konstanter Geschwindigkeit c, keine Laufzeitverzögerung am Flächenpunkt und keine Abschwächung voraus. Brechung, Beugung, Mehrfachwege, Abschattung und die winkelabhängige Reflexionsbedingung werden nicht modelliert. Das ist eine idealisierte Zuordnungsvorschrift und kein vollständiges optisches Reflexionsmodell.', '6a873c2bbdf09baad1ce1f5235d228c2d1bb0e0112e7711bc1f891a76e8f676d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 23, 'K1-P-0056', 'Mess- beziehungsweise Rechengröße. Die zugeordnete Gesamtlaufzeit ist die Summe der beiden euklidischen Segmentlängen, geteilt durch die Ausbreitungsgeschwindigkeit. Mit xₛ=5 m, b=1 m, d=3 m und a=0,20 m⁻¹ gilt (Gleichung 1.4):', 'a0eef7676e5e5120ca5c9603e71925a13db5cc8c673624dd6b72bf0b8ab32bb9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 24, 'K1-P-0058', 'Word-LaTeX: \\tau(u,v)=\\frac{\\sqrt{\\left(x_{S}-d-a(u^{2}-v^{2})\\right)^{2}+u^{2}+v^{2}}+d+a(u^{2}-v^{2})-b}{c}', 'cdce6fb924ff3b624c6475b2051d4e14f45543fefbed18004a59e1d01253321f', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 25, 'K1-P-0059', 'Dabei steht c=299 792 458 m/s für die im Internationalen Einheitensystem exakt festgelegte Vakuumlichtgeschwindigkeit (Bureau International des Poids et Mesures (2026). The International System of Units, 9. Auflage, aktualisierte Fassung. DOI: 10.59161/AUEZ1291.)[15]. Die berechnete Laufzeit ist eine Modellgröße. Eine tatsächliche Messung oder ein bestimmter physikalischer Reflexionsvorgang wird dadurch nicht nachgewiesen.', '6eddb03f2b3bab8b47a86f4af24143b7e672574481858211002398a2f8579682', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 26, 'K1-P-0060', 'Ergebnisfunktion und Darstellung. Mit der Zuordnung jedes Beobachtungspunkts zu seiner Laufzeit entsteht ein Skalarfeld auf dem Dreieck (Gleichung 1.5):', '81c6062c4047872571baa3fb304a43684c059cdb425aa5768b668d2402653683', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 27, 'K1-P-0062', 'Word-LaTeX: F:P(u,v)\\longmapsto \\tau(u,v),\\qquad (u,v)\\in D', '912925769700d29ec67c46a4b26d4606433c0deaf24287c5e71c1504732ca9ad', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 28, 'K1-P-0063', 'Zur numerischen Darstellung werden die Bereiche −0,50 m ≤ u ≤ 0,50 m und −0,50 m ≤ v ≤ (√3−1)/2 m jeweils mit 281 gleichmäßig verteilten Stützstellen abgetastet. Ausgewertet werden ausschließlich Punkte innerhalb des abgeschlossenen Dreiecks D. An jedem gültigen Gitterpunkt werden Q, die beiden Signalstrecken und τ in dieser Reihenfolge berechnet. Für die reproduzierbare Farbkodierung in Abbildung 1.F4 wird der Bereich von 13,34 ns bis 13,75 ns fest vorgegeben; größere Werte entsprechen dem oberen Ende der Farbskala. Die exakte Gebietsmaske, die Farbstufen und der Algorithmus sind in Anlage 1E dokumentiert.', 'ff069135b7b8dc52e0da6210e35d1f3faa068498057c97deb530c694a42c2943', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 29, 'K1-P-0064', 'Kontrollrechnung. Für (u,v)=(0,0) folgt Q=(3,0,0) m und P=(1,0,0) m. Damit betragen beide Wegabschnitte jeweils 2 m. Aus der Gesamtstrecke von 4 m ergibt sich τ(0,0)=13,3426 ns. Für die beiden unteren Dreiecksecken A und B ergeben sich jeweils 13,7472 ns; für die obere Ecke C ergibt sich 13,4519 ns. Diese Zahlen lassen sich unmittelbar durch Einsetzen in die angegebenen Gleichungen kontrollieren.', 'e4271aaff3ce6b7af8d4fdbe313779b1555b09dde1e2176d3ae50fd297988082', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 30, 'K1-P-0066', 'Abbildung 1.F4: Numerisch reproduzierte Laufzeitverteilung auf dem Beobachtungsdreieck für die offengelegten Referenzparameter (s=1 m, b=1 m, d=3 m, a=0,20 m⁻¹, xₛ=5 m, c=299 792 458 m/s). Berechnung und Darstellung für diese Dissertation; nicht aus den historischen Abbildungen 1.F2 und 1.F3 abgeleitet.', '590413fa99c820bbc4854a98f7889b38fb33cdf6ca358fdd20c2be5d0e2a78c4', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 31, 'K1-P-0067', 'Prüfgrenzen des Referenzfalls. Die Gleichungen ermöglichen es, den geometrischen und numerischen Rechenweg unabhängig zu wiederholen; insbesondere sind Definitionsbereich, Flächenfunktion, Zuordnung, Signalweg, Konstanten und Farbbereich festgelegt. Damit ist die modellinterne Reproduzierbarkeit des hier definierten Referenzfalls hergestellt. Offen bleibt dagegen, ob die ursprünglichen Abbildungen auf denselben oder anderen Parametern beruhen. Ebenso ist mit der Konstruktion weder die physikalische Gültigkeit einer realen Signalstreuung noch eine allgemeine mathematische oder didaktische Wirksamkeit des FRZK belegt.', '5f0d66629255791d0e6e8eca70198f9ab0b8d94abaa4b70bd626fcdacd3340f0', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 32, 'K1-P-0068', 'Das Referenzmodell zeigt, wie sich eine technische Problemstellung durch explizite Annahmen, eine definierte Geometrie, eine Zuordnungsregel und überprüfbare Rechnungen bearbeiten lässt. Darin liegt sein methodischer Bezug zum FRZK: Aus einer zunächst offenen Frage wird ein nachvollziehbarer Lösungsweg entwickelt und geprüft. Weder die gewählte Geometrie noch die Signalvorschrift sind Bestandteile des allgemeinen FRZK-Grundgerüsts; spezielle mathematische FRZK-Zustände und Operatoren werden in diesem Referenzmodell nicht benötigt.', '81fc75cb8b244ccb59144beb86fb9b0a97e448a87631a2fba5d3411dac7a6451', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 33, 'K1-P-0069', 'Zwischen dem technischen Beispiel und meinen Unterrichtsbeobachtungen erkenne ich ein gemeinsames methodisches Motiv: Ich bestimme relevante Größen und Annahmen, ordne Beziehungen ausdrücklich zu und überprüfe die daraus ableitbaren Ergebnisse. Bei der Kartoffelaufgabe betrifft dies gegebene und gesuchte Angaben, bei linearen Funktionen die Abhängigkeit veränderlicher Größen. Eine Verbesserung von Lernleistungen ist damit noch nicht nachgewiesen.', '4bf3cf63f6827a00133df7c7c79384c3e3f31d16493b156f20e0ca137b7b25ac', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 34, 'K1-P-0070', 'Das technische Referenzmodell und die Unterrichtsbeobachtungen sind methodisch vergleichbar, aber weder mathematisch noch empirisch identisch. Carroll diskutiert das Verhältnis naturwissenschaftlicher Weltbeschreibung zu weiterführenden philosophischen Fragestellungen (Carroll, Sean (2016). The Big Picture: On the Origins of Life, Meaning, and the Universe Itself. New York: Dutton.)[11]. Dieser allgemeine Bezug begründet weder die vorliegende technische Modellwahl noch die pädagogische Wirksamkeit des FRZK.', 'edc3bb5968de263d1e6b8f41f021ab983a3a01762bc77473c9e76420d7246632', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 35, 'K1-P-0071', 'Im Beispiel der Grundschülerin konnte ich beobachten, dass sie zunächst alle Informationen als gleichwertig behandelte. Eine schrittweise Strukturierung der Aufgabe bot die Gelegenheit, zwischen den vorhandenen Angaben und der gesuchten Größe zu unterscheiden. Welche Rolle dabei die konkrete Alltagssituation, das Vorwissen und die sprachliche Aufgabenformulierung spielten, blieb offen.', '57ba752a3e0e2cac287a2c3a8f804ab547e9c64a15ba59bb038162449e9cf8ff', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 36, 'K1-P-0072', 'Bei den Schülerinnen der neunten Klasse zeigte sich eine andere Schwierigkeit: Eine bekannte Formel konnte nicht ohne Weiteres in eine verständliche Erklärung überführt werden. Für die Modellierung ist deshalb zu unterscheiden zwischen einer symbolischen Darstellung, den Bedeutungen ihrer Variablen und den funktionalen Beziehungen im jeweiligen Sachkontext. Die mögliche didaktische Wirkung einer solchen Unterscheidung ist Gegenstand meiner Untersuchung.', '973c310c571e454b5e7cb64fd60f7f45d77df760301eac3484cc2b16cd23fe02', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), 37, 'K1-P-0073', 'Aus beiden Situationen leite ich keine allgemeine Lerntheorie ab. Ich entwickle daraus eine Forschungsfrage nach dem Nutzen expliziter Orientierung: Hilft es, wenn Lernende einen mathematischen Zusammenhang durch eigene Beschreibungen, Beispiele und überprüfbare Zuordnungen erschließen?', '85f03896652ba3d5a1b1b7a2e39566ae87e3d30bfe5076232f36a7e01026b31d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.3' LIMIT 1), 1, 'K1-P-0076', 'Nach meinen Erfahrungen aus drei Jahren Nachhilfepraxis umfasst die Aufgabe eines Tutors mehr als das Nachholen versäumter Lerninhalte oder die kurzfristige Vorbereitung auf Leistungsüberprüfungen. In meiner Arbeit dienen die Nachhilfestunden auch der Vertiefung behandelter Themen, der Überprüfung des übergreifenden fachlichen Verständnisses und der schrittweisen Entwicklung eigenständiger Problemlösestrategien. Ich bezeichne diese Arbeit als spezifischer auf den einzelnen Lernenden ausgerichtet, weil ich Aufgaben, Erklärungen, Rückfragen und Übungsphasen unmittelbar an dessen fachlichen Voraussetzungen anpassen kann. Damit beschreibe ich die Möglichkeiten meiner konkreten Nachhilfepraxis, nicht eine allgemeingültige Überlegenheit der Nachhilfe gegenüber dem Schulunterricht.', 'b7b3697475d8862f4e00dc3aa034b663a3f15ae15136b581eba32794154bd829', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.3' LIMIT 1), 2, 'K1-P-0077', 'Der schulische Unterricht ist an Lehrpläne, Unterrichtszeiten und das gemeinsame Lernen einer Klasse gebunden. Auch dort finden Differenzierung, individuelle Förderung und Vertiefung statt. In meinen kleinen Nachhilfegruppen kann ich jedoch zusätzliche Zeit auf einzelne Verständnisfragen verwenden, frühere Grundlagen erneut aufgreifen und das Tempo sowie den Schwierigkeitsgrad der Aufgaben personenbezogen verändern. Die Vertiefung richtet sich dabei nicht nur auf aktuelle Hausaufgaben, sondern auf die fachlichen Zusammenhänge des jeweiligen Themengebiets.', '0c9f45859d53dff70e2b8f4bed53195e8d80ad1fc8fc6d2c60777c1ac35221b7', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.3' LIMIT 1), 3, 'K1-P-0078', 'Ein zentraler Bestandteil ist die allgemeine Verständniskontrolle über die unmittelbar bearbeitete Aufgabe hinaus. Dazu lasse ich Lernende Begriffe und Zusammenhänge in eigenen Worten erklären, Lösungsentscheidungen begründen, typische Fehler erkennen und bekannte Verfahren in veränderten Aufgabenstellungen anwenden. Zeigen sich dabei Lücken im Vorwissen, greife ich diese gezielt auf. Rückfragen, ergänzende Erklärungen und die Anpassung der Arbeitsblätter dienen so nicht allein der Kontrolle eines Rechenergebnisses, sondern der Überprüfung, ob der zugrunde liegende mathematische Gedanke verstanden wurde. Die in Abschnitt 1.5 erläuterte altersabhängige Selbstkontrolle von Arbeitsergebnissen ersetzt diese übergreifende fachliche Verständniskontrolle nicht.', 'b10c323f72fe114dc27264ddbf68e21027488dd9edca568c8ceda6b1f2f42093', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.3' LIMIT 1), 4, 'K1-P-0079', 'Ich messe der Lernatmosphäre, dem fachlichen Feedback und der nachvollziehbaren Rückmeldung über Lösungswege besondere Aufmerksamkeit bei. Hattie bündelt umfangreiche Forschung zu Faktoren schulischen Lernens und behandelt unter anderem die Bedeutung von Rückmeldung (Hattie, John (2009). Visible Learning: A Synthesis of Over 800 Meta-Analyses Relating to Achievement. London: Routledge.)[12]. Daraus lässt sich für meine konkreten Lerngruppen weder eine bestimmte Effektstärke ableiten noch die Wirksamkeit des FRZK voraussetzen; diese Zusammenhänge müssen im Untersuchungsdesign getrennt beobachtet werden.', '59b93ddcf7e08f945ee11a8d4372bab0a7439cf0e31accbdc534e943dcde990c', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.3' LIMIT 1), 5, 'K1-P-0080', 'Die individuelle Förderung berücksichtigt unterschiedliche Vorkenntnisse, Stärken, Schwierigkeiten und Interessen. Zu Beginn eines Themengebiets erhalten die Lernenden eine Concept-Map oder ein Kompendium als Überblick. Anschließend erfolgt die Vertiefung themen- und defizitorientiert anhand persönlich angepasster Arbeitsblätter. Durch gezielte Rückmeldungen und Verständnisfragen beobachte ich, welche Beziehungen bereits sicher erklärt werden können und wo weitere Übungen oder eine erneute grundlegende Erklärung erforderlich sind.', '60d83416518f19636be98fea700f33da4a9ad2602b4602c69385adbdc76fd74a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.3' LIMIT 1), 6, 'K1-P-0081', 'Nicht zuletzt spielt die Berücksichtigung der persönlichen Bezugssysteme der Lernenden eine zentrale Rolle. Lernende können nur dann effektiv lernen, wenn neue Informationen in ein für sie verständliches und handhabbares System eingebunden werden. Durch die Aktivierung und den Aufbau eines solchen Bezugssystems werden abstrakte Inhalte greifbar, Zusammenhänge sichtbar und das eigenständige Arbeiten gefördert.', '0b83d37b8cf06ec58132e56e80a7ce103ba0584a63e16cd0b4ab0c2c9f51d826', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.3' LIMIT 1), 7, 'K1-P-0082', 'Die Wirkung des Tutors auf die Lernenden ist entscheidend für den Erfolg der Nachhilfestunde. Ein Tutor hat die Aufgabe, eine positive, unterstützende Lernatmosphäre zu schaffen, die es den Lernenden ermöglicht, sich mit dem Stoff auseinanderzusetzen und gleichzeitig Vertrauen in ihre eigenen Fähigkeiten zu entwickeln. Die zwischenmenschliche Beziehung zwischen Tutor und Lernendem spielt dabei eine ebenso wichtige Rolle wie die fachliche Expertise. Empathie, Verständnis und die Fähigkeit, auf die individuellen Bedürfnisse des Lernenden einzugehen, sind ebenso entscheidend wie das Fachwissen.', '438afa266e25c2ffd9fafbe29ada0682087e49f1eb84f028706527163628e409', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.3' LIMIT 1), 8, 'K1-P-0083', 'Diese wechselseitige Beziehung bildet in meiner Nachhilfepraxis eine wichtige Arbeitsbedingung. Ich verstehe meine Rolle nicht allein als Wissensvermittler, sondern als Lernbegleiter, der eigenständige Lösungsversuche aufgreift und durch Erklärungen, Rückfragen und gemeinsame Überprüfung weiterführt. In schriftlichen Rückmeldungen und Rezensionen werden insbesondere eine verlässliche Unterrichtsstruktur, individuelle Vorbereitung, wiederholte Erklärungen und eine unterstützende Lernbeziehung hervorgehoben (vgl. die qualitative Materialauswertung in Abschnitt 1.5, Tabelle 1.2). Diese Fremdeinschätzungen ergänzen meine Eigenbeobachtungen, ersetzen aber weder eine systematische Vergleichsstudie noch einen gesonderten Wirksamkeitsnachweis des FRZK.', '26bf37af985a5ffaa06236c39903fdea659cd7d823f809d4d7ee8ab96a3370ff', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.1' LIMIT 1), 1, 'K1-P-0087', 'Die Unterschiede zwischen meinem Nachhilfeangebot und dem schulischen Unterricht liegen aus meiner Sicht vor allem in den Rahmenbedingungen und in der Schwerpunktsetzung. Der Schulunterricht verfolgt gemeinsame curriculare Ziele und muss die Lernprozesse einer ganzen Klasse organisieren. Die Nachhilfe kann demgegenüber unter den Bedingungen kleiner Lerngruppen gezielter an individuellen Wissenslücken, Verständnisproblemen und Interessen ansetzen. Sie bietet mir die Möglichkeit, einen Unterrichtsgegenstand so lange aus verschiedenen Blickwinkeln zu bearbeiten, bis der Lernende seine wesentlichen Begriffe und Beziehungen nachvollziehbar erklären kann. Dies ist eine Beschreibung meines praktischen Vorgehens, keine Aussage, dass entsprechende Förderung im Schulunterricht grundsätzlich fehlt.', '6754641c5cdbe2a58884ffa7be3320d039c8cba7c5e37ef80054e6975251f89d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.1' LIMIT 1), 2, 'K1-P-0088', 'In meiner dreijährigen Praxis hat sich für die Nachhilfe ein Schwerpunkt auf stoffliche Vertiefung, allgemeine Verständniskontrolle und eigenständige Anwendung herausgebildet. Bei der Kontrolle beschränke ich mich nicht auf richtig oder falsch gelöste Aufgaben: Ich frage nach dem Warum eines Verfahrens, überprüfe die Verfügbarkeit vorausgesetzter Grundkenntnisse und lasse ähnliche Zusammenhänge in neuen Darstellungen oder Kontexten erläutern. Aus den erkennbaren Schwierigkeiten leite ich die Auswahl und den Schwierigkeitsgrad der nächsten individuell angepassten Arbeitsblätter ab. Diese wiederkehrende Arbeitsweise ist eine qualitative empirische Eigenbeobachtung aus meiner Nachhilfepraxis; ein vergleichender Nachweis höherer Lernwirksamkeit gegenüber dem Schulunterricht ist damit nicht erbracht. Die direkte Prüfung sämtlicher Rechenergebnisse und die fachliche Überprüfung des Verständnisses behandle ich dabei als unterschiedliche Aufgaben; mit zunehmendem Lernstand kann ein größerer Teil der Ergebniskontrolle von den Lernenden übernommen werden.', '069d1436be628d11721025970f864ae143fb3bfbaa252b11e3bb1cda8710755c', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.2' LIMIT 1), 1, 'K1-P-0091', 'Ein zentrales Thema meiner Nachhilfe ist das jeweilige Vorwissen der Lernenden, das ich in diesem Zusammenhang als persönliches didaktisches Bezugssystem bezeichne. Ich versuche, mathematische Themen mit bereits vertrauten Vorstellungen und geeigneten Beispielen zu verknüpfen und zugleich die fachlichen Grundlagen hinter einem Verfahren zu verdeutlichen. Die in Abschnitt 1.1 beschriebenen Unterrichtsbeobachtungen zeigen Schwierigkeiten beim Erfassen von Aufgabenangaben beziehungsweise beim Erklären einer linearen Funktion. Aus diesen Einzelfällen lässt sich jedoch nicht sicher schließen, dass fehlender Lebensweltbezug die Ursache war.', '022e263fc36cdeca93876a937d7d01cccbfd906f3702a6c62d2a44e4e7fdb6c5', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.2' LIMIT 1), 2, 'K1-P-0092', 'Für meine Unterrichtsgestaltung ergibt sich daraus die Frage, ob Lernende die bearbeiteten Beziehungen auch unabhängig von der ursprünglichen Beispielaufgabe verstehen. Deshalb schließe ich an eine Erklärung gezielte Verständnisfragen, Varianten und Transferaufgaben an. Wenn eine Aufgabe richtig gerechnet, aber der zugehörige Zusammenhang nicht eigenständig erläutert werden kann, bildet dies in meiner Praxis einen Anlass für weitere Vertiefung. Ob die so gestaltete Nachhilfe zu nachhaltigeren Lernergebnissen führt, ist gesondert zu prüfen.', '1d773c6d35c077afc3d1a810b6a2f73663567d01c9cdc811cde38951bd149a08', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.3' LIMIT 1), 1, 'K1-P-0095', 'In meiner bisherigen Nachhilfepraxis begleite ich häufig Lernende, deren schulische Leistungen sehr unterschiedlich sind und die zum Teil erhebliche fachliche Schwierigkeiten mitbringen. Beobachtete Notenverteilungen aus meinen Gruppen sind bislang nicht nach einem einheitlichen Erhebungsverfahren dokumentiert worden. Deshalb verwende ich an dieser Stelle keine Prozentanteile als vermeintlich statistisch gesicherte Stichprobenbeschreibung. Die Ausgangsleistungen werden erst für die geplante Untersuchung nach festgelegten Kriterien erfasst. Eine konkrete anonymisierte Übersicht unterschiedlicher Klassenstufen und Schulformen innerhalb der Kursgruppen ist in Abschnitt 1.5 (Tabelle 1.1) dokumentiert; sie dient der Beschreibung der Lernumgebung, nicht als Nachweis von Lernerfolgen.', 'c996a31df5ceb7a116907f240fb17ca72fc713d7ec6c67d77b8326b7d3597a04', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.3' LIMIT 1), 2, 'K1-P-0096', 'Für die Unterrichtsgestaltung bedeutet dies, dass unterschiedliche Vorkenntnisse und Schwierigkeiten im Unterricht zu berücksichtigen sind. Standardisierte Erklärungen können hilfreich sein, müssen jedoch nicht für alle Lernenden ausreichen. Das Prinzip eines zunächst bewusst reduzierten Bezugssystems soll es ermöglichen, aufgabenrelevante Informationen schrittweise zu ordnen. Es setzt nicht voraus, dass die Lernenden tatsächlich ohne Vorwissen lernen können; vielmehr muss ich den Zusammenhang zu bereits vorhandenen Kenntnissen im Lernprozess untersuchen.', '1abab330cdf937cb5f093434f8e464ff305ce80a7f3ea03ff90f5a160eeb97d2', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.3' LIMIT 1), 3, 'K1-P-0097', 'Das Bezugssystem der Lernenden ist nicht mit einem mathematischen Koordinatensystem gleichzusetzen. Ich verwende den Ausdruck an dieser Stelle als didaktische Metapher für die jeweils verfügbaren Vorstellungen, Erfahrungen und Kenntnisse, mit denen Lernende Angaben einer Aufgabe einordnen. Ob die schrittweise explizite Darstellung funktionaler Beziehungen das eigene Verständnis und den Transfer unterstützt, bleibt Gegenstand der Untersuchung.', 'a35e295501d9111152ca95ef58aef4a86fdc1d232825701838407fda92722fd9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.3' LIMIT 1), 4, 'K1-P-0098', 'Bei der Bearbeitung einzelner Aufgaben nutze ich ein zunächst leeres Darstellungsblatt als methodisches Hilfsmittel, um aufgabenrelevante Angaben, Begriffe und Beziehungen schrittweise festzuhalten. Dieses aufgabenbezogene Vorgehen ist von der Concept-Map beziehungsweise dem Kompendium zu unterscheiden, die zu Beginn eines Themengebiets einen übergreifenden Überblick bereitstellen. Ich verbinde die Aufgabenbearbeitung in der Nachhilfe mit Fragen, Rückmeldungen und einer möglichst unterstützenden Lernatmosphäre. Ein nachweisbarer Lernvorteil folgt aus dieser Beschreibung noch nicht.', 'aaa4cae72e01f8834feb92aa7efa3a177ee74ce6ef9456937e4daad86ee66899', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.3' LIMIT 1), 5, 'K1-P-0099', 'Meine Erfahrungen als Nachhilfelehrer sowie meine Tätigkeiten als Verfahrenstechniker, IT-Projektleiter und Dozent helfen mir bei der Strukturierung von Aufgabenstellungen und bei der Gestaltung individueller Lernangebote. Das leere Bezugssystem setze ich in meiner Praxis als methodische Unterstützung ein. Ob diese Unterstützung zu nachweisbaren Verbesserungen beim Aufgabenverständnis, bei der eigenständigen Bearbeitung oder beim Transfer führt, muss ich anhand dokumentierter Lernverläufe und geeigneter Vergleichsmaßstäbe untersuchen.', '88dbd8c126c86aaa45b63818bbddcb476f07bd152047d704ab6fc064c327efdb', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.4.3' LIMIT 1), 6, 'K1-P-0100', 'Für meine Unterrichtspraxis bildet dieses Vorgehen einen erprobungsbedürftigen Ausgangspunkt zur individuellen Anpassung von Aufgaben und Hilfen. Darin sehe ich einen möglichen Untersuchungsgegenstand des FRZK, nicht bereits ein gegenüber regulärem Unterricht überlegenes Verfahren.', 'b813c043022c9f447e00642bb02a360183e38dbce72790839bcd54834df87e31', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 1, 'K1-P-0103', 'Meine Nachhilfe findet in Unterrichtsräumen der Schülerhilfe statt. Der hier beschriebene Raum verfügt über acht Plätze an einem quadratischen Tisch sowie über eine Tafel. Ich sitze gewöhnlich an einer Ecke des Tisches; auch einige Lernende bevorzugen bestimmte Plätze, die Platzwahl bleibt jedoch frei. Bei Bedarf ändere ich die Sitzordnung, beispielsweise um Gruppenarbeit zu ermöglichen, konzentriertes Arbeiten zu erleichtern oder den Zugang zum Laptop sicherzustellen.', 'f013e2c71263c251fdc0fe6f40ec0f8c47ba1251fa1c73f83676fa1a15080390', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 2, 'K1-P-0104', 'Ich möchte den Unterrichtsraum so gestalten, dass die Lernenden einen persönlichen Bezug zu ihm entwickeln und sich dort wohlfühlen. Obwohl acht Plätze vorhanden sind, betreue ich in meinen Lerngruppen höchstens sechs Lernende gleichzeitig. Zwei Lerngruppen haben eigene Plakate mit den Aussagen „Mathe macht stark“ und „Ma(ke)the Best“ angebracht. Diese Texte entstanden ohne meine Vorgabe; ich verstehe sie als Hinweise auf die Haltung der betreffenden Lernenden, nicht als systematisch erhobene Ergebnisse.', '737f586355ae2debce7bf459f7c2dcd902d5cdfe185ef029bf8ae0a0f9f6038b', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 3, 'K1-P-0105', 'Kursbelegung als dokumentierter Hinweis auf heterogene Lerngruppen.', '31a728d89cadd3b38cbc21869712031e0a01a95a1b2bac7894fa726305ee7e2d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 4, 'K1-P-0106', 'Ein konkreter Einblick in die Zusammensetzung meiner Lerngruppen ergibt sich aus der ICAS-Kursbelegungsansicht für die Woche vom 9. bis 15. November 2026. Der bereitgestellte Ausschnitt enthält fünf Unterrichtsgruppen mit jeweils fünf oder sechs eingetragenen Lernenden, insgesamt 27 Kursbelegungen. Zwei Lernende sind in jeweils zwei Gruppen eingetragen; damit lassen sich im Ausschnitt 25 unterschiedliche Lernende anhand der Einträge unterscheiden. Die erfassten Klassenstufen reichen von 5 bis 12. Schon innerhalb einzelner Kurse treten Unterschiede von mehreren Klassenstufen sowie verschiedene Schulformkennzeichnungen auf. In einer Gruppe werden Aufgaben aus Mathematik und Physik parallel bearbeitet. Die nachfolgende Übersicht gibt nur anonymisierte Strukturmerkmale wieder.', 'f32402952fca5e3f818d1bc23b8f040649ff9c61922a3e0ad07c60587c6678d7', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 5, 'K1-P-0108', 'Tabelle 1.1: Anonymisierte Kursbelegungen in fünf sichtbaren Lerngruppen. Quelle: ICAS-Kursübersicht, Woche 09.11.–15.11.2026, vom Autor bereitgestellter Bildschirmausschnitt; eigene Zählung. Die Schulformkürzel sind unverändert aus der Ansicht übernommen.', '3e0bcff06cd635eeddab2d5e431bd00a36d2901cc2fc7e7593da7cc85f1ef8e3', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 6, 'K1-P-0109', 'Die Übersicht dokumentiert die aktuelle organisatorische Heterogenität: Beispielsweise umfasst Gruppe D die Klassenstufen 7, 9, 10 und 12. Die gleichzeitige Betreuung unterschiedlicher Jahrgangsstufen und teils unterschiedlicher Fächer verlangt voneinander abweichende Aufgaben, Rückfragen und Erklärungen. Dies ist ein wesentlicher Grund für den Einsatz persönlich angepasster Arbeitsblätter und für die in diesem Abschnitt beschriebene alters- und lernstandsabhängige Selbstkontrolle. Bei einer vollständigen Kontrolle aller Aufgaben durch den Tutor würde die für individuelle Hilfe verfügbare Zeit entsprechend eingeschränkt.', 'c9fed3121c06198177f3fb23a734e708e55015484f31c08e37a9d19ff7c695cb', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 7, 'K1-P-0110', 'Die Kursübersicht ist ein Beleg für eingetragene Belegungen einer einzelnen, zum Zeitpunkt des Screenshots noch bevorstehenden Kalenderwoche. Sie erlaubt keine Feststellung über tatsächliche Anwesenheit, regelmäßige Belegungsmuster über drei Jahre, individuelle Lernfortschritte oder die Wirksamkeit des FRZK. Für eine empirische Auswertung der Unterrichtspraxis müssen Belegung, Anwesenheit, Lernstand und Leistungsentwicklung getrennt dokumentiert werden. Der ursprüngliche Bildschirmausschnitt enthält personenbezogene Angaben minderjähriger Lernender und wird deshalb nicht unverändert in die Dissertation übernommen.', 'f395cf9563a5a2ae7a7817502c57677ca852b13144c30e5c335513e7d4ab7ba5', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 8, 'K1-P-0111', 'Die 90-minütigen Lerneinheiten orientieren sich an vier aufeinanderfolgenden Phasen. Individuelle Fragen und Hilfestellungen erfolgen während der Arbeitsphase:', '74ce4b73175d4cfb68c9197ec5b661eedc79192f32b793783ac943f17e78f921', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 9, 'K1-P-0112', 'Blitzlicht – 5 Minuten: Die Lernenden berichten kurz über Erlebnisse und benennen ihre aktuelle Stimmung.', '9949129fdea47b6d95b4aebf194d9793de39d23b83ab862a48c1c680d7c79e0f', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 10, 'K1-P-0113', 'Arbeitsphase – 75 Minuten: Themenbezogene Vertiefung mit persönlich angepassten Arbeitsblättern, Bearbeitung fachlicher Defizite, Ergebnisselbstkontrolle und fortlaufende allgemeine Verständniskontrolle, bei Bedarf mit Übertragungsaufgaben.', 'a3e457decf3898f1598aee9449424f22140a94a40e6ff85eaab7af830b195cd7', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 11, 'K1-P-0114', 'Nachhilfehefter – 5 Minuten: Die Lernenden ordnen die erarbeiteten Unterlagen in ihre nach einem einheitlichen Ablagesystem geführten Fachhefter ein.', 'd5b571f5719b8c713940a4c572082398376e709e625747e9772fbd4fb9875671', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 12, 'K1-P-0115', 'Abschlussreflexion – 5 Minuten: Die Lernenden berichten über ihre Arbeit und darüber, was sie verstanden haben; ich gebe dazu eine individuelle Rückmeldung.', '4a3a4cd751ef68b2b4200d1dfadc476d18ae7333db89a24d49c32443a091ed59', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 13, 'K1-P-0116', 'Zu Beginn eines neuen Themengebiets erhalten die Lernenden von mir eine Concept-Map oder ein Kompendium. Dieses Material gibt einen fachlichen Überblick und macht wichtige Begriffe sowie Beziehungen sichtbar. Der anschließende Unterricht erfolgt themenbezogen und defizitorientiert mit persönlich angepassten Arbeitsblättern. Dabei vertiefe ich den Stoff, überprüfe fortlaufend, ob die Lernenden die fachlichen Zusammenhänge auch ohne unmittelbare Vorlage erklären können, und greife erkannte Lücken im Vorwissen auf. Zu den Verständnisprüfungen gehören Begründungsfragen, eigene Formulierungen, die Analyse von Fehlern und die Anwendung auf veränderte Aufgaben. Concept-Map oder Kompendium bleiben bei Bedarf als Nachschlage- und Orientierungsunterlagen verfügbar; sie ersetzen die individuelle Arbeitsblattarbeit nicht.', '41fd530f68f275ad37713aa3cd890a9194d5ff02c6c32b330860f641ee8cc595', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 14, 'K1-P-0117', 'Diese Abfolge aus thematischer Einführung, vertiefender Arbeitsblattarbeit und allgemeiner Verständniskontrolle habe ich über drei Jahre in meiner Nachhilfepraxis wiederholt angewandt und beobachtet. Nach meiner Praxiseinschätzung macht die zusätzliche Kontrolle über das bloße Rechenergebnis hinaus unterschiedliche Wissensstände und Verständnislücken sichtbar und ermöglicht mir, nachfolgende Aufgaben gezielter auszuwählen. Diese qualitative empirische Eigenbeobachtung wird durch Rückmeldungen von Lernenden und beobachtete schulische Leistungsentwicklungen ergänzt, die im Folgenden als eigene, unterschiedliche Beobachtungsarten ausgewiesen werden.', 'b4803e2035e4c603e62df0b6cdb08f2005fc4694844aede49493a4442e3c4b47', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 15, 'K1-P-0118', 'Rückmeldungen von Lernenden. Ergänzend zu meinen Unterrichtsbeobachtungen habe ich informelle Gespräche mit Schülerinnen und Schülern der 11. Gymnasialklasse geführt, die nach meiner Angabe bereits mindestens ein Jahr meine Nachhilfe besucht hatten. Die Lernenden beschrieben den wahrgenommenen Nutzen der Nachhilfe sinngemäß als deutlich bessere schulische Ausgangslage gegenüber einer Situation ohne diese Unterstützung. Für diese Gesprächsangabe liegen im hier ausgewerteten Material weder ein standardisierter Fragebogen noch vollständige Originalprotokolle oder eine gesicherte Anzahl befragter Personen vor (vgl. Nachweisstatus NB-16, Anlage 1B). Daher verwende ich sie ausschließlich als qualitative Selbsteinschätzung nach eigener Gesprächswiedergabe, nicht als systematisch ausgewertete Befragung oder Kausalbeleg.', '9b777af13fbab93bd4d392b760691ce47542b544d3dc288d96fa1b3c6260bfd8', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 16, 'K1-P-0119', 'Berichtete Notenentwicklung. In den bereitgestellten Unterlagen finden sich Elternmitteilungen und abgeschriebene Online-Rezensionen, die Verbesserungen in Mathematik beschreiben. Eine Elternmitteilung berichtet über den Wechsel einer Zeugnisnote von 4 auf 3 (NB-07), eine übermittelte Online-Rezension über eine Verbesserung um zwei Notenstufen (NB-09). Weitere Rückmeldungen berichten allgemeiner über verbesserte Noten (NB-10, NB-11); ein Bericht über mehrere Lehrkräfte ist nicht eindeutig meiner Unterrichtstätigkeit zuzuordnen (NB-13). Originalzeugnisse, Vergleichszeitpunkte und vollständige schulische Verlaufsdaten liegen zu diesen Angaben im Prüfkorpus nicht vor. Die Angaben belegen somit elterlich berichtete Leistungsentwicklungen, keine unabhängig verifizierten Notenverläufe und erst recht keine kausal nachgewiesene FRZK-Wirkung.', '0f17de8effe77f2362f0cb92061794e26041bb78b6634aab50e0f1b5363d5581', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 17, 'K1-P-0120', 'Qualitative Fremdrückmeldungen zur Unterrichtsgestaltung', 'f86cf3ff2bd864e3762d2560adbd2cb6ce1bafca159771b87285599964ca5778', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 18, 'K1-P-0121', 'Für die vorläufige explorative Sichtung habe ich eine vom Autor zusammengestellte Materialsammlung ausgewertet (private schriftliche Lernendenrückmeldungen, vom Autor redigierte Gesprächswiedergaben, Elternmitteilungen sowie übertragene Texte öffentlicher Rezensionen). Als Nachweisregister führe ich die einzelnen Fundstellen unter den Kennungen NB-01 bis NB-16 in Anlage 1B. Jede Kennung ist als Quelle, Textart, Aussagegehalt und Prüfstatus erläutert. Die Materialien wurden weder mit einem einheitlichen Fragenkatalog erhoben noch als vollständige Übersicht aller positiven und negativen Erfahrungen zusammengestellt. Deshalb handelt es sich um eine selektive qualitative Materialauswertung, nicht um eine repräsentative Befragung. Es werden keine Namen, Telefonnummern oder identifizierenden Details aus den Originalnachrichten in die Anlage übernommen.', '99eb8246f06090797095d246d5bceb411de19388db91fbcb72c294c27c73427f', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 19, 'K1-P-0122', 'Mehrere Rückmeldungen heben individuell vorbereitete Arbeitsblätter (NB-03, NB-14), eine feste Unterrichtsstruktur mit Blitzlicht und Reflexion (NB-03, NB-14) sowie wiederholte Erklärungen und gemeinsame fachliche Klärungen (NB-03, NB-14) hervor. Die Rückmeldung zur Einbeziehung eigener Lösungswege (NB-04) liegt als unmittelbar von einem Lernenden verfasste Ergänzung vor. Die fünfteilige Beschreibung zu NB-03 wurde hingegen vom Autor redigiert und dem Lernenden zur Verwendung vorgelegt; sie ist daher keine wortgetreue Verschriftlichung einer Schüleräußerung. Eine weitergehende Fassung wurde später vorgeschlagen, aber im vorliegenden Material nicht ausdrücklich bestätigt (NB-05) und deshalb nicht als Schülerrückmeldung ausgewertet.', 'f38924d6aa78ca427aa6cc575e35364b3aba183481dce340ca1027477722f195', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 20, 'K1-P-0123', 'Tabelle 1.2 ordnet die identifizierten Unterrichtsmerkmale den konkreten Fundstellen aus Anlage 1B zu. Mehrfachnennungen und mögliche Identitätsüberschneidungen werden nicht als statistisch unabhängige Antworten gewertet. Die Einträge zeigen, welche Merkmale in den vorliegenden Fremdrückmeldungen beschrieben werden, nicht wie häufig sie in der Grundgesamtheit vorkommen oder ob sie in jeder Stunde nachweislich umgesetzt wurden.', 'bd0af12edead862dd0dbfe009c0ae634afcf9ba0c2daf9ac3fee765ecc1e460a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 21, 'K1-P-0125', 'Tabelle 1.2: Qualitativ identifizierte Merkmale der Unterrichtsführung. Quelle: Materialsammlung „meine Bewertungen.txt“, eigene vorläufige Kategorisierung. Die Belegkennungen NB-xx verweisen auf das pseudonymisierungsarme Nachweisregister in Anlage 1B. Originalplattformen, berichtete Noten und Urheberschaften übertragener Rezensionstexte wurden nicht unabhängig überprüft.', 'e28e4185a3822dd9a239900f7dc8de1006708f86724927030a7336a199e09b1c', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 22, 'K1-P-0126', 'Methodische Grenzen der Rückmeldungen. Die Sammlung ist positiv selektiert und enthält auch bloße Entwürfe, vom Autor redigierte Gesprächszusammenfassungen und Verwaltungsnotizen. NB-05, NB-06, NB-08 und NB-15 werden nicht als bestätigte Lernendenbewertungen in die Befundbildung aufgenommen. Für NB-02 und NB-03 ist eine schriftliche Zustimmung der betreffenden Lernenden zur anonymisierten Verwendung der jeweils vorgelegten Formulierungen dokumentiert; diese Zustimmung ersetzt nicht automatisch weitere erforderliche datenschutz- oder sorgeberechtigtenbezogene Prüfungen. Die Einzeläußerung NB-04 ist ein direkter Zusatz desselben Lernenden wie NB-03 und kein zweiter unabhängiger Fall. Mögliche Überschneidungen zwischen persönlichen Mitteilungen und Plattformrezensionen sind nicht auflösbar; daher wird weder eine Zahl unabhängiger Personen noch eine Zufriedenheitsquote ausgewiesen. Kritik, Nichtteilnahme und ausbleibende Rückmeldungen wurden nicht systematisch erfasst.', 'f3564bfad61fd12e3d05a54c2d7f1e32a429b2e4b23662a14d1a03d5824b7467', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 23, 'K1-P-0127', 'Abgrenzung zum FRZK. Das anonymisierte Register dokumentiert Aussagen über meine bereits bestehende Nachhilfepraxis: Vorbereitung, angepasste Aufgaben, Lernbeziehung, Reflexion, individuelle Erklärungen und wahrgenommene Lernentwicklungen. Die beschriebenen Leistungen dürfen nicht als Wirkung des erst gesondert zu untersuchenden FRZK-Darstellungsrahmens gewertet werden. Weder der anfängliche Einsatz einer Concept-Map beziehungsweise eines Kompendiums noch die ungefähren prozentualen Kontrollmodelle sind durch die vorliegenden Fremdrückmeldungen als solche ausdrücklich belegt. Sie bleiben zunächst Aussagen über meine eigene Unterrichtsorganisation.', 'c5cbc5eabd66f2d7dc37fa69ad8a9f4cbde88fbf0a258111c99e07c5e374a561', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 24, 'K1-P-0128', 'Ergebniskontrolle, Selbstkontrolle und Betreuungszeit', '9996e923961dbac5eee5495fc9e13eae3ca69f02eea01d68f6c80b503227a993', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 25, 'K1-P-0129', 'Die beiden folgenden Orientierungsmodelle zur Unterrichtsorganisation beruhen auf wiederholten qualitativen Eigenbeobachtungen aus drei Jahren Nachhilfepraxis. Sie wurden weder durch standardisierte Zeitmessungen noch durch eine systematische Zählung aller Arbeitsergebnisse gewonnen und sind deshalb keine statistisch abgesicherten Verteilungen oder nachgewiesenen optimalen Unterrichtsquoten. Das erste Modell beschreibt, wer Arbeitsergebnisse kontrolliert; das zweite Modell betrifft die inhaltliche Gewichtung von Übungsrechnen und Problembearbeitung. Beide Modelle dürfen nicht miteinander gleichgesetzt werden. Unter Ergebniskontrolle verstehe ich die Prüfung bearbeiteter Aufgaben und Resultate. Davon unterscheide ich die allgemeine Verständniskontrolle anhand von Rückfragen zu Begriffen, Begründungen und Übertragungen, die unabhängig von der Klassenstufe Bestandteil meiner Betreuung bleibt.', '4ac15392bdce9beeadbffc1998c130e87125d722ec5dffe27c6f271a887f965a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 26, 'K1-P-0130', 'Für den ungefähren Anteil der durch mich unmittelbar kontrollierten Arbeitsergebnisse haben sich die in Tabelle 1.3 dargestellten, lernstandsabhängig anpassbaren Richtwerte herausgebildet:', '1a01e0924933fc9d03f32304e0e420ce4e8efcbcd90b2711a0360b82cd7386b6', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 27, 'K1-P-0131', 'Tabelle 1.3: Erfahrungsbasierte Aufteilung der Ergebniskontrolle nach Lernstufen. Eigene qualitative Praxisbeobachtungen aus drei Jahren Nachhilfe; keine standardisierte Messung.', '04f091c4f655e6db530381cb2a4953293c810451cba380c38c2a77b03d1334b9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 28, 'K1-P-0133', 'Die Lösungen in den Arbeitsblättern ermöglichen den Lernenden einen eigenständigen Abgleich ihrer Ergebnisse und, soweit vorhanden, ihrer Rechenwege. Erkannte Abweichungen führen zu erneuter Bearbeitung oder zu gezielten Rückfragen. Meine unmittelbare Kontrolle konzentriert sich bei älteren Lernenden stärker auf ausgewählte Aufgaben, erkennbare Fehlerschwerpunkte und die Überprüfung des fachlichen Verständnisses. Die Zuordnung in Tabelle 1.3 stellt keine starre Altersnorm dar: Lernstand, Aufgabenschwierigkeit und Bedarf an Unterstützung können eine andere Verteilung erfordern.', '1dbde270b4c29784ef5d42ca8e5f018e0b56a2427031bafefe29edc8195f52bd', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 29, 'K1-P-0134', 'Die Verlagerung geeigneter Ergebniskontrollen in die Eigenverantwortung hat auch organisatorische Gründe. Während einer 75-minütigen Arbeitsphase betreue ich zeitweise bis zu sechs Lernende unterschiedlicher Klassen- und Studienjahre. Würde ich für die vollständige Kontrolle der Aufgaben jedes Lernenden jeweils zehn Minuten ansetzen, ergäben sich rechnerisch 6 × 10 = 60 Minuten. Von der Arbeitsphase blieben dann nur 15 Minuten für individuelle Erklärungen, die Bearbeitung anderer Schwierigkeiten und allgemeine Verständniskontrollen. Wechsel- und Unterbrechungszeiten sind dabei noch nicht berücksichtigt. Diese Modellrechnung veranschaulicht einen möglichen Zeitkonflikt; sie ist keine standardisierte Zeitmessung.', '4f9f4b0d88a19b3f596d2e2a682a6e4be4db90c950f59a63b9caf0dd0187ea26', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 30, 'K1-P-0135', 'Aus meiner Unterrichtserfahrung wäre eine durchgängige vollständige Ergebniskontrolle sämtlicher Aufgaben durch mich bei sechs gleichzeitig betreuten Lernenden pädagogisch nicht angemessen: Die Zeit für die individuelle Betreuung der anderen Lernenden würde zu stark eingeschränkt. Die angeleitete Selbstkontrolle erhält daher eine doppelte Funktion: Sie unterstützt das eigenständige Arbeiten und schafft Betreuungszeit für fachliche Rückfragen und gezielte Vertiefung. Daraus folgt noch kein Nachweis einer höheren Lernwirksamkeit.', '02cc94d36369e961f4dddb4572b671056f8d0b43116b109a81ed15b6eeb3cbff', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 31, 'K1-P-0136', 'In der geplanten systematischen Untersuchung sollen die tatsächlich vom Tutor überprüften Arbeitsergebnisse, die selbst kontrollierten Lösungen, dabei unerkannte Fehler sowie zusätzliche Hilfestellungen gesondert dokumentiert werden. Auf diese Weise lassen sich die bisherigen Richtwerte später anhand nachvollziehbarer Beobachtungen prüfen.', 'e0d91553367a347ec5cbe71511d1ded0e6a6c28e40277a28e7b094e0a6812fb9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 32, 'K1-P-0137', 'Gewichtung von Übungsrechnen und Problembearbeitung', 'fefa29e09577c333921bf6d89ac5b2b7b89e4aeb429eb375211e52305613e4d5', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 33, 'K1-P-0138', 'Tabelle 1.4: Erfahrungsbasierte inhaltliche Schwerpunktsetzung in der Arbeitsphase. Die Anteile beschreiben eine ungefähre Planungspraxis, keine gemessenen Zeiten und keine allgemeinen Empfehlungen.', '2dcf3eca8c371a06657073d8b32c596baef14f7fe46ed0aff46759fa36112c2b', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), 34, 'K1-P-0140', 'Die zweite Einteilung beschreibt die von mir bevorzugte Gewichtung fachlicher Arbeitsschwerpunkte, nicht die Zeit für persönliche Ergebniskontrolle. Sie wird an individuelle Lernstände, Themen und Aufgaben angepasst; insbesondere kann notwendiges Übungsrechnen auch in höheren Klassen einen größeren Umfang erhalten. Die Angaben in den Tabellen 1.3 und 1.4 sind daher als erfahrungsbasierte, noch zu überprüfende Orientierung zu verstehen. Aus ihnen lässt sich weder eine allgemeingültige optimale Verteilung noch ein kausaler Einfluss auf schulische Leistungen oder auf die Wirksamkeit des FRZK ableiten.', '77d5a54e63fb40719532346c579394a5bdc024227b8a2b45273e423045904139', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.1' LIMIT 1), 1, 'K1-P-0144', 'Einige Ansätze der theoretischen Physik untersuchen, ob bestimmte Raumzeit- oder Gravitationseigenschaften aus tieferliegenden Strukturen hervorgehen können (Rovelli, Carlo (2016). Reality Is Not What It Seems: The Journey to Quantum Gravity. London: Penguin.)[13] (Verlinde, Erik P. (2017). Emergent Gravity and the Dark Universe. SciPost Physics, 2(3), Artikel 016. DOI: 10.21468/SciPostPhys.2.3.016.)[14]. Diese Ansätze sind nicht allgemein bestätigte Aussagen über die Entstehung der Raumzeit und stellen keinen physikalischen Gültigkeitsbeleg für das FRZK dar. Für meine Arbeit dienen sie ausschließlich als Beispiel dafür, warum die Unterscheidung von Grundannahmen und abgeleiteten Modellgrößen wichtig ist.', 'cbfebed7e1bd539c02fae06440ea84d4c589ee0c85c67f95b402d5343d74a280', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.2' LIMIT 1), 1, 'K1-P-0146', 'Systemtheoretische und kybernetische Arbeiten untersuchen unter anderem Rückbezüge, Beobachtungsbedingungen und die Abhängigkeit von Beschreibungen [2][3]. Für mein Vorhaben ist dies ein möglicher begrifflicher Vergleichsrahmen. Ich setze jedoch weder eine rekursive Selbstbezüglichkeit noch eine besondere Beobachterstruktur als notwendige Eigenschaft sämtlicher im FRZK dargestellter Funktionen voraus.', '56bb90b7889f6b1549a08cb522e09f27f184e7804b354545536ffe42fbb28125', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.3' LIMIT 1), 1, 'K1-P-0148', 'In der didaktischen und bildungswissenschaftlichen Forschung bestehen bereits mehrere Ansätze, die einzelne Aspekte meines Vorhabens berühren. Die Abgrenzung des FRZK muss deshalb bei konkreten Funktionen und prüfbaren Unterschieden ansetzen, nicht bei der bloßen Verwendung der Wörter „Struktur“, „Beziehung“ oder „Bezugssystem“. Für meine Untersuchung sind die Repräsentation fachlichen Wissens, das Bearbeiten mathematischer Probleme, die lernprozessbezogene Rückmeldung und das selbstregulierte Lernen von besonderer Bedeutung.', '852d72b1a07c8545b8b07df0715a1c602eb2684887a58a33e419b69d8843fad0', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.3' LIMIT 1), 2, 'K1-P-0149', 'Concept-Maps werden in der Literatur als grafische Werkzeuge zur Organisation und Darstellung von Wissen beschrieben. Novak und Cañas erläutern, dass Begriffe durch beschriftete Beziehungen zu sinnvollen Aussagen verknüpft werden können (Novak; Cañas, 2008, S. 1) [16]. In meiner Nachhilfepraxis dienen Concept-Maps oder Kompendien zu Beginn eines Themas der fachlichen Orientierung. Die anschließende Bearbeitung erfolgt überwiegend mit individuell angepassten Arbeitsblättern. Daraus folgt weder, dass diese Einführung bereits das FRZK darstellt, noch dass eine grafische Übersicht als solche eine methodische Neuerung ist.', '65bb24961d1af295309826b4be15e79086628ff1dce84f5f19a3ab1acc36baef', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.3' LIMIT 1), 3, 'K1-P-0150', 'Der Umgang mit mehreren Darstellungsformen ist ebenfalls wissenschaftlich untersucht. Ainsworth differenziert in ihrem DeFT-Rahmen zwischen der Gestaltung multipler Repräsentationen, ihren Funktionen und den kognitiven Anforderungen an die Lernenden. Ihr Beitrag zeigt zugleich, dass mehrere Darstellungen allein keinen Lernerfolg garantieren (Ainsworth, 2006, S. 183–198, insbesondere S. 183) [17]. Bei mathematischen Aufgaben unterscheide ich daher sprachliche Aufgabenbeschreibung, Gleichung, grafische Veranschaulichung und Bedeutung der Variablen. Ob der zusätzliche FRZK-Rahmen diese Übergänge erleichtert, ist eine offene Frage; der bloße Wechsel von Darstellungen ist keine FRZK-spezifische Leistung.', '79a07d7a9066f405a5b61e16e4417680a5b9e96fe14c301767eca631a84bc5ad', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.3' LIMIT 1), 4, 'K1-P-0151', 'Für das mathematische Problemlösen beschreibt Schoenfeld einen Analyseansatz, der kognitive Ressourcen, heuristische Strategien, Kontrolle des Lösungsprozesses und Überzeugungen unterscheidet (Schoenfeld, 1985) [18]. Die bibliografischen Angaben und diese thematische Gliederung sind durch den Verlag nachweisbar; eine auf einzelne Buchseiten bezogene Originalstellenprüfung steht noch aus. Meine Unterrichtsbeobachtungen zu Textaufgaben und linearen Funktionen lassen sich damit vorläufig in einen etablierten Forschungszusammenhang einordnen. Weder das Erkennen relevanter Angaben noch das Reflektieren eines Lösungswegs kann daher ohne weitere Abgrenzung als neu ausgewiesen werden.', '8814dc05a779c0183c6b702593561dc4b27bfe0836b1ca53c482d62c16eb7020', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.3' LIMIT 1), 5, 'K1-P-0152', 'Zur Rückmeldung und Verständniskontrolle unterscheiden Hattie und Timperley unter anderem Feedback zur Aufgabe, zum Bearbeitungsprozess und zur Selbstregulation (Hattie; Timperley, 2007, S. 86 und 90) [19]. Damit ist fachlich zu trennen, ob ich eine korrekte Endlösung kontrolliere, einen Lösungsweg bespreche oder die selbstständige Fehlerprüfung eines Lernenden fördere. Für meine altersabhängige Verlagerung der Ergebniskontrolle auf die Lernenden ist ergänzend die Forschung zur Selbstregulation einschlägig: Zimmerman beschreibt unter anderem Zielsetzung, Selbstbeobachtung, Selbstbewertung und Reflexion (Zimmerman, 2002, S. 64 und 68) [20]. Die in Abschnitt 1.5 genannten Prozentwerte bleiben gleichwohl empirische Richtwerte meiner Praxis und werden nicht durch diese Literatur als optimale Stufenmodelle bestätigt.', '84cb77764f9b303ce71bc75c84bb608ddafd926c6a267d4d8c0bbb47f7c1b11c', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.3' LIMIT 1), 6, 'K1-P-0153', 'Die Einzelförderung und die Unterschiede zur Gruppenunterrichtung werden unter anderem bei Bloom (1984) [21] thematisiert. Der historische Beitrag zu individuellen Tutorbedingungen ist ein Vergleichsrahmen, keine direkte Untersuchung meiner fachlich und altersmäßig heterogenen Nachhilfegruppen mit bis zu sechs Lernenden. Die Metadaten und der Untersuchungsgegenstand sind bibliografisch gesichert; der vollständige Primärtext wurde für die hier vorgelegte Stellenprüfung nicht ausgewertet. Aus Bloom leite ich deshalb weder eine bestimmte Effektstärke meiner Nachhilfe noch eine Überlegenheit gegenüber dem Schulunterricht ab.', '917c60bad6473d9035ec79396c5a2ddcf365100cbe67d41fe100fcf286a59547', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.3' LIMIT 1), 7, 'K1-P-0154', 'Als entwicklungsorientierter methodischer Bezugspunkt bleibt Design-Based Research relevant (Reinmann, 2005) [4]. Ein solcher Bezug erfordert die überprüfbare Dokumentation der Entwicklung, Erprobung, Rückmeldung und gegebenenfalls Überarbeitung des Verfahrens. Die bereits vorliegenden qualitativen Bewertungen aus Anlage 1B dokumentieren meine bestehende Unterrichtspraxis; sie ersetzen weder eine systematische Untersuchung der FRZK-Anwendung noch eine gezielte Gegenüberstellung mit bestehenden Verfahren.', '0c37ec2d3534a175fe5668749f91c507ba56832605dc8ddcf14a6a3a732e0826', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.4' LIMIT 1), 1, 'K1-P-0156', 'Die theoretischen Anknüpfungen betreffen unterschiedliche Ebenen: mathematische Modellierung und formale Gültigkeit, didaktische Darstellung und Unterrichtsorganisation sowie die Beobachtung von Lernprozessen. Systemtheorie und theoretische Physik dienen mir zur begrifflichen und methodischen Orientierung; die didaktische Begründung des Lernverfahrens muss hingegen auf einschlägiger Bildungs- und Mathematikdidaktik beruhen. Die gemeinsame Verwendung von Begriffen wie „Beobachtung“, „Orientierung“ oder „Kohärenz“ stellt keine Identität dieser Theorien her und belegt weder neue physikalische Gesetze noch die Wirksamkeit des FRZK.', '710a254c7ba41661b6d776a2069432a6dd3514f61bc6146c88dbbeed4b2cc8aa', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.5' LIMIT 1), 1, 'K1-P-0158', 'Concept-Maps strukturieren Begriffe und deren Beziehungen; in meiner Praxis eröffnen sie ein Thema. Multiple Repräsentationen, Problemlösestrategien sowie Feedback- und Selbstregulationsmodelle beschreiben weitere etablierte Aspekte des Lernprozesses [16][17][18][19][20]. Das FRZK beansprucht demgegenüber zunächst die Funktion eines ausdrücklich beschriebenen methodischen Vorgehens, das von der Problemformulierung über die Unterscheidung von Gegebenem und Gesuchtem, die Prüfung von Voraussetzungen und Zusammenhängen bis zur Entwicklung, Ausführung und Kontrolle einer Lösung reicht. Die mathematischen Erweiterungen des FRZK, insbesondere besondere Symbole und Operationen für Grenzwert- und Vektorprobleme, sind davon zu trennen. Ob die methodische Abfolge gegenüber bestehenden Problemlösestrategien eigenständig ist, muss kritisch verglichen und nicht bloß behauptet werden.', '5fc193fb24b27356b48dbb9d3fed51b72c86d1858924e7096cefa9ad072a48df', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.5' LIMIT 1), 2, 'K1-P-0159', 'Ein möglicher didaktischer Zusatznutzen folgt nicht schon aus einem geordneten Arbeitsblatt, einer Concept-Map oder einer ausführlicheren Erklärung. Zu prüfen ist, ob ein zusätzlich explizit durchlaufener und dokumentierter FRZK-Problemlöseweg bei vergleichbarer Aufgabenstellung und Tutorunterstützung zu nachvollziehbareren Begründungen, früherer Fehlererkennung oder besserem Transfer führt. Die besonderen Grenzwert- und Vektorzeichen sind für diese allgemeine Intervention nicht erforderlich. Gleiche Unterrichtsbedingungen ohne den zusätzlich festgelegten Ablauf bilden die Vergleichsbasis. Positive Rückmeldungen und Notenentwicklungen aus meiner bisherigen Nachhilfe belegen noch keinen solchen Zusatznutzen.', 'd8a40c3294c8e4e17a7e771ca4077c3648bb565167ba5b0d3ad5bf9374bb3329', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.5' LIMIT 1), 3, 'K1-P-0160', 'Die herangezogenen Arbeiten belegen, dass wesentliche Einzelbestandteile des beschriebenen Vorgehens bereits Forschungsgegenstände sind. Die vorliegende Auswahl ist jedoch keine vollständige systematische Recherche zu allen formalen Darstellungs- und Modellierungsverfahren. Dass hier kein mit dem vorgeschlagenen FRZK identisches Verfahren dargestellt wird, beweist deshalb weder seine weltweite Neuheit noch die Nichtexistenz verwandter Ansätze. Eine belastbare Neuheitsbehauptung verlangt eine gesonderte, methodisch dokumentierte Recherche und eine präzise Gegenüberstellung definierter Merkmale.', 'cb989213e66c51fc05cd23bef281d9005ebf9f061c7929e06f71fb35ba29f8c7', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.5' LIMIT 1), 4, 'K1-P-0161', 'Für die nachfolgenden Kapitel bestehen drei voneinander zu unterscheidende Prüfaufgaben: Erstens ist das methodische Grundgerüst des FRZK nachvollziehbar zu beschreiben und gegenüber vorhandenen Verfahren abzugrenzen. Zweitens müssen seine gesonderten mathematischen Erweiterungen auf definierte Bereiche, formale Konsistenz und mögliche Gegenbeispiele geprüft werden. Drittens ist ein möglicher didaktischer Zusatznutzen empirisch zu untersuchen. Die Prüfung einer Ebene ersetzt nicht die Prüfung einer anderen.', '246faab7ee797d84d52bffae5cdec66ea77cb087e68b0d250b8199cb0b4e7833', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7' LIMIT 1), 1, 'K1-P-0163', 'Ich unterscheide die Entwicklung des FRZK als methodischen Ansatz zur Problemstellung und Problemlösung von seinen zusätzlichen mathematischen Symbol- und Operationssystemen. Davon gesondert ist zu prüfen, ob das methodische Vorgehen im Unterricht Vorteile gegenüber der bestehenden Praxis bietet. Aus dieser Trennung ergeben sich methodische, formale und didaktische Forschungsfragen mit unterschiedlichen Geltungsbereichen.', '47b247824acb534b78b5eeddb498c8247c6890b536b4ccd25c661df07801d24f', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7' LIMIT 1), 2, 'K1-P-0164', 'Mit dem Funktionalen Raum-Zeit-Kohärenzsystem (FRZK) möchte ich Aufgaben so bearbeiten, dass aus einer zunächst zu klärenden Problemstellung ein begründeter, überprüfbarer Lösungsweg entsteht. Die methodische Abfolge umfasst Problemformulierung, Bestimmung der Angaben und Zielgrößen, Klärung der Voraussetzungen und Beziehungen, Entwicklung und Durchführung der Lösung sowie Ergebnisprüfung. Eine grafische oder formale Darstellung kann diesen Ablauf stützen, ist jedoch nicht selbst mit ihm gleichzusetzen. Der Ansatz beansprucht damit weder die Erzeugung physikalischer Raumzeit noch eine besondere mathematische Symbolik als universelle Voraussetzung.', '428751c5567985f30e844ef2f28d591312bdb9a221ff84ab514977982d6d5dd9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7' LIMIT 1), 3, 'K1-P-0165', 'Die erste Forschungsfrage lautet, wie sich dieser problemorientierte Ablauf so präzisieren lässt, dass er in verschiedenen mathematischen und gegebenenfalls weiteren fachlichen Situationen nachvollziehbar angewendet werden kann. Für konkrete Aufgaben sind die erforderlichen Größen, Annahmen, funktionalen Beziehungen und Gültigkeitsbedingungen jeweils ausdrücklich anzugeben. Besondere Fälle wie Rekursion, Rückbezug oder Kohärenzprüfung und die Verwendung spezieller Grenzwert- oder Vektorzeichen verlangen gesonderte Definitionen; sie gehören nicht notwendig zum allgemeinen methodischen Ablauf.', '488ca4d57a157f9f6ced5ae5372b0292ea6e5845b33a168d4ec371fb228c884e', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7' LIMIT 1), 4, 'K1-P-0166', 'Ein zweiter Forschungsgegenstand betrifft die formale Prüfung eigens eingeführter mathematischer FRZK-Erweiterungen. Zu klären ist, für welche definierten Mengen, Zustände und Operatoren die jeweiligen Rechenregeln widerspruchsfrei und reproduzierbar angewendet werden können. Diese Frage ist von der Verständlichkeit des methodischen Problemlösewegs ebenso zu trennen wie vom empirischen Nachweis einer didaktischen Wirkung.', '8864ad78efafe752ecb8f14530af181e1ec71a1dde4974288bd759861d94a82a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7' LIMIT 1), 5, 'K1-P-0167', 'Die didaktische Forschungsfrage lautet, ob und unter welchen Bedingungen die systematische Anwendung des beschriebenen Problemlösewegs das Aufgabenverständnis, die Auswahl und Begründung eines Verfahrens, die Fehlererkennung, die Ergebniskontrolle und die Übertragung auf neue Aufgaben unterstützt. Dabei ist die ausdrückliche Trennung zwischen Problemfrage, gegebenen Informationen, gesuchten Größen, Voraussetzungen und funktionalen Beziehungen ein möglicher, aber nicht der einzige Wirkmechanismus.', 'fe0996199ee5a42d4326074a44ccb3cb2ac49fd191c764359dd2ff5b1b90ba3d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7' LIMIT 1), 6, 'K1-P-0168', 'Ergänzend frage ich, wie die Nachvollziehbarkeit solcher Darstellungen beurteilt werden kann: Welche Merkmale machen einen Lösungsweg überprüfbar, welche Voraussetzungen müssen offengelegt werden und wie lassen sich Schwierigkeiten in der Anwendung des FRZK selbst dokumentieren? Dabei berücksichtige ich ausdrücklich auch Fälle, in denen der Ansatz keinen erkennbaren Zusatznutzen bietet.', 'efd982d24b855a6ca2b8cf849e65d4f32627c57e35e16ec87aff2540d2667dbf', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7' LIMIT 1), 7, 'K1-P-0169', 'Diese Fragen bestimmen die Gliederung der Untersuchung. Zunächst arbeite ich die relevanten wissenschaftlichen Bezüge und die mathematischen Voraussetzungen heraus. Darauf folgen die Beschreibung des Modellierungsrahmens sowie seine fachliche und didaktische Prüfung. Ein interner Konsistenznachweis ersetzt keine empirische Untersuchung.', '9c163c38b5c3068f2417c28f2cfecda605310675f118d717b59ebbc7095ee272', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.1' LIMIT 1), 1, 'K1-P-0171', 'Forschungsgegenstand.  Ich untersuche drei getrennte Gegenstände: erstens das FRZK als methodischen Ablauf vom Formulieren bis zum Lösen und Prüfen einer Problemstellung; zweitens die fachliche Gültigkeit gesondert definierter mathematischer Erweiterungen für Grenzwert- und Vektoraufgaben; drittens den möglichen didaktischen Zusatznutzen eines ausdrücklich angewendeten FRZK-Problemlösewegs gegenüber der bereits etablierten Nachhilfepraxis. Die positiven Schüler- und Elternrückmeldungen aus Anlage 1B charakterisieren diese Praxis; sie sind keine Interventionsdaten zur Wirksamkeit des FRZK.', '2e882c5d0a62e455b5bbe167b52794549cee650aae95c477b4b35ae9b4482b95', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.1' LIMIT 1), 2, 'K1-P-0172', 'Primäre didaktische Frage (F1).  Verbessert die zusätzliche, ausdrücklich dokumentierte Anwendung des methodischen FRZK-Problemlösewegs bei fachlich vergleichbaren Aufgaben und vergleichbarer Tutorunterstützung die Nachvollziehbarkeit einer selbstständig entwickelten Lösung gegenüber der üblichen themen- und defizitorientierten Bearbeitung? Als primärer Vergleichswert ist ein vorab fixierter Summenwert aus vier Kriterien von 0 bis 12 Punkten vorgesehen. Sonderzeichen der Grenzwert- und Vektorrechnung sind für diesen allgemeinen Vergleich nicht vorgesehen.', '1649d8c322c74bd55b0cce2330c47c690951a2d6101da7e64929e3d058ab6885', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.1' LIMIT 1), 3, 'K1-P-0173', 'Sekundäre Fragen (F2–F4). F2: Erkennen Lernende fachliche Fehler oder unzulässige Annahmen früher bzw. selbstständiger? F3: Übertragen sie eine erarbeitete Beziehung auf eine neue, strukturell vergleichbare Aufgabe? F4: Welchen zusätzlichen Zeit- und Unterstützungsbedarf erzeugt die Darstellung, und in welchen Lernstufen oder Aufgabentypen erscheint sie hilfreich, entbehrlich oder hinderlich? Eine erwartete positive Wirkung ist eine Arbeitshypothese, kein bereits vorliegendes Ergebnis. Nullbefunde und Nachteile gehören zum Untersuchungsgegenstand.', '6e2367bb3395d777c6f3c2d464114177738e2d2c70808638536489b90cfa70a3', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.2' LIMIT 1), 1, 'K1-P-0175', 'Gemeinsame Unterrichtsbasis. Beide Bedingungen finden innerhalb der regulären, 90-minütigen Nachhilfe statt. Der Themenbeginn kann durch eine Concept-Map oder ein Kompendium vorbereitet werden; anschließend arbeite ich mit persönlich angepassten Aufgabenblättern, fachlichen Rückfragen, vertiefenden Erklärungen, einer altersabhängigen Ergebnisselbstkontrolle und einer Abschlussreflexion. Diese Bestandteile sind keine FRZK-spezifische Intervention. Die festgelegte Unterrichtsorganisation mit Blitzlicht, Arbeitsphase, Hefterführung und Auswertung bleibt unverändert.', 'e0f96b6f7b4441a93e10edb74629c8cabda14098bdbaa8f0cd0b5348f8d68991', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.2' LIMIT 1), 2, 'K1-P-0176', 'Bedingung K (übliche Bearbeitung). Lernende bearbeiten eine fachlich passende Aufgabe mit den gewohnten Hilfen und zugelassenen Lösungsdarstellungen. Sie dürfen Angaben unterstreichen, Skizzen anfertigen, Formeln verwenden, nachfragen und Lösungen selbst kontrollieren. Es wird jedoch kein zusätzliches verpflichtendes FRZK-Protokoll vorgegeben. Bereits vorhandene Strukturierungsstrategien werden nicht künstlich unterbunden; ihr Auftreten wird im Protokoll vermerkt.', 'f098bb7bbd08b189672b1d3b0ebb59f85065c9d19f64c96fee65fbe0d051b7a8', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.2' LIMIT 1), 3, 'K1-P-0177', 'Bedingung F (zusätzlicher FRZK-Schritt).  Bei identischer fachlicher Zielsetzung bearbeiten Lernende die Aufgabe mithilfe eines einseitigen, vorab festgelegten FRZK-Problemlösebogens mit fünf Schritten: (1) die Problemfrage und das Ziel verständlich formulieren, (2) Gegebenes und Gesuchtes unterscheiden, (3) erforderliche Annahmen, Größen und Beziehungen begründet festlegen, (4) einen Lösungsweg entwickeln und ausführen und (5) Ergebnis, Gültigkeit und Übertragbarkeit prüfen, soweit fachlich sinnvoll. Die Schritte sind anhand der Schülerlösung nachvollziehbar. Spezielle FRZK-Grenzzeichen, Nullzustände oder Vektoroperationen gehören nicht zum methodischen Grundgerüst und werden in diesem allgemeinen Unterrichtsvergleich nicht verlangt.', '9769159d8030a2f147216922a89f4957720db3c2618d5aba106058400cff9a20', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.2' LIMIT 1), 4, 'K1-P-0178', 'Isolierung des Unterschieds. Zwischen K und F darf nicht zugleich die Qualität des Arbeitsblatts, die verfügbare Arbeitszeit, die Intensität der Tutorhilfe oder der Zugang zu Lösungen verändert werden. Die FRZK-Bearbeitung erfolgt innerhalb derselben vorgesehenen Aufgabenzeit. Zusätzliche Hilfen, Zeitüberschreitungen und unvorhergesehene Abweichungen werden erfasst. Die vollständige Beschreibung von Materialien, Durchführung, Anpassungen und tatsächlicher Anwendung orientiert sich ergänzend an der TIDieR-Berichtsstruktur [22]; diese stammt aus der Interventionsforschung und wird hier nur als Dokumentationshilfe, nicht als Wirksamkeitsnachweis verwendet.', 'f58b361184a3d4f02ed7f4aa4a059efd5353dc812c6f2b70b43b863d38314f4a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.3' LIMIT 1), 1, 'K1-P-0180', 'Explorative Planung. Vorgesehen ist eine kleine, nicht repräsentativ gezogene Gelegenheitsstichprobe von ungefähr 25 Lernenden aus unterschiedlichen Schularten und Klassen- bzw. Studienjahren. Die sichtbaren Kursbelegungen aus Tabelle 1.1 entsprechen nicht automatisch der späteren Forschungsstichprobe. Einschlusskriterien, Einwilligungen, verfügbare Lernende, Teilnahmezeitraum, Ausgangsleistungen sowie dokumentierte Ausschlüsse werden vor Beginn der Auswertung festgelegt. Aussagen über eine repräsentative Gesamtpopulation sind nicht beabsichtigt.', '647e1f4f464055e44197d9d62a5b3b7d59989cb8d8de0edfeeb9e96fa0fe72f9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.3' LIMIT 1), 2, 'K1-P-0181', 'Aufgabenpaare. Für vorab bestimmte Stoffgebiete werden Aufgabenpaare konstruiert, die denselben mathematischen Kompetenzbereich, ähnliche Rechenanforderungen und einen vergleichbaren sprachlichen Schwierigkeitsgrad aufweisen. Mindestens ein Aufgabenpaar umfasst das Identifizieren relevanter Angaben, ein anderes die Erklärung funktionaler Beziehungen; eine neue Transferaufgabe wird gesondert bereitgestellt. Eine fachkundige zweite Person prüft die Vergleichbarkeit der Aufgaben, bevor die eigentliche Untersuchung beginnt. Die Aufgaben einschließlich Musterlösungen werden versioniert archiviert.', '7f5179c8ac74a43d9d9eef54d1a54f6a3f62cbd1009799a465c65d4a1f324abf', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.3' LIMIT 1), 3, 'K1-P-0182', 'Zuordnung und Reihenfolge. Wenn durchführbar, bearbeitet ein Lernender mehrere vergleichbare Aufgaben unter beiden Bedingungen; die Reihenfolge K→F bzw. F→K wird nach einem vorab dokumentierten Plan ausbalanciert. Eine zufällige Zuordnung wird nur dann berichtet, wenn sie tatsächlich durchgeführt und protokolliert wurde. Lern- und Übertragungseffekte sind besonders kritisch, weil einmal erlernte FRZK-Schritte in späteren K-Aufgaben weiterverwendet werden können. Ein solcher Übertrag ist keine Verletzung durch den Lernenden, sondern ein möglicher Störfaktor und zugleich ein zu dokumentierender Befund. Falls er die Trennung der Bedingungen verhindert, beschränke ich die Auswertung auf Machbarkeit und beschreibende Beobachtungen oder verwende ein prospektiv begründetes anderes Vergleichsdesign.', '199ebb0341816fa254f469b465a16815d76c0ff26e62ab5a24ecd83726feb17d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.3' LIMIT 1), 4, 'K1-P-0183', 'Unterrichtsalltag als Kontext. Die Lerngruppen können bis zu sechs Personen mit unterschiedlichen Klassenstufen umfassen. Für die Untersuchungsaufgaben muss daher festgelegt werden, welche Zeitfenster, individuellen Tutorhinweise und äußeren Unterbrechungen zulässig sind. Die reguläre Förderung anderer Lernender darf durch die Datenerhebung nicht beeinträchtigt werden. Fachlich notwendige Hilfen werden aus pädagogischen Gründen nicht verweigert, sondern mit Zeitpunkt, Art und Umfang protokolliert.', '5e3351c91401aad9cf145083beefdd8eb689e523af5b61ca9ef8bbc7f01837d9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.4' LIMIT 1), 1, 'K1-P-0185', 'Primärer Zielwert. Der Lösungsweg wird mit einem vierdimensionalen Bewertungsraster beurteilt: A – korrekte Bestimmung gegebener und gesuchter Größen; B – Beschreibung funktionaler Beziehungen und wesentlicher Gültigkeitsbedingungen; C – fachlich begründete Wahl und Durchführung des Lösungsverfahrens; D – selbstständige Übertragung auf eine neue, strukturell ähnliche Aufgabe. Jede Dimension erhält 0 bis 3 Punkte, insgesamt 0 bis 12 Punkte. Der Transferwert D wird ausschließlich aus einer gesonderten, vorab festgelegten Transferaufgabe ermittelt, nicht aus der Wiederholung des vorgeführten Lösungswegs. Die vorläufigen Ankerbeschreibungen stehen in Anlage 1D.', 'ebcefa606f6166fd988e3474de52eef8a8b51d8743aa5a30f8516969621d2d4c', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.4' LIMIT 1), 2, 'K1-P-0186', 'Bewertungsvoraussetzungen. Vor Beginn der Hauptdatenerhebung werden die Aufgaben und die vollständigen Ankerbeispiele für die Punktstufen 0, 1, 2 und 3 fachlich erprobt, erforderlichenfalls überarbeitet und anschließend als feste Version freigegeben. Die Punktzahl 0–12 ist eine entworfene, nicht bereits validierte Bewertungsskala. Lösungen werden nach Möglichkeit ohne Angabe der Bearbeitungsbedingung pseudonymisiert durch eine zweite fachkundige Person bewertet; Abweichungen zwischen den Bewertungen werden dokumentiert. Eine Anpassung des Rasters an bereits beobachtete gewünschte Ergebnisse ist ausgeschlossen.', 'bc945a8102e87c3a3e0b69a01c4df466b98219a55dcf6c5774dc6dbd6cfd6a7e', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.4' LIMIT 1), 3, 'K1-P-0187', 'Weitere Beobachtungsgrößen. Sekundär werden Bearbeitungszeit und gegebenenfalls Zeitüberschreitung, fachliche Fehlerarten, selbstständig bemerkte und korrigierte Fehler, Häufigkeit und Art von Tutorhinweisen, tatsächlich geleistete Selbstkontrolle sowie vollständig, teilweise oder nicht ausgeführte FRZK-Schritte protokolliert. Notenänderungen und die bereits vorliegenden Bewertungen der Nachhilfepraxis gehören nicht zum primären FRZK-Vergleich.', '214e80336c0c5f7268a327202cb788190d543f18eb0efb180432b44e3e0219b0', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.5' LIMIT 1), 1, 'K1-P-0189', 'Sitzungsprotokoll. Zu jeder ausgewerteten Aufgabenbearbeitung sind mindestens pseudonymisierte Kennung, Klassen- oder Studienjahr, Aufgaben- und Materialversion, Stoffgebiet, Datum, Bedingung K/F, Zuordnungs- und Reihenfolgeplan, Dauer, Hilfen, Selbstkontrolle, unerwartete Ereignisse sowie die archivierte Schülerlösung zu dokumentieren. Die Datenerfassung erfolgt in meiner didaktisch-methodischen Datenbank. Deren konkrete technische Bezeichnung, Datenmodell, Zugriffsrechte und Prüfregeln werden erst im Methodenkapitel verbindlich angegeben. Ein Muster des Protokolls steht in Anlage 1D.', 'ca4ac7095125985b4d1db00f3a6c5725ee0e2ff4f354fc66bdeb528a307b8ffa', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.5' LIMIT 1), 2, 'K1-P-0190', 'Durchführungstreue.  Für F werden die fünf Schritte des methodischen FRZK-Problemlösebogens anhand der tatsächlich ausgefüllten Darstellung erfasst; für K wird festgehalten, ob vergleichbare Strukturierungen spontan verwendet wurden. Personalisierte Arbeitsblätter dürfen in beiden Bedingungen nach denselben dokumentierten Regeln angepasst werden. Abweichungen vom Unterrichtsplan, fehlende Daten und vorzeitige Bearbeitungsabbrüche werden nicht nachträglich verschwiegen. Die Intervention wird dadurch nicht mit einer besonders gut vorbereiteten Unterrichtsstunde verwechselt.', 'ec37e6213c91be3fd93c90df402d6ec338b0c73013cfd4bb9012aca29c423619', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.5' LIMIT 1), 3, 'K1-P-0191', 'Beobachter- und Erwartungseinfluss. Da ich zugleich Tutor, Entwickler und Untersuchender bin, bestehen Risiken durch eigene Erwartungen, unterschiedliche Hilfestellungen und mein Vorwissen über die Lernenden. Eine unabhängige Zweitbewertung der anonymisierten Aufgabenlösungen, vorab freigegebene Bewertungskriterien und ein getrenntes Protokoll aller Tutorhinweise sollen diese Risiken vermindern, aber nicht vollständig beseitigen. Die dokumentierte Untersuchung orientiert sich an der allgemeinen Forderung nach nachvollziehbarer Evidenzbewertung in der Bildungsforschung [23], ohne die Anforderungen einer randomisierten Wirksamkeitsstudie als bereits erfüllt darzustellen.', '80c83af55163eb03a2842f3c93ffdec4dd52b640ff49c47bd51726faa8bbed4b', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.6' LIMIT 1), 1, 'K1-P-0193', 'Auswertung. Ich berichte zunächst Zahl und Merkmale der tatsächlich teilnehmenden Lernenden, Aufgabenpaare und auswertbaren Bearbeitungen sowie fehlende Werte und Abweichungen vom Plan. Für die 0–12-Punkte-Summen und die getrennten Kriterien werden Verteilungen, Median, Spannweite und – soweit sinnvoll – Streuungsmaße beschrieben. Bei zuordenbaren, hinreichend vergleichbaren Aufgabenpaaren werden individuelle Differenzen F minus K ausgewiesen und nach Schulstufe bzw. Aufgabentyp explorativ betrachtet. Die kleine und heterogene Stichprobe erlaubt ohne weitergehende Voraussetzungen keine verallgemeinernden Kausalbehauptungen.', 'bf3de6f3a016012693c9d42c38df2739c136204a40691a18a7f91f753d94662b', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.6' LIMIT 1), 2, 'K1-P-0194', 'Interpretation. Ein positiver Unterschied gilt zunächst als Hinweis auf einen möglichen Zusatznutzen unter den dokumentierten Bedingungen. Er ist kritisch gegen Aufgabenunterschiede, Übung, Reihenfolge, Übertragung, Tutorhilfe, Vorkenntnisse und zusätzliche Bearbeitungszeit abzuwägen. Bei ungeklärter Vergleichbarkeit oder unzureichender Trennung der Bedingungen darf ich auch einen größeren Zahlenunterschied nicht als isolierten FRZK-Effekt ausgeben. Nullbefunde, Verschlechterungen, abgebrochene Bearbeitungen und Fälle ohne FRZK-Mehrwert werden gleichrangig berichtet.', '306915f2020b9f53f19370421261148c6c1578f6d114a11fc7e1ef94405bbd76', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.6' LIMIT 1), 3, 'K1-P-0195', 'Getrennte Nachweisketten.  Die fachliche Schlüssigkeit des allgemeinen methodischen FRZK-Problemlösewegs und seine Abgrenzung gegenüber bekannten Verfahren werden unabhängig vom Unterrichtsergebnis beurteilt. Spezielle mathematische Erweiterungen erhalten jeweils eine eigene formale Prüfung. Die didaktische Untersuchung bezieht sich auf die konkret operationalisierte Problemstellungs- und Lösungsintervention. Gute Unterrichtsbewertungen, verbesserte Noten oder korrekte Modellgleichungen können keinen dieser Nachweise stellvertretend ersetzen.', '793c44a1139f6bf4865813f049db3d50d0017fca0fa328498d8a3022a6b46bba', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.7' LIMIT 1), 1, 'K1-P-0197', 'Freiwilligkeit. Da minderjährige Lernende beteiligt sein können und ich zugleich ihr Tutor bin, dürfen Teilnahme oder Nichtteilnahme keinerlei Einfluss auf Nachhilfe, Bewertung oder Betreuung haben. Vor der Datenerhebung werden die erforderlichen Zustimmungen der Sorgeberechtigten und die altersangemessene Zustimmung der Lernenden sowie gegebenenfalls eine unabhängige institutionelle oder ethische Prüfung geklärt. Informationen zu Rückzugsmöglichkeiten, Aufbewahrungsdauer und Löschung sind in verständlicher Form bereitzustellen.', '26309ae98380da359a36f12bb0a389b097e435135ef5a512e7d96e39ed795278', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.7' LIMIT 1), 2, 'K1-P-0198', 'Trennung der Datenbestände. Identifizierende Kontaktdaten und die Zuordnungstabelle werden getrennt und zugriffsgeschützt aufbewahrt. Für die Auswertung werden nur erforderliche Merkmale und pseudonymisierte Schülerlösungen verwendet. Die vorhandenen Bewertungen aus Anlage 1B dienen ausschließlich als qualitative Kontextdaten, soweit ihre Verwendung zulässig ist. Unbestätigte Gesprächszusammenfassungen oder nicht unabhängig belegte Notenverbesserungen werden nicht als gesicherte Wirkungsdaten umgedeutet.', 'f2964829ef17607314ec9e9c2a6fda520594bb57cdf9686858b0baf582eac681', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.7.7' LIMIT 1), 3, 'K1-P-0199', 'Status der Planung. Die vorstehenden Angaben beschreiben ein zu präzisierendes, vor der Erhebung festzulegendes Untersuchungsprotokoll; sie behaupten weder eine bereits durchgeführte Randomisierung noch validierte Skalen, bestätigte Stichprobengrößen oder eine nachgewiesene Wirksamkeit. Das vollständige Protokoll, die Aufgabenpaare, Ankerbeispiele, Auswertungsentscheidungen und ihre Versionen sind vor dem Beginn einer systematischen FRZK-Wirkungsuntersuchung zu fixieren.', '0405c54b078c2e9a8b87c393af4887ffa7ae51b86e7e3c8e2f1411dab0cf4a03', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.8' LIMIT 1), 1, 'K1-P-0201', 'Mein Interesse an einer wissenschaftlichen Auseinandersetzung mit mathematischen und technischen Fragestellungen reicht bis in meine Schul- und Studienzeit zurück. In späteren beruflichen Tätigkeiten konnte ich wissenschaftliche Methoden vor allem in der Entwicklung, Organisation und Vermittlung komplexer Systeme anwenden. Die Frage, wie aus einer umfangreichen Aufgabenstellung eine nachvollziehbare Struktur entsteht, begleitete mich dabei in unterschiedlichen Zusammenhängen.', '11a676938b47cc74e5ae41c555d07cdc47366bc48bfff94b2414b8e16f217df7', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.8' LIMIT 1), 2, 'K1-P-0202', 'Erfahrungen aus der Verfahrenstechnik, aus der Informationstechnologie und aus der Erwachsenenbildung haben mein Verständnis dafür geprägt, dass die explizite Darstellung von Voraussetzungen und Beziehungen eine wichtige Voraussetzung für die gemeinsame Bearbeitung komplexer Probleme sein kann. Diese Berufserfahrung ist eine Motivation für die Themenwahl, aber kein wissenschaftlicher Nachweis der Eignung des FRZK.', 'a8c585d7065fffd08d6135cb2a240569da08ea443bef422b23b79ce5c81b68e4', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.8' LIMIT 1), 3, 'K1-P-0203', 'In meiner späteren Unterrichts- und Nachhilfetätigkeit rückte für mich die Frage in den Mittelpunkt, wie sich ein solches Vorgehen auf mathematische Lernaufgaben übertragen lässt. Ich habe dabei wiederkehrende Schwierigkeiten beobachtet, aus denen ich prüfbare Fragestellungen ableite. Ihre Ursachen und mögliche Verbesserungen müssen im Rahmen einer systematisch dokumentierten Untersuchung geklärt werden.', '849a54bbc12ba938ef9e80516b7e7bda1b4b2b03b46d95e19dd854961b87d24c', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.8' LIMIT 1), 4, 'K1-P-0204', 'Mit der Dissertation möchte ich diese Erfahrungen in ein wissenschaftlich kontrollierbares Vorhaben überführen. Mein Ziel ist, einen offen gelegten Darstellungsrahmen zu formulieren, seine Grenzen zu benennen und seinen möglichen didaktischen Nutzen anhand geeigneter Kriterien untersuchen zu lassen. Persönliche Überzeugung und wissenschaftlicher Befund bleiben dabei ausdrücklich getrennt.', 'e01cfb6175cfe4b18b6c3b672ce9140dea42964787994020b70037bde14d4415', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.9' LIMIT 1), 1, 'K1-P-0206', 'Kapitel 2 erarbeitet die mathematischen, methodischen und didaktischen Grundlagen des FRZK. Es stellt funktionale Zusammenhänge und ihre Darstellungsformen ebenso dar wie zentrale Bedingungen des Aufgabenverständnisses, des Problemlösens und der individuellen Lernförderung. Die einschlägige Fachliteratur wird dabei zur Begründung, Einordnung und kritischen Abgrenzung herangezogen; Kapitel 2 ist jedoch keine eigenständige Literaturprüfung oder systematische Evidenzsynthese. Kapitel 3 entwickelt darauf aufbauend die formale Beschreibung des FRZK und die davon getrennt zu prüfenden mathematischen Erweiterungen. Formal nachgewiesene Teilresultate spezieller Grenzwert- und Vektoroperatoren ersetzen weder den Vergleich des methodischen Problemlöseverfahrens mit bestehenden Ansätzen noch die empirische Prüfung seines möglichen Lernnutzens.', 'aba2be620666374d3c62f93a884a7dc1790795eef2ae8ad81bbc32bae4e6860e', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.9' LIMIT 1), 2, 'K1-P-0207', 'Die wissenschaftliche Relevanz des Projekts liegt in der überprüfbaren Frage, wie Problemstellungen methodisch erfasst, strukturiert, bearbeitet und gelöst werden können und ob die explizite Anwendung dieses Ablaufs Lernenden einen Zusatznutzen bietet. Die einzelnen Bearbeitungsschritte sollen unabhängig von meiner Person nachvollziehbar sein und an unterschiedlichen Aufgaben erprobt und kritisch mit bestehenden Problemlöseverfahren verglichen werden. Gesonderte mathematische Symbolerweiterungen begründen diesen methodischen Anspruch weder automatisch noch ersetzen sie ihn.', 'ea4bfab0053e68fc3bf44d4abb8ddcf06ce2e7556405b003c03ec7ae2d1f36e4', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.9' LIMIT 1), 3, 'K1-P-0208', 'Ich gehe von der Arbeitsannahme aus, dass ein fehlender oder unzureichend strukturierter Überblick über Variablen und Beziehungen die Bearbeitung mathematischer Aufgaben erschweren kann. Diese Annahme ist weder allgemein noch für jede Lernsituation bewiesen. Die Dissertation muss deshalb die Bedingungen angeben, unter denen eine FRZK-Darstellung nützlich, entbehrlich oder möglicherweise hinderlich ist.', '724eac41a3ef3316572c494651d4926396644c524b00b32673eecc5e73a7addd', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.9' LIMIT 1), 4, 'K1-P-0209', 'Unter einem zunächst leeren Darstellungsrahmen verstehe ich hier methodisch, dass die für eine konkrete Aufgabe benötigten Angaben und Beziehungen schrittweise eingetragen werden. Dies ist nicht mit der leeren Menge der Mathematik identisch. Eine solche Arbeitsweise soll Vorannahmen sichtbar machen; sie bedeutet nicht, dass Lernende ohne Vorwissen arbeiten oder dass mathematische Strukturen aus dem Nichts entstehen.', 'dfd707681c1cb7313fb23f0fc8a17c5367c3e3c8ed97ac14e819a0fd06fccc84', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.9' LIMIT 1), 5, 'K1-P-0210', 'Die Analogie zu technischen Modellierungs- und Datenbanksystemen hilft mir, Annahmen, Eingaben, Verknüpfungen und Ausgaben getrennt zu dokumentieren. Ich verwende diese Analogie als heuristisches Werkzeug, nicht als Beweis dafür, dass kognitive Prozesse denselben Regeln wie Softwarearchitekturen folgen.', '3cc563107d22174d30b4300f50dcebe2a804196abe115965981552229267152f', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.9' LIMIT 1), 6, 'K1-P-0211', 'Für die Dissertation ergibt sich daraus ein begrenzter methodischer Anspruch: Ich möchte das Vorgehen von der Problemformulierung bis zur begründeten Lösung und Ergebniskontrolle präzisieren, seine Grenzen bestimmen und es auf ausgewählte Lernaufgaben anwenden. Ob Lernende dadurch besser verstehen, begründen oder übertragen können, ist empirisch zu prüfen. Die darüber hinaus eingeführten mathematischen FRZK-Symbole sind unabhängig davon in ihrem jeweiligen formalen Geltungsbereich zu untersuchen.', '942d55c5d864baacb7e3fd0703f171d2ea1013937112e6d5c58a5ccf3e9bb1c6', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.9' LIMIT 1), 7, 'K1-P-0212', 'Die zusätzlichen mathematischen Festlegungen – insbesondere zu typisierten Nullzuständen, Grenzrichtungen, orthogonaler Ausgangsorientierung und Vektoroperationen – werden auf der Grundlage von Kapitel 2 in Kapitel 3 eigenständig definiert und formal geprüft. Sie gehören nicht notwendig zum allgemein anwendbaren methodischen Grundgerüst. Die Einleitung macht deshalb weder diese Erweiterungen zu Voraussetzungen jeder Problemstellung noch leitet sie ihre mathematische Gültigkeit aus einer gelungenen Unterrichtsanwendung ab.', 'd7b104a1a1be29582a1583bf350a22e4ecb399c685b8c20ae428db5ee85797a8', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.10' LIMIT 1), 1, 'K1-P-0214', 'Kapitel 2 beschreibt die mathematischen, methodischen und didaktischen Grundlagen des FRZK. Dazu gehören insbesondere funktionale Zusammenhänge und Modelle, Repräsentationen und Visualisierungen, Aufgabenverständnis und Problemlösen, Vorwissen und Begriffsbildung, individuelle Lernförderung, mathematisches Argumentieren, Fehlerdiagnose und Lernumgebungen. Die fachwissenschaftliche und didaktische Literatur wird innerhalb dieser Grundlagenarbeit herangezogen, um die verwendeten Begriffe und Ansätze wissenschaftlich einzuordnen. Kapitel 2 ist keine eigenständige Literaturprüfung.', '214d5f81a2f821138ba07e527df6e61fad81aec5ccfbbbf2edf351c31344d243', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.10' LIMIT 1), 2, 'K1-P-0215', 'Kapitel 3 formalisiert den methodischen FRZK-Ablauf auf der Grundlage der in Kapitel 2 entwickelten Begriffe: Problemstellung, Angaben und Zielgrößen, Voraussetzungen und Beziehungen, Lösungsentwicklung sowie Ergebniskontrolle. Davon getrennt werden zusätzliche mathematische FRZK-Strukturen entwickelt, insbesondere typisierte Grenzzustände, Vektorkonstruktionen und spezielle Operationen. Für sie sind Definitionen, Annahmen, Rechenregeln und Gültigkeitsbereiche jeweils eigens anzugeben und zu prüfen. Auch die orthogonale Ausgangsorientierung im Nullgrenzzustand gehört nur zu denjenigen mathematischen Modellen, in denen sie ausdrücklich festgelegt ist; sie ist keine Voraussetzung für jede methodische FRZK-Anwendung.', '29d98a0d59527ef6e57174445f0a77f07e26fffa4f73bcc36cf8060d3731036d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.10' LIMIT 1), 3, 'K1-P-0216', 'Die folgenden Untersuchungskapitel behandeln die Anwendung und Grenzen des methodischen Vorgehens sowie die eigenständige formale Prüfung zusätzlich eingeführter mathematischer Konstruktionen. Rekursionen, Fixpunkte, besondere Grenzzustände oder Kohärenzbedingungen sind speziell definierte Untersuchungsfälle und keine universell notwendigen Bearbeitungsschritte des FRZK. Ein formaler Beweis für eine bestimmte Modellklasse begründet weder die globale Konsistenz sämtlicher Erweiterungen noch ein neues physikalisches Gesetz.', 'd841ef3c67e723f4996861d7242eab3cd592739b0d92e009574c249727445373', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.10' LIMIT 1), 4, 'K1-P-0217', 'Der didaktische Teil der Arbeit soll den methodischen FRZK-Ablauf zur Problemstellung und Problemlösung an ausgewählten Aufgaben untersuchen. Hierfür werden Beobachtungskriterien, Aufgabenformate, Vergleichsbedingungen und Auswertungsverfahren offengelegt. Mathematische Zusatzzeichen und -operatoren werden nur bei einer gesondert gekennzeichneten, fachlich geeigneten Aufgabenklasse verwendet und dürfen nicht unbemerkt Bestandteil der allgemeinen didaktischen Intervention werden.', 'acda7359b73d63e2487cafd51396219bf45310ecd6c43130c46d50308f80e8e9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.10' LIMIT 1), 5, 'K1-P-0218', 'Mit diesem Aufbau unterscheide ich die in Kapitel 2 dargestellten fachlichen Grundlagen, die formale Entwicklung und mathematische Prüfung in Kapitel 3 sowie die spätere empirische Untersuchung der methodischen Anwendung. Die Literatur dient in den betreffenden Kapiteln der wissenschaftlichen Begründung und Abgrenzung; sie bildet nicht den alleinigen Gegenstand von Kapitel 2. Dadurch sollen auch nicht bestätigte Annahmen und die Grenzen des entwickelten Ansatzes nachvollziehbar geprüft werden können.', 'fbca18af8dd8b54b1fe73e88e08681074fce19f0f08b7341a2cbec7dbbc225b8', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.11' LIMIT 1), 1, 'K1-P-0220', 'Mit dieser Einleitung stelle ich das Funktionale Raum-Zeit-Kohärenzsystem vorrangig als methodischen Ansatz zur Formulierung, Strukturierung, Bearbeitung und Lösung von Problemen vor. Das Forschungsinteresse leite ich aus Schwierigkeiten beim Verstehen von Aufgaben, dem Erkennen von Größen und Beziehungen sowie der Überprüfung eigener Lösungswege ab. Die Einleitung beschreibt Anlass, Zielsetzung, wissenschaftliche Abgrenzung und geplanten Untersuchungsweg, ohne besondere mathematische Erweiterungen zur Voraussetzung der Methode zu machen.', '968f45468d5313ec0fec375eef6dd7b97e54f7d76267c5f2cf206b3f1fab0bf4', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.11' LIMIT 1), 2, 'K1-P-0221', 'Der angestrebte Beitrag besteht in einem nachvollziehbaren, kritisch überprüfbaren Problemlöseverfahren und in der Untersuchung seines möglichen didaktischen Nutzens. Zusätzliche mathematische Symbole und Operationen aus Grenzwert- und Vektorrechnung bilden einen gesonderten, formal zu prüfenden Erweiterungsbereich. Ob der methodische Ansatz Vorteile gegenüber vorhandenen Verfahren bietet, lässt sich aus Unterrichtsbeobachtungen oder Modellbeschreibungen allein nicht folgern.', 'e99a8d0fe699d73ec1aacc6358b7476be306f9ecdfa8475d0a00081fab90bf7a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.11' LIMIT 1), 3, 'K1-P-0222', 'Die folgenden Kapitel müssen daher das methodische Grundgerüst, die Reichweite und Konsistenz spezieller mathematischer Erweiterungen sowie die didaktische Tragfähigkeit getrennt untersuchen. Die Unterscheidung zwischen Problemlöseverfahren, formaler Zusatzstruktur und empirischer Wirksamkeit bleibt leitend.', '07df3aaf8c0bda4f539aeff0f9d0962743f05dec73dfab23620769be28cbec32', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
