INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.A' LIMIT 1), 1, 'K1-P-0249', 'Herkunft: vom Autor eingereichte Datei „Anlage 1.A - Inkrementelles Setup einer Textaufgabe(1).docx“ mit fünf aufeinanderfolgenden Originalillustrationen. Die Abbildungen werden in ihrer ursprünglichen Reihenfolge und ohne inhaltliche Änderung wiedergegeben. Sie dokumentieren die Visualisierung des didaktischen Vorgehens, nicht eine datierte Schülerlösung.', 'bea50f62fb8862d3095d0c3652bfbd8d146ff2cb12b71d347867cfb06caaa507', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.A' LIMIT 1), 2, 'K1-P-0250', 'Die Schritte zeigen, dass hier nicht nur Angaben schematisch erfasst werden: Der Ausgangspunkt wird als Situation beschrieben, eine Problemfrage wird sichtbar und die bekannten Zahlen werden anschließend ergänzt. Die Auswertung und rechnerische Lösung folgen erst nach dieser Strukturierung. Diese Abfolge veranschaulicht das methodische FRZK-Grundgerüst, ohne besondere Grenzwert- oder Vektorsymbole vorauszusetzen.', 'd3935df917b73a248bb89fbe1bba2030e48949dcb5892752177bee70ec3af806', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
