INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.A.5' LIMIT 1), 3, 'K1-P-0271', 'Ergänzende rechnerische Einordnung (nicht Bestandteil der ursprünglichen fünf Illustrationen): Bei gleichmäßiger Verteilung von 173 Kartoffeln auf 8 Säcke ergeben sich 21 Kartoffeln je Sack und 5 Kartoffeln Rest (173 = 8 · 21 + 5). Diese Rechnung darf nicht als im Bildmaterial dokumentierte Schülerleistung ausgegeben werden.', 'db8559018bbfa170f80ef5ab7cdcbd0e1231e9068f917c6c55ee211d31a04024', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.A.5' LIMIT 1), 4, 'K1-P-0272', 'Nachweis- und Rechtevorbehalt: Die vorgelegte Anlage enthält eine bildliche Darstellung des vom Autor beschriebenen Lehrwegs, aber weder eine datierte Originalschrift der Schülerin noch ein standardisiertes Beobachtungsprotokoll. Entstehungsdatum, gegebenenfalls verwendete Drittanbieter-Bildmotive, Nutzungsrechte und die Zustimmung zur Veröffentlichung sind vor einer externen Dissertationseinreichung zu klären. Die Anlage kann den beschriebenen Ablauf veranschaulichen, jedoch weder Lernerfolg noch die Wirksamkeit des FRZK belegen.', 'a5b219b3b8260f3801fc43ed46cc989b88b5b716f41b61a1f0f8b82de36a2e9f', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.B' LIMIT 1), 1, 'K1-P-0274', 'Prüfstand: 06.11.2026. Grundlage ist ausschließlich die vom Autor bereitgestellte Textsammlung „meine Bewertungen.txt“; NB-16 dokumentiert eine zusätzliche Autorenangabe aus dem Kapiteltext. Die Fundstellen sind für wissenschaftliche Nachprüfbarkeit gruppiert, jedoch nicht als unabhängige Personenbeobachtungen zu verstehen. Die Originaldatei enthält identifizierende Daten und gehört nicht in den öffentlich weitergegebenen Anhang.', 'd921af4fea91acdcfda22b7f20459588cbcbbe1e7396bd1ae25a397d4e2a1a95', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.B' LIMIT 1), 2, 'K1-P-0275', 'Prüfkategorien: D = unmittelbar vorliegende Nachricht; Z = vom Autor redigierte Gesprächszusammenfassung; P = von Eltern übermittelte Rückmeldung; O = in die Sammlung übertragener Rezensionstext, Originalplattform nicht geprüft; V = verwaltungsbezogener Eintrag; A = bloße Autorenangabe oder Entwurf. „Zustimmung dokumentiert“ bedeutet lediglich, dass im bereitgestellten Material eine positive Antwort auf eine Verwendungsanfrage sichtbar ist; daraus folgt noch keine abschließende datenschutzrechtliche Freigabe.', '855efd754bd976e41b9043acab1e28c25443859a5330e185da4f6c640c923d9e', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.B' LIMIT 1), 3, 'K1-P-0277', 'Tabelle A1B.1: Quellen- und Statusregister der bereitgestellten qualitativen Rückmeldungen. Zeitangaben „Datum relativ“ geben nur die im Abschrifttext enthaltenen relativen Angaben wieder; sie sind kein verifiziertes Publikationsdatum.', 'e74e200ba8d2d41f51b46934375c1d4db0d3e8956631206339c30f04ef4059fb', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.B.1' LIMIT 1), 1, 'K1-P-0280', 'Tabelle A1B.2: Kodierung der sieben Unterrichtsmerkmale und Zuordnung zu den Fundstellen des anonymisierten Nachweisregisters. Eigene qualitative Kategorisierung.', '02eb97ffc8d58bf45a77ac9a41056af1556f84e52048815389a3b565ea699c9c', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.B.1' LIMIT 1), 2, 'K1-P-0281', 'Grenzen der Auswertung. Die Kodierung ist eine analytische Zuordnung zu einzelnen Aussagen und keine Frequenzzählung. NB-03/NB-04 bilden denselben Lernenden ab, bei NB-07/NB-10 sowie NB-01/NB-12 sind Überschneidungen möglich. Ohne vollständige Metadaten ist die Zahl unabhängiger Befragter unbestimmbar. Die elterlich berichteten Notenveränderungen sind nicht durch Originalzeugnisse verifiziert; die Nachhilfeleistung und ein möglicher zusätzlicher FRZK-Effekt dürfen daraus nicht kausal abgeleitet werden.', '42d3c49d746bc2416bae2265c949239db92c79f22d534d96ab4c08c4fdc5c5db', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.B.1' LIMIT 1), 3, 'K1-P-0282', 'Archivierungs- und Forschungsbedarf. Die Originaldatei sollte zugriffsbeschränkt und getrennt von dieser für das Manuskript vorgesehenen Fassung aufbewahrt werden. Für eine spätere belastbare Auswertung wären Erhebungszeitpunkt, Originalquelle, Identitätsabgleich (nur in geschützter Zuordnungsliste), Nutzungsbefugnis einschließlich erforderlicher Zustimmungen, dokumentierte Notenverläufe und systematisch erfasste Gegenbeispiele nachzutragen. Bis dahin erhalten unbestätigte Einträge keine Freigabe als wörtliches Lernendenzitat oder unabhängiger Wirkungsbeleg.', '0b217bd0d8da316f1bd30eb70b6e0b9f8b42c5d0b1e18e7ffb6a485c5b500c2a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.C' LIMIT 1), 1, 'K1-P-0285', 'Prüfstand 06.11.2026. Die Fundstellen wurden mit veröffentlichten Originaltexten bzw. Verlags- und Indexeinträgen abgeglichen. „Originaltext“ bedeutet eine am angegebenen Ort inhaltlich kontrollierte Textstelle; „Metadaten“ bezeichnet nur den überprüften bibliografischen Nachweis und den beschriebenen Forschungsgegenstand. Diese Anlage ist keine vollständige systematische Literaturrecherche.', '1744b223a1b5324445b2b8cff65a6ae84064851b8ee21c7c307b897065544a7d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.C' LIMIT 1), 2, 'K1-P-0287', 'Tabelle A1C.1: Aussage-Quelle-Prüfung der neu aufgenommenen Literatur [16]–[21]. Die Kurzbelege entsprechen veröffentlichten Originalauszügen; für [18] und [21] werden keine unüberprüften wörtlichen Originalzitate behauptet.', 'e20723d55e0b91cd03750aad9a60938d3b51c2dd9c840da02ee82376ca6602a3', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.C' LIMIT 1), 3, 'K1-P-0288', 'Originalfundorte (Prüfprovenienz): [16] https://cmap.ihmc.us/publications/researchpapers/theoryunderlyingconceptmaps.pdf ; [17] https://www.inf.ufpr.br/alexd/REPRESENTACOES_EXTERNAS/Ainsworth_2006.pdf ; [19] https://assess.ucr.edu/sites/g/files/rcwecm2336/files/2019-02/hattietimperley_2007.pdf ; [20] https://www.normanjackson.co.uk/uploads/1/0/8/4/10842717/zimmerman_-_2002_-_becoming_a_self-regulated_learner_an_overview__1_.pdf .', '49ddd183a5c1e112abecd11305082091aea2065c7ad35b806d79e5352572e83d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.C' LIMIT 1), 4, 'K1-P-0289', 'Bibliografische Kontrollstellen: [18] https://www.sciencedirect.com/book/monograph/9780126288704/mathematical-problem-solving ; [21] https://eric.ed.gov/?id=EJ303699 und https://journals.sagepub.com/doi/10.3102/0013189X013006004 . Verfügbarkeit und Zugriffsrechte der Originalpublikationen sind getrennt von ihrer bibliografischen Existenz zu beurteilen.', 'eee772b5166df64da961ff82844c76ac79d5b63a5c84e738da0511aeca6bfe1a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.C' LIMIT 1), 5, 'K1-P-0290', 'Offener Prüfschritt: Für [18] und [21] sind vor einer abschließenden Originalstellen-Freigabe die relevanten Buch- bzw. Aufsatzseiten zu beschaffen. Die herangezogenen Arbeiten stützen den jeweiligen Forschungsstand, ersetzen jedoch keine systematische Neuheitsrecherche und keine Untersuchung der Wirkung des FRZK.', 'e534988ff298f93fae0353650de3f8f7428219a5ea02f6e2db2f955f9bb08a55', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.D' LIMIT 1), 1, 'K1-P-0292', 'Status: Forschungsplanung, 06.11.2026. Die folgenden Vorgaben sind ein Vorschlag zur prüfbaren Operationalisierung. Vor einer systematischen Datenerhebung sind Aufgaben, Aufgabenpaare, Materialien, Einwilligungen, Kriterien und die Freigabeversion verbindlich festzulegen.', 'e681b7c02eb77a473a7186160e4dcf0309979aedc1d175fb519edf8136323b67', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.D' LIMIT 1), 2, 'K1-P-0293', 'Tabelle A1D.1: Vergleich der Unterrichtsbedingungen', '405461da4914593ac34ac0f2c725b78f63828f4d8b4c3a438d609061b542c8da', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.D' LIMIT 1), 3, 'K1-P-0296', 'Abweichungen und mögliche Überträge von FRZK-Schritten auf K-Aufgaben werden protokolliert. Die Tabelle beschreibt den beabsichtigten Unterschied der Bedingungen, nicht bereits überprüfte Durchführungstreue.', 'cbfb67530296899782065fc62d0350258910d7dc34a6c81e902aa8ef2149b7b5', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.D' LIMIT 1), 4, 'K1-P-0297', 'Tabelle A1D.2: Vorläufiges Bewertungsraster (0–12 Punkte)', '450cabc2f69c85ac2e84de9a8cb44731664db08fd7db8a53b5f40aed2c3a00c9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.D' LIMIT 1), 5, 'K1-P-0300', 'Die Dimension D setzt eine eigenständige Transferaufgabe voraus. Punktestufen und Ankerbeispiele sind vor der Erhebung zu pilotieren und danach zu fixieren. Die Tabelle ist ein Entwurf, keine validierte Skala.', 'fdb603dc132928c93731b0c53a6129ff91afa9bf46908b5f83880b406766454a', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.D' LIMIT 1), 6, 'K1-P-0301', 'Tabelle A1D.3: Mindestfelder des Erhebungsprotokolls', '6a7d73f4ae0587833fc434e2db0e4c1358a28210c1a4996712369177aa36d0e4', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.D' LIMIT 1), 7, 'K1-P-0304', 'Dokumentationsgrenze: Die Auflistung enthält keine personenbezogenen Schülerdaten. Vor einer Veröffentlichung sind auch indirekte Identifikationsrisiken kleiner heterogener Gruppen zu prüfen.', '5e327d5659e2c15aa63cbefcefdd2e05cab2d83851c7a48f632ac62fda347a93', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E' LIMIT 1), 1, 'K1-P-0306', 'Geltungsbereich: Diese Anlage beschreibt ausschließlich das in Abschnitt 1.2 neu festgelegte Referenzmodell. Sie rekonstruiert nicht die unbekannten historischen Rechenparameter der ursprünglichen beiden Abbildungen.', '1796520618312b6950c0145572c00619d01e210a6d88851f2dd5346621fcabae', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.1' LIMIT 1), 1, 'K1-P-0308', 's = 1 m; b = 1 m; d = 3 m; a = 0,20 m⁻¹; xₛ = 5 m; c = 299 792 458 m/s. Der Parameterbereich bildet ein Dreieck mit A = (−0,5; −0,5) m, B = (0,5; −0,5) m und C = (0; h) m, h = (√3 − 1)/2 ≈ 0,3660254 m.', 'fe9bd4ad35dab69a14ecd1f7107500cdd4b269d98e282bc479fae34b9821220e', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.1' LIMIT 1), 2, 'K1-P-0309', 'Ein Gitterpunkt (u, v) gehört genau dann zum geschlossenen Dreieck, wenn −0,5 ≤ u ≤ 0,5 sowie −0,5 ≤ v ≤ h − √3·|u| gelten. Außerhalb dieses Gebiets wird keine Laufzeit ausgewertet und keine Dreiecksfarbe vergeben.', 'ee2449c48e2806827afc9e4e981f3d6063369b979336675f7b904ee19a5bc8cc', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 1, 'K1-P-0311', 'h = (sqrt(3) - 1) / 2', '06eba74e6214ee2b55a96dc30218cefbb0ac0fad5e1add506f57ff9af0a8b292', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 2, 'K1-P-0312', 'U = 281 äquidistante Werte von -0.5 bis +0.5 (einschließlich)', 'ea0ebdeb9b4349dc0a8c6bc7f0e74f58f4c172fcc89dc9495fa200457929fb96', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 3, 'K1-P-0313', 'V = 281 äquidistante Werte von -0.5 bis h (einschließlich)', '16a94d25499c5caa564ebdd164d458e918ae44fa403d8d33b4db16fd62598c70', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 4, 'K1-P-0314', 'für jedes (u,v) aus U × V:', '1a15bb6a87d6da660717420dc09be7927ccfb7749737365edd3bc57365fba2a7', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 5, 'K1-P-0315', 'falls v < -0.5 oder v > h - sqrt(3)*abs(u): überspringen', '0b67421843e452c3c300e5358ecd7d6f409f7e6da84343e66b8a2a538ba55eb9', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 6, 'K1-P-0316', 'xQ = 3.0 + 0.20*(u*u - v*v)', '2bb83a720666999191d7f7b45204d5097b42e4f2d21d0a167b4e3f03f6455e7f', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 7, 'K1-P-0317', 'L1 = sqrt((5.0 - xQ)^2 + u*u + v*v)', '0ec8263e1ccaa6488c6f34ed1a1ab981213aa5e1dae5630b540784fd1e41920b', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 8, 'K1-P-0318', 'L2 = abs(xQ - 1.0)', 'e7918ec181b8cbea7db81dfa768baeb66a64ed2d53b9dc0fbd3732d3aa2ebe7e', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 9, 'K1-P-0319', 'tau_ns = 1e9*(L1 + L2)/299792458', '975c18d1afa2c6338a621abe47d279b7bacdf2764bd7646f0796012a8dfe57fb', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.2' LIMIT 1), 10, 'K1-P-0320', 'tau_ns für die Farbdarstellung dem Punkt (u,v) zuordnen', 'c6801393997f969316b80aa88884e6cef145833c400f81f26600ba61f12c6a42', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.3' LIMIT 1), 1, 'K1-P-0322', 'Die Laufzeit wird in Nanosekunden dargestellt. Zur Wiedergabe von Abbildung 1.F4 wird eine gefüllte Konturdarstellung mit 25 linear verteilten Stufengrenzen von 13,34 ns bis 13,75 ns und der Farbpalette „viridis“ verwendet. Die Dreiecksränder werden als Linien verbunden. Die Gitterpunkte außerhalb des Dreiecks bleiben maskiert. Die Farbgrenzen sind fest vorgegeben und werden nicht für jede Wiederholung neu an die Daten angepasst.', '28115909f986e363471745a61f9ac6165038a6e22b145a236bfd48cc87103a19', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.4' LIMIT 1), 1, 'K1-P-0324', 'Analytischer Kontrollpunkt (u,v) = (0,0): τ = 13,3425638079 ns. Eckpunkte A und B: je τ = 13,7472449142 ns. Eckpunkt C: τ = 13,4519250616 ns. Auf dem beschriebenen 281 × 281-Gitter liegen 39 481 Punkte innerhalb der Dreiecksmaske; der kleinste erfasste Gitterwert beträgt ungefähr 13,3425647406 ns, der größte 13,7472449142 ns. Die geringe Abweichung des Gitterminimums vom Wert am Mittelpunkt entsteht, weil v = 0 keine der 281 gleichmäßig verteilten v-Koordinaten ist.', 'b83637b062b862c6db1564dfeaf1b70742613c4cb50da0619bc386bec132135d', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
INSERT INTO `paragraphs` (`section_id`, `paragraph_index`, `paragraph_label`, `paragraph_text`, `content_sha256`, `created_revision_id`) VALUES ((SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.E.5' LIMIT 1), 1, 'K1-P-0326', 'Die Regel beschreibt einen idealisierten zweiteiligen Signalweg vom Sender über einen zugeordneten Flächenpunkt zu einem Punkt der Beobachtungsebene. Sie berücksichtigt keine realistische winkelabhängige Reflexion, keine Mehrfachwege und keine Streu- oder Dämpfungseffekte. Das Ergebnis ist deshalb ein geometrisch begründetes Laufzeit-Skalarfeld, kein nachgewiesenes optisches Messverfahren. Die zwei historischen Skizzen in Abschnitt 1.2 bleiben ohne ihre ursprünglichen Daten eigenständige Illustrationen; mit diesem Referenzmodell werden sie nicht nachträglich validiert.', '55b2319d4573fc1a7a2f1a94a5d8ef6bcf8ff15276782f366a452582fd02d9a0', @frzk_rev_id) ON DUPLICATE KEY UPDATE `paragraph_label`=VALUES(`paragraph_label`), `paragraph_text`=VALUES(`paragraph_text`), `content_sha256`=VALUES(`content_sha256`), `created_revision_id`=VALUES(`created_revision_id`);
