INSERT INTO `figures` (`object_id`, `figure_number`, `title`, `figure_type`, `caption`, `description`, `alt_text`, `provenance_type`, `provenance_notes`, `rights_status`, `validation_status`, `notes`) VALUES (@frzk_obj_1_F1, '1.F2', 'Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.', 'DIAGRAM', 'Abbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.', 'Abbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.', 'Abbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.', 'OWN', 'Eigene Darstellung gemäß Bildunterschrift des Manuskripts.', 'OWN_WORK', 'CHECKED', 'Bildinhalt und Dokumentquelle dokumentiert; historisches Modell separat vom neuen Referenzmodell halten.') ON DUPLICATE KEY UPDATE `figure_number`=VALUES(`figure_number`), `object_id`=VALUES(`object_id`), `title`=VALUES(`title`), `figure_type`=VALUES(`figure_type`), `caption`=VALUES(`caption`), `description`=VALUES(`description`), `alt_text`=VALUES(`alt_text`), `provenance_type`=VALUES(`provenance_type`), `provenance_notes`=VALUES(`provenance_notes`), `rights_status`=VALUES(`rights_status`), `validation_status`=VALUES(`validation_status`), `notes`=VALUES(`notes`);
