INSERT INTO `manuscript_tables` (`object_id`, `table_number`, `title`, `caption`, `description`, `table_data_json`, `source_note`, `validation_status`) VALUES (@frzk_obj_tab_1_1, '1.1', 'Anonymisierte Kursbelegungen in fünf sichtbaren Lerngruppen. Quelle: ICAS-Kursübersicht, Woche 09.11.–15.11.2026, vom Autor bereitgestellter Bildschirmausschnitt; eigene Zählung. Die Schulformkürzel sind unverändert aus der Ansicht übernommen.', 'Tabelle 1.1: Anonymisierte Kursbelegungen in fünf sichtbaren Lerngruppen. Quelle: ICAS-Kursübersicht, Woche 09.11.–15.11.2026, vom Autor bereitgestellter Bildschirmausschnitt; eigene Zählung. Die Schulformkürzel sind unverändert aus der Ansicht übernommen.', 'Tabelle 1.1: Anonymisierte Kursbelegungen in fünf sichtbaren Lerngruppen. Quelle: ICAS-Kursübersicht, Woche 09.11.–15.11.2026, vom Autor bereitgestellter Bildschirmausschnitt; eigene Zählung. Die Schulformkürzel sind unverändert aus der Ansicht übernommen.', '{"header": ["Gruppe", "Belegungen", "Klassenstufen", "Fächer und Schulformkürzel"], "rows": [["A", "5", "7, 9, 10, 11", "MAT; GYM, RS"], ["B", "5", "11, 12", "MAT; GYM"], ["C", "5", "5, 7, 8", "MAT; GYM, GR"], ["D", "6", "7, 9, 10, 12", "MAT; GYM, GS"], ["E", "6", "8, 9, 11, 12", "MAT, PHY; GYM, RS"]]}', 'Aus konsolidierter Word-Datei extrahiert; Quelle und Einschränkung gemäß Tabellenunterschrift.', 'CHECKED') ON DUPLICATE KEY UPDATE `object_id`=VALUES(`object_id`), `title`=VALUES(`title`), `caption`=VALUES(`caption`), `description`=VALUES(`description`), `table_data_json`=VALUES(`table_data_json`), `source_note`=VALUES(`source_note`), `validation_status`=VALUES(`validation_status`);
