INSERT INTO `manuscript_tables` (`object_id`, `table_number`, `title`, `caption`, `description`, `table_data_json`, `source_note`, `validation_status`) VALUES (@frzk_obj_tab_1_2, '1.2', 'Qualitativ identifizierte Merkmale der Unterrichtsführung. Quelle: Materialsammlung „meine Bewertungen.txt“, eigene vorläufige Kategorisierung. Die Belegkennungen NB-xx verweisen auf das pseudonymisierungsarme Nachweisregister in Anlage 1B. Originalplattformen, berichtete Noten und Urheberschaften übertragener Rezensionstexte wurden nicht unabhängig überprüft.', 'Tabelle 1.2: Qualitativ identifizierte Merkmale der Unterrichtsführung. Quelle: Materialsammlung „meine Bewertungen.txt“, eigene vorläufige Kategorisierung. Die Belegkennungen NB-xx verweisen auf das pseudonymisierungsarme Nachweisregister in Anlage 1B. Originalplattformen, berichtete Noten und Urheberschaften übertragener Rezensionstexte wurden nicht unabhängig überprüft.', 'Tabelle 1.2: Qualitativ identifizierte Merkmale der Unterrichtsführung. Quelle: Materialsammlung „meine Bewertungen.txt“, eigene vorläufige Kategorisierung. Die Belegkennungen NB-xx verweisen auf das pseudonymisierungsarme Nachweisregister in Anlage 1B. Originalplattformen, berichtete Noten und Urheberschaften übertragener Rezensionstexte wurden nicht unabhängig überprüft.', '{"header": ["Merkmal", "Im Material beschrieben", "Belegart / Einordnung"], "rows": [["Individuelle Vorbereitung", "Vorbereitete, an Thema, Wissenslücken und Arbeitstempo angepasste Aufgabenblätter", "NB-03, NB-14 (NB-06 nur unbestätigte Kontextnotiz)"], ["Verlässliche Struktur und Reflexion", "Blitzlicht zu Stundenbeginn; individuelle Rückschau und Lernreflexion zum Abschluss", "NB-03, NB-14; allgemeine Strukturwahrnehmung NB-02"], ["Mehrperspektivische Erklärungen", "Geduldiges wiederholtes Erklären, gemeinsames Nachschlagen und fachliches Nachfragen", "NB-03, NB-14"], ["Schülerorientierte Lösungswege", "Eigenständige Lösungsvorschläge werden verstanden, besprochen und in die we