INSERT INTO `manuscript_tables` (`object_id`, `table_number`, `title`, `caption`, `description`, `table_data_json`, `source_note`, `validation_status`) VALUES (@frzk_obj_tab_1_4, '1.4', 'Erfahrungsbasierte inhaltliche Schwerpunktsetzung in der Arbeitsphase. Die Anteile beschreiben eine ungefähre Planungspraxis, keine gemessenen Zeiten und keine allgemeinen Empfehlungen.', 'Tabelle 1.4: Erfahrungsbasierte inhaltliche Schwerpunktsetzung in der Arbeitsphase. Die Anteile beschreiben eine ungefähre Planungspraxis, keine gemessenen Zeiten und keine allgemeinen Empfehlungen.', 'Tabelle 1.4: Erfahrungsbasierte inhaltliche Schwerpunktsetzung in der Arbeitsphase. Die Anteile beschreiben eine ungefähre Planungspraxis, keine gemessenen Zeiten und keine allgemeinen Empfehlungen.', '{"header": ["Lernstufe", "Übungsrechnen", "Problembearbeitung", "Typische Aufgabenakzente"], "rows": [["Bis Klasse 4", "ca. 80 %", "ca. 20 %", "Grundfertigkeiten und einfache Textaufgaben"], ["Klassen 5–7", "ca. 50 %", "ca. 50 %", "Übung und zunehmend eigenständige Problemlösung"], ["Ab Klasse 8", "ca. 20 %", "ca. 80 %", "Komplexere Aufgaben, Begründungen und Transfer"]]}', 'Aus konsolidierter Word-Datei extrahiert; Quelle und Einschränkung gemäß Tabellenunterschrift.', 'CHECKED') ON DUPLICATE KEY UPDATE `object_id`=VALUES(`object_id`), `title`=VALUES(`title`), `caption`=VALUES(`caption`), `description`=VALUES(`description`), `table_data_json`=VALUES(`table_data_json`), `source_note`=VALUES(`source_note`), `validation_status`=VALUES(`validation_status`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.B' LIMIT 1), 'TABLE', 'K1.TAB.A1B_1', 'Tabelle A1B.1: Quellen- und Statusregister der bereitgestellten qualitativen Rückmeldungen. Zeitangaben „Datum relativ“ geben nur die im Abschrifttext enthaltenen relativen Angaben wieder; sie sind kein verifiziertes Publikationsdatum.', 276, 'RELEASED', @frzk_rev_id, 'Tabellendaten vollständig im JSON-Feld manuscript_tables.table_data_json.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `manuscript_tables` (`object_id`, `table_number`, `title`, `caption`, `description`, `table_data_json`, `source_note`, `validation_status`) VALUES (@frzk_obj_tab_A1B_1, 'A1B.1', 'Quellen- und Statusregister der bereitgestellten qualitativen Rückmeldungen. Zeitangaben „Datum relativ“ geben nur die im Abschrifttext enthaltenen relativen Angaben wieder; sie sind kein verifiziertes Publikationsdatum.', 'Tabelle A1B.1: Quellen- und Statusregister der bereitgestellten qualitativen Rückmeldungen. Zeitangaben „Datum relativ“ geben nur die im Abschrifttext enthaltenen relativen Angaben wieder; sie sind kein verifiziertes Publikationsdatum.', 'Tabelle A1B.1: Quellen- und Statusregister der bereitgestellten qualitativen Rückmeldungen. Zeitangaben „Datum relativ“ geben nur die im Abschrifttext enthaltenen relativen Angaben wieder; sie sind kein verifiziertes Publikationsdatum.', '{"header": ["Kennung", "Art / Zeit", "Inhaltlicher Kern (anonymisiert)", "Beleg- und Nutzungsstatus"], "rows": [["NB-01", "März 2026 · D", "Lernenden-Nachricht: möchte Nachhilfe fortsetzen und erlebt sie als hilfreich.", "Text in Sammlung; keine gesonderte Veröffentlichungseinwilligung im Fundabschnitt belegt; keine Leistungsdaten."], ["NB-02", "April 2026 · Z", "Vom Autor formulierte Wiedergabe: Unterricht als strukturiert und präzise wahrgenommen, persönliches Interesse.", "Schriftliche Zustimmung zur anonymisierten Nutzung des vorgelegten Textes sichtbar; keine Originaltranskription des Gesprächs."], ["NB-03", "April 2026 · Z", "Vom Autor aus Schülergespräch ausgearbeitete Punkte 1–5: Blitzlicht, Rückblick, gemeinsames Nachschlagen, passgenaue Arbeitsblätter, Fachhefter.", "Schriftliche Zustimmung des Lernenden zur Nutzung der vorgelegten Zusammenfassung; nicht als wörtliche Schüleraussage behandeln."], ["NB-04", "April 2026 · D", "Direkte Lernenden-Ergänzung: eigene Lösungsvorschläge werden aufgegriffen und besprochen.", "Direkter Text derselben Person wie NB-03; nicht als unabhängige zusätzliche Person zählen."], ["NB-05", "April 2026 · A", "Nachträglich vom Autor vorgeschlagene Erweiterung: Lösungsvorschläge und zeitweise intensive Einzelbetreuung.", "Bestätigende Antwort im verfügbaren Material nicht enthalten; nur Entwurf, nicht als bestätigter Schülerbeleg nutzbar."], ["NB-06", "Datum offen · Z", "Vom Autor festgehaltene Schülereinschätzung zur fachlichen Vorbereitung und zu themenbegleitenden Materialien.", "Keine direkt zugeordnete Zustimmung und kein wörtliches Originalprotokoll; nur Kontextnotiz."], ["NB-07", "Datum offen · P", "Elternmitteilung über Zufriedenheit und Zeugnisverbesserung in Mathematik von 4 auf 3.", "Text übermittelt; Zeugnisbelege und Einwilligungsstatus nicht vorhanden; mögliches Quellen-Overlap mit NB-10."], ["NB-08", "Jan./Feb. 2026 · V", "Interne organisatorische Verwaltungsnotizen über Kursführung und Teilnahmen.", "Ausgeschlossen: enthält Drittdaten und Bewertungen anderer Personen, ohne ausreichende Befugnis oder Forschungsrelevanz."], ["NB-09", "Datum relativ · O", "Online-Rezension eines Elternteils berichtet Verbesserung um zwei Notenstufen.", "Nur in Textsammlung übertragene Rezension; Erscheinungsdatum und Originalfundort nicht extern bestätigt."], ["NB-10", "Datum relativ · O", "Online-Rezension eines Elternteils: Mathematiknoten hätten sich nach mehreren Monaten verbessert.", "Nur übertragener Rezensionstext; mögliche Personenüberschneidung mit NB-07 nicht ausgeschlossen."], ["NB-11", "Datum relativ · O", "Online-Rezension einer Familie zu zwei Kindern: Geduld, gute Lernbeziehung und verbesserte Mathematiknoten.", "Nur übertragener Rezensionstext; keine unabhängigen Schulnotennachweise."], ["NB-12", "Datum relativ · O", "Online-Rezension eines Lernenden: modern, flexibel, schnelles Erlernen neuer Inhalte.", "Nur übertragener Rezensionstext; Identitätsüberschneidung mit direkten Nachrichten möglich."], ["NB-13", "Datum relativ · O", "Online-Rezension eines Lernenden: positive Lern- und Notenentwicklung; mehrere Lehrkräfte werden genannt.", "Keine eindeutige Zuordnung der Notenentwicklung zu genau diesem Tutor; nur eingeschränkt verwendbar."], ["NB-14", "Juni 2026 · O", "Übertragener Plattformbewertungstext: Vorbereitung, individuelle Erklärungen, Rückfragen, Reflexion.", "Im Material auf 02.06.2026 datiert; Originalplattform und Urheberschaft nicht unabhängig überprüft."], ["NB-15", "Datum offen · A", "Vom Autor formulierte Gesprächswiedergabe zu präparierten Aufgabenblättern, Unterrichtsvorliebe und Noten 1–2.", "Nur Anfrageentwurf; im Material keine zustimmende Antwort; nicht als bestätigter Schülerbeleg nutzbar."], ["NB-16", "Datum offen · A", "Vom Autor berichtete informelle Gespräche mit Gymnasiasten der 11. Klasse nach mindestens einjähriger Nachhilfe.", "In „meine Bewertungen.txt“ nicht als genau diese Gesprächsserie nachgewiesen; Zahl, Wortlaut, Frageleitfaden und Zustimmungen offen."]]}', 'Aus konsolidierter Word-Datei extrahiert; Quelle und Einschränkung gemäß Tabellenunterschrift.', 'CHECKED') ON DUPLICATE KEY UPDATE `object_id`=VALUES(`object_id`), `title`=VALUES(`title`), `caption`=VALUES(`caption`), `description`=VALUES(`description`), `table_data_json`=VALUES(`table_data_json`), `source_note`=VALUES(`source_note`), `validation_status`=VALUES(`validation_status`);
