INSERT INTO `manuscript_tables` (`object_id`, `table_number`, `title`, `caption`, `description`, `table_data_json`, `source_note`, `validation_status`) VALUES (@frzk_obj_tab_A1B_2, 'A1B.2', 'Kodierung der sieben Unterrichtsmerkmale und Zuordnung zu den Fundstellen des anonymisierten Nachweisregisters. Eigene qualitative Kategorisierung.', 'Tabelle A1B.2: Kodierung der sieben Unterrichtsmerkmale und Zuordnung zu den Fundstellen des anonymisierten Nachweisregisters. Eigene qualitative Kategorisierung.', 'Tabelle A1B.2: Kodierung der sieben Unterrichtsmerkmale und Zuordnung zu den Fundstellen des anonymisierten Nachweisregisters. Eigene qualitative Kategorisierung.', '{"header": ["Code", "Unterrichtsmerkmal", "Tragende Fundstellen"], "rows": [["M1", "Individuelle Vorbereitung und Arbeitsblätter", "NB-03, NB-14; NB-06 nur unbestätigte Kontextnotiz"], ["M2", "Stundenstruktur und Reflexion", "NB-02, NB-03, NB-14"], ["M3", "Wiederholte Erklärungen und gemeinsames Prüfen", "NB-03, NB-14"], ["M4", "Aufgreifen eigener Lösungswege", "NB-04"], ["M5", "Persönliche Lernbeziehung", "NB-02; zusätzlich NB-11/12 als unüberprüfte Plattformtexte"], ["M6", "Dokumentation im Fachhefter", "NB-03"], ["M7", "Subjektiv wahrgenommener Nutzen / berichtete Schulnoten", "NB-01, NB-07, NB-09 bis NB-11; NB-13 nur eingeschränkt"]]}', 'Aus konsolidierter Word-Datei extrahiert; Quelle und Einschränkung gemäß Tabellenunterschrift.', 'CHECKED') ON DUPLICATE KEY UPDATE `object_id`=VALUES(`object_id`), `title`=VALUES(`title`), `caption`=VALUES(`caption`), `description`=VALUES(`description`), `table_data_json`=VALUES(`table_data_json`), `source_note`=VALUES(`source_note`), `validation_status`=VALUES(`validation_status`);
