INSERT INTO `manuscript_tables` (`object_id`, `table_number`, `title`, `caption`, `description`, `table_data_json`, `source_note`, `validation_status`) VALUES (@frzk_obj_tab_A1C_1, 'A1C.1', 'Aussage-Quelle-Prüfung der neu aufgenommenen Literatur [16]–[21]. Die Kurzbelege entsprechen veröffentlichten Originalauszügen; für [18] und [21] werden keine unüberprüften wörtlichen Originalzitate behauptet.', 'Tabelle A1C.1: Aussage-Quelle-Prüfung der neu aufgenommenen Literatur [16]–[21]. Die Kurzbelege entsprechen veröffentlichten Originalauszügen; für [18] und [21] werden keine unüberprüften wörtlichen Originalzitate behauptet.', 'Tabelle A1C.1: Aussage-Quelle-Prüfung der neu aufgenommenen Literatur [16]–[21]. Die Kurzbelege entsprechen veröffentlichten Originalauszügen; für [18] und [21] werden keine unüberprüften wörtlichen Originalzitate behauptet.', '{"header": ["Quelle", "Verifizierte Fundstelle / Kurzbeleg", "Deckung im Kapitel", "Prüfgrenze"], "rows": [["16 · Novak/Cañas", "Originaltext: S. 1, Einleitung. „Concept maps are graphical tools for organizing and representing knowledge.“", "Begriffs- und Beziehungsdarstellung durch Concept-Maps ist etabliert.", "Originalstelle geprüft; weder FRZK-Originalität noch dessen Wirkung belegt."], ["17 · Ainsworth", "Originaltext: S. 183, Abstract. „many studies have shown this promise is not always achieved.“", "Verschiedene Darstellungsformen bedürfen geeigneter Gestaltung und Lernhandlungen.", "Originalstelle geprüft; kein allgemeiner Nutzen multipler Darstellungen garantiert."], ["18 · Schoenfeld", "Verlagseintrag/Gliederungsangaben; DOI 10.1016/C2013-0-05012-8.", "Mathematisches Problemlösen umfasst Ressourcen, Heuristiken, Kontrolle, Überzeugungen.", "Metadaten und thematischer Inhalt gesichert; exakte Buchseiten/Originalzitate offen."], ["19 · Hattie/Timperley", "Originaltext: S. 81 und 86/90. „Feedback is one of the most powerful influences on learning and achievement, but this impact can be either positive or negative.“", "Aufgaben-, Prozess- und Selbstregulationsfeedback unterscheiden; Feedback kann unterschiedlich wirken.", "Originalstellen geprüft; keine konkrete Effektstärke für die eigene Nachhilfe."], ["20 · Zimmerman", "Originaltext: S. 68. „Self-evaluation refers to comparisons of self-observed performances against some standard“", "Selbstregulation schließt Selbstbeobachtung, Selbstbewertung und Reflexion ein.", "Originalstelle geprüft; keine altersabhängige 100/50/10-Verteilung empfohlen."], ["21 · Bloom", "Verlags-/ERIC-Nachweis 1984, 13(6), S. 4–16; DOI 10.3102/0013189X013006004.", "Einzelbetreuung und Gruppenunterricht sind Gegenstand vergleichender Forschung.", "Metadaten/Forschungsgegenstand gesichert; Originalseitenbefund offen; nicht auf 6er-Gruppe übertragbar."]]}', 'Aus konsolidierter Word-Datei extrahiert; Quelle und Einschränkung gemäß Tabellenunterschrift.', 'CHECKED') ON DUPLICATE KEY UPDATE `object_id`=VALUES(`object_id`), `title`=VALUES(`title`), `caption`=VALUES(`caption`), `description`=VALUES(`description`), `table_data_json`=VALUES(`table_data_json`), `source_note`=VALUES(`source_note`), `validation_status`=VALUES(`validation_status`);
