INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.0' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.0' AND p.paragraph_index=4 LIMIT 1), 'CLAIM', 'K1.C01', 'Das methodische Grundgerüst des FRZK beschreibt eine Folge nachvollziehbarer Bearbeitungshandlungen: Eine Problemstellung wird zunächst geklärt und als Frage formuliert; anschließend werden bekannte und gesuchte Größen, Voraussetzungen und Beziehungen geordnet, Lösungsansätze entwickelt, ausgeführt und anhand der Ergebnisse überprüft. Die ausdrückliche Darstellung funktionaler Zusammenhänge ist ein Hilfsmittel innerhalb dieses Weges, nicht dessen einziges Ziel. Das Grundgerüs', 4, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C01, 'K1.C01', 'METHODOLOGICAL', 'Das methodische Grundgerüst des FRZK beschreibt eine Folge nachvollziehbarer Bearbeitungshandlungen: Eine Problemstellung wird zunächst geklärt und als Frage formuliert; anschließend werden bekannte und gesuchte Größen, Voraussetzungen und Beziehungen geordnet, Lösungsansätze entwickelt, ausgeführt und anhand der Ergebnisse überprüft. Die ausdrückliche Darstellung funktionaler Zusammenhänge ist ein Hilfsmittel innerhalb dieses Weges, nicht dessen einziges Ziel. Das Grundgerüst setzt weder ein bestimmtes Koordinatensystem noch eine spezielle Geometrie, Dynamik oder Algebra voraus. Rekursion, Fixpunkte, Kohärenzbedingungen und mathematische Sonderzeichen werden nur dann hinzugenommen, wenn die konkrete Aufgabe dies erfordert.', 0, 'AUTHOR_DEFINITION', 'CHECKED', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.0' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.0' AND p.paragraph_index=5 LIMIT 1), 'CLAIM', 'K1.C02', 'Die in Kapitel 3 behandelten besonderen FRZK-Zustände, gerichteten Grenzannäherungen, Grenzzeichen, Null- und Vektoroperationen sowie die orthogonale Ausgangsorientierung bilden eine gesonderte mathematische Erweiterung des methodischen Ansatzes. Sie sind nicht als Voraussetzungen für jede Problemstellung oder für jede Anwendung des FRZK zu verstehen. Ihre Bedeutung, Rechenregeln und Gültigkeitsbereiche müssen unabhängig vom Grundgerüst definiert und formal geprüft werden. In', 5, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C02, 'K1.C02', 'MATHEMATICAL', 'Die in Kapitel 3 behandelten besonderen FRZK-Zustände, gerichteten Grenzannäherungen, Grenzzeichen, Null- und Vektoroperationen sowie die orthogonale Ausgangsorientierung bilden eine gesonderte mathematische Erweiterung des methodischen Ansatzes. Sie sind nicht als Voraussetzungen für jede Problemstellung oder für jede Anwendung des FRZK zu verstehen. Ihre Bedeutung, Rechenregeln und Gültigkeitsbereiche müssen unabhängig vom Grundgerüst definiert und formal geprüft werden. Insbesondere ist eine leere Darstellung nicht mit der mathematisch leeren Menge oder einem physikalisch leeren Raum gleichzusetzen; ein FRZK-Nullzustand ist kein gewöhnlicher reeller Zahlenwert und ein orientierter Nullzustand nicht ohne zusätzliche Information rückskalierbar.', 0, 'AUTHOR_DEFINITION', 'CHECKED', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.1.1' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.1.1' AND p.paragraph_index=4 LIMIT 1), 'CLAIM', 'K1.C03', 'Ich erarbeitete daraufhin mit der Schülerin auf einem leeren Blatt Papier eine schrittweise Strukturierung der Situation. Die vom Autor bereitgestellte Anlage 1A („Inkrementelles Setup einer Textaufgabe“) veranschaulicht in fünf Bildern den Weg vom leeren Blatt über eine Orientierung in der Situation zur Unterscheidung von Gesuchtem und Gegebenem. Sie dokumentiert einen didaktischen Aufbau, ist aber kein datiertes Original der von der Schülerin angefertigten Lösung und kein s', 11, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C03, 'K1.C03', 'DIDACTIC', 'Ich erarbeitete daraufhin mit der Schülerin auf einem leeren Blatt Papier eine schrittweise Strukturierung der Situation. Die vom Autor bereitgestellte Anlage 1A („Inkrementelles Setup einer Textaufgabe“) veranschaulicht in fünf Bildern den Weg vom leeren Blatt über eine Orientierung in der Situation zur Unterscheidung von Gesuchtem und Gegebenem. Sie dokumentiert einen didaktischen Aufbau, ist aber kein datiertes Original der von der Schülerin angefertigten Lösung und kein standardisiert erhobener Lernfortschritt. Der berichtete Gesprächsverlauf bleibt eine retrospektive Unterrichtsbeobachtung.', 1, 'PARTIAL', 'OPEN', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.2' AND p.paragraph_index=9 LIMIT 1), 'CLAIM', 'K1.C04', 'Im Ausgangsgedanken sollte ein Signal vom Sender über einen Punkt der gekrümmten Fläche zu einem zugeordneten Punkt des Beobachtungsdreiecks gelangen. Die gesamte Weglänge wurde in eine Laufzeit umgerechnet und anschließend farblich kodiert. Damit entsteht eine zweidimensionale Darstellung eines aus einer dreidimensionalen Konstruktion abgeleiteten Skalarfelds. Für eine wissenschaftlich wiederholbare Berechnung sind die Geometrie, die Zuordnung und die Ausbreitungsannahmen au', 38, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C04, 'K1.C04', 'MATHEMATICAL', 'Im Ausgangsgedanken sollte ein Signal vom Sender über einen Punkt der gekrümmten Fläche zu einem zugeordneten Punkt des Beobachtungsdreiecks gelangen. Die gesamte Weglänge wurde in eine Laufzeit umgerechnet und anschließend farblich kodiert. Damit entsteht eine zweidimensionale Darstellung eines aus einer dreidimensionalen Konstruktion abgeleiteten Skalarfelds. Für eine wissenschaftlich wiederholbare Berechnung sind die Geometrie, die Zuordnung und die Ausbreitungsannahmen ausdrücklich anzugeben.', 1, 'OPEN', 'OPEN', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.2' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.2' AND p.paragraph_index=31 LIMIT 1), 'CLAIM', 'K1.C05', 'Prüfgrenzen des Referenzfalls. Die Gleichungen ermöglichen es, den geometrischen und numerischen Rechenweg unabhängig zu wiederholen; insbesondere sind Definitionsbereich, Flächenfunktion, Zuordnung, Signalweg, Konstanten und Farbbereich festgelegt. Damit ist die modellinterne Reproduzierbarkeit des hier definierten Referenzfalls hergestellt. Offen bleibt dagegen, ob die ursprünglichen Abbildungen auf denselben oder anderen Parametern beruhen. Ebenso ist mit der Konstruktion ', 67, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C05, 'K1.C05', 'LIMITATION', 'Prüfgrenzen des Referenzfalls. Die Gleichungen ermöglichen es, den geometrischen und numerischen Rechenweg unabhängig zu wiederholen; insbesondere sind Definitionsbereich, Flächenfunktion, Zuordnung, Signalweg, Konstanten und Farbbereich festgelegt. Damit ist die modellinterne Reproduzierbarkeit des hier definierten Referenzfalls hergestellt. Offen bleibt dagegen, ob die ursprünglichen Abbildungen auf denselben oder anderen Parametern beruhen. Ebenso ist mit der Konstruktion weder die physikalische Gültigkeit einer realen Signalstreuung noch eine allgemeine mathematische oder didaktische Wirksamkeit des FRZK belegt.', 0, 'NOT_REQUIRED', 'CHECKED', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.5' AND p.paragraph_index=15 LIMIT 1), 'CLAIM', 'K1.C06', 'Rückmeldungen von Lernenden. Ergänzend zu meinen Unterrichtsbeobachtungen habe ich informelle Gespräche mit Schülerinnen und Schülern der 11. Gymnasialklasse geführt, die nach meiner Angabe bereits mindestens ein Jahr meine Nachhilfe besucht hatten. Die Lernenden beschrieben den wahrgenommenen Nutzen der Nachhilfe sinngemäß als deutlich bessere schulische Ausgangslage gegenüber einer Situation ohne diese Unterstützung. Für diese Gesprächsangabe liegen im hier ausgewerteten Ma', 118, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C06, 'K1.C06', 'EMPIRICAL', 'Rückmeldungen von Lernenden. Ergänzend zu meinen Unterrichtsbeobachtungen habe ich informelle Gespräche mit Schülerinnen und Schülern der 11. Gymnasialklasse geführt, die nach meiner Angabe bereits mindestens ein Jahr meine Nachhilfe besucht hatten. Die Lernenden beschrieben den wahrgenommenen Nutzen der Nachhilfe sinngemäß als deutlich bessere schulische Ausgangslage gegenüber einer Situation ohne diese Unterstützung. Für diese Gesprächsangabe liegen im hier ausgewerteten Material weder ein standardisierter Fragebogen noch vollständige Originalprotokolle oder eine gesicherte Anzahl befragter Personen vor (vgl. Nachweisstatus NB-16, Anlage 1B). Daher verwende ich sie ausschließlich als qualitative Selbsteinschätzung nach eigener Gesprächswiedergabe, nicht als systematisch ausgewertete Befragung oder Kausalbeleg.', 1, 'PARTIAL', 'OPEN', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.5' AND p.paragraph_index=25 LIMIT 1), 'CLAIM', 'K1.C07', 'Die beiden folgenden Orientierungsmodelle zur Unterrichtsorganisation beruhen auf wiederholten qualitativen Eigenbeobachtungen aus drei Jahren Nachhilfepraxis. Sie wurden weder durch standardisierte Zeitmessungen noch durch eine systematische Zählung aller Arbeitsergebnisse gewonnen und sind deshalb keine statistisch abgesicherten Verteilungen oder nachgewiesenen optimalen Unterrichtsquoten. Das erste Modell beschreibt, wer Arbeitsergebnisse kontrolliert; das zweite Modell be', 129, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C07, 'K1.C07', 'EMPIRICAL', 'Die beiden folgenden Orientierungsmodelle zur Unterrichtsorganisation beruhen auf wiederholten qualitativen Eigenbeobachtungen aus drei Jahren Nachhilfepraxis. Sie wurden weder durch standardisierte Zeitmessungen noch durch eine systematische Zählung aller Arbeitsergebnisse gewonnen und sind deshalb keine statistisch abgesicherten Verteilungen oder nachgewiesenen optimalen Unterrichtsquoten. Das erste Modell beschreibt, wer Arbeitsergebnisse kontrolliert; das zweite Modell betrifft die inhaltliche Gewichtung von Übungsrechnen und Problembearbeitung. Beide Modelle dürfen nicht miteinander gleichgesetzt werden. Unter Ergebniskontrolle verstehe ich die Prüfung bearbeiteter Aufgaben und Resultate. Davon unterscheide ich die allgemeine Verständniskontrolle anhand von Rückfragen zu Begriffen, Begründungen und Übertragungen, die unabhängig von der Klassenstufe Bestandteil meiner Betreuung bleibt.', 1, 'PARTIAL', 'OPEN', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.5' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.5' AND p.paragraph_index=29 LIMIT 1), 'CLAIM', 'K1.C08', 'Die Verlagerung geeigneter Ergebniskontrollen in die Eigenverantwortung hat auch organisatorische Gründe. Während einer 75-minütigen Arbeitsphase betreue ich zeitweise bis zu sechs Lernende unterschiedlicher Klassen- und Studienjahre. Würde ich für die vollständige Kontrolle der Aufgaben jedes Lernenden jeweils zehn Minuten ansetzen, ergäben sich rechnerisch 6 × 10 = 60 Minuten. Von der Arbeitsphase blieben dann nur 15 Minuten für individuelle Erklärungen, die Bearbeitung and', 134, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C08, 'K1.C08', 'METHODOLOGICAL', 'Die Verlagerung geeigneter Ergebniskontrollen in die Eigenverantwortung hat auch organisatorische Gründe. Während einer 75-minütigen Arbeitsphase betreue ich zeitweise bis zu sechs Lernende unterschiedlicher Klassen- und Studienjahre. Würde ich für die vollständige Kontrolle der Aufgaben jedes Lernenden jeweils zehn Minuten ansetzen, ergäben sich rechnerisch 6 × 10 = 60 Minuten. Von der Arbeitsphase blieben dann nur 15 Minuten für individuelle Erklärungen, die Bearbeitung anderer Schwierigkeiten und allgemeine Verständniskontrollen. Wechsel- und Unterbrechungszeiten sind dabei noch nicht berücksichtigt. Diese Modellrechnung veranschaulicht einen möglichen Zeitkonflikt; sie ist keine standardisierte Zeitmessung.', 0, 'NOT_REQUIRED', 'CHECKED', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.3' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.6.3' AND p.paragraph_index=2 LIMIT 1), 'CLAIM', 'K1.C09', 'Concept-Maps werden in der Literatur als grafische Werkzeuge zur Organisation und Darstellung von Wissen beschrieben. Novak und Cañas erläutern, dass Begriffe durch beschriftete Beziehungen zu sinnvollen Aussagen verknüpft werden können (Novak; Cañas, 2008, S. 1) [16]. In meiner Nachhilfepraxis dienen Concept-Maps oder Kompendien zu Beginn eines Themas der fachlichen Orientierung. Die anschließende Bearbeitung erfolgt überwiegend mit individuell angepassten Arbeitsblättern. D', 149, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C09, 'K1.C09', 'LITERATURE', 'Concept-Maps werden in der Literatur als grafische Werkzeuge zur Organisation und Darstellung von Wissen beschrieben. Novak und Cañas erläutern, dass Begriffe durch beschriftete Beziehungen zu sinnvollen Aussagen verknüpft werden können (Novak; Cañas, 2008, S. 1) [16]. In meiner Nachhilfepraxis dienen Concept-Maps oder Kompendien zu Beginn eines Themas der fachlichen Orientierung. Die anschließende Bearbeitung erfolgt überwiegend mit individuell angepassten Arbeitsblättern. Daraus folgt weder, dass diese Einführung bereits das FRZK darstellt, noch dass eine grafische Übersicht als solche eine methodische Neuerung ist.', 1, 'PARTIAL', 'OPEN', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
INSERT INTO `research_objects` (`dissertation_id`, `chapter_id`, `section_id`, `paragraph_id`, `object_type`, `object_code`, `title`, `sort_order`, `status`, `created_revision_id`, `notes`) VALUES (@frzk_diss_id, @frzk_ch1_id, (SELECT id FROM sections WHERE chapter_id=@frzk_ch1_id AND section_number='1.6.5' LIMIT 1), (SELECT p.id FROM paragraphs p JOIN sections s ON s.id=p.section_id WHERE s.chapter_id=@frzk_ch1_id AND s.section_number='1.6.5' AND p.paragraph_index=1 LIMIT 1), 'CLAIM', 'K1.C10', 'Concept-Maps strukturieren Begriffe und deren Beziehungen; in meiner Praxis eröffnen sie ein Thema. Multiple Repräsentationen, Problemlösestrategien sowie Feedback- und Selbstregulationsmodelle beschreiben weitere etablierte Aspekte des Lernprozesses [16][17][18][19][20]. Das FRZK beansprucht demgegenüber zunächst die Funktion eines ausdrücklich beschriebenen methodischen Vorgehens, das von der Problemformulierung über die Unterscheidung von Gegebenem und Gesuchtem, die Prüfu', 158, 'RELEASED', @frzk_rev_id, 'Textbasierte Aussageklassifikation; keine darüber hinausgehende Wirksamkeitsbehauptung.') ON DUPLICATE KEY UPDATE `section_id`=VALUES(`section_id`), `paragraph_id`=VALUES(`paragraph_id`), `title`=VALUES(`title`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`), `created_revision_id`=VALUES(`created_revision_id`), `notes`=VALUES(`notes`);
INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C10, 'K1.C10', 'METHODOLOGICAL', 'Concept-Maps strukturieren Begriffe und deren Beziehungen; in meiner Praxis eröffnen sie ein Thema. Multiple Repräsentationen, Problemlösestrategien sowie Feedback- und Selbstregulationsmodelle beschreiben weitere etablierte Aspekte des Lernprozesses [16][17][18][19][20]. Das FRZK beansprucht demgegenüber zunächst die Funktion eines ausdrücklich beschriebenen methodischen Vorgehens, das von der Problemformulierung über die Unterscheidung von Gegebenem und Gesuchtem, die Prüfung von Voraussetzungen und Zusammenhängen bis zur Entwicklung, Ausführung und Kontrolle einer Lösung reicht. Die mathematischen Erweiterungen des FRZK, insbesondere besondere Symbole und Operationen für Grenzwert- und Vektorprobleme, sind davon zu trennen. Ob die methodische Abfolge gegenüber bestehenden Problemlösestrategien eigenständig ist, muss kritisch verglichen und nicht bloß behauptet werden.', 1, 'OPEN', 'OPEN', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
