INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C11, 'K1.C11', 'DIDACTIC', 'Primäre didaktische Frage (F1).  Verbessert die zusätzliche, ausdrücklich dokumentierte Anwendung des methodischen FRZK-Problemlösewegs bei fachlich vergleichbaren Aufgaben und vergleichbarer Tutorunterstützung die Nachvollziehbarkeit einer selbstständig entwickelten Lösung gegenüber der üblichen themen- und defizitorientierten Bearbeitung? Als primärer Vergleichswert ist ein vorab fixierter Summenwert aus vier Kriterien von 0 bis 12 Punkten vorgesehen. Sonderzeichen der Grenzwert- und Vektorrechnung sind für diesen allgemeinen Vergleich nicht vorgesehen.', 1, 'OPEN', 'OPEN', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
