INSERT INTO `claims` (`object_id`, `claim_code`, `claim_type`, `claim_text`, `requires_citation`, `support_status`, `verification_status`, `notes`) VALUES (@frzk_obj_claim_K1_C12, 'K1.C12', 'DIDACTIC', 'Sekundäre Fragen (F2–F4). F2: Erkennen Lernende fachliche Fehler oder unzulässige Annahmen früher bzw. selbstständiger? F3: Übertragen sie eine erarbeitete Beziehung auf eine neue, strukturell vergleichbare Aufgabe? F4: Welchen zusätzlichen Zeit- und Unterstützungsbedarf erzeugt die Darstellung, und in welchen Lernstufen oder Aufgabentypen erscheint sie hilfreich, entbehrlich oder hinderlich? Eine erwartete positive Wirkung ist eine Arbeitshypothese, kein bereits vorliegendes Ergebnis. Nullbefunde und Nachteile gehören zum Untersuchungsgegenstand.', 1, 'OPEN', 'OPEN', 'Rohtext aus Kapitel 1; Status bewertet Beleglage, nicht die Wahrheit des empirischen Effekts.') ON DUPLICATE KEY UPDATE `claim_type`=VALUES(`claim_type`), `claim_text`=VALUES(`claim_text`), `requires_citation`=VALUES(`requires_citation`), `support_status`=VALUES(`support_status`), `verification_status`=VALUES(`verification_status`), `notes`=VALUES(`notes`);
