INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,21,'K1-A2-21','A2-6: Steigungsdreieck mit Δx und Δy. Autorenvorlage.','be83f243806b63e9baf2a554c7ba81a5f764f5c99c69015d353a06587b2b1ac9',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,22,'K1-A2-22','Schritt 7 – Den y-Achsenabschnitt bestimmen','bea8349974fdee928f3985e9de10d4db6b890eaa2627286b8d878805731935dd',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,23,'K1-A2-23','Der Schnittpunkt der Geraden mit der y-Achse wird als b = f(0) bezeichnet. Die neue Autorenvorlage gibt b = 5,5 an. Zusammen mit a = 0,9 ergibt sich f(x) = 0,9x + 5,5. Dies ist die in der Vorlage verwendete lineare beziehungsweise affine Funktionsdarstellung.','90eac3e53a54cc691aa3de5186fb909d4bfe125994c18ee0533b0d87af75be51',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,24,'K1-A2-24','Allgemeine Form: f(x) = ax + b.  Beispiel der Autorenvorlage: f(x) = 0,9x + 5,5.','1affceaeddb9994470d4a703ea60e0103991ede22a5f5deb92d662221f6e5fd5',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,25,'K1-A2-25','Word-LaTeX: f(x)=ax+b,\\quad f(x)=0{,}9x+5{,}5','01d4ea1375bb748adf05bd65d15bb388c69b3ca3306fc162670b60a28f6bbf50',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,26,'K1-A2-26','A2-7: y-Achsenabschnitt b und Steigungsdreieck. Autorenvorlage.','38e5b3231acf1e06f78619e8f404cac24e6a996d2838a1b37b9fe5713afd1f79',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,27,'K1-A2-27','Ergänzende Erläuterung der Funktionsparameter (neue Autorenvorlage)','59d0f61f750e490869c595dadd26f617cc185aca0ea93b682dedf646c7eded34',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,28,'K1-A2-28','Die Funktionsgleichung f(x)=ax+b beschreibt eine Gerade; die Parameter a und b bestimmen ihre Form und Lage.','a4cb5baaac43d70fd5028fa59365ad53c278c563b74062c4615a014fb7e6245d',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,29,'K1-A2-29','Hier sind die beiden mathematischen Bausteine kurz zusammengefasst:','0140a27783791f4825bf35c6c8e6d9977d203baa2f65d87ee6ace7b711fc3390',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,30,'K1-A2-30','Der Anstieg / die Steigung (a): Positives a bedeutet eine steigende, negatives a eine fallende Gerade; bei a=0 verläuft sie waagerecht.','1106a5a687a2d397a5896ba273a05ed8b1577b5f7821b9521ba2a87b892c5db6',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,31,'K1-A2-31','Der y-Achsenabschnitt (b): Die Gerade schneidet die vertikale y-Achse im Punkt (0,b); b beschreibt ihre vertikale Lage beziehungsweise Verschiebung.','77899f65f757f94d8c51e5e35765f0135c67a52e5121713b423d08b713aa6afc',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,32,'K1-A2-32','Schritt 8 – Eindeutigkeit und Geltungsbereich prüfen','e576ac6bcc9c1518bdb6177749690d4b0e3dd5f2c6782471fd8cdbf5f16dee84',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,33,'K1-A2-33','Die Vorlage spricht von „eineindeutiger Zuordnung“. Für den Funktionsbegriff muss jedem x des festgelegten Definitionsbereichs genau ein y-Wert zugeordnet sein. Eine allgemeine Umkehr-Eindeutigkeit ist nicht erforderlich. Bei der hier angegebenen Steigung a = 0,9 ist die konkret dargestellte Funktion auf ℝ allerdings streng monoton und damit injektiv. Die beiden Aussagen sind zu unterscheiden.','29dabf5ad33099be3f03a12b63c8ce06a91221dc5c3ce75edbc0f2f2bea6d326',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,34,'K1-A2-34','Schritt 9 – Iterative Rückprüfung (methodische Ergänzung)','350c4bff1c089f127c451a2d89f956e752275ade5a4477b13debaf7980fa0543',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,35,'K1-A2-35','Bei Widersprüchen oder fehlenden Angaben kann zu einem früheren Bearbeitungsschritt zurückgekehrt werden: Sind Achsen und Einheiten festgelegt? Ist der Definitionsbereich benannt? Passen a = Δy/Δx und b = f(0) zur Zeichnung? Als Kontrollbeispiel liefert die Funktionsgleichung f(0) = 5,5 und f(1) − f(0) = 0,9. Wenn eine Prüfung misslingt, werden Annahme oder Darstellung angepasst und erneut überprüft. Die aktualisierten sieben Originalgrafiken zeigen den Aufbau; einen tatsächlichen Rücksprung oder Lernerfolg dokumentieren sie nicht.','3286b3369f69ecec7cfec5e0860fba4102e0c90589483e882a0818c58c7e755a',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,36,'K1-A2-36','Wissenschaftliche Einordnung. Die Anlage illustriert den methodischen FRZK-Ansatz als strukturierte, potenziell wiederholbare Problemerschließung. Das Verfahren ist hier ohne FRZK-spezifische Grenzwertzeichen und Vektoroperatoren anwendbar. Die in der Vorlage genannten Zahlenwerte sind als grafische Beispielparameter zu behandeln; ihre unabhängige Kalibrierung und die empirische Wirksamkeit gehören nicht zum Nachweisumfang dieser Anlage.','a8710fcfd918ab9fd2056058ac9dbf0dc7a5756d41ed6cd1c1c096b54f0d15b1',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) SELECT @k1_112,@k1_next,'K1-A2-VERWEIS','Anlage 1A.2 zeigt ergänzend zur hier beschriebenen Unterrichtsbeobachtung den schrittweisen Aufbau einer linearen Funktion. Die aktualisierte Vorlage führt die Bestimmung von Steigung und y-Achsenabschnitt bis zur Funktionsgleichung f(x) = 0,9x + 5,5 fort. Die Rückprüfung wird als methodische Ergänzung erläutert; ein empirischer Lernerfolg ist damit nicht nachgewiesen.','c9260c2e2ef377c03b7e0dcac423bc257b837d54fb6dba5113c0d6e32e319993',@k1_r FROM DUAL WHERE @k1_link_id IS NULL;
INSERT INTO research_objects (dissertation_id,chapter_id,section_id,object_type,object_code,title,sort_order,status,created_revision_id,notes) VALUES (@k1_d,@k1_c,@k1_s,'FIGURE','K1_A2_F01','A2-1: Ausgangsposition vor dem Aufbau des Bezugssystems. Autorenvorlage.',1,'REVIEW',@k1_r,'Bild aus aktualisierter Autorenvorlage') ON DUPLICATE KEY UPDATE section_id=VALUES(section_id),title=VALUES(title),created_revision_id=VALUES(created_revision_id);
