INSERT INTO revisions (dissertation_id,revision_code,title,revision_type,source_filename,content_sha256,status,notes) VALUES
(@frzk_diss_id,'K1_GESAMT_2026-11-09','Kapitel 1 mit iterativem FRZK-Schema und Anlage 1A.2 v3','RELEASE','FRZK_Kapitel1_Iterativer_Erkenntnisprozess_2026-11-09.docx','a3fcd99db815be9750523202c88b61d89f19d178625da4b72e1238e045c57cd8','FINAL','Konsolidierte Autorenfassung; externe wissenschaftliche Originalstellen- und Rechteprüfung teilweise offen.')
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.0-001','In meiner Nachhilfepraxis beobachte ich wiederholt, dass Lernende bei komplexen Aufgaben Schwierigkeiten haben, relevante Angaben zu ordnen, Beziehungen zu erkennen und den eigenen Lösungsweg zu reflektieren. Ich untersuche deshalb einen methodischen Ablauf, der bei der Formulierung der Problemstellung beginnt, Gegebenes und Gesuchtes trennt, Beziehungen erschließt, eine Lösung entwickelt und diese überprüft. Das Funktionale Raum-Zeit-Kohärenzsystem (FRZK) verstehe ich primär als methodischen Ansatz zur Problemstellung und Problemlösung. Seine mathematischen Erweiterungen um besondere Grenzwert- und Vektorsymbole gehören nicht zum allgemeinen methodischen Grundgerüst. Ob das Vorgehen die Nachvollziehbarkeit, Fehlererkennung und Übertragbarkeit von Lösungsstrategien verbessert, bleibt eine empirisch zu prüfende Frage.','b04fa3671810083b055254a8e4a9b80e39d8c9a0d14bf526138b03ce95ff3d34',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,2,'K1-1.0-002','Die Fragestellung berührt wissenschaftliche Diskussionen über Modellbildung, Beobachtung und die Begriffe Raum und Zeit. Rovelli behandelt die Grundlagen unseres Zeitverständnisses und die Grenzen herkömmlicher Vorstellungen von Zeit (Rovelli, Carlo (2018). The Order of Time. London: Penguin Books.)[1]. Ich verwende diese Darstellung als physikalisch-philosophischen Hintergrund, nicht als Bestätigung einer aus dem FRZK hervorgehenden Raumzeit oder als Nachweis seines didaktischen Nutzens.','37eed69ba4c872b4847c456a747f8451d4d60a19e0f6501656a2f09f602d4445',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,3,'K1-1.0-003','Die Systemtheorie und die Kybernetik eröffnen unterschiedliche Perspektiven auf Systembeziehungen, Beobachtung und die Beschreibung von Lern- und Kommunikationsprozessen (von Foerster, Heinz (1981). Observing Systems. Seaside, CA: Intersystems Publications.)[2] (Maturana, Humberto R.; Varela, Francisco J. (1987). The Tree of Knowledge: The Biological Roots of Human Understanding. Boston: Shambhala.)[3]. Für die Entwicklung und Untersuchung didaktischer Verfahren ist die gestaltungsorientierte Lehr-Lernforschung ein methodischer Bezugspunkt (Reinmann, Gabi (2005). Innovation ohne Forschung? Ein Plädoyer für den Design-Based Research-Ansatz in der Lehr-Lernforschung. Unterrichtswissenschaft, 33(1), S. 52–69. DOI: 10.25656/01:5787.)[4]. Einen Ansatz zur Begleitung und Anregung eigenständiger Lernprozesse erläutert Arnold (Arnold, Rolf (2012). Wie man lehrt, ohne zu belehren. 29 Regeln für eine kluge Lehre. Das LENA-Modell. 1. Auflage. Heidelberg: Carl-Auer. ISBN: 978-3-89670-838-0.)[5]. Sfard untersucht mathematisches Denken aus einer kommunikationstheoretischen Perspektive (Sfard, Anna (2008). Thinking as Communicating: Human Development, the Growth of Discourses, and Mathematizing. Cambridge: Cambridge University Press. DOI: 10.1017/CBO9780511499944.)[6]. Luhmann stellt mit seiner Theorie sozialer Systeme einen weiteren, davon zu unterscheidenden systemtheoretischen Bezug bereit (Luhmann, Niklas (1984). Soziale Systeme: Grundriß einer allgemeinen Theorie. Frankfurt am Main: Suhrkamp.)[7]. Keiner dieser Ansätze beweist bereits die Wirksamkeit des FRZK.','bfaa44a62d42b134123b93fc2ffab4ad698507dfcbfbdbc6d8dbbfb9b82d4511',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,4,'K1-1.0-004','Das methodische Grundgerüst des FRZK beschreibt eine Folge nachvollziehbarer Bearbeitungshandlungen: Eine Problemstellung wird zunächst geklärt und als Frage formuliert; anschließend werden bekannte und gesuchte Größen, Voraussetzungen und Beziehungen geordnet, Lösungsansätze entwickelt, ausgeführt und anhand der Ergebnisse überprüft. Die ausdrückliche Darstellung funktionaler Zusammenhänge ist ein Hilfsmittel innerhalb dieses Weges, nicht dessen einziges Ziel. Das Grundgerüst setzt weder ein bestimmtes Koordinatensystem noch eine spezielle Geometrie, Dynamik oder Algebra voraus. Rekursion, Fixpunkte, Kohärenzbedingungen und mathematische Sonderzeichen werden nur dann hinzugenommen, wenn die konkrete Aufgabe dies erfordert.','259a3188f55ba5901909723a7d8dbfe3215713012bf3edfbe279c5b57861c1d3',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,5,'K1-1.0-005','Abbildung 1.F1 veranschaulicht das methodische FRZK als wiederholbaren Erkenntnis- und Problemlöseprozess. Ausgangspunkt sind vorhandenes Wissen und eine zu klärende Problemstellung. Die anschließenden Schritte – Strukturieren, Visualisieren, Prüfen sowie Erweitern oder Revidieren – können bei neuen Erkenntnissen erneut durchlaufen werden.','7421cd71f5022bf9084c75775caa9f4591aa37ae79276b11c1420408a17977c7',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,6,'K1-1.0-006','Abbildung 1.F1: Iterativer Erkenntnis- und Problemlöseprozess des FRZK. Konzeptionelle Darstellung des methodischen Grundgerüsts, nicht als bereits validierter Algorithmus zu verstehen. Die methodische Ausgestaltung der Einzelschritte, Übergänge und Rückkopplungsregeln erfolgt in Kapitel 2. Darstellung nach dem in dieser Arbeit beschriebenen Ansatz.','c41a20f8b8c1b5eb67e0250a420fa9f11ade6c17d21bf77c8b0500ce8613b5c7',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,7,'K1-1.0-007','Die Rückkopplung von Schritt 5 zu Schritt 2 steht für die erneute Strukturierung veränderten oder erweiterten Wissens. Die Grafik legt weder eine feste Schrittzahl für jede Aufgabe noch einen zwingenden Ablauf ohne Zwischenschritte fest. Auch eine erneute Klärung der ursprünglichen Problemstellung kann notwendig werden; diese Rückkehr zu Schritt 1 ist im vereinfachten Schema nicht eigens dargestellt. Die mathematischen FRZK-Zusatzsymbole gehören nicht zu diesem methodischen Ablauf.','5d0e6b13ec5681c7fdf505af646e450c332cee5d32e3d44ad0ea63a8cefc4bd7',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,8,'K1-1.0-008','Die in Kapitel 3 behandelten besonderen FRZK-Zustände, gerichteten Grenzannäherungen, Grenzzeichen, Null- und Vektoroperationen sowie die orthogonale Ausgangsorientierung bilden eine gesonderte mathematische Erweiterung des methodischen Ansatzes. Sie sind nicht als Voraussetzungen für jede Problemstellung oder für jede Anwendung des FRZK zu verstehen. Ihre Bedeutung, Rechenregeln und Gültigkeitsbereiche müssen unabhängig vom Grundgerüst definiert und formal geprüft werden. Insbesondere ist eine leere Darstellung nicht mit der mathematisch leeren Menge oder einem physikalisch leeren Raum gleichzusetzen; ein FRZK-Nullzustand ist kein gewöhnlicher reeller Zahlenwert und ein orientierter Nullzustand nicht ohne zusätzliche Information rückskalierbar.','e3f14ce31cf6f4ee96da6671897da17a9301ed6996bf01ae18836e4901186353',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.1.2-001','Zwei Schülerinnen aus der 9. Klasse Gymnasium standen vor der Aufgabe: „Wie würdest du deinem besten Freund oder deiner besten Freundin erklären, was eine lineare Funktion ist?“ Die Aufgabe zielte darauf ab, ein grundlegendes Verständnis für lineare Funktionen zu entwickeln, indem die Schülerinnen den Begriff selbstständig formulieren und ihre eigenen Worte finden sollten, um diese mathematische Beziehung zu erklären. Doch anstatt eine klare Vorstellung von einer linearen Funktion zu entwickeln, standen die Schülerinnen vor einer mentalen Blockade.','e061b41b28fd95b7cf051420081bbe6ba72d68d9c268212b83bd3c36f9772bc0',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,2,'K1-1.1.2-002','In einer ersten Rückmeldung erklärten beide Schülerinnen, dass sie nicht wüssten, wie sie ihre Antwort beginnen sollten. Ich deutete dies als Hinweis darauf, dass ihnen ein sprachlicher und anschaulicher Zugang zu der gefragten Beziehung fehlte. Ob dabei die Begriffskenntnis, das Vorwissen, die konkrete Aufgabenstellung oder weitere Faktoren entscheidend waren, ließ sich in dieser Situation nicht isolieren.','cb048177eb6df53468d4c6137623d4c9b389d9c546f6ed23082984ab18c17502',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,3,'K1-1.1.2-003','Eine der Schülerinnen äußerte: „Was ist das, eine Linie? Es sind doch Zahlen, aber wie hängen die zusammen?“ Sie hatte Schwierigkeiten, das Konzept einer linearen Funktion als eine mathematische Beziehung zu begreifen, die über abstrakte Zahlen und Parameter hinausgeht und in einem konkreten Zusammenhang, wie etwa einer realen Situation (z.B. eine Geschwindigkeit über Zeit oder den Zusammenhang zwischen dem Einkommen und den Arbeitsstunden), interpretiert werden könnte. Auch die andere Schülerin konnte die Aufgabe nicht anders angehen, als die Parameter der linearen Funktion als isolierte mathematische Elemente zu betrachten, ohne deren Einfluss auf die Gestalt der Linie oder auf die Veränderung der Werte in einer praktischen Anwendung zu begreifen.','61bfb8ddbff3bcb03ddef29bb132b575df2ee7fef1aeecaffda71f56a3fce672',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,4,'K1-1.1.2-004','In der Situation konnten die Schülerinnen die Formel einer linearen Funktion benennen, hatten aber Schwierigkeiten, die Bedeutung der Parameter und den Zusammenhang der Größen in eigenen Worten zu erläutern. Für meine Untersuchung ist daran besonders interessant, ob eine ausdrücklich geordnete Darstellung von Größen, Beziehungen und Beispielen den Übergang von einer symbolischen Schreibweise zu einer fachlich angemessenen Erklärung unterstützen kann.','9fd4761666b2a8067a64328b2edec39dc7501cdb1419f6c508505b656b8429f7',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,5,'K1-1.1.2-005','Ich beobachtete, dass die Schülerinnen zunächst nach einer bekannten Definition suchten und eigene Beispiele kaum verwendeten. Daraus ergibt sich für mich eine prüfbare didaktische Frage: Welche Darstellungshilfen erleichtern es Lernenden, den mathematischen Zusammenhang als Beziehung veränderlicher Größen zu beschreiben? Die Beobachtung allein lässt weder auf eine allgemeine Ursache noch auf die Wirksamkeit einer bestimmten Unterrichtsmethode schließen.','729e238740fe322ca9f9606aea1e0e89f235a608beb9b7d85a4c830e7e8c3e39',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,6,'K1-1.1.2-006','Die beiden Unterrichtsbeobachtungen lassen sich mit der didaktischen Frage verbinden, wie Lernende tragfähige Begriffe aufbauen und neues Wissen mit vorhandenem Wissen verknüpfen. Bruner behandelt die Struktur von Unterrichtsinhalten und die schrittweise Vertiefung grundlegender Vorstellungen (Bruner, Jerome S. (1960). The Process of Education. Cambridge, MA: Harvard University Press. DOI: 10.4159/9780674028999.)[8]. Ausubels Arbeiten befassen sich mit der Bedeutung der kognitiven Struktur für sinnvolles sprachliches Lernen (Ausubel, David P. (1963). The Psychology of Meaningful Verbal Learning. New York: Grune & Stratton.)[9]. Die genaue Zuordnung einzelner Buchseiten bleibt bis zur Editionsprüfung offen.','3ec66c81be66901e42fa9700d8d68807e7b2c31185642c0c408ff975f854a941',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,7,'K1-1.1.2-007','Anlage 1A.2 zeigt ergänzend zur hier beschriebenen Unterrichtsbeobachtung den schrittweisen Aufbau einer linearen Funktion. Die aktualisierte Vorlage führt die Bestimmung von Steigung und y-Achsenabschnitt bis zur Funktionsgleichung f(x) = 0,9x + 5,5 fort. Die Rückprüfung wird als methodische Ergänzung erläutert; ein empirischer Lernerfolg ist damit nicht nachgewiesen.','c9260c2e2ef377c03b7e0dcac423bc257b837d54fb6dba5113c0d6e32e319993',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.2-001','Um die Entstehung meiner Forschungsfrage nachvollziehbar zu machen, wählte ich zunächst bewusst eine Aufgabe außerhalb meiner üblichen Nachhilfepraxis: Wie lässt sich eine gekrümmte, im Allgemeinen intrinsisch nichteuklidische Fläche auf einer zweidimensionalen Beobachtungsfläche durch berechnete Signalgrößen darstellen? Mein Interesse an Geometrie, Astronomie und physikalischer Modellbildung gab den Anlass. Die nachfolgende Beschreibung unterscheidet die ursprüngliche Ideenskizze von einem neu festgelegten, rechnerisch reproduzierbaren Referenzfall.','39cff554a2b5f6382a7c2d81809023cb1d4acbe541d8bf408fa6778cd70bcd42',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,2,'K1-1.2-002','Bei der Bearbeitung trennte ich zunächst die Angaben, die frei wählbaren Annahmen und die gesuchten Ergebnisse. Unter einem zunächst leeren Bezugssystem verstand ich dabei kein physikalisches Vakuum und keine mathematisch leere Menge, sondern ein Koordinaten- und Darstellungsgerüst, dessen konkrete Objekte und Regeln ich erst nach und nach festlegte.','2f337c31773881e091ac8057a8bc46083fd12f47804a50c012c13626b4b0cfe1',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,3,'K1-1.2-003','In der ursprünglichen Skizze setzte ich den Beobachter in den Ursprung eines räumlichen Koordinatensystems, führte eine gekrümmte Fläche ein und wählte ein gleichseitiges Dreieck als zweidimensionale Beobachtungsfläche. Die historische Darstellung in Abbildung 1.F2 dokumentiert diese Reihenfolge; aus der Skizze allein lassen sich jedoch weder die genaue Flächenfunktion noch messbare Signalwerte bestimmen.','dd4bfb824cd4b71efb2dab42640a0f706ad372df2c365eae5821005c09329dd7',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,4,'K1-1.2-004','Abbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.','1a6e55d6999b441e09d1248adfdf477022b332a81ec51d8c5f152c1c2ca87d5c',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,5,'K1-1.2-005','Die Darstellung unterscheidet den Beobachter im Koordinatenursprung, die dreieckige Beobachtungsebene und die untersuchte gekrümmte Fläche. Welche Eigenschaften die Fläche besitzt, ist mathematisch erst nach Angabe einer Parametrisierung und eines Definitionsbereichs entschieden.','4a23f7be3232099b70187b20a316a0716480d048187635cf433125db2e646689',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,6,'K1-1.2-006','Eine zweidimensionale Darstellung macht eine dreidimensionale Situation nicht vollständig sichtbar. Daher unterscheide ich im Folgenden ausdrücklich zwischen den geometrischen Objekten des Modells, den berechneten Signalgrößen und deren Farbcodierung. Aus einer graphischen Projektion folgt weder, dass physikalischer Raum entsteht, noch, dass die Modellgröße eine tatsächliche Messung darstellt.','136ea078b229342614ce810daaf81e0d022dafec847b2560e81e2b0c13229edd',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,7,'K1-1.2-007','Die geometrische Skizze beantwortete die eigentliche Aufgabe noch nicht. Um Beziehungen quantitativ auszuwerten, musste ich festlegen, welcher Punkt der gekrümmten Fläche welchem Punkt des Dreiecks zugeordnet wird. Eine solche eindeutige Zuordnung ist die hier benötigte Bezugsfunktion; sie ist eine Modellentscheidung und keine automatisch aus der Zeichnung folgende Gesetzmäßigkeit.','b0b693e5c873c5b271bb828c899e1ca9514a02034569585f48ba673ba80312ae',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,8,'K1-1.2-008','Anschließend ergänzte ich einen Sender und eine Signalvorschrift. Erst damit ließ sich jedem zugeordneten Punktpaar eine berechenbare Laufzeit zuweisen. Der Sender ist kein allgemeines Axiom des FRZK, sondern ausschließlich ein Bestandteil dieses technischen Beispiels. Die Einführung von Laufzeiten macht eine zeitbezogene Größe auswertbar; sie bedeutet nicht, dass sich die Geometrie selbst zeitlich verändern muss.','dae76d9d1574217c713f7f3116c1ebded39296ba7550fe72ce9d419808407471',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,9,'K1-1.2-009','Im Ausgangsgedanken sollte ein Signal vom Sender über einen Punkt der gekrümmten Fläche zu einem zugeordneten Punkt des Beobachtungsdreiecks gelangen. Die gesamte Weglänge wurde in eine Laufzeit umgerechnet und anschließend farblich kodiert. Damit entsteht eine zweidimensionale Darstellung eines aus einer dreidimensionalen Konstruktion abgeleiteten Skalarfelds. Für eine wissenschaftlich wiederholbare Berechnung sind die Geometrie, die Zuordnung und die Ausbreitungsannahmen ausdrücklich anzugeben.','8041772119b135f5d5245c78c387d2144f89c2226a0312abc237512fd0723085',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,10,'K1-1.2-010','Abbildung 1.F3 zeigt die ursprüngliche Visualisierung solcher berechneten Laufzeitgrößen. Die dafür verwendeten Originalparameter, Programmdateien und Rohdaten sind hier nicht dokumentiert; deshalb gebe ich ihre Werte nicht nachträglich als überprüft aus. Stattdessen definiere ich im Folgenden ein unabhängiges Referenzmodell, mit dem derselbe methodische Rechengang vollständig nachvollzogen werden kann. Über einen rechtlichen Status oder Schutzrechte trifft dieser Abschnitt keine Aussage.','c2c750dfee6f56ba449728a3a2afec72d2584aff2f95032dcd6a1c8ee0669edf',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,11,'K1-1.2-011','Abbildung 1.F3: Ursprüngliche dreidimensionale Visualisierung modellierter Signallaufzeiten. Die historischen Rechenparameter sind für die vorliegende Fassung nicht belegt; die Darstellung wird daher nicht als numerischer Nachweis des nachfolgenden Referenzmodells verwendet. Eigene Darstellung.','833bcffa81bc978c5ae194e87c1a8ff7803ff06a984a4349453634ca054de02d',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,12,'K1-1.2-012','Reproduzierbares technisches Referenzmodell','50aba3203b5c2d326e6d3fe5d073280ab2478fa722b0ad1c47bf62109692daad',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,13,'K1-1.2-013','Die folgende Konkretisierung ist eine ausdrücklich neu festgelegte Modellvariante, keine nachträgliche Rekonstruktion der unzugänglichen Originalrechnung. Sie dient dazu, den in der Entstehungsgeschichte beschriebenen Rechenweg mit vollständig offengelegten Größen und Regeln zu demonstrieren. Alle Koordinaten und Längen werden in Metern, Zeiten in Sekunden beziehungsweise Nanosekunden angegeben.','2655afa9db75f869005c1b8d9a6aa38bc6ff3bcfdc1c366a867f6b7cd1d9cba9',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,14,'K1-1.2-014','Koordinatensystem und Dreieck. Der Beobachter O=(0, 0, 0) ist der geometrische Bezugspunkt. Das Beobachtungsdreieck liegt in der Ebene x=b mit b=1 m; seine Seitenlänge beträgt s=1 m. Für die beiden ebenen Koordinaten u und v wird das abgeschlossene Dreiecksgebiet D durch die Eckpunkte A, B und C festgelegt (Gleichung 1.1):','11269b12189f9b48266b477e4bd8624c8b52c3ed7f561f4a1c478e0acdfeffb7',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,15,'K1-1.2-015','Word-LaTeX: A=(-\\tfrac{s}{2},-\\tfrac{s}{2}),\\quad B=(\\tfrac{s}{2},-\\tfrac{s}{2}),\\quad C=(0,\\frac{(\\sqrt{3}-1)s}{2})','9f5c02e712181b4c3a120116988e0bb83c92f7038857b02def4fa4e90ef32d49',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,16,'K1-1.2-016','Die Punkte A, B und C der vorstehenden Formel sind (u,v)-Koordinaten in der Beobachtungsebene. Das Dreieck ist gleichseitig, denn alle drei Seiten haben die Länge s. Jeder Punkt (u,v)∈D beschreibt genau einen Beobachtungspunkt P(u,v) in der Ebene x=b.','6a8b436d2bc6dd3a47f650d9ae608d932e40b1f061e4953577cd2f705c9659e2',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,17,'K1-1.2-017','Gekrümmte Fläche und Bezugsfunktion. Im dreidimensionalen Raum definiere ich die Fläche Q durch die folgende Parametrisierung. Für das Beispiel setze ich d=3 m und a=0,20 m⁻¹; der Definitionsbereich der Fläche ist genau das Dreiecksgebiet D. Die Zuordnung P(u,v)↔Q(u,v) verwendet dieselben beiden Parameter u und v und ist daher eindeutig (Gleichung 1.2).','32ced43e75d6a2a670d1d8bdf20dbb37136af8b65fb88942e63faa92c94a892b',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,18,'K1-1.2-018','Word-LaTeX: Q(u,v)=\\left(d+a(u^{2}-v^{2}),\\,u,\\,v\\right),\\qquad P(u,v)=(b,u,v)','487a9fa3c5a62559dab8db08e45dd8a094cf18f0b00bbed31d4559184469d686',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,19,'K1-1.2-019','Die Oberfläche ist eine Sattelfläche. Ihre Gauß-Krümmung ergibt sich aus den ersten und zweiten Ableitungen der Flächenfunktion und ist bei a≠0 überall negativ (Gleichung 1.3):','1e1af513a310098382d6ab09b6e029b4ba98ada0176fd7680cca8e8d78b0e316',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,20,'K1-1.2-020','Word-LaTeX: K(u,v)=\\frac{-4a^{2}}{\\left(1+4a^{2}(u^{2}+v^{2})\\right)^{2}}<0','cc53ade50c584193f5c12932bd5581401c9894d8be37d416ae205244ca71109f',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,21,'K1-1.2-021','Damit ist „nichteuklidisch“ in diesem Beispiel präzisiert: Gemeint ist die innere Geometrie einer gekrümmten zweidimensionalen Fläche, nicht eine Krümmung des umgebenden dreidimensionalen Raums oder der physikalischen Raumzeit. Wege außerhalb der Fläche werden im Referenzmodell euklidisch berechnet.','dacaf80ad81a6301e5ac12298a388abcb45ba8736c3d3f57dd2ee246bf8d4b7c',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,22,'K1-1.2-022','Sender, Signalweg und Ausbreitungsannahmen. Der Sender liegt bei S=(xₛ,0,0) mit xₛ=5 m. Jeder Flächenpunkt Q(u,v) wird idealisiert als punktförmiger, unmittelbar weiterstrahlender Signalpunkt angenommen. Für das jeweilige Parameterpaar wird genau der zweite Wegabschnitt von Q(u,v) zu P(u,v) ausgewertet. Beide Wegabschnitte sind gerade Strecken im dreidimensionalen euklidischen Raum. Das Modell setzt Vakuumausbreitung mit konstanter Geschwindigkeit c, keine Laufzeitverzögerung am Flächenpunkt und keine Abschwächung voraus. Brechung, Beugung, Mehrfachwege, Abschattung und die winkelabhängige Reflexionsbedingung werden nicht modelliert. Das ist eine idealisierte Zuordnungsvorschrift und kein vollständiges optisches Reflexionsmodell.','6a873c2bbdf09baad1ce1f5235d228c2d1bb0e0112e7711bc1f891a76e8f676d',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,23,'K1-1.2-023','Mess- beziehungsweise Rechengröße. Die zugeordnete Gesamtlaufzeit ist die Summe der beiden euklidischen Segmentlängen, geteilt durch die Ausbreitungsgeschwindigkeit. Mit xₛ=5 m, b=1 m, d=3 m und a=0,20 m⁻¹ gilt (Gleichung 1.4):','a0eef7676e5e5120ca5c9603e71925a13db5cc8c673624dd6b72bf0b8ab32bb9',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,24,'K1-1.2-024','Word-LaTeX: \\tau(u,v)=\\frac{\\sqrt{\\left(x_{S}-d-a(u^{2}-v^{2})\\right)^{2}+u^{2}+v^{2}}+d+a(u^{2}-v^{2})-b}{c}','cdce6fb924ff3b624c6475b2051d4e14f45543fefbed18004a59e1d01253321f',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,25,'K1-1.2-025','Dabei steht c=299 792 458 m/s für die im Internationalen Einheitensystem exakt festgelegte Vakuumlichtgeschwindigkeit (Bureau International des Poids et Mesures (2026). The International System of Units, 9. Auflage, aktualisierte Fassung. DOI: 10.59161/AUEZ1291.)[15]. Die berechnete Laufzeit ist eine Modellgröße. Eine tatsächliche Messung oder ein bestimmter physikalischer Reflexionsvorgang wird dadurch nicht nachgewiesen.','6eddb03f2b3bab8b47a86f4af24143b7e672574481858211002398a2f8579682',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,26,'K1-1.2-026','Ergebnisfunktion und Darstellung. Mit der Zuordnung jedes Beobachtungspunkts zu seiner Laufzeit entsteht ein Skalarfeld auf dem Dreieck (Gleichung 1.5):','81c6062c4047872571baa3fb304a43684c059cdb425aa5768b668d2402653683',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,27,'K1-1.2-027','Word-LaTeX: F:P(u,v)\\longmapsto \\tau(u,v),\\qquad (u,v)\\in D','912925769700d29ec67c46a4b26d4606433c0deaf24287c5e71c1504732ca9ad',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,28,'K1-1.2-028','Zur numerischen Darstellung werden die Bereiche −0,50 m ≤ u ≤ 0,50 m und −0,50 m ≤ v ≤ (√3−1)/2 m jeweils mit 281 gleichmäßig verteilten Stützstellen abgetastet. Ausgewertet werden ausschließlich Punkte innerhalb des abgeschlossenen Dreiecks D. An jedem gültigen Gitterpunkt werden Q, die beiden Signalstrecken und τ in dieser Reihenfolge berechnet. Für die reproduzierbare Farbkodierung in Abbildung 1.F4 wird der Bereich von 13,34 ns bis 13,75 ns fest vorgegeben; größere Werte entsprechen dem oberen Ende der Farbskala. Die exakte Gebietsmaske, die Farbstufen und der Algorithmus sind in Anlage 1E dokumentiert.','49b552c41f8598caf045991bdaed3c7eced8123fc97791362ee88df89628eff8',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,29,'K1-1.2-029','Kontrollrechnung. Für (u,v)=(0,0) folgt Q=(3,0,0) m und P=(1,0,0) m. Damit betragen beide Wegabschnitte jeweils 2 m. Aus der Gesamtstrecke von 4 m ergibt sich τ(0,0)=13,3426 ns. Für die beiden unteren Dreiecksecken A und B ergeben sich jeweils 13,7472 ns; für die obere Ecke C ergibt sich 13,4519 ns. Diese Zahlen lassen sich unmittelbar durch Einsetzen in die angegebenen Gleichungen kontrollieren.','e4271aaff3ce6b7af8d4fdbe313779b1555b09dde1e2176d3ae50fd297988082',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,30,'K1-1.2-030','Abbildung 1.F4: Numerisch reproduzierte Laufzeitverteilung auf dem Beobachtungsdreieck für die offengelegten Referenzparameter (s=1 m, b=1 m, d=3 m, a=0,20 m⁻¹, xₛ=5 m, c=299 792 458 m/s). Berechnung und Darstellung für diese Dissertation; nicht aus den historischen Abbildungen 1.F2 und 1.F3 abgeleitet.','d8876e71db8ee41ff7cb47ae4a3d7f12e61a98216402bf7fd76afec825bbea02',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,31,'K1-1.2-031','Prüfgrenzen des Referenzfalls. Die Gleichungen ermöglichen es, den geometrischen und numerischen Rechenweg unabhängig zu wiederholen; insbesondere sind Definitionsbereich, Flächenfunktion, Zuordnung, Signalweg, Konstanten und Farbbereich festgelegt. Damit ist die modellinterne Reproduzierbarkeit des hier definierten Referenzfalls hergestellt. Offen bleibt dagegen, ob die ursprünglichen Abbildungen auf denselben oder anderen Parametern beruhen. Ebenso ist mit der Konstruktion weder die physikalische Gültigkeit einer realen Signalstreuung noch eine allgemeine mathematische oder didaktische Wirksamkeit des FRZK belegt.','5f0d66629255791d0e6e8eca70198f9ab0b8d94abaa4b70bd626fcdacd3340f0',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,32,'K1-1.2-032','Das Referenzmodell zeigt, wie sich eine technische Problemstellung durch explizite Annahmen, eine definierte Geometrie, eine Zuordnungsregel und überprüfbare Rechnungen bearbeiten lässt. Darin liegt sein methodischer Bezug zum FRZK: Aus einer zunächst offenen Frage wird ein nachvollziehbarer Lösungsweg entwickelt und geprüft. Weder die gewählte Geometrie noch die Signalvorschrift sind Bestandteile des allgemeinen FRZK-Grundgerüsts; spezielle mathematische FRZK-Zustände und Operatoren werden in diesem Referenzmodell nicht benötigt.','81fc75cb8b244ccb59144beb86fb9b0a97e448a87631a2fba5d3411dac7a6451',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,33,'K1-1.2-033','Zwischen dem technischen Beispiel und meinen Unterrichtsbeobachtungen erkenne ich ein gemeinsames methodisches Motiv: Ich bestimme relevante Größen und Annahmen, ordne Beziehungen ausdrücklich zu und überprüfe die daraus ableitbaren Ergebnisse. Bei der Kartoffelaufgabe betrifft dies gegebene und gesuchte Angaben, bei linearen Funktionen die Abhängigkeit veränderlicher Größen. Eine Verbesserung von Lernleistungen ist damit noch nicht nachgewiesen.','4bf3cf63f6827a00133df7c7c79384c3e3f31d16493b156f20e0ca137b7b25ac',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,34,'K1-1.2-034','Das technische Referenzmodell und die Unterrichtsbeobachtungen sind methodisch vergleichbar, aber weder mathematisch noch empirisch identisch. Carroll diskutiert das Verhältnis naturwissenschaftlicher Weltbeschreibung zu weiterführenden philosophischen Fragestellungen (Carroll, Sean (2016). The Big Picture: On the Origins of Life, Meaning, and the Universe Itself. New York: Dutton.)[11]. Dieser allgemeine Bezug begründet weder die vorliegende technische Modellwahl noch die pädagogische Wirksamkeit des FRZK.','edc3bb5968de263d1e6b8f41f021ab983a3a01762bc77473c9e76420d7246632',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,35,'K1-1.2-035','Im Beispiel der Grundschülerin konnte ich beobachten, dass sie zunächst alle Informationen als gleichwertig behandelte. Eine schrittweise Strukturierung der Aufgabe bot die Gelegenheit, zwischen den vorhandenen Angaben und der gesuchten Größe zu unterscheiden. Welche Rolle dabei die konkrete Alltagssituation, das Vorwissen und die sprachliche Aufgabenformulierung spielten, blieb offen.','57ba752a3e0e2cac287a2c3a8f804ab547e9c64a15ba59bb038162449e9cf8ff',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,36,'K1-1.2-036','Bei den Schülerinnen der neunten Klasse zeigte sich eine andere Schwierigkeit: Eine bekannte Formel konnte nicht ohne Weiteres in eine verständliche Erklärung überführt werden. Für die Modellierung ist deshalb zu unterscheiden zwischen einer symbolischen Darstellung, den Bedeutungen ihrer Variablen und den funktionalen Beziehungen im jeweiligen Sachkontext. Die mögliche didaktische Wirkung einer solchen Unterscheidung ist Gegenstand meiner Untersuchung.','973c310c571e454b5e7cb64fd60f7f45d77df760301eac3484cc2b16cd23fe02',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,37,'K1-1.2-037','Aus beiden Situationen leite ich keine allgemeine Lerntheorie ab. Ich entwickle daraus eine Forschungsfrage nach dem Nutzen expliziter Orientierung: Hilft es, wenn Lernende einen mathematischen Zusammenhang durch eigene Beschreibungen, Beispiele und überprüfbare Zuordnungen erschließen?','85f03896652ba3d5a1b1b7a2e39566ae87e3d30bfe5076232f36a7e01026b31d',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.E-001','Geltungsbereich: Diese Anlage beschreibt ausschließlich das in Abschnitt 1.2 neu festgelegte Referenzmodell. Sie rekonstruiert nicht die unbekannten historischen Rechenparameter der ursprünglichen beiden Abbildungen.','1796520618312b6950c0145572c00619d01e210a6d88851f2dd5346621fcabae',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.E.1-001','s = 1 m; b = 1 m; d = 3 m; a = 0,20 m⁻¹; xₛ = 5 m; c = 299 792 458 m/s. Der Parameterbereich bildet ein Dreieck mit A = (−0,5; −0,5) m, B = (0,5; −0,5) m und C = (0; h) m, h = (√3 − 1)/2 ≈ 0,3660254 m.','fe9bd4ad35dab69a14ecd1f7107500cdd4b269d98e282bc479fae34b9821220e',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,2,'K1-1.E.1-002','Ein Gitterpunkt (u, v) gehört genau dann zum geschlossenen Dreieck, wenn −0,5 ≤ u ≤ 0,5 sowie −0,5 ≤ v ≤ h − √3·|u| gelten. Außerhalb dieses Gebiets wird keine Laufzeit ausgewertet und keine Dreiecksfarbe vergeben.','ee2449c48e2806827afc9e4e981f3d6063369b979336675f7b904ee19a5bc8cc',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.E.2-001','h = (sqrt(3) - 1) / 2','06eba74e6214ee2b55a96dc30218cefbb0ac0fad5e1add506f57ff9af0a8b292',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,2,'K1-1.E.2-002','U = 281 äquidistante Werte von -0.5 bis +0.5 (einschließlich)','ea0ebdeb9b4349dc0a8c6bc7f0e74f58f4c172fcc89dc9495fa200457929fb96',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,3,'K1-1.E.2-003','V = 281 äquidistante Werte von -0.5 bis h (einschließlich)','16a94d25499c5caa564ebdd164d458e918ae44fa403d8d33b4db16fd62598c70',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,4,'K1-1.E.2-004','für jedes (u,v) aus U × V:','1a15bb6a87d6da660717420dc09be7927ccfb7749737365edd3bc57365fba2a7',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,5,'K1-1.E.2-005','falls v < -0.5 oder v > h - sqrt(3)*abs(u): überspringen','0b67421843e452c3c300e5358ecd7d6f409f7e6da84343e66b8a2a538ba55eb9',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,6,'K1-1.E.2-006','xQ = 3.0 + 0.20*(u*u - v*v)','2bb83a720666999191d7f7b45204d5097b42e4f2d21d0a167b4e3f03f6455e7f',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,7,'K1-1.E.2-007','L1 = sqrt((5.0 - xQ)^2 + u*u + v*v)','0ec8263e1ccaa6488c6f34ed1a1ab981213aa5e1dae5630b540784fd1e41920b',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,8,'K1-1.E.2-008','L2 = abs(xQ - 1.0)','e7918ec181b8cbea7db81dfa768baeb66a64ed2d53b9dc0fbd3732d3aa2ebe7e',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,9,'K1-1.E.2-009','tau_ns = 1e9*(L1 + L2)/299792458','975c18d1afa2c6338a621abe47d279b7bacdf2764bd7646f0796012a8dfe57fb',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,10,'K1-1.E.2-010','tau_ns für die Farbdarstellung dem Punkt (u,v) zuordnen','c6801393997f969316b80aa88884e6cef145833c400f81f26600ba61f12c6a42',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.E.3-001','Die Laufzeit wird in Nanosekunden dargestellt. Zur Wiedergabe von Abbildung 1.F4 wird eine gefüllte Konturdarstellung mit 25 linear verteilten Stufengrenzen von 13,34 ns bis 13,75 ns und der Farbpalette „viridis“ verwendet. Die Dreiecksränder werden als Linien verbunden. Die Gitterpunkte außerhalb des Dreiecks bleiben maskiert. Die Farbgrenzen sind fest vorgegeben und werden nicht für jede Wiederholung neu an die Daten angepasst.','84bd5c1aa58fd95a2dd5a059e530abbf9911f258dc61522bd0378d56d9ce4317',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.E.4-001','Analytischer Kontrollpunkt (u,v) = (0,0): τ = 13,3425638079 ns. Eckpunkte A und B: je τ = 13,7472449142 ns. Eckpunkt C: τ = 13,4519250616 ns. Auf dem beschriebenen 281 × 281-Gitter liegen 39 481 Punkte innerhalb der Dreiecksmaske; der kleinste erfasste Gitterwert beträgt ungefähr 13,3425647406 ns, der größte 13,7472449142 ns. Die geringe Abweichung des Gitterminimums vom Wert am Mittelpunkt entsteht, weil v = 0 keine der 281 gleichmäßig verteilten v-Koordinaten ist.','b83637b062b862c6db1564dfeaf1b70742613c4cb50da0619bc386bec132135d',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_section_id,1,'K1-1.E.5-001','Die Regel beschreibt einen idealisierten zweiteiligen Signalweg vom Sender über einen zugeordneten Flächenpunkt zu einem Punkt der Beobachtungsebene. Sie berücksichtigt keine realistische winkelabhängige Reflexion, keine Mehrfachwege und keine Streu- oder Dämpfungseffekte. Das Ergebnis ist deshalb ein geometrisch begründetes Laufzeit-Skalarfeld, kein nachgewiesenes optisches Messverfahren. Die zwei historischen Skizzen in Abschnitt 1.2 bleiben ohne ihre ursprünglichen Daten eigenständige Illustrationen; mit diesem Referenzmodell werden sie nicht nachträglich validiert.','55b2319d4573fc1a7a2f1a94a5d8ef6bcf8ff15276782f366a452582fd02d9a0',@k1_final_rev) ON DUPLICATE KEY UPDATE paragraph_text=VALUES(paragraph_text),content_sha256=VALUES(content_sha256),created_revision_id=VALUES(created_revision_id);
INSERT INTO research_objects (dissertation_id,chapter_id,section_id,object_type,object_code,title,sort_order,status,created_revision_id,notes) VALUES
(@frzk_diss_id,@frzk_ch1_id,@k1_intro_id,'FIGURE','K1.FIG.ITERATION','Iterativer Erkenntnis- und Problemlöseprozess des FRZK',1,'RELEASED',@k1_final_rev,'Konzeptionelle Grafik, keine Algorithmusvalidierung; methodische Ausarbeitung in Kapitel 2') ON DUPLICATE KEY UPDATE section_id=VALUES(section_id),title=VALUES(title),created_revision_id=VALUES(created_revision_id);
INSERT INTO figures (object_id,figure_number,title,figure_type,caption,description,alt_text,provenance_type,provenance_notes,rights_status,validation_status,notes) VALUES
(@k1_concept_obj,'1.F1','Iterativer Erkenntnis- und Problemlöseprozess des FRZK','FLOWCHART','Abbildung 1.F1: Iterativer Erkenntnis- und Problemlöseprozess des FRZK. Konzeptionelle Darstellung des methodischen Grundgerüsts, nicht als bereits validierter Algorithmus zu verstehen. Die methodische Ausgestaltung der Einzelschritte, Übergänge und Rückkopplungsregeln erfolgt in Kapitel 2. Darstellung nach dem in dieser Arbeit beschriebenen Ansatz.','Konzeptioneller iterativer FRZK-Prozess mit Rückführung von Schritt 5 zu Schritt 2.','Konzeptionelles FRZK-Schema mit fünf Schritten: Vorwissen/Problemstellung, Wissen strukturieren, Beziehungen visualisieren, Zusammenhänge prüfen, Wissen erweitern/revidieren. Rückkopplung von Schritt 5 zu Schritt 2.','UNKNOWN','Als Abbildung vom Autor für das Manuskript bereitgestellt; grafische Provenienz nicht unabhängig geprüft.','UNCLEAR','OPEN','Validierung eines Lern- oder Problemlösealgorithmus in Kapitel 2 offen')
INSERT INTO figure_assets (figure_id,asset_role,filename,relative_path,mime_type,width_px,height_px,file_size_bytes,sha256,embedded_media_ref,created_with,notes) VALUES (@k1_concept_figure,'PRIMARY','figure_1_F1.png','assets/frzk_kapitel_1/figure_1_F1.png','image/png',750,654,62421,'90f16ce139eba714bf440f30869e043a4ca71f3681ab7731312211afd011b124','FRZK_Kapitel1_Iterativer_Erkenntnisprozess_2026-11-09.docx','DOCX-Einbettung','Originalgrafik vom 09.11.2026, Quelle konzeptionell');
INSERT INTO figure_descriptions (figure_id,text_type,language_code,text_value,sort_order) VALUES (@k1_concept_figure,'CAPTION','de','Abbildung 1.F1: Iterativer Erkenntnis- und Problemlöseprozess des FRZK. Konzeptionelle Darstellung des methodischen Grundgerüsts, nicht als bereits validierter Algorithmus zu verstehen. Die methodische Ausgestaltung der Einzelschritte, Übergänge und Rückkopplungsregeln erfolgt in Kapitel 2. Darstellung nach dem in dieser Arbeit beschriebenen Ansatz.',0),(@k1_concept_figure,'ALT_TEXT','de','Konzeptionelles FRZK-Schema mit fünf Schritten: Vorwissen/Problemstellung, Wissen strukturieren, Beziehungen visualisieren, Zusammenhänge prüfen, Wissen erweitern/revidieren. Rückkopplung von Schritt 5 zu Schritt 2.',1);
INSERT INTO figure_assets (figure_id,asset_role,filename,relative_path,mime_type,width_px,height_px,file_size_bytes,sha256,embedded_media_ref,created_with,notes) VALUES (@k1_historic_fig,'PRIMARY','figure_1_F2.png','assets/frzk_kapitel_1/figure_1_F2.png','image/png',1146,693,84384,'c18c3b62fa60895ddf76b77e119f9f6bd99c7eb8f92fe781913130020bbd0d72','FRZK_Kapitel1_Iterativer_Erkenntnisprozess_2026-11-09.docx','DOCX-Export','Stabile Objekt-ID, aktualisierte Abbildungsnummer 1.F2');
INSERT INTO figure_descriptions (figure_id,text_type,language_code,text_value,sort_order) VALUES (@k1_historic_fig,'CAPTION','de','Abbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.',0),(@k1_historic_fig,'ALT_TEXT','de','Abbildung 1.F2: Ursprüngliche geometrische Ideenskizze mit Beobachter, Beobachtungsdreieck und gekrümmter Fläche. Die Abbildung dokumentiert den Entstehungsweg; sie ist keine maßstäbliche Darstellung des anschließend definierten Referenzmodells. Eigene Darstellung.',1);
INSERT INTO figure_assets (figure_id,asset_role,filename,relative_path,mime_type,width_px,height_px,file_size_bytes,sha256,embedded_media_ref,created_with,notes) VALUES (@k1_historic_fig,'PRIMARY','figure_1_F3.png','assets/frzk_kapitel_1/figure_1_F3.png','image/png',815,591,269796,'668c85a28cec4cb2fd1dca82bd04d06e46d71156bc54b3cdf6cb2fb72a153066','FRZK_Kapitel1_Iterativer_Erkenntnisprozess_2026-11-09.docx','DOCX-Export','Stabile Objekt-ID, aktualisierte Abbildungsnummer 1.F3');
INSERT INTO figure_descriptions (figure_id,text_type,language_code,text_value,sort_order) VALUES (@k1_historic_fig,'CAPTION','de','Abbildung 1.F3: Ursprüngliche dreidimensionale Visualisierung modellierter Signallaufzeiten. Die historischen Rechenparameter sind für die vorliegende Fassung nicht belegt; die Darstellung wird daher nicht als numerischer Nachweis des nachfolgenden Referenzmodells verwendet. Eigene Darstellung.',0),(@k1_historic_fig,'ALT_TEXT','de','Abbildung 1.F3: Ursprüngliche dreidimensionale Visualisierung modellierter Signallaufzeiten. Die historischen Rechenparameter sind für die vorliegende Fassung nicht belegt; die Darstellung wird daher nicht als numerischer Nachweis des nachfolgenden Referenzmodells verwendet. Eigene Darstellung.',1);
INSERT INTO figure_assets (figure_id,asset_role,filename,relative_path,mime_type,width_px,height_px,file_size_bytes,sha256,embedded_media_ref,created_with,notes) VALUES (@k1_historic_fig,'PRIMARY','figure_1_F4.png','assets/frzk_kapitel_1/figure_1_F4.png','image/png',1126,856,101198,'13bfbcd0390c69ae1d24cc628b3cbf7b4745c6b38b123fe699a70fedf4dfbcf2','FRZK_Kapitel1_Iterativer_Erkenntnisprozess_2026-11-09.docx','DOCX-Export','Stabile Objekt-ID, aktualisierte Abbildungsnummer 1.F4');
INSERT INTO figure_descriptions (figure_id,text_type,language_code,text_value,sort_order) VALUES (@k1_historic_fig,'CAPTION','de','Abbildung 1.F4: Numerisch reproduzierte Laufzeitverteilung auf dem Beobachtungsdreieck für die offengelegten Referenzparameter (s=1 m, b=1 m, d=3 m, a=0,20 m⁻¹, xₛ=5 m, c=299 792 458 m/s). Berechnung und Darstellung für diese Dissertation; nicht aus den historischen Abbildungen 1.F2 und 1.F3 abgeleitet.',0),(@k1_historic_fig,'ALT_TEXT','de','Abbildung 1.F4: Numerisch reproduzierte Laufzeitverteilung auf dem Beobachtungsdreieck für die offengelegten Referenzparameter (s=1 m, b=1 m, d=3 m, a=0,20 m⁻¹, xₛ=5 m, c=299 792 458 m/s). Berechnung und Darstellung für diese Dissertation; nicht aus den historischen Abbildungen 1.F2 und 1.F3 abgeleitet.',1);
INSERT INTO research_objects (dissertation_id,chapter_id,section_id,object_type,object_code,title,sort_order,status,created_revision_id,notes) VALUES (@frzk_diss_id,@frzk_ch1_id,@k1_s,'EQUATION','K1.A2.EQ01','Steigung einer nicht senkrechten Geraden',901,'REVIEW',@k1_final_rev,'Anlage 1A.2; klassische Mathematik, keine eigenständige FRZK-Zusatzsymbolik') ON DUPLICATE KEY UPDATE title=VALUES(title),section_id=VALUES(section_id),created_revision_id=VALUES(created_revision_id);
INSERT INTO equations (object_id,equation_number,title,equation_latex,word_latex,unicode_math,plain_description,equation_type,provenance,assumptions_text,validity_domain_text,validation_status,notes) VALUES (@k1_math_obj,'1.A2.1','Steigung einer nicht senkrechten Geraden','a=\\frac{\\Delta y}{\\Delta x}','a=\\frac{\\Delta y}{\\Delta x}','a = Δy/Δx','Steigung einer nicht senkrechten Geraden','EXAMPLE','CLASSICAL','Δx ≠ 0','Δx ≠ 0','PASS','Anlage 1A.2; sachlich bekannte Formel bzw. Autorenbeispiel') ON DUPLICATE KEY UPDATE title=VALUES(title),equation_latex=VALUES(equation_latex),word_latex=VALUES(word_latex),unicode_math=VALUES(unicode_math),assumptions_text=VALUES(assumptions_text),validation_status=VALUES(validation_status);
